INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('2Co', 5, 'pt', '[{"numero": 1, "texto": "Porque sabemos que, se nossa casa terrestre deste tabernáculo se desfizer, temos um edifício de Deus, uma casa não feita por mãos, [mas] eterna, nos céus."}, {"numero": 2, "texto": "Porque nesta [casa] gememos, desejando sermos revestidos de nossa habitação do céu;"}, {"numero": 3, "texto": "Dado que, se estivermos vestidos, não seremos achados nus."}, {"numero": 4, "texto": "Pois de fato nós, os que estamos neste tabernáculo, gememos pressionados, não porque queremos ser despidos, mas sim, revestidos; para que a mortalidade seja devorada pela vida."}, {"numero": 5, "texto": "E para isto mesmo que Deus nos preparou, ele que também deu o penhor do Espírito."}, {"numero": 6, "texto": "Por isso sempre temos confiança, e sabemos que, enquanto habitarmos no corpo, estamos ausentes do Senhor."}, {"numero": 7, "texto": "(Pois andamos pela fé, e não pela vista)."}, {"numero": 8, "texto": "Temos, porém, confiança, e queremos mais deixar o corpo, e habitar com o Senhor;"}, {"numero": 9, "texto": "Por isso também desejamos muito ser agradáveis a ele, quer presentes [no nosso corpo] ,quer ausentes;"}, {"numero": 10, "texto": "Pois todos devemos comparecer diante do Tribunal de Cristo, para que cada um receba o pagamento das coisas que fez no corpo, seja bem ou mal."}, {"numero": 11, "texto": "Conhecendo, pois, o temor ao Senhor, persuadimos as pessoas para a fé, e a Deus somos claramente visíveis; mas espero, também, que estejamos claramente visíveis em vossas consciências."}, {"numero": 12, "texto": "Porque não nos recomendamos novamente para vós; mas damos oportunidade de vos orgulhardes de nós; para que tenhais [o que responder] aos que se orgulham da aparência, e não do coração."}, {"numero": 13, "texto": "Pois se nós enlouquecemos, é para Deus; se estamos sensatos, é para vós."}, {"numero": 14, "texto": "Porque é o amor de Cristo que nos controla; pois temos certeza que, se um morreu por todos, logo todos morreram."}, {"numero": 15, "texto": "E ele morreu por todos, para que os que vivem não vivam mais para si, mas sim, para aquele que por eles morreu e ressuscitou."}, {"numero": 16, "texto": "Portanto daqui em diante a ninguém conhecemos segundo a carne, e ainda que também tenhamos conhecido a Cristo segundo a carne, todavia agora não o conhecemos [assim] ."}, {"numero": 17, "texto": "Portanto, se alguém está em Cristo, uma nova criatura [é] ; as coisas velhas já passaram, eis que tudo se fez novo."}, {"numero": 18, "texto": "E tudo isto [vem] de Deus, o qual por Jesus Cristo nos reconciliou consigo, e nos deu o ministério da reconciliação."}, {"numero": 19, "texto": "Porque Deus estava em Cristo reconciliando consigo ao mundo, não lhes atribuindo seus pecados; e pôs em nós a palavra da reconciliação."}, {"numero": 20, "texto": "Assim, pois, nós somos embaixadores da parte de Cristo, como se Deus rogasse por nós; [por isso] ,rogamos em Cristo: Reconciliai-vos com Deus."}, {"numero": 21, "texto": "Pois ele fez com que aquele que não conheceu pecado [se tornasse] pecado por nós; para que nós nele fôssemos feitos justiça de Deus."}]'::jsonb, 'Almeida Livre'),
  ('2Co', 5, 'en', '[{"numero": 1, "texto": "For we know that if our earthly house of this tabernacle were dissolved, we have a building of God, an house not made with hands, eternal in the heavens."}, {"numero": 2, "texto": "For in this we groan, earnestly desiring to be clothed upon with our house which is from heaven:"}, {"numero": 3, "texto": "If so be that being clothed we shall not be found naked."}, {"numero": 4, "texto": "For we that are in this tabernacle do groan, being burdened: not for that we would be unclothed, but clothed upon, that mortality might be swallowed up of life."}, {"numero": 5, "texto": "Now he that hath wrought us for the selfsame thing is God, who also hath given unto us the earnest of the Spirit."}, {"numero": 6, "texto": "Therefore we are always confident, knowing that, whilst we are at home in the body, we are absent from the Lord:"}, {"numero": 7, "texto": "(For we walk by faith, not by sight:)"}, {"numero": 8, "texto": "We are confident, I say, and willing rather to be absent from the body, and to be present with the Lord."}, {"numero": 9, "texto": "Wherefore we labour, that, whether present or absent, we may be accepted of him."}, {"numero": 10, "texto": "For we must all appear before the judgment seat of Christ; that every one may receive the things done in his body, according to that he hath done, whether it be good or bad."}, {"numero": 11, "texto": "Knowing therefore the terror of the Lord, we persuade men; but we are made manifest unto God; and I trust also are made manifest in your consciences."}, {"numero": 12, "texto": "For we commend not ourselves again unto you, but give you occasion to glory on our behalf, that ye may have somewhat to answer them which glory in appearance, and not in heart."}, {"numero": 13, "texto": "For whether we be beside ourselves, it is to God: or whether we be sober, it is for your cause."}, {"numero": 14, "texto": "For the love of Christ constraineth us; because we thus judge, that if one died for all, then were all dead:"}, {"numero": 15, "texto": "And that he died for all, that they which live should not henceforth live unto themselves, but unto him which died for them, and rose again."}, {"numero": 16, "texto": "Wherefore henceforth know we no man after the flesh: yea, though we have known Christ after the flesh, yet now henceforth know we him no more."}, {"numero": 17, "texto": "Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new."}, {"numero": 18, "texto": "And all things are of God, who hath reconciled us to himself by Jesus Christ, and hath given to us the ministry of reconciliation;"}, {"numero": 19, "texto": "To wit, that God was in Christ, reconciling the world unto himself, not imputing their trespasses unto them; and hath committed unto us the word of reconciliation."}, {"numero": 20, "texto": "Now then we are ambassadors for Christ, as though God did beseech you by us: we pray you in Christ''s stead, be ye reconciled to God."}, {"numero": 21, "texto": "For he hath made him to be sin for us, who knew no sin; that we might be made the righteousness of God in him."}]'::jsonb, 'King James Version'),
  ('2Co', 5, 'fr', '[{"numero": 1, "texto": "Nous savons, en effet, que, si cette tente où nous habitons sur la terre est détruite, nous avons dans le ciel un édifice qui est l''''ouvrage de Dieu, une demeure éternelle qui n''''a pas été faite de main d''''homme."}, {"numero": 2, "texto": "Aussi nous gémissons dans cette tente, désirant revêtir notre domicile céleste,"}, {"numero": 3, "texto": "si du moins nous sommes trouvés vêtus et non pas nus."}, {"numero": 4, "texto": "Car tandis que nous sommes dans cette tente, nous gémissons, accablés, parce que nous voulons, non pas nous dépouiller, mais nous revêtir, afin que ce qui est mortel soit englouti par la vie."}, {"numero": 5, "texto": "Et celui qui nous a formés pour cela, c''''est Dieu, qui nous a donné les arrhes de l''''Esprit."}, {"numero": 6, "texto": "Nous sommes donc toujours pleins de confiance, et nous savons qu''''en demeurant dans ce corps nous demeurons loin du Seigneur-"}, {"numero": 7, "texto": "car nous marchons par la foi et non par la vue,"}, {"numero": 8, "texto": "nous sommes pleins de confiance, et nous aimons mieux quitter ce corps et demeurer auprès du Seigneur."}, {"numero": 9, "texto": "C''''est pour cela aussi que nous nous efforçons de lui être agréables, soit que nous demeurions dans ce corps, soit que nous le quittions."}, {"numero": 10, "texto": "Car il nous faut tous comparaître devant le tribunal de Christ, afin que chacun reçoive selon le bien ou le mal qu''''il aura fait, étant dans son corps."}, {"numero": 11, "texto": "Connaissant donc la crainte du Seigneur, nous cherchons à convaincre les hommes; Dieu nous connaît, et j''''espère que dans vos consciences vous nous connaissez aussi."}, {"numero": 12, "texto": "Nous ne nous recommandons pas de nouveau nous-mêmes auprès de vous; mais nous vous donnons occasion de vous glorifier à notre sujet, afin que vous puissiez répondre à ceux qui tirent gloire de ce qui est dans les apparences et non dans le coeur."}, {"numero": 13, "texto": "En effet, si je suis hors de sens, c''''est pour Dieu; si je suis de bon sens, c''''est pour vous."}, {"numero": 14, "texto": "Car l''''amour de Christ nous presse, parce que nous estimons que, si un seul est mort pour tous, tous donc sont morts;"}, {"numero": 15, "texto": "et qu''''il est mort pour tous, afin que ceux qui vivent ne vivent plus pour eux-mêmes, mais pour celui qui est mort et ressuscité pour eux."}, {"numero": 16, "texto": "Ainsi, dès maintenant, nous ne connaissons personne selon la chair; et si nous avons connu Christ selon la chair, maintenant nous ne le connaissons plus de cette manière."}, {"numero": 17, "texto": "Si quelqu''''un est en Christ, il est une nouvelle créature. Les choses anciennes sont passées; voici, toutes choses sont devenues nouvelles."}, {"numero": 18, "texto": "Et tout cela vient de Dieu, qui nous a réconciliés avec lui par Christ, et qui nous a donné le ministère de la réconciliation."}, {"numero": 19, "texto": "Car Dieu était en Christ, réconciliant le monde avec lui-même, en n''''imputant point aux hommes leurs offenses, et il a mis en nous la parole de la réconciliation."}, {"numero": 20, "texto": "Nous faisons donc les fonctions d''''ambassadeurs pour Christ, comme si Dieu exhortait par nous; nous vous en supplions au nom de Christ: Soyez réconciliés avec Dieu!"}, {"numero": 21, "texto": "Celui qui n''''a point connu le péché, il l''''a fait devenir péché pour nous, afin que nous devenions en lui justice de Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('2Co', 5, 'es', '[{"numero": 1, "texto": "PORQUE sabemos, que si la casa terrestre de nuestra habitación se deshiciere, tenemos de Dios un edificio, una casa no hecha de manos, eterna en los cielos."}, {"numero": 2, "texto": "Y por esto también gemimos, deseando ser sobrevestidos de aquella nuestra habitación celestial;"}, {"numero": 3, "texto": "Puesto que en verdad habremos sido hallados vestidos, y no desnudos."}, {"numero": 4, "texto": "Porque asimismo los que estamos en este tabernáculo, gemimos agravados; porque no quisiéramos ser desnudados, sino sobrevestidos, para que lo mortal sea absorbido por la vida."}, {"numero": 5, "texto": "Mas el que nos hizo para esto mismo, es Dios; el cual nos ha dado la prenda del Espíritu."}, {"numero": 6, "texto": "Así que vivimos confiados siempre, y sabiendo, que entre tanto que estamos en el cuerpo, peregrinamos ausentes del Señor;"}, {"numero": 7, "texto": "(Porque por fe andamos, no por vista;)"}, {"numero": 8, "texto": "Mas confiamos, y más quisiéramos partir del cuerpo, y estar presentes al Señor."}, {"numero": 9, "texto": "Por tanto procuramos también, ó ausentes, ó presentes, serle agradables:"}, {"numero": 10, "texto": "Porque es menester que todos nosotros parezcamos ante el tribunal de Cristo, para que cada uno reciba según lo que hubiere hecho por medio del cuerpo, ora sea bueno ó malo."}, {"numero": 11, "texto": "Estando pues poseídos del temor del Señor, persuadimos á los hombres, mas á Dios somos manifiestos; y espero que también en vuestras conciencias somos manifiestos."}, {"numero": 12, "texto": "No nos encomendamos pues otra vez á vosotros, sino os damos ocasión de gloriaros por nosotros, para que tengáis qué responder contra los que se glorían en las apariencias, y no en el corazón."}, {"numero": 13, "texto": "Porque si loqueamos, es para Dios; y si estamos en seso, es para vosotros."}, {"numero": 14, "texto": "Porque el amor de Cristo nos constriñe, pensando esto: Que si uno murió por todos, luego todos son muertos;"}, {"numero": 15, "texto": "Y por todos murió, para que los que viven, ya no vivan para sí, mas para aquel que murió y resucitó por ellos."}, {"numero": 16, "texto": "De manera que nosotros de aquí adelante á nadie conocemos según la carne: y aun si á Cristo conocimos según la carne, empero ahora ya no le conocemos."}, {"numero": 17, "texto": "De modo que si alguno está en Cristo, nueva criatura es: las cosas viejas pasaron; he aquí todas son hechas nuevas."}, {"numero": 18, "texto": "Y todo esto es de Dios, el cual nos reconcilió á sí por Cristo; y nos dió el ministerio de la reconciliación."}, {"numero": 19, "texto": "Porque ciertamente Dios estaba en Cristo reconciliando el mundo á sí, no imputándole sus pecados, y puso en nosotros la palabra de la reconciliación."}, {"numero": 20, "texto": "Así que, somos embajadores en nombre de Cristo, como si Dios rogase por medio nuestro; os rogamos en nombre de Cristo: Reconciliaos con Dios."}, {"numero": 21, "texto": "Al que no conoció pecado, hizo pecado por nosotros, para que nosotros fuésemos hechos justicia de Dios en él."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Cr', 36, 'pt', '[{"numero": 1, "texto": "Então o povo da terra tomou a Jeoacaz filho de Josias, e fizeram-lhe rei em lugar de seu pai em Jerusalém."}, {"numero": 2, "texto": "De vinte e três anos era Jeoacaz quando começou a reinar, e três meses reinou em Jerusalém."}, {"numero": 3, "texto": "E o rei do Egito o tirou de Jerusalém, e condenou a terra em cem talentos de prata e um de ouro."}, {"numero": 4, "texto": "E o rei do Egito constituiu o seu irmão Eliaquim como rei sobre Judá e Jerusalém, e mudou-lhe o nome em Jeoaquim; e Neco tomou o seu irmão Jeoacaz, e o levou ao Egito."}, {"numero": 5, "texto": "Quando começou a reinar Jeoaquim era de vinte e cinco anos, e reinou onze anos em Jerusalém: e fez o que era mau aos olhos do SENHOR seu Deus."}, {"numero": 6, "texto": "E subiu contra ele Nabucodonosor rei da Babilônia, e acorrentado com correntes o levou à Babilônia."}, {"numero": 7, "texto": "Também levou Nabucodonosor à Babilônia dos utensílios da casa do SENHOR, e os pôs no seu templo em Babilônia."}, {"numero": 8, "texto": "Os demais dos feitos de Jeoaquim, e as abominações que fez, e o que nele se achou, eis que estão escritos no livro dos reis de Israel e de Judá: e reinou em seu lugar Joaquim seu filho."}, {"numero": 9, "texto": "De oito anos era Joaquim quando começou a reinar, e reinou três meses e dez dias em Jerusalém: e fez o que era mau aos olhos do SENHOR."}, {"numero": 10, "texto": "Na primavera do ano, o rei Nabucodonosor mandou que o trouxessem à Babilônia, juntamente com os utensílos preciosos da casa do SENHOR; e constituiu o seu irmão Zedequias como rei sobre Judá e Jerusalém."}, {"numero": 11, "texto": "De vinte e um anos era Zedequias quando começou a reinar, e onze anos reinou em Jerusalém."}, {"numero": 12, "texto": "E fez o que era mau aos olhos do SENHOR seu Deus, e não se humilhou diante do profeta Jeremias, que lhe falava da parte do SENHOR."}, {"numero": 13, "texto": "Rebelou-se também contra Nabucodonosor, ao qual havia jurado por Deus; e endureceu sua cerviz, e obstinou seu coração, para não voltar-se ao SENHOR o Deus de Israel."}, {"numero": 14, "texto": "E também todos os príncipes dos sacerdotes, e o povo, aumentaram a transgressão, seguindo todas as abominações das nações, e contaminando a casa do SENHOR, a qual ele havia santificado em Jerusalém."}, {"numero": 15, "texto": "E o SENHOR o Deus de seus pais enviou a eles por meio de seus mensageiros, enviando insistentemente: porque ele tinha misericórdia de seu povo, e de sua habitação."}, {"numero": 16, "texto": "Mas eles faziam escárnio dos mensageiros de Deus, e menosprezavam suas palavras, ridicularizando-se de seus profetas, até que subiu o furor do SENHOR contra seu povo, de maneira que não havia remédio."}, {"numero": 17, "texto": "Pelo qual trouxe contra eles ao rei dos caldeus, que matou à espada seus rapazes na casa de seu santuário, sem perdoar jovem, nem virgem, nem velho, nem decrépito; todos os entregou em suas mãos."}, {"numero": 18, "texto": "Também todos os vasos da casa de Deus, grandes e pequenos, os tesouros da casa do SENHOR, e os tesouros do rei e de seus príncipes, tudo o levou à Babilônia."}, {"numero": 19, "texto": "E queimaram a casa de Deus, e romperam o muro de Jerusalém, e consumiram ao fogo todos seus palácios, e destruíram todos os seus objetos valiosos."}, {"numero": 20, "texto": "Os que restaram da espada foram passados à Babilônia; e foram servos dele e de seus filhos, até que veio o reino dos persas;"}, {"numero": 21, "texto": "Para que se cumprisse a palavra do SENHOR pela boca de Jeremias, até que a terra houvesse aproveitado os seus descansos sabáticos; pois durante todo o tempo de sua ruina ela descansou, até que os setenta anos fossem cumpridos."}, {"numero": 22, "texto": "Mas ao primeiro ano de Ciro rei dos persas, para que se cumprisse a palavra do SENHOR por boca de Jeremias, o SENHOR induziu o espírito de Ciro rei dos persas, o qual fez apregoar por todo seu reino, e também por escrito, dizendo:"}, {"numero": 23, "texto": "Assim diz Ciro rei dos persas: o SENHOR, o Deus dos céus, me deu todos os reinos da terra; e ele me encarregou que lhe edifique casa em Jerusalém, que é em Judá. Quem houver de vós de todo seu povo, o SENHOR seu Deus seja com o tal, e suba."}]'::jsonb, 'Almeida Livre'),
  ('2Cr', 36, 'en', '[{"numero": 1, "texto": "Then the people of the land took Jehoahaz the son of Josiah, and made him king in his father''s stead in Jerusalem."}, {"numero": 2, "texto": "Jehoahaz was twenty and three years old when he began to reign, and he reigned three months in Jerusalem."}, {"numero": 3, "texto": "And the king of Egypt put him down at Jerusalem, and condemned the land in an hundred talents of silver and a talent of gold."}, {"numero": 4, "texto": "And the king of Egypt made Eliakim his brother king over Judah and Jerusalem, and turned his name to Jehoiakim. And Necho took Jehoahaz his brother, and carried him to Egypt."}, {"numero": 5, "texto": "Jehoiakim was twenty and five years old when he began to reign, and he reigned eleven years in Jerusalem: and he did that which was evil in the sight of the Lord his God."}, {"numero": 6, "texto": "Against him came up Nebuchadnezzar king of Babylon, and bound him in fetters, to carry him to Babylon."}, {"numero": 7, "texto": "Nebuchadnezzar also carried of the vessels of the house of the Lord to Babylon, and put them in his temple at Babylon."}, {"numero": 8, "texto": "Now the rest of the acts of Jehoiakim, and his abominations which he did, and that which was found in him, behold, they are written in the book of the kings of Israel and Judah: and Jehoiachin his son reigned in his stead."}, {"numero": 9, "texto": "Jehoiachin was eight years old when he began to reign, and he reigned three months and ten days in Jerusalem: and he did that which was evil in the sight of the Lord."}, {"numero": 10, "texto": "And when the year was expired, king Nebuchadnezzar sent, and brought him to Babylon, with the goodly vessels of the house of the Lord, and made Zedekiah his brother king over Judah and Jerusalem."}, {"numero": 11, "texto": "Zedekiah was one and twenty years old when he began to reign, and reigned eleven years in Jerusalem."}, {"numero": 12, "texto": "And he did that which was evil in the sight of the Lord his God, and humbled not himself before Jeremiah the prophet speaking from the mouth of the Lord."}, {"numero": 13, "texto": "And he also rebelled against king Nebuchadnezzar, who had made him swear by God: but he stiffened his neck, and hardened his heart from turning unto the Lord God of Israel."}, {"numero": 14, "texto": "Moreover all the chief of the priests, and the people, transgressed very much after all the abominations of the heathen; and polluted the house of the Lord which he had hallowed in Jerusalem."}, {"numero": 15, "texto": "And the Lord God of their fathers sent to them by his messengers, rising up betimes, and sending; because he had compassion on his people, and on his dwelling place:"}, {"numero": 16, "texto": "But they mocked the messengers of God, and despised his words, and misused his prophets, until the wrath of the Lord arose against his people, till there was no remedy."}, {"numero": 17, "texto": "Therefore he brought upon them the king of the Chaldees, who slew their young men with the sword in the house of their sanctuary, and had no compassion upon young man or maiden, old man, or him that stooped for age: he gave them all into his hand."}, {"numero": 18, "texto": "And all the vessels of the house of God, great and small, and the treasures of the house of the Lord, and the treasures of the king, and of his princes; all these he brought to Babylon."}, {"numero": 19, "texto": "And they burnt the house of God, and brake down the wall of Jerusalem, and burnt all the palaces thereof with fire, and destroyed all the goodly vessels thereof."}, {"numero": 20, "texto": "And them that had escaped from the sword carried he away to Babylon; where they were servants to him and his sons until the reign of the kingdom of Persia:"}, {"numero": 21, "texto": "To fulfil the word of the Lord by the mouth of Jeremiah, until the land had enjoyed her sabbaths: for as long as she lay desolate she kept sabbath, to fulfil threescore and ten years."}, {"numero": 22, "texto": "Now in the first year of Cyrus king of Persia, that the word of the Lord spoken by the mouth of Jeremiah might be accomplished, the Lord stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}, {"numero": 23, "texto": "Thus saith Cyrus king of Persia, All the kingdoms of the earth hath the Lord God of heaven given me; and he hath charged me to build him an house in Jerusalem, which is in Judah. Who is there among you of all his people? The Lord his God be with him, and let him go up."}]'::jsonb, 'King James Version'),
  ('2Cr', 36, 'fr', '[{"numero": 1, "texto": "Le peuple du pays prit Joachaz, fils de Josias, et l''''établit roi à la place de son père à Jérusalem."}, {"numero": 2, "texto": "Joachaz avait vingt-trois ans lorsqu''''il devint roi, et il régna trois mois à Jérusalem."}, {"numero": 3, "texto": "Le roi d''''Egypte le destitua à Jérusalem, et frappa le pays d''''une contribution de cent talents d''''argent et d''''un talent d''''or."}, {"numero": 4, "texto": "Et le roi d''''Egypte établit roi sur Juda et sur Jérusalem Eliakim, frère de Joachaz; et il changea son nom en celui de Jojakim. Néco prit son frère Joachaz, et l''''emmena en Egypte."}, {"numero": 5, "texto": "Jojakim avait vingt-cinq ans lorsqu''''il devint roi, et il régna onze ans à Jérusalem. Il fit ce qui est mal aux yeux de l''''Eternel, son Dieu."}, {"numero": 6, "texto": "Nebucadnetsar, roi de Babylone, monta contre lui, et le lia avec des chaînes d''''airain pour le conduire à Babylone."}, {"numero": 7, "texto": "Nebucadnetsar emporta à Babylone des ustensiles de la maison de l''''Eternel, et il les mit dans son palais à Babylone."}, {"numero": 8, "texto": "Le reste des actions de Jojakim, les abominations qu''''il commit, et ce qui se trouvait en lui, cela est écrit dans le livre des rois d''''Israël et de Juda. Et Jojakin, son fils, régna à sa place."}, {"numero": 9, "texto": "Jojakin avait huit ans lorsqu''''il devint roi, et il régna trois mois et dix jours à Jérusalem. Il fit ce qui est mal aux yeux de l''''Eternel."}, {"numero": 10, "texto": "L''''année suivante, le roi Nebucadnetsar le fit emmener à Babylone avec les ustensiles précieux de la maison de l''''Eternel. Et il établit roi sur Juda et sur Jérusalem Sédécias, frère de Jojakin."}, {"numero": 11, "texto": "Sédécias avait vingt et un ans lorsqu''''il devint roi, et il régna onze ans à Jérusalem."}, {"numero": 12, "texto": "Il fit ce qui est mal aux yeux de l''''Eternel, son Dieu; et il ne s''''humilia point devant Jérémie, le prophète, qui lui parlait de la part de l''''Eternel."}, {"numero": 13, "texto": "Il se révolta même contre le roi Nebucadnetsar, qui l''''avait fait jurer par le nom de Dieu; et il raidit son cou et endurcit son coeur, au point de ne pas retourner à l''''Eternel, le Dieu d''''Israël."}, {"numero": 14, "texto": "Tous les chefs des sacrificateurs et le peuple multiplièrent aussi les transgressions, selon toutes les abominations des nations; et ils profanèrent la maison de l''''Eternel, qu''''il avait sanctifiée à Jérusalem."}, {"numero": 15, "texto": "L''''Eternel, le Dieu de leurs pères, donna de bonne heure à ses envoyés la mission de les avertir, car il voulait épargner son peuple et sa propre demeure."}, {"numero": 16, "texto": "Mais ils se moquèrent des envoyés de Dieu, ils méprisèrent ses paroles, et ils se raillèrent de ses prophètes, jusqu''''à ce que la colère de l''''Eternel contre son peuple devînt sans remède."}, {"numero": 17, "texto": "Alors l''''Eternel fit monter contre eux le roi des Chaldéens, et tua par l''''épée leurs jeunes gens dans la maison de leur sanctuaire; il n''''épargna ni le jeune homme, ni la jeune fille, ni le vieillard, ni l''''homme aux cheveux blancs, il livra tout entre ses mains."}, {"numero": 18, "texto": "Nebucadnetsar emporta à Babylone tous les ustensiles de la maison de Dieu, grands et petits, les trésors de la maison de l''''Eternel, et les trésors du roi et de ses chefs."}, {"numero": 19, "texto": "Ils brûlèrent la maison de Dieu, ils démolirent les murailles de Jérusalem, ils livrèrent au feu tous ses palais et détruisirent tous les objets précieux."}, {"numero": 20, "texto": "Nebucadnetsar emmena captifs à Babylone ceux qui échappèrent à l''''épée; et ils lui furent assujettis, à lui et à ses fils, jusqu''''à la domination du royaume de Perse,"}, {"numero": 21, "texto": "afin que s''''accomplît la parole de l''''Eternel prononcée par la bouche de Jérémie; jusqu''''à ce que le pays eût joui de ses sabbats, il se reposa tout le temps qu''''il fut dévasté, jusqu''''à l''''accomplissement de soixante-dix ans."}, {"numero": 22, "texto": "La première année de Cyrus, roi de Perse, afin que s''''accomplît la parole de l''''Eternel prononcée par la bouche de Jérémie, l''''Eternel réveilla l''''esprit de Cyrus, roi de Perse, qui fit faire de vive voix et par écrit cette publication dans tout son royaume:"}, {"numero": 23, "texto": "Ainsi parle Cyrus, roi de Perse: L''''Eternel, le Dieu des cieux, m''''a donné tous les royaumes de la terre, et il m''''a commandé de lui bâtir une maison à Jérusalem en Juda. Qui d''''entre vous est de son peuple? Que l''''Eternel, son Dieu, soit avec lui, et qu''''il monte!"}]'::jsonb, 'Louis Segond 1910'),
  ('2Cr', 36, 'es', '[{"numero": 1, "texto": "ENTONCES el pueblo de la tierra tomó á Joachâz hijo de Josías, é hiciéronle rey en lugar de su padre en Jerusalem."}, {"numero": 2, "texto": "De veinte y tres años era Joachâz cuando comenzó á reinar, y tres meses reinó en Jerusalem."}, {"numero": 3, "texto": "Y el rey de Egipto lo quitó de Jerusalem, y condenó la tierra en cien talentos de plata y uno de oro."}, {"numero": 4, "texto": "Y constituyó el rey de Egipto á su hermano Eliacim por rey sobre Judá y Jerusalem, y mudóle el nombre en Joacim; y á Joachâz su hermano tomó Nechâo, y llevólo á Egipto."}, {"numero": 5, "texto": "Cuando comenzó á reinar Joacim era de veinte y cinco años, y reinó once años en Jerusalem: é hizo lo malo en ojos de Jehová su Dios."}, {"numero": 6, "texto": "Y subió contra él Nabucodonosor rey de Babilonia, y atado con cadenas lo llevó á Babilonia."}, {"numero": 7, "texto": "También llevó Nabucodonosor á Babilonia de los vasos de la casa de Jehová, y púsolos en su templo en Babilonia."}, {"numero": 8, "texto": "Lo demás de los hechos de Joacim, y las abominaciones que hizo, y lo que en él se halló, he aquí está escrito en el libro de los reyes de Israel y de Judá: y reinó en su lugar Joachîn su hijo."}, {"numero": 9, "texto": "De ocho años era Joachîn cuando comenzó á reinar, y reinó tres meses y diez días en Jerusalem: é hizo lo malo en ojos de Jehová."}, {"numero": 10, "texto": "A la vuelta del año el rey Nabucodonosor envió, é hízolo llevar á Babilonia juntamente con los vasos preciosos de la casa de Jehová; y constituyó á Sedecías su hermano por rey sobre Judá y Jerusalem."}, {"numero": 11, "texto": "De veinte y un años era Sedecías cuando comenzó á reinar, y once años reinó en Jerusalem."}, {"numero": 12, "texto": "E hizo lo malo en ojos de Jehová su Dios, y no se humilló delante de Jeremías profeta, que le hablaba de parte de Jehová."}, {"numero": 13, "texto": "Rebelóse asimismo contra Nabucodonosor, al cual había jurado por Dios; y endureció su cerviz, y obstinó su corazón, para no volverse á Jehová el Dios de Israel."}, {"numero": 14, "texto": "Y también todos los príncipes de los sacerdotes, y el pueblo, aumentaron la prevaricación, siguiendo todas las abominaciones de las gentes, y contaminando la casa de Jehová, la cual él había santificado en Jerusalem."}, {"numero": 15, "texto": "Y Jehová el Dios de sus padres envió á ellos por mano de sus mensajeros, levantándose de mañana y enviando: porque él tenía misericordia de su pueblo, y de su habitación."}, {"numero": 16, "texto": "Mas ellos hacían escarnio de los mensajeros de Dios, y menospreciaban sus palabras, burlándose de sus profetas, hasta que subió el furor de Jehová contra su pueblo, y que no hubo remedio."}, {"numero": 17, "texto": "Por lo cual trajo contra ellos al rey de los Caldeos, que mató á cuchillo sus mancebos en la casa de su santuario, sin perdonar joven, ni doncella, ni viejo, ni decrépito; todos los entregó en sus manos."}, {"numero": 18, "texto": "Asimismo todos los vasos de la casa de Dios, grandes y chicos, los tesoros de la casa de Jehová, y los tesoros del rey y de sus príncipes, todo lo llevó á Babilonia."}, {"numero": 19, "texto": "Y quemaron la casa de Dios, y rompieron el muro de Jerusalem, y consumieron al fuego todos sus palacios, y destruyeron todos sus vasos deseables."}, {"numero": 20, "texto": "Los que quedaron del cuchillo, pasáronlos á Babilonia; y fueron siervos de él y de sus hijos, hasta que vino el reino de los Persas;"}, {"numero": 21, "texto": "Para que se cumpliese la palabra de Jehová por la boca de Jeremías, hasta que la tierra hubo gozado sus sábados: porque todo el tiempo de su asolamiento reposó, hasta que los setenta años fueron cumplidos."}, {"numero": 22, "texto": "Mas al primer año de Ciro rey de los Persas, para que se cumpliese la palabra de Jehová por boca de Jeremías, Jehová excitó el espíritu de Ciro rey de los Persas, el cual hizo pasar pregón por todo su reino, y también por escrito, diciendo:"}, {"numero": 23, "texto": "Así dice Ciro rey de los Persas: Jehová, el Dios de los cielos, me ha dado todos los reinos de la tierra; y él me ha encargado que le edifique casa en Jerusalem, que es en Judá. ¿Quién de vosotros hay de todo su pueblo? Jehová su Dios sea con él, y suba."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 1, 'pt', '[{"numero": 1, "texto": "Depois da morte de Acabe, Moabe rebelou-se contra Israel."}, {"numero": 2, "texto": "E Acazias caiu pela sacada de uma sala da casa que tinha em Samaria; e estando enfermo enviou mensageiros, e disse-lhes: Ide, e consultai a Baal-Zebube deus de Ecrom, se sararei desta minha enfermidade."}, {"numero": 3, "texto": "Então o anjo do SENHOR falou a Elias Tisbita, dizendo: Levanta-te, e sobe a encontrar-te com os mensageiros do rei de Samaria, e lhes dirás: Acaso não há Deus em Israel, para que vades a consultar Baal-Zebube, deus de Ecrom?"}, {"numero": 4, "texto": "Portanto assim disse o SENHOR: Do leito em que subiste não descerás, antes certamente morrerás. E Elias se foi."}, {"numero": 5, "texto": "E quando os mensageiros voltaram ao rei, ele lhes disse: Por que, pois, voltastes?"}, {"numero": 6, "texto": "E eles lhe responderam: Encontramos um homem que nos disse: Ide, e voltai ao rei que vos enviou, e dizei-lhe: Assim disse o SENHOR: Acaso não há Deus em Israel, para que tu envias a consultar Baal-Zebube, deus de Ecrom? Portanto, do leito em que subiste não descerás, antes certamente morrerás."}, {"numero": 7, "texto": "Então ele lhes disse: Qual era a roupa daquele homem que encontrastes, e que vos disse tais palavras?"}, {"numero": 8, "texto": "E eles lhe responderam: Um homem vestido de pelos, e cingia seus lombos com um cinto de couro. Então ele disse: É Elias, o tisbita."}, {"numero": 9, "texto": "E enviou logo a ele um capitão de cinquenta com seus cinquenta, o qual subiu a ele; e eis que ele estava sentado no cume do monte. E ele lhe disse: Homem de Deus, o rei disse que desças."}, {"numero": 10, "texto": "E Elias respondeu, e disse ao capitão de cinquenta: Se eu sou homem de Deus, desça fogo do céu, e consuma-te com teus cinquenta. E desceu fogo do céu, que o consumiu a ele e a seus cinquenta."}, {"numero": 11, "texto": "Voltou o rei a enviar a ele outro capitão de cinquenta com seus cinquenta; e falou-lhe, e disse: Homem de Deus, o rei disse assim: Desce logo."}, {"numero": 12, "texto": "E respondeu-lhe Elias, e disse: Se eu sou homem de Deus, desça fogo do céu, e consuma-te com teus cinquenta. E desceu fogo do céu, que o consumiu a ele e a seus cinquenta."}, {"numero": 13, "texto": "E voltou a enviar o terceiro capitão de cinquenta com seus cinquenta; e subindo aquele terceiro capitão de cinquenta, ficou de joelhos diante de Elias, e rogou-lhe, dizendo: Homem de Deus, rogo-te que diante dos teus olhos seja preciosa minha vida e a vida destes teus cinquenta servos."}, {"numero": 14, "texto": "Eis que desceu fogo do céu, e consumiu os dois primeiros capitães de cinquenta, com seus cinquenta; seja agora minha vida preciosa diante de teus olhos."}, {"numero": 15, "texto": "Então o anjo do SENHOR disse a Elias: Desce com ele; não tenhas dele medo. E ele se levantou, e desceu com ele ao rei."}, {"numero": 16, "texto": "E disse-lhe: Assim disse o SENHOR: Por que enviaste mensageiros a consultar Baal-Zebube, deus de Ecrom? Acaso não há Deus em Israel para consultar a sua palavra? Não descerás, portanto, do leito em que subiste, antes certamente morrerás."}, {"numero": 17, "texto": "E morreu conforme à palavra do SENHOR que Elias havia falado; e reinou em seu lugar Jorão, no segundo ano de Jeorão, filho de Josafá rei de Judá; porque Acazias não tinha filho."}, {"numero": 18, "texto": "E os demais dos feitos de Acazias, não estão escrito no livro das crônicas dos reis de Israel?"}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 1, 'en', '[{"numero": 1, "texto": "Then Moab rebelled against Israel after the death of Ahab."}, {"numero": 2, "texto": "And Ahaziah fell down through a lattice in his upper chamber that was in Samaria, and was sick: and he sent messengers, and said unto them, Go, enquire of Baalzebub the god of Ekron whether I shall recover of this disease."}, {"numero": 3, "texto": "But the angel of the Lord said to Elijah the Tishbite, Arise, go up to meet the messengers of the king of Samaria, and say unto them, Is it not because there is not a God in Israel, that ye go to enquire of Baalzebub the god of Ekron?"}, {"numero": 4, "texto": "Now therefore thus saith the Lord, Thou shalt not come down from that bed on which thou art gone up, but shalt surely die. And Elijah departed."}, {"numero": 5, "texto": "And when the messengers turned back unto him, he said unto them, Why are ye now turned back?"}, {"numero": 6, "texto": "And they said unto him, There came a man up to meet us, and said unto us, Go, turn again unto the king that sent you, and say unto him, Thus saith the Lord, Is it not because there is not a God in Israel, that thou sendest to enquire of Baalzebub the god of Ekron? therefore thou shalt not come down from that bed on which thou art gone up, but shalt surely die."}, {"numero": 7, "texto": "And he said unto them, What manner of man was he which came up to meet you, and told you these words?"}, {"numero": 8, "texto": "And they answered him, He was an hairy man, and girt with a girdle of leather about his loins. And he said, It is Elijah the Tishbite."}, {"numero": 9, "texto": "Then the king sent unto him a captain of fifty with his fifty. And he went up to him: and, behold, he sat on the top of an hill. And he spake unto him, Thou man of God, the king hath said, Come down."}, {"numero": 10, "texto": "And Elijah answered and said to the captain of fifty, If I be a man of God, then let fire come down from heaven, and consume thee and thy fifty. And there came down fire from heaven, and consumed him and his fifty."}, {"numero": 11, "texto": "Again also he sent unto him another captain of fifty with his fifty. And he answered and said unto him, O man of God, thus hath the king said, Come down quickly."}, {"numero": 12, "texto": "And Elijah answered and said unto them, If I be a man of God, let fire come down from heaven, and consume thee and thy fifty. And the fire of God came down from heaven, and consumed him and his fifty."}, {"numero": 13, "texto": "And he sent again a captain of the third fifty with his fifty. And the third captain of fifty went up, and came and fell on his knees before Elijah, and besought him, and said unto him, O man of God, I pray thee, let my life, and the life of these fifty thy servants, be precious in thy sight."}, {"numero": 14, "texto": "Behold, there came fire down from heaven, and burnt up the two captains of the former fifties with their fifties: therefore let my life now be precious in thy sight."}, {"numero": 15, "texto": "And the angel of the Lord said unto Elijah, Go down with him: be not afraid of him. And he arose, and went down with him unto the king."}, {"numero": 16, "texto": "And he said unto him, Thus saith the Lord, Forasmuch as thou hast sent messengers to enquire of Baalzebub the god of Ekron, is it not because there is no God in Israel to enquire of his word? therefore thou shalt not come down off that bed on which thou art gone up, but shalt surely die."}, {"numero": 17, "texto": "So he died according to the word of the Lord which Elijah had spoken. And Jehoram reigned in his stead in the second year of Jehoram the son of Jehoshaphat king of Judah; because he had no son."}, {"numero": 18, "texto": "Now the rest of the acts of Ahaziah which he did, are they not written in the book of the chronicles of the kings of Israel?"}]'::jsonb, 'King James Version'),
  ('2Rs', 1, 'fr', '[{"numero": 1, "texto": "Moab se révolta contre Israël, après la mort d''''Achab."}, {"numero": 2, "texto": "Or Achazia tomba par le treillis de sa chambre haute à Samarie, et il en fut malade. Il fit partir des messagers, et leur dit: Allez, consultez Baal-Zebub, dieu d''''Ekron, pour savoir si je guérirai de cette maladie."}, {"numero": 3, "texto": "Mais l''''ange de l''''Eternel dit à Elie, le Thischbite: Lève-toi, monte à la rencontre des messagers du roi de Samarie, et dis-leur: Est-ce parce qu''''il n''''y a point de Dieu en Israël que vous allez consulter Baal-Zebub, dieu d''''Ekron?"}, {"numero": 4, "texto": "C''''est pourquoi ainsi parle l''''Eternel: Tu ne descendras pas du lit sur lequel tu es monté, car tu mourras. Et Elie s''''en alla."}, {"numero": 5, "texto": "Les messagers retournèrent auprès d''''Achazia. Et il leur dit: Pourquoi revenez-vous?"}, {"numero": 6, "texto": "Ils lui répondirent: Un homme est monté à notre rencontre, et nous a dit: Allez, retournez vers le roi qui vous a envoyés, et dites-lui: Ainsi parle l''''Eternel: Est-ce parce qu''''il n''''y a point de Dieu en Israël que tu envoies consulter Baal-Zebub, dieu d''''Ekron? C''''est pourquoi tu ne descendras pas du lit sur lequel tu es monté, car tu mourras."}, {"numero": 7, "texto": "Achazia leur dit: Quel air avait l''''homme qui est monté à votre rencontre et qui vous a dit ces paroles?"}, {"numero": 8, "texto": "Ils lui répondirent: C''''était un homme vêtu de poil et ayant une ceinture de cuir autour des reins. Et Achazia dit: C''''est Elie, le Thischbite."}, {"numero": 9, "texto": "Il envoya vers lui un chef de cinquante avec ses cinquante hommes. Ce chef monta auprès d''''Elie, qui était assis sur le sommet de la montagne, et il lui dit: Homme de Dieu, le roi a dit: Descends!"}, {"numero": 10, "texto": "Elie répondit au chef de cinquante: Si je suis un homme de Dieu, que le feu descende du ciel et te consume, toi et tes cinquante hommes! Et le feu descendit du ciel et le consuma, lui et ses cinquante hommes."}, {"numero": 11, "texto": "Achazia envoya de nouveau vers lui un autre chef de cinquante avec ses cinquante hommes. Ce chef prit la parole et dit à Elie: Homme de Dieu, ainsi a dit le roi: Hâte-toi de descendre!"}, {"numero": 12, "texto": "Elie leur répondit: Si je suis un homme de Dieu, que le feu descende du ciel et te consume, toi et tes cinquante hommes! Et le feu de Dieu descendit du ciel et le consuma, lui et ses cinquante hommes."}, {"numero": 13, "texto": "Achazia envoya de nouveau un troisième chef de cinquante avec ses cinquante hommes. Ce troisième chef de cinquante monta; et à son arrivée, il fléchit les genoux devant Elie, et lui dit en suppliant: Homme de Dieu, que ma vie, je te prie, et que la vie de ces cinquante hommes tes serviteurs soit précieuse à tes yeux!"}, {"numero": 14, "texto": "Voici, le feu est descendu du ciel et a consumé les deux premiers chefs de cinquante et leurs cinquante hommes: mais maintenant, que ma vie soit précieuse à tes yeux!"}, {"numero": 15, "texto": "L''''ange de l''''Eternel dit à Elie: Descends avec lui, n''''aie aucune crainte de lui. Elie se leva et descendit avec lui vers le roi."}, {"numero": 16, "texto": "Il lui dit: Ainsi parle l''''Eternel: Parce que tu as envoyé des messagers pour consulter Baal-Zebub, dieu d''''Ekron, comme s''''il n''''y avait en Israël point de Dieu dont on puisse consulter la parole, tu ne descendras pas du lit sur lequel tu es monté, car tu mourras."}, {"numero": 17, "texto": "Achazia mourut, selon la parole de l''''Eternel prononcée par Elie. Et Joram régna à sa place, la seconde année de Joram, fils de Josaphat, roi de Juda; car il n''''avait point de fils."}, {"numero": 18, "texto": "Le reste des actions d''''Achazia, et ce qu''''il a fait, cela n''''est-il pas écrit dans le livre des Chroniques des rois d''''Israël?"}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 1, 'es', '[{"numero": 1, "texto": "DESPUÉS de la muerte de Achâb rebelóse Moab contra Israel."}, {"numero": 2, "texto": "Y Ochôzías cayó por las celosías de una sala de la casa que tenía en Samaria; y estando enfermo envió mensajeros, y díjoles: Id, y consultad á Baal-zebub dios de Ecrón, si tengo de sanar de esta mi enfermedad."}, {"numero": 3, "texto": "Entonces el ángel de Jehová habló á Elías Thisbita, diciendo: Levántate, y sube á encontrarte con los mensajeros del rey de Samaria, y les dirás: ¿No hay Dios en Israel, que vosotros vais á consultar á Baal-zebub dios de Ecrón?"}, {"numero": 4, "texto": "Por tanto así ha dicho Jehová: Del lecho en que subiste no descenderás, antes morirás ciertamente. Y Elías se fué."}, {"numero": 5, "texto": "Y como los mensajeros se volvieron al rey, él les dijo: ¿Por qué pues os habéis vuelto?"}, {"numero": 6, "texto": "Y ellos le respondieron: Encontramos un varón que nos dijo: Id, y volveos al rey que os envió, y decidle: Así ha dicho Jehová: ¿No hay Dios en Israel, que tú envías á consultar á Baal-zebub dios de Ecrón? Por tanto, del lecho en que subiste no descenderás, antes morirás de cierto."}, {"numero": 7, "texto": "Entonces él les dijo: ¿Qué hábito era el de aquel varón que encontrasteis, y os dijo tales palabras?"}, {"numero": 8, "texto": "Y ellos le respondieron: Un varón velloso, y ceñía sus lomos con un cinto de cuero. Entonces él dijo: Elías Thisbita es."}, {"numero": 9, "texto": "Y envió luego á él un capitán de cincuenta con sus cincuenta, el cual subió á él; y he aquí que él estaba sentado en la cumbre del monte. Y él le dijo: Varón de Dios, el rey ha dicho que desciendas."}, {"numero": 10, "texto": "Y Elías respondió, y dijo al capitán de cincuenta: Si yo soy varón de Dios, descienda fuego del cielo, y consúmate con tus cincuenta. Y descendió fuego del cielo, que lo consumió á él y á sus cincuenta."}, {"numero": 11, "texto": "Volvió el rey á enviar á él otro capitán de cincuenta con sus cincuenta; y hablóle, y dijo: Varón de Dios, el rey ha dicho así: Desciende presto."}, {"numero": 12, "texto": "Y respondióle Elías, y dijo: Si yo soy varón de Dios, descienda fuego del cielo, y consúmate con tus cincuenta. Y descendió fuego del cielo, que lo consumió á él y á sus cincuenta."}, {"numero": 13, "texto": "Y volvió á enviar el tercer capitán de cincuenta con sus cincuenta: y subiendo aquel tercer capitán de cincuenta, hincóse de rodillas delante de Elías, y rogóle, diciendo: Varón de Dios, ruégote que sea de valor delante de tus ojos mi vida, y la vida de estos tus cincuenta siervos."}, {"numero": 14, "texto": "He aquí ha descendido fuego del cielo, y ha consumido los dos primeros capitanes de cincuenta, con sus cincuenta; sea ahora mi vida de valor delante de tus ojos."}, {"numero": 15, "texto": "Entonces el ángel de Jehová dijo á Elías: Desciende con él; no hayas de él miedo. Y él se levantó, y descendió con él al rey."}, {"numero": 16, "texto": "Y díjole: Así ha dicho Jehová: Pues que enviaste mensajeros á consultar á Baal-zebub dios de Ecrón, ¿no hay Dios en Israel para consultar en su palabra? No descenderás, por tanto, del lecho en que subiste, antes morirás de cierto."}, {"numero": 17, "texto": "Y murió conforme á la palabra de Jehová que había hablado Elías: y reinó en su lugar Joram, en el segundo año de Joram, hijo de Josaphat rey de Judá; porque Ochôzías no tenía hijo."}, {"numero": 18, "texto": "Y lo demás de los hechos de Ochôzías, ¿no está escrito en el libro de las crónicas de los reyes de Israel?"}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 2, 'pt', '[{"numero": 1, "texto": "E aconteceu que, quando o SENHOR quis erguer Elias num turbilhão ao céu, Elias vinha com Eliseu de Gilgal."}, {"numero": 2, "texto": "E disse Elias a Eliseu: Fica-te agora aqui, porque o SENHOR me enviou a Betel. E Eliseu disse: Vive o SENHOR, e vive tua alma, que não te deixarei. Desceram pois a Betel."}, {"numero": 3, "texto": "E saindo a Eliseu os filhos dos profetas que estavam em Betel, disseram-lhe: Sabes como o SENHOR tirará hoje o teu senhor de tua cabeça? E ele disse: Sim, eu o sei; calai."}, {"numero": 4, "texto": "E Elias lhe voltou a dizer: Eliseu, fica-te aqui agora, porque o SENHOR me enviou a Jericó. E ele disse: Vive o SENHOR, e vive tua alma, que não te deixarei. Vieram, pois, a Jericó."}, {"numero": 5, "texto": "E achegaram-se a Eliseu os filhos dos profetas que estavam em Jericó, e disseram-lhe: Sabes como o SENHOR tirará hoje o teu senhor de tua cabeça? E ele respondeu: Sim, eu o sei; calai."}, {"numero": 6, "texto": "E Elias lhe disse: Rogo-te que te fiques aqui, porque o SENHOR me enviou ao Jordão. E ele disse: Vive o SENHOR, e vive tua alma, que não te deixarei. Foram, pois, ambos."}, {"numero": 7, "texto": "E vieram cinquenta homens dos filhos dos profetas, e pararam-se em frente a o longe: e eles dois se pararam junto ao Jordão."}, {"numero": 8, "texto": "Tomando então Elias seu manto, dobrou-o, e feriu as águas, as quais se apartaram a um e a outro lado, e passaram ambos em seco."}, {"numero": 9, "texto": "E quando houveram passado, Elias disse a Eliseu: Pede o que queres que faça por ti, antes que seja tirado de contigo. E disse Eliseu: Rogo-te que a porção dobrada de teu espírito seja sobre mim."}, {"numero": 10, "texto": "E ele lhe disse: Coisa difícil pediste. Se me vires quando for tirado de ti, te será assim feito; mas se não, não."}, {"numero": 11, "texto": "E aconteceu que, indo eles falando, eis que um carro de fogo com cavalos de fogo separou os dois; e Elias subiu ao céu num turbilhão."}, {"numero": 12, "texto": "E vendo-o Eliseu, clamava: Meu pai, meu pai! Carro de Israel e seus cavaleiros! E nunca mais lhe viu, e segurando de suas roupas, rompeu-os em duas partes."}, {"numero": 13, "texto": "Levantou logo o manto de Elias que se lhe havia caído, e voltou, e parou-se à beira do Jordão."}, {"numero": 14, "texto": "E tomando o manto de Elias que se lhe havia caído, feriu as águas, e disse: Onde está o SENHOR, o Deus de Elias? E assim que houve do mesmo modo ferido as águas, apartaram-se a um e a outro lado, e passou Eliseu."}, {"numero": 15, "texto": "E vendo-lhe os filhos dos profetas que estavam em Jericó da outra parte, disseram: O espírito de Elias repousou sobre Eliseu. E vieram-lhe a receber, e inclinaram-se a ele até a terra."}, {"numero": 16, "texto": "E disseram-lhe: Eis que há com teus servos cinquenta homens fortes; vão agora e busquem o teu senhor; talvez o Espírito do SENHOR o levantou, e o lançou em algum monte ou em algum vale. E ele lhes disse: Não envieis."}, {"numero": 17, "texto": "Mas eles lhe importunaram, até que envergonhando-se, disse: Enviai. Então eles enviaram cinquenta homens, os quais o buscaram três dias, mas não o acharam."}, {"numero": 18, "texto": "E quando voltaram a ele, que se havia restado em Jericó, ele lhes disse: Não vos disse eu que não fôsseis?"}, {"numero": 19, "texto": "E os homens da cidade disseram a Eliseu: Eis que o assento desta cidade é bom, como meu senhor vai; mas as águas são más, e a terra enferma."}, {"numero": 20, "texto": "Então ele disse: Trazei-me uma botija nova, e ponde nela sal. E trouxeram-na."}, {"numero": 21, "texto": "E saindo ele aos mananciais das águas, lançou dentro o sal, e disse: Assim disse o SENHOR: Eu sarei estas águas, e não haverá mais nelas morte nem enfermidade."}, {"numero": 22, "texto": "E foram saradas as águas até hoje, conforme a palavra que falou Eliseu."}, {"numero": 23, "texto": "Depois subiu dali a Betel; e subindo pelo caminho, saíram os meninos da cidade, e se ridicularizavam dele, dizendo: Sobe, calvo! Sobe, calvo!"}, {"numero": 24, "texto": "E olhando ele atrás, viu-os, e amaldiçoou-os no nome do SENHOR. E duas ursas saíram da floresta, e despedaçaram deles quarenta e dois meninos."}, {"numero": 25, "texto": "De ali foi ao monte de Carmelo, e dali voltou a Samaria."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 2, 'en', '[{"numero": 1, "texto": "And it came to pass, when the Lord would take up Elijah into heaven by a whirlwind, that Elijah went with Elisha from Gilgal."}, {"numero": 2, "texto": "And Elijah said unto Elisha, Tarry here, I pray thee; for the Lord hath sent me to Bethel. And Elisha said unto him, As the Lord liveth, and as thy soul liveth, I will not leave thee. So they went down to Bethel."}, {"numero": 3, "texto": "And the sons of the prophets that were at Bethel came forth to Elisha, and said unto him, Knowest thou that the Lord will take away thy master from thy head to day? And he said, Yea, I know it; hold ye your peace."}, {"numero": 4, "texto": "And Elijah said unto him, Elisha, tarry here, I pray thee; for the Lord hath sent me to Jericho. And he said, As the Lord liveth, and as thy soul liveth, I will not leave thee. So they came to Jericho."}, {"numero": 5, "texto": "And the sons of the prophets that were at Jericho came to Elisha, and said unto him, Knowest thou that the Lord will take away thy master from thy head to day? And he answered, Yea, I know it; hold ye your peace."}, {"numero": 6, "texto": "And Elijah said unto him, Tarry, I pray thee, here; for the Lord hath sent me to Jordan. And he said, As the Lord liveth, and as thy soul liveth, I will not leave thee. And they two went on."}, {"numero": 7, "texto": "And fifty men of the sons of the prophets went, and stood to view afar off: and they two stood by Jordan."}, {"numero": 8, "texto": "And Elijah took his mantle, and wrapped it together, and smote the waters, and they were divided hither and thither, so that they two went over on dry ground."}, {"numero": 9, "texto": "And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me."}, {"numero": 10, "texto": "And he said, Thou hast asked a hard thing: nevertheless, if thou see me when I am taken from thee, it shall be so unto thee; but if not, it shall not be so."}, {"numero": 11, "texto": "And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven."}, {"numero": 12, "texto": "And Elisha saw it, and he cried, My father, my father, the chariot of Israel, and the horsemen thereof. And he saw him no more: and he took hold of his own clothes, and rent them in two pieces."}, {"numero": 13, "texto": "He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of Jordan;"}, {"numero": 14, "texto": "And he took the mantle of Elijah that fell from him, and smote the waters, and said, Where is the Lord God of Elijah? and when he also had smitten the waters, they parted hither and thither: and Elisha went over."}, {"numero": 15, "texto": "And when the sons of the prophets which were to view at Jericho saw him, they said, The spirit of Elijah doth rest on Elisha. And they came to meet him, and bowed themselves to the ground before him."}, {"numero": 16, "texto": "And they said unto him, Behold now, there be with thy servants fifty strong men; let them go, we pray thee, and seek thy master: lest peradventure the Spirit of the Lord hath taken him up, and cast him upon some mountain, or into some valley. And he said, Ye shall not send."}, {"numero": 17, "texto": "And when they urged him till he was ashamed, he said, Send. They sent therefore fifty men; and they sought three days, but found him not."}, {"numero": 18, "texto": "And when they came again to him, (for he tarried at Jericho,) he said unto them, Did I not say unto you, Go not?"}, {"numero": 19, "texto": "And the men of the city said unto Elisha, Behold, I pray thee, the situation of this city is pleasant, as my lord seeth: but the water is naught, and the ground barren."}, {"numero": 20, "texto": "And he said, Bring me a new cruse, and put salt therein. And they brought it to him."}, {"numero": 21, "texto": "And he went forth unto the spring of the waters, and cast the salt in there, and said, Thus saith the Lord, I have healed these waters; there shall not be from thence any more death or barren land."}, {"numero": 22, "texto": "So the waters were healed unto this day, according to the saying of Elisha which he spake."}, {"numero": 23, "texto": "And he went up from thence unto Bethel: and as he was going up by the way, there came forth little children out of the city, and mocked him, and said unto him, Go up, thou bald head; go up, thou bald head."}, {"numero": 24, "texto": "And he turned back, and looked on them, and cursed them in the name of the Lord. And there came forth two she bears out of the wood, and tare forty and two children of them."}, {"numero": 25, "texto": "And he went from thence to mount Carmel, and from thence he returned to Samaria."}]'::jsonb, 'King James Version'),
  ('2Rs', 2, 'fr', '[{"numero": 1, "texto": "Lorsque l''''Eternel fit monter Elie au ciel dans un tourbillon, Elie partait de Guilgal avec Elisée."}, {"numero": 2, "texto": "Elie dit à Elisée: Reste ici, je te prie, car l''''Eternel m''''envoie jusqu''''à Béthel. Elisée répondit: L''''Eternel est vivant et ton âme est vivante! je ne te quitterai point. Et ils descendirent à Béthel."}, {"numero": 3, "texto": "Les fils des prophètes qui étaient à Béthel sortirent vers Elisée, et lui dirent: Sais-tu que l''''Eternel enlève aujourd''''hui ton maître au-dessus de ta tête? Et il répondit: Je le sais aussi; taisez-vous."}, {"numero": 4, "texto": "Elie lui dit: Elisée, reste ici, je te prie, car l''''Eternel m''''envoie à Jéricho. Il répondit: L''''Eternel est vivant et ton âme est vivante! je ne te quitterai point. Et ils arrivèrent à Jéricho."}, {"numero": 5, "texto": "Les fils des prophètes qui étaient à Jéricho s''''approchèrent d''''Elisée, et lui dirent: Sais-tu que l''''Eternel enlève aujourd''''hui ton maître au-dessus de ta tête? Et il répondit: Je le sais aussi; taisez-vous."}, {"numero": 6, "texto": "Elie lui dit: Reste ici, je te prie, car l''''Eternel m''''envoie au Jourdain. Il répondit: L''''Eternel est vivant et ton âme est vivante! je ne te quitterai point. Et ils poursuivirent tous deux leur chemin."}, {"numero": 7, "texto": "Cinquante hommes d''''entre les fils des prophètes arrivèrent et s''''arrêtèrent à distance vis-à-vis, et eux deux s''''arrêtèrent au bord du Jourdain."}, {"numero": 8, "texto": "Alors Elie prit son manteau, le roula, et en frappa les eaux, qui se partagèrent çà et là, et ils passèrent tous deux à sec."}, {"numero": 9, "texto": "Lorsqu''''ils eurent passé, Elie dit à Elisée: Demande ce que tu veux que je fasse pour toi, avant que je sois enlevé d''''avec toi. Elisée répondit: Qu''''il y ait sur moi, je te prie, une double portion de ton esprit!"}, {"numero": 10, "texto": "Elie dit: Tu demandes une chose difficile. Mais si tu me vois pendant que je serai enlevé d''''avec toi, cela t''''arrivera ainsi; sinon, cela n''''arrivera pas."}, {"numero": 11, "texto": "Comme ils continuaient à marcher en parlant, voici, un char de feu et des chevaux de feu les séparèrent l''''un de l''''autre, et Elie monta au ciel dans un tourbillon."}, {"numero": 12, "texto": "Elisée regardait et criait: Mon père! mon père! Char d''''Israël et sa cavalerie! Et il ne le vit plus. Saisissant alors ses vêtements, il les déchira en deux morceaux,"}, {"numero": 13, "texto": "et il releva le manteau qu''''Elie avait laissé tomber. Puis il retourna, et s''''arrêta au bord du Jourdain;"}, {"numero": 14, "texto": "il prit le manteau qu''''Elie avait laissé tomber, et il en frappa les eaux, et dit: Où est l''''Eternel, le Dieu d''''Elie? Lui aussi, il frappa les eaux, qui se partagèrent çà et là, et Elisée passa."}, {"numero": 15, "texto": "Les fils des prophètes qui étaient à Jéricho, vis-à-vis, l''''ayant vu, dirent: L''''esprit d''''Elie repose sur Elisée! Et ils allèrent à sa rencontre, et se prosternèrent contre terre devant lui."}, {"numero": 16, "texto": "Ils lui dirent: Voici, il y a parmi tes serviteurs cinquante hommes vaillants; veux-tu qu''''ils aillent chercher ton maître? Peut-être que l''''esprit de l''''Eternel l''''a emporté et l''''a jeté sur quelque montagne ou dans quelque vallée. Il répondit: Ne les envoyez pas."}, {"numero": 17, "texto": "Mais ils le pressèrent longtemps; et il dit: Envoyez-les. Ils envoyèrent les cinquante hommes, qui cherchèrent Elie pendant trois jours et ne le trouvèrent point."}, {"numero": 18, "texto": "Lorsqu''''ils furent de retour auprès d''''Elisée, qui était à Jéricho, il leur dit: Ne vous avais-je pas dit: N''''allez pas?"}, {"numero": 19, "texto": "Les gens de la ville dirent à Elisée: Voici, le séjour de la ville est bon, comme le voit mon seigneur; mais les eaux sont mauvaises, et le pays est stérile."}, {"numero": 20, "texto": "Il dit: Apportez-moi un plat neuf, et mettez-y du sel. Et ils le lui apportèrent."}, {"numero": 21, "texto": "Il alla vers la source des eaux, et il y jeta du sel, et dit: Ainsi parle l''''Eternel: J''''assainis ces eaux; il n''''en proviendra plus ni mort, ni stérilité."}, {"numero": 22, "texto": "Et les eaux furent assainies, jusqu''''à ce jour, selon la parole qu''''Elisée avait prononcée."}, {"numero": 23, "texto": "Il monta de là à Béthel; et comme il cheminait à la montée, des petits garçons sortirent de la ville, et se moquèrent de lui. Ils lui disaient: Monte, chauve! monte, chauve!"}, {"numero": 24, "texto": "Il se retourna pour les regarder, et il les maudit au nom de l''''Eternel. Alors deux ours sortirent de la forêt, et déchirèrent quarante-deux de ces enfants."}, {"numero": 25, "texto": "De là il alla sur la montagne du Carmel, d''''où il retourna à Samarie."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 2, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que, cuando quiso Jehová alzar á Elías en un torbellino al cielo, Elías venía con Eliseo de Gilgal."}, {"numero": 2, "texto": "Y dijo Elías á Eliseo: Quédate ahora aquí, porque Jehová me ha enviado á Beth-el. Y Eliseo dijo: Vive Jehová, y vive tu alma, que no te dejaré. Descendieron pues á Beth-el."}, {"numero": 3, "texto": "Y saliendo á Eliseo los hijos de los profetas que estaban en Beth-el, dijéronle: ¿Sabes como Jehová quitará hoy á tu señor de tu cabeza? Y él dijo: Sí, yo lo sé; callad."}, {"numero": 4, "texto": "Y Elías le volvió á decir: Eliseo, quédate aquí ahora, porque Jehová me ha enviado á Jericó. Y él dijo: Vive Jehová, y vive tu alma, que no te dejaré. Vinieron pues á Jericó."}, {"numero": 5, "texto": "Y llegáronse á Eliseo los hijos de los profetas que estaban en Jericó, y dijéronle: ¿Sabes cómo Jehová quitará hoy á tu señor de tu cabeza? Y él respondió: Sí, yo lo sé; callad."}, {"numero": 6, "texto": "Y Elías le dijo: Ruégote que te quedes aquí, porque Jehová me ha enviado al Jordán. Y él dijo: Vive Jehová, y vive tu alma, que no te dejaré. Fueron pues ambos á dos."}, {"numero": 7, "texto": "Y vinieron cincuenta varones de los hijos de los profetas, y paráronse enfrente á lo lejos: y ellos dos se pararon junto al Jordán."}, {"numero": 8, "texto": "Tomando entonces Elías su manto, doblólo, é hirió las aguas, las cuales se apartaron á uno y á otro lado, y pasaron ambos en seco."}, {"numero": 9, "texto": "Y como hubieron pasado, Elías dijo á Eliseo: Pide lo que quieres que haga por ti, antes que sea quitado de contigo. Y dijo Eliseo: Ruégote que las dos partes de tu espíritu sean sobre mí."}, {"numero": 10, "texto": "Y él le dijo: Cosa difícil has pedido. Si me vieres cuando fuere quitado de ti, te será así hecho; mas si no, no."}, {"numero": 11, "texto": "Y aconteció que, yendo ellos hablando, he aquí, un carro de fuego con caballos de fuego apartó á los dos: y Elías subió al cielo en un torbellino."}, {"numero": 12, "texto": "Y viéndolo Eliseo, clamaba: ¡Padre mío, padre mío, carro de Israel y su gente de á caballo! Y nunca más le vió, y trabando de sus vestidos, rompiólos en dos partes."}, {"numero": 13, "texto": "Alzó luego el manto de Elías que se le había caído, y volvió, y paróse á la orilla del Jordán."}, {"numero": 14, "texto": "Y tomando el manto de Elías que se le había caído, hirió las aguas, y dijo: ¿Dónde está Jehová, el Dios de Elías? Y así que hubo del mismo modo herido las aguas, apartáronse á uno y á otro lado, y pasó Eliseo."}, {"numero": 15, "texto": "Y viéndole los hijos de los profetas que estaban en Jericó de la otra parte, dijeron: El espíritu de Elías reposó sobre Eliseo. Y viniéronle á recibir, é inclináronse á él hasta la tierra."}, {"numero": 16, "texto": "Y dijéronle: He aquí hay con tus siervos cincuenta varones fuertes: vayan ahora y busquen á tu señor; quizá lo ha levantado el espíritu de Jehová, y lo ha echado en algún monte ó en algún valle. Y él les dijo: No enviéis."}, {"numero": 17, "texto": "Mas ellos le importunaron, hasta que avergonzándose dijo: Enviad. Entonces ellos enviaron cincuenta hombres, los cuales lo buscaron tres días, mas no lo hallaron."}, {"numero": 18, "texto": "Y cuando volvieron á él, que se había quedado en Jericó, él les dijo: ¿No os dije yo que no fueseis?"}, {"numero": 19, "texto": "Y los hombres de la ciudad dijeron á Eliseo: He aquí el asiento de esta ciudad es bueno, como mi señor ve; mas las aguas son malas, y la tierra enferma."}, {"numero": 20, "texto": "Entonces él dijo: Traedme una botija nueva, y poned en ella sal. Y trajéronsela."}, {"numero": 21, "texto": "Y saliendo él á los manaderos de las aguas, echó dentro la sal, y dijo: Así ha dicho Jehová: Yo sané estas aguas, y no habrá más en ellas muerte ni enfermedad."}, {"numero": 22, "texto": "Y fueron sanas las aguas hasta hoy, conforme á la palabra que habló Eliseo."}, {"numero": 23, "texto": "Después subió de allí á Beth-el; y subiendo por el camino, salieron los muchachos de la ciudad, y se burlaban de él, diciendo: ¡Calvo, sube! ¡calvo, sube!"}, {"numero": 24, "texto": "Y mirando él atrás, viólos, y maldíjolos en el nombre de Jehová. Y salieron dos osos del monte, y despedazaron de ellos cuarenta y dos muchachos."}, {"numero": 25, "texto": "De allí fué al monte de Carmelo, y de allí volvió á Samaria."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 4, 'pt', '[{"numero": 1, "texto": "Uma mulher, das mulheres dos filhos dos profetas, clamou a Eliseu, dizendo: Teu servo, meu marido, é morto; e tu sabes que teu servo era temeroso ao SENHOR; e veio o credor para tomar-se dois filhos meus por servos."}, {"numero": 2, "texto": "E Eliseu lhe disse: que te farei eu? Declara-me o que tens em casa. E ela disse: Tua serva nenhuma coisa tem em casa, a não ser uma botija de azeite."}, {"numero": 3, "texto": "E ele lhe disse: Vai, e pede para ti vasos emprestados de todos teus vizinhos, vasos vazios, não poucos."}, {"numero": 4, "texto": "Entra logo, e fecha a porta atrás de ti e atrás teus filhos; e deita em todos os vasos, e em estando um cheio, põe-o à parte."}, {"numero": 5, "texto": "E partiu-se a mulher dele, e fechou a porta atrás si e atrás seus filhos; e eles lhe traziam os vasos, e ela deitava do azeite."}, {"numero": 6, "texto": "E quando os vasos foram cheios, disse a um filho seu: Traze-me ainda outro vaso. E ele disse: Não há mais vasos. Então cessou o azeite."}, {"numero": 7, "texto": "Veio ela logo, e contou-o ao homem de Deus, o qual disse: Vai, e vende o azeite, e paga a teus credores; e tu e teus filhos vivei do que restar."}, {"numero": 8, "texto": "E aconteceu também que um dia passava Eliseu por Suném; e havia ali uma mulher rica, a qual lhe constrangeu a que comesse do pão; e quando por ali passava, vinha-se à sua casa a comer do pão."}, {"numero": 9, "texto": "E ela disse a seu marido: Eis que agora, eu entendo que este que sempre passa por nossa casa, é homem de Deus santo."}, {"numero": 10, "texto": "Eu te rogo que faças uma pequena câmara de paredes, e ponhamos nela cama, e mesa, e cadeira, e candelabro, para que quando vier a nós, se recolha nela."}, {"numero": 11, "texto": "E aconteceu que um dia veio ele por ali, e recolheu-se naquela câmara, e dormiu nela."}, {"numero": 12, "texto": "Então disse a Geazi seu criado: Chama a esta sunamita. E quando ele a chamou, ela se apresentou diante dele."}, {"numero": 13, "texto": "E disse ele a Geazi: Dize-lhe: Eis que tu tens sido prestativa por nós com todo este esmero: que queres que eu faça por ti? Tens necessidade que fale por ti ao rei, ou ao general do exército? E ela respondeu: Eu habito em meio de meu povo."}, {"numero": 14, "texto": "E ele disse: Que, pois, faremos por ela? E Geazi respondeu: Eis que ela não tem filho, e seu marido é velho."}, {"numero": 15, "texto": "Disse então: Chama-a. E ele a chamou, e ela se parou à porta."}, {"numero": 16, "texto": "E ele lhe disse: A este tempo segundo o tempo da vida, abraçarás um filho. E ela disse: Não, senhor meu, homem de Deus, não mintas para tua serva."}, {"numero": 17, "texto": "Mas a mulher concebeu, e pariu um filho a aquele tempo que Eliseu lhe havia dito, segundo o tempo da vida."}, {"numero": 18, "texto": "E quando o menino foi grande, aconteceu que um dia saiu a seu pai, aos ceifeiros."}, {"numero": 19, "texto": "E disse a seu pai: Minha cabeça, minha cabeça! E ele disse a um criado: Leva-o a sua mãe."}, {"numero": 20, "texto": "E havendo-lhe ele tomado, e trazido-o a sua mãe, esteve sentado sobre seus joelhos até meio dia, e morreu-se."}, {"numero": 21, "texto": "Ela então subiu, e o pôs sobre a cama do homem de Deus, e fechando-lhe a porta, saiu-se."}, {"numero": 22, "texto": "Chamando logo a seu marido, disse-lhe: Rogo-te que envies comigo a algum dos criados e uma das asnas, para que eu vá correndo ao homem de Deus, e volte."}, {"numero": 23, "texto": "E ele disse: Para que hás de ir a ele hoje? Não é nova lua, nem sábado. E ela respondeu: Paz."}, {"numero": 24, "texto": "Depois fez preparar uma jumenta, e disse ao jovem: Guia e anda; e não me faças deter para que suba, a não ser quando eu te disser."}, {"numero": 25, "texto": "Partiu-se, pois, e veio ao homem de Deus ao monte do Carmelo. E quando o homem de Deus a viu de longe, disse a seu criado Geazi: Eis que a sunamita:"}, {"numero": 26, "texto": "Rogo-te que vás agora correndo a recebê-la, e dize-lhe: Há paz contigo, com teu marido, e com teu filho? E ela disse: Paz."}, {"numero": 27, "texto": "E logo que chegou ao homem de Deus no monte, pegou seus pés. E chegou-se Geazi para tirá-la; mas o homem de Deus lhe disse: Deixa-a, porque sua alma está em amargura, e o SENHOR me encobriu o motivo, e não me revelou."}, {"numero": 28, "texto": "E ela disse: Pedi eu filho a meu senhor? Não disse eu, que não me enganasses?"}, {"numero": 29, "texto": "Então disse ele a Geazi: Cinge teus lombos, e toma meu bordão em tua mão, e vai; e se alguém te encontrar, não o saúdes; e se alguém te saudar, não lhe respondas: e porás meu bordão sobre o rosto do menino."}, {"numero": 30, "texto": "E disse a mãe do menino: Vive o SENHOR, e vive tua alma, que não te deixarei."}, {"numero": 31, "texto": "Ele então se levantou, e seguiu-a. E Geazi havia ido diante deles, e havia posto o bordão sobre o rosto do menino, mas nem tinha voz nem sentido; e assim se havia voltado para encontrar a Eliseu; e declarou-o a ele, dizendo: O jovem não desperta."}, {"numero": 32, "texto": "E vindo Eliseu à casa, eis que o menino que estava estendido morto sobre sua cama."}, {"numero": 33, "texto": "Entrando ele então, fechou a porta sobre ambos, e orou ao SENHOR."}, {"numero": 34, "texto": "Depois subiu, e lançou-se sobre o menino, pondo sua boca sobre a boca dele, e seus olhos sobre seus olhos, e suas mãos sobre as mãos suas; assim se estendeu sobre ele, e aqueceu a carne do jovem."}, {"numero": 35, "texto": "Voltando-se logo, andou pela casa a uma parte e a outra, e depois subiu, e estendeu-se sobre ele; e o jovem espirrou sete vezes, e abriu seus olhos."}, {"numero": 36, "texto": "Então ele chamou a Geazi, e disse-lhe: Chama a esta sunamita. E ele a chamou. E entrando ela, ele lhe disse: Toma teu filho."}, {"numero": 37, "texto": "E assim que ela entrou, lançou-se a seus pés, e inclinou-se a terra: depois tomou seu filho, e saiu-se."}, {"numero": 38, "texto": "E Eliseu se voltou a Gilgal. Havia então grande fome na terra. E os filhos dos profetas estavam com ele, pelo que disse a seu criado: Põe uma grande caçarola, e faze sopa para os filhos dos profetas."}, {"numero": 39, "texto": "E saiu um ao campo a colher ervas, e achou uma como parreira selvagem, e agarrou dela uma capa de frutos silvestres; e voltou, e cortou-as na caçarola da sopa: porque não sabia o que era."}, {"numero": 40, "texto": "Serviu depois para que comessem os homens; mas sucedeu que comendo eles daquele guisado, deram vozes, dizendo: Homem de Deus, há morte na caçarola! E não o puderam comer."}, {"numero": 41, "texto": "Ele então disse: Trazei farinha. E espalhou-a na caçarola, e disse: Dá de comer à gente. E não houve mais mal na caçarola."}, {"numero": 42, "texto": "Veio então um homem de Baal-Salisa, o qual trouxe ao homem de Deus pães de primícias, vinte pães de cevada, e trigo novo em sua espiga. E ele disse: Da ao povo, para que comam."}, {"numero": 43, "texto": "E respondeu seu servente: Como porei isto diante de cem homens? Mas ele voltou a dizer: Da ao povo para que comam, porque assim disse o SENHOR: Comerão, e sobrará."}, {"numero": 44, "texto": "Então ele o pôs diante deles, e comeram, e sobrou-lhes, conforme a palavra do SENHOR."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 4, 'en', '[{"numero": 1, "texto": "Now there cried a certain woman of the wives of the sons of the prophets unto Elisha, saying, Thy servant my husband is dead; and thou knowest that thy servant did fear the Lord: and the creditor is come to take unto him my two sons to be bondmen."}, {"numero": 2, "texto": "And Elisha said unto her, What shall I do for thee? tell me, what hast thou in the house? And she said, Thine handmaid hath not any thing in the house, save a pot of oil."}, {"numero": 3, "texto": "Then he said, Go, borrow thee vessels abroad of all thy neighbours, even empty vessels; borrow not a few."}, {"numero": 4, "texto": "And when thou art come in, thou shalt shut the door upon thee and upon thy sons, and shalt pour out into all those vessels, and thou shalt set aside that which is full."}, {"numero": 5, "texto": "So she went from him, and shut the door upon her and upon her sons, who brought the vessels to her; and she poured out."}, {"numero": 6, "texto": "And it came to pass, when the vessels were full, that she said unto her son, Bring me yet a vessel. And he said unto her, There is not a vessel more. And the oil stayed."}, {"numero": 7, "texto": "Then she came and told the man of God. And he said, Go, sell the oil, and pay thy debt, and live thou and thy children of the rest."}, {"numero": 8, "texto": "And it fell on a day, that Elisha passed to Shunem, where was a great woman; and she constrained him to eat bread. And so it was, that as oft as he passed by, he turned in thither to eat bread."}, {"numero": 9, "texto": "And she said unto her husband, Behold now, I perceive that this is an holy man of God, which passeth by us continually."}, {"numero": 10, "texto": "Let us make a little chamber, I pray thee, on the wall; and let us set for him there a bed, and a table, and a stool, and a candlestick: and it shall be, when he cometh to us, that he shall turn in thither."}, {"numero": 11, "texto": "And it fell on a day, that he came thither, and he turned into the chamber, and lay there."}, {"numero": 12, "texto": "And he said to Gehazi his servant, Call this Shunammite. And when he had called her, she stood before him."}, {"numero": 13, "texto": "And he said unto him, Say now unto her, Behold, thou hast been careful for us with all this care; what is to be done for thee? wouldest thou be spoken for to the king, or to the captain of the host? And she answered, I dwell among mine own people."}, {"numero": 14, "texto": "And he said, What then is to be done for her? And Gehazi answered, Verily she hath no child, and her husband is old."}, {"numero": 15, "texto": "And he said, Call her. And when he had called her, she stood in the door."}, {"numero": 16, "texto": "And he said, About this season, according to the time of life, thou shalt embrace a son. And she said, Nay, my lord, thou man of God, do not lie unto thine handmaid."}, {"numero": 17, "texto": "And the woman conceived, and bare a son at that season that Elisha had said unto her, according to the time of life."}, {"numero": 18, "texto": "And when the child was grown, it fell on a day, that he went out to his father to the reapers."}, {"numero": 19, "texto": "And he said unto his father, My head, my head. And he said to a lad, Carry him to his mother."}, {"numero": 20, "texto": "And when he had taken him, and brought him to his mother, he sat on her knees till noon, and then died."}, {"numero": 21, "texto": "And she went up, and laid him on the bed of the man of God, and shut the door upon him, and went out."}, {"numero": 22, "texto": "And she called unto her husband, and said, Send me, I pray thee, one of the young men, and one of the asses, that I may run to the man of God, and come again."}, {"numero": 23, "texto": "And he said, Wherefore wilt thou go to him to day? it is neither new moon, nor sabbath. And she said, It shall be well."}, {"numero": 24, "texto": "Then she saddled an ass, and said to her servant, Drive, and go forward; slack not thy riding for me, except I bid thee."}, {"numero": 25, "texto": "So she went and came unto the man of God to mount Carmel. And it came to pass, when the man of God saw her afar off, that he said to Gehazi his servant, Behold, yonder is that Shunammite:"}, {"numero": 26, "texto": "Run now, I pray thee, to meet her, and say unto her, Is it well with thee? is it well with thy husband? is it well with the child? And she answered, It is well:"}, {"numero": 27, "texto": "And when she came to the man of God to the hill, she caught him by the feet: but Gehazi came near to thrust her away. And the man of God said, Let her alone; for her soul is vexed within her: and the Lord hath hid it from me, and hath not told me."}, {"numero": 28, "texto": "Then she said, Did I desire a son of my lord? did I not say, Do not deceive me?"}, {"numero": 29, "texto": "Then he said to Gehazi, Gird up thy loins, and take my staff in thine hand, and go thy way: if thou meet any man, salute him not; and if any salute thee, answer him not again: and lay my staff upon the face of the child."}, {"numero": 30, "texto": "And the mother of the child said, As the Lord liveth, and as thy soul liveth, I will not leave thee. And he arose, and followed her."}, {"numero": 31, "texto": "And Gehazi passed on before them, and laid the staff upon the face of the child; but there was neither voice, nor hearing. Wherefore he went again to meet him, and told him, saying, The child is not awaked."}, {"numero": 32, "texto": "And when Elisha was come into the house, behold, the child was dead, and laid upon his bed."}, {"numero": 33, "texto": "He went in therefore, and shut the door upon them twain, and prayed unto the Lord."}, {"numero": 34, "texto": "And he went up, and lay upon the child, and put his mouth upon his mouth, and his eyes upon his eyes, and his hands upon his hands: and stretched himself upon the child; and the flesh of the child waxed warm."}, {"numero": 35, "texto": "Then he returned, and walked in the house to and fro; and went up, and stretched himself upon him: and the child sneezed seven times, and the child opened his eyes."}, {"numero": 36, "texto": "And he called Gehazi, and said, Call this Shunammite. So he called her. And when she was come in unto him, he said, Take up thy son."}, {"numero": 37, "texto": "Then she went in, and fell at his feet, and bowed herself to the ground, and took up her son, and went out."}, {"numero": 38, "texto": "And Elisha came again to Gilgal: and there was a dearth in the land; and the sons of the prophets were sitting before him: and he said unto his servant, Set on the great pot, and seethe pottage for the sons of the prophets."}, {"numero": 39, "texto": "And one went out into the field to gather herbs, and found a wild vine, and gathered thereof wild gourds his lap full, and came and shred them into the pot of pottage: for they knew them not."}, {"numero": 40, "texto": "So they poured out for the men to eat. And it came to pass, as they were eating of the pottage, that they cried out, and said, O thou man of God, there is death in the pot. And they could not eat thereof."}, {"numero": 41, "texto": "But he said, Then bring meal. And he cast it into the pot; and he said, Pour out for the people, that they may eat. And there was no harm in the pot."}, {"numero": 42, "texto": "And there came a man from Baalshalisha, and brought the man of God bread of the firstfruits, twenty loaves of barley, and full ears of corn in the husk thereof. And he said, Give unto the people, that they may eat."}, {"numero": 43, "texto": "And his servitor said, What, should I set this before an hundred men? He said again, Give the people, that they may eat: for thus saith the Lord, They shall eat, and shall leave thereof."}, {"numero": 44, "texto": "So he set it before them, and they did eat, and left thereof, according to the word of the Lord."}]'::jsonb, 'King James Version'),
  ('2Rs', 4, 'fr', '[{"numero": 1, "texto": "Une femme d''''entre les femmes des fils des prophètes cria à Elisée, en disant: Ton serviteur mon mari est mort, et tu sais que ton serviteur craignait l''''Eternel; or le créancier est venu pour prendre mes deux enfants et en faire ses esclaves."}, {"numero": 2, "texto": "Elisée lui dit: Que puis-je faire pour toi? Dis-moi, qu''''as-tu à la maison? Elle répondit: Ta servante n''''a rien du tout à la maison qu''''un vase d''''huile."}, {"numero": 3, "texto": "Et il dit: Va demander au dehors des vases chez tous tes voisins, des vases vides, et n''''en demande pas un petit nombre."}, {"numero": 4, "texto": "Quand tu seras rentrée, tu fermeras la porte sur toi et sur tes enfants; tu verseras dans tous ces vases, et tu mettras de côté ceux qui seront pleins."}, {"numero": 5, "texto": "Alors elle le quitta. Elle ferma la porte sur elle et sur ses enfants; ils lui présentaient les vases, et elle versait."}, {"numero": 6, "texto": "Lorsque les vases furent pleins, elle dit à son fils: Présente-moi encore un vase. Mais il lui répondit: Il n''''y a plus de vase. Et l''''huile s''''arrêta."}, {"numero": 7, "texto": "Elle alla le rapporter à l''''homme de Dieu, et il dit: Va vendre l''''huile, et paie ta dette; et tu vivras, toi et tes fils, de ce qui restera."}, {"numero": 8, "texto": "Un jour Elisée passait par Sunem. Il y avait là une femme de distinction, qui le pressa d''''accepter à manger. Et toutes les fois qu''''il passait, il se rendait chez elle pour manger."}, {"numero": 9, "texto": "Elle dit à son mari: Voici, je sais que cet homme qui passe toujours chez nous est un saint homme de Dieu."}, {"numero": 10, "texto": "Faisons une petite chambre haute avec des murs, et mettons-y pour lui un lit, une table, un siège et un chandelier, afin qu''''il s''''y retire quand il viendra chez nous."}, {"numero": 11, "texto": "Elisée, étant revenu à Sunem, se retira dans la chambre haute et y coucha."}, {"numero": 12, "texto": "Il dit à Guéhazi, son serviteur: Appelle cette Sunamite. Guéhazi l''''appela, et elle se présenta devant lui."}, {"numero": 13, "texto": "Et Elisée dit à Guéhazi: Dis-lui: Voici, tu nous as montré tout cet empressement; que peut-on faire pour toi? Faut-il parler pour toi au roi ou au chef de l''''armée? Elle répondit: J''''habite au milieu de mon peuple."}, {"numero": 14, "texto": "Et il dit: Que faire pour elle? Guéhazi répondit: Mais, elle n''''a point de fils, et son mari est vieux."}, {"numero": 15, "texto": "Et il dit: Appelle-la. Guéhazi l''''appela, et elle se présenta à la porte."}, {"numero": 16, "texto": "Elisée lui dit: A cette même époque, l''''année prochaine, tu embrasseras un fils. Et elle dit: Non! mon seigneur, homme de Dieu, ne trompe pas ta servante!"}, {"numero": 17, "texto": "Cette femme devint enceinte, et elle enfanta un fils à la même époque, l''''année suivante, comme Elisée lui avait dit."}, {"numero": 18, "texto": "L''''enfant grandit. Et un jour qu''''il était allé trouver son père vers les moissonneurs,"}, {"numero": 19, "texto": "il dit à son père: Ma tête! ma tête! Le père dit à son serviteur: Porte-le à sa mère."}, {"numero": 20, "texto": "Le serviteur l''''emporta et l''''amena à sa mère. Et l''''enfant resta sur les genoux de sa mère jusqu''''à midi, puis il mourut."}, {"numero": 21, "texto": "Elle monta, le coucha sur le lit de l''''homme de Dieu, ferma la porte sur lui, et sortit."}, {"numero": 22, "texto": "Elle appela son mari, et dit: Envoie-moi, je te prie, un des serviteurs et une des ânesses; je veux aller en hâte vers l''''homme de Dieu, et je reviendrai."}, {"numero": 23, "texto": "Et il dit: Pourquoi veux-tu aller aujourd''''hui vers lui? Ce n''''est ni nouvelle lune ni sabbat. Elle répondit: Tout va bien."}, {"numero": 24, "texto": "Puis elle fit seller l''''ânesse, et dit à son serviteur: Mène et pars; ne m''''arrête pas en route sans que je te le dise."}, {"numero": 25, "texto": "Elle partit donc et se rendit vers l''''homme de Dieu sur la montagne du Carmel. L''''homme de Dieu, l''''ayant aperçue de loin, dit à Guéhazi, son serviteur: Voici cette Sunamite!"}, {"numero": 26, "texto": "Maintenant, cours donc à sa rencontre, et dis-lui: Te portes-tu bien? Ton mari et ton enfant se portent-ils bien? Elle répondit: Bien."}, {"numero": 27, "texto": "Et dès qu''''elle fut arrivée auprès de l''''homme de Dieu sur la montagne, elle embrassa ses pieds. Guéhazi s''''approcha pour la repousser. Mais l''''homme de Dieu dit: Laisse-la, car son âme est dans l''''amertume, et l''''Eternel me l''''a caché et ne me l''''a point fait connaître."}, {"numero": 28, "texto": "Alors elle dit: Ai-je demandé un fils à mon seigneur? N''''ai-je pas dit: Ne me trompe pas?"}, {"numero": 29, "texto": "Et Elisée dit à Guéhazi: Ceins tes reins, prends mon bâton dans ta main, et pars. Si tu rencontres quelqu''''un, ne le salue pas; et si quelqu''''un te salue, ne lui réponds pas. Tu mettras mon bâton sur le visage de l''''enfant."}, {"numero": 30, "texto": "La mère de l''''enfant dit: L''''Eternel est vivant et ton âme est vivante! je ne te quitterai point. Et il se leva et la suivit."}, {"numero": 31, "texto": "Guéhazi les avait devancés, et il avait mis le bâton sur le visage de l''''enfant; mais il n''''y eut ni voix ni signe d''''attention. Il s''''en retourna à la rencontre d''''Elisée, et lui rapporta la chose, en disant: L''''enfant ne s''''est pas réveillé."}, {"numero": 32, "texto": "Lorsque Elisée arriva dans la maison, voici, l''''enfant était mort, couché sur son lit."}, {"numero": 33, "texto": "Elisée entra et ferma la porte sur eux deux, et il pria l''''Eternel."}, {"numero": 34, "texto": "Il monta, et se coucha sur l''''enfant; il mit sa bouche sur sa bouche, ses yeux sur ses yeux, ses mains sur ses mains, et il s''''étendit sur lui. Et la chair de l''''enfant se réchauffa."}, {"numero": 35, "texto": "Elisée s''''éloigna, alla çà et là par la maison, puis remonta et s''''étendit sur l''''enfant. Et l''''enfant éternua sept fois, et il ouvrit les yeux."}, {"numero": 36, "texto": "Elisée appela Guéhazi, et dit: Appelle cette Sunamite. Guéhazi l''''appela, et elle vint vers Elisée, qui dit: Prends ton fils!"}, {"numero": 37, "texto": "Elle alla se jeter à ses pieds, et se prosterna contre terre. Et elle prit son fils, et sortit."}, {"numero": 38, "texto": "Elisée revint à Guilgal, et il y avait une famine dans le pays. Comme les fils des prophètes étaient assis devant lui, il dit à son serviteur: Mets le grand pot, et fais cuire un potage pour les fils des prophètes."}, {"numero": 39, "texto": "L''''un d''''eux sortit dans les champs pour cueillir des herbes; il trouva de la vigne sauvage et il y cueillit des coloquintes sauvages, plein son vêtement. Quand il rentra, il les coupa en morceaux dans le pot où était le potage, car on ne les connaissait pas."}, {"numero": 40, "texto": "On servit à manger à ces hommes; mais dès qu''''ils eurent mangé du potage, ils s''''écrièrent: La mort est dans le pot, homme de Dieu! Et ils ne purent manger."}, {"numero": 41, "texto": "Elisée dit: Prenez de la farine. Il en jeta dans le pot, et dit: Sers à ces gens, et qu''''ils mangent. Et il n''''y avait plus rien de mauvais dans le pot."}, {"numero": 42, "texto": "Un homme arriva de Baal-Schalischa. Il apporta du pain des prémices à l''''homme de Dieu, vingt pains d''''orge, et des épis nouveaux dans son sac. Elisée dit: Donne à ces gens, et qu''''ils mangent."}, {"numero": 43, "texto": "Son serviteur répondit: Comment pourrais-je en donner à cent personnes? Mais Elisée dit: Donne à ces gens, et qu''''ils mangent; car ainsi parle l''''Eternel: On mangera, et on en aura de reste."}, {"numero": 44, "texto": "Il mit alors les pains devant eux; et ils mangèrent et en eurent de reste, selon la parole de l''''Eternel."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 4, 'es', '[{"numero": 1, "texto": "UNA mujer, de las mujeres de los hijos de los profetas, clamó á Eliseo, diciendo: Tu siervo mi marido es muerto; y tú sabes que tu siervo era temeroso de Jehová: y ha venido el acreedor para tomarse dos hijos míos por siervos."}, {"numero": 2, "texto": "Y Eliseo le dijo: ¿Qué te haré yo? Declárame qué tienes en casa. Y ella dijo: Tu sierva ninguna cosa tiene en casa, sino una botija de aceite."}, {"numero": 3, "texto": "Y él le dijo: Ve, y pide para ti vasos prestados de todos tus vecinos, vasos vacíos, no pocos."}, {"numero": 4, "texto": "Entra luego, y cierra la puerta tras ti y tras tus hijos; y echa en todos los vasos, y en estando uno lleno, ponlo aparte."}, {"numero": 5, "texto": "Y partióse la mujer de él, y cerró la puerta tras sí y tras sus hijos; y ellos le llegaban los vasos, y ella echaba del aceite."}, {"numero": 6, "texto": "Y como los vasos fueron llenos, dijo á un hijo suyo: Tráeme aún otro vaso. Y él dijo: No hay más vasos. Entonces cesó el aceite."}, {"numero": 7, "texto": "Vino ella luego, y contólo al varón de Dios, el cual dijo: Ve, y vende el aceite, y paga á tus acreedores; y tú y tus hijos vivid de lo que quedare."}, {"numero": 8, "texto": "Y aconteció también que un día pasaba Eliseo por Sunem; y había allí una mujer principal, la cual le constriñó á que comiese del pan: y cuando por allí pasaba, veníase á su casa á comer del pan."}, {"numero": 9, "texto": "Y ella dijo á su marido: He aquí ahora, yo entiendo que éste que siempre pasa por nuestra casa, es varón de Dios santo."}, {"numero": 10, "texto": "Yo te ruego que hagas una pequeña cámara de paredes, y pongamos en ella cama, y mesa, y silla, y candelero, para que cuando viniere á nosotros, se recoja en ella."}, {"numero": 11, "texto": "Y aconteció que un día vino él por allí, y recogióse en aquella cámara, y durmió en ella."}, {"numero": 12, "texto": "Entonces dijo á Giezi su criado: Llama á esta Sunamita. Y como él la llamó, pareció ella delante de él."}, {"numero": 13, "texto": "Y dijo él á Giezi: Dile: He aquí tú has estado solícita por nosotros con todo este esmero: ¿qué quieres que haga por ti? ¿has menester que hable por ti al rey, ó al general del ejército? Y ella respondió: Yo habito en medio de mi pueblo."}, {"numero": 14, "texto": "Y él dijo: ¿Qué pues haremos por ella? Y Giezi respondió: He aquí ella no tiene hijo, y su marido es viejo."}, {"numero": 15, "texto": "Dijo entonces: Llámala. Y él la llamó, y ella se paró á la puerta."}, {"numero": 16, "texto": "Y él le dijo: A este tiempo según el tiempo de la vida, abrazarás un hijo. Y ella dijo: No, señor mío, varón de Dios, no hagas burla de tu sierva."}, {"numero": 17, "texto": "Mas la mujer concibió, y parió un hijo á aquel tiempo que Eliseo le había dicho, según el tiempo de la vida."}, {"numero": 18, "texto": "Y como el niño fué grande, aconteció que un día salió á su padre, á los segadores."}, {"numero": 19, "texto": "Y dijo á su padre: ¡Mi cabeza, mi cabeza! Y él dijo á un criado: Llévalo á su madre."}, {"numero": 20, "texto": "Y habiéndole él tomado, y traídolo á su madre, estuvo sentado sobre sus rodillas hasta medio día, y murióse."}, {"numero": 21, "texto": "Ella entonces subió, y púsolo sobre la cama del varón de Dios, y cerrándole la puerta, salióse."}, {"numero": 22, "texto": "Llamando luego á su marido, díjole: Ruégote que envíes conmigo á alguno de los criados y una de las asnas, para que yo vaya corriendo al varón de Dios, y vuelva."}, {"numero": 23, "texto": "Y él dijo: ¿Para qué has de ir á él hoy? No es nueva luna, ni sábado. Y ella respondió: Paz."}, {"numero": 24, "texto": "Después hizo enalbardar una borrica, y dijo al mozo: Guía y anda; y no me hagas detener para que suba, sino cuando yo te lo dijere."}, {"numero": 25, "texto": "Partióse pues, y vino al varón de Dios al monte del Carmelo. Y cuando el varón de Dios la vió de lejos, dijo á su criado Giezi: He aquí la Sunamita:"}, {"numero": 26, "texto": "Ruégote que vayas ahora corriendo á recibirla, y dile: ¿Tienes paz? ¿y tu marido, y tu hijo? Y ella dijo: Paz."}, {"numero": 27, "texto": "Y luego que llegó al varón de Dios en el monte, asió de sus pies. Y llegóse Giezi para quitarla; mas el varón de Dios le dijo: Déjala, porque su alma está en amargura, y Jehová me ha encubierto el motivo, y no me lo ha revelado."}, {"numero": 28, "texto": "Y ella dijo: ¿Pedí yo hijo á mi señor? ¿No dije yo, que no me burlases?"}, {"numero": 29, "texto": "Entonces dijo él á Giezi: Ciñe tus lomos, y toma mi bordón en tu mano, y ve; y si alguno te encontrare, no lo saludes; y si alguno te saludare, no le respondas: y pondrás mi bordón sobre el rostro del niño."}, {"numero": 30, "texto": "Y dijo la madre del niño: Vive Jehová, y vive tu alma, que no te dejaré."}, {"numero": 31, "texto": "El entonces se levantó, y siguióla. Y Giezi había ido delante de ellos, y había puesto el bordón sobre el rostro del niño, mas ni tenía voz ni sentido; y así se había vuelto para encontrar á Eliseo; y declaróselo, diciendo: El mozo no despierta."}, {"numero": 32, "texto": "Y venido Eliseo á la casa, he aquí el niño que estaba tendido muerto sobre su cama."}, {"numero": 33, "texto": "Entrando él entonces, cerró la puerta sobre ambos, y oró á Jehová."}, {"numero": 34, "texto": "Después subió, y echóse sobre el niño, poniendo su boca sobre la boca de él, y sus ojos sobre sus ojos, y sus manos sobre las manos suyas; así se tendió sobre él, y calentóse la carne del joven."}, {"numero": 35, "texto": "Volviéndose luego, paseóse por la casa á una parte y á otra, y después subió, y tendióse sobre él; y el joven estornudó siete veces, y abrió sus ojos."}, {"numero": 36, "texto": "Entonces llamó él á Giezi, y díjole: Llama á esta Sunamita. Y él la llamó. Y entrando ella, él le dijo: Toma tu hijo."}, {"numero": 37, "texto": "Y así que ella entró, echóse á sus pies, é inclinóse á tierra: después tomó su hijo, y salióse."}, {"numero": 38, "texto": "Y Eliseo se volvió á Gilgal. Había entonces grande hambre en la tierra. Y los hijos de los profetas estaban con él, por lo que dijo á su criado: Pon una grande olla, y haz potaje para los hijos de los profetas."}, {"numero": 39, "texto": "Y salió uno al campo á coger hierbas, y halló una como parra montés, y cogió de ella una faldada de calabazas silvestres: y volvió, y cortólas en la olla del potaje: porque no sabía lo que era."}, {"numero": 40, "texto": "Echóse después para que comieran los hombres; pero sucedió que comiendo ellos de aquel guisado, dieron voces, diciendo: ¡Varón de Dios, la muerte en la olla! Y no lo pudieron comer."}, {"numero": 41, "texto": "El entonces dijo: Traed harina. Y esparcióla en la olla, y dijo: Echa de comer á la gente. Y no hubo más mal en la olla."}, {"numero": 42, "texto": "Vino entonces un hombre de Baal-salisa, el cual trajo al varón de Dios panes de primicias, veinte panes de cebada, y trigo nuevo en su espiga. Y él dijo: Da á la gente para que coman."}, {"numero": 43, "texto": "Y respondió su sirviente: ¿Cómo he de poner esto delante de cien hombres? Mas él tornó á decir: Da á la gente para que coman, porque así ha dicho Jehová: Comerán, y sobrará."}, {"numero": 44, "texto": "Entonces él lo puso delante de ellos, y comieron, y sobróles, conforme á la palabra de Jehová."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 5, 'pt', '[{"numero": 1, "texto": "Naamã, general do exército do rei da Síria, era grande homem diante de seu senhor, e em alta estima, porque por meio dele o SENHOR havia dado salvamento à Síria. Era este homem valente em extremo, mas leproso."}, {"numero": 2, "texto": "E da Síria haviam saído tropas, e haviam levado cativa da terra de Israel uma menina; a qual servindo à mulher de Naamã,"}, {"numero": 3, "texto": "disse à sua senhora: Se meu senhor rogasse ao profeta que está em Samaria, ele o sararia de sua lepra."}, {"numero": 4, "texto": "E Naamã, vindo a seu senhor, declarou-o a ele, dizendo: Assim e assim disse uma menina que é da terra de Israel."}, {"numero": 5, "texto": "E disse-lhe o rei da Síria: Anda, vai, e eu enviarei cartas ao rei de Israel. Partiu, pois, ele, levando consigo dez talentos de prata, e seis mil peças de ouro, e dez mudas de roupas."}, {"numero": 6, "texto": "Tomou também cartas para o rei de Israel, que diziam assim: Logo em chegando a ti estas cartas, sabe por elas que eu envio a ti meu servo Naamã, para que o sares de sua lepra."}, {"numero": 7, "texto": "E logo que o rei de Israel leu as cartas, rasgou suas roupas, e disse: Sou eu Deus, que mate e dê vida, para que este envie a mim a que sare um homem de sua lepra? Considerai agora, e vede como busca ocasião contra mim."}, {"numero": 8, "texto": "E quando Eliseu, homem de Deus ouviu que o rei de Israel havia rasgado suas roupas, enviou a dizer ao rei: Por que rasgaste tuas vestes? Venha agora a mim, e saberá que há profeta em Israel."}, {"numero": 9, "texto": "E veio Naamã com seus cavalos e com seu carro, e parou-se às portas da casa de Eliseu."}, {"numero": 10, "texto": "Então Eliseu lhe enviou um mensageiro, dizendo: Vai, e lava-te sete vezes no Jordão, e tua carne se te restaurará, e serás limpo."}, {"numero": 11, "texto": "E Naamã se foi irritado, dizendo: Eis que eu dizia para mim: Sairá ele logo, e estando em pé invocará o nome do SENHOR seu Deus, e levantará sua mão, e tocará o lugar, e sarará a lepra."}, {"numero": 12, "texto": "Abana e Farpar, rios de Damasco, não são melhores que todas as águas de Israel? Se me lavar neles, não serei também limpo? E voltou-se, e foi-se irritado."}, {"numero": 13, "texto": "Mas seus criados se chegaram a ele, e falaram-lhe, dizendo: Pai meu, se o profeta te mandasse alguma grande coisa, não a farias? Quanto mais, dizendo-te: Lava-te, e serás limpo?"}, {"numero": 14, "texto": "Ele então desceu, e mergulhou sete vezes no Jordão, conforme a palavra do homem de Deus; e sua carne se restaurou como a carne de um menino, e foi limpo."}, {"numero": 15, "texto": "E voltou ao homem de Deus, ele e toda sua companhia, e pôs-se diante dele, e disse: Eis que agora conheço que não há Deus em toda a terra, a não ser em Israel. Rogo-te que recebas algum presente do teu servo."}, {"numero": 16, "texto": "Mas ele disse: Vive o SENHOR, diante do qual estou, que não o tomarei. E insistindo-lhe que tomasse, ele não quis."}, {"numero": 17, "texto": "Então Naamã disse: Rogo-te, pois, não se dará a teu servo uma carga de um par de mulas desta terra? Porque de agora em diante teu servo não sacrificará holocausto nem sacrifício a outros deuses, a não ser ao SENHOR."}, {"numero": 18, "texto": "Em isto perdoe o SENHOR a teu servo: que quando meu senhor entrar no templo de Rimom, e para adorar nele se apoiar sobre minha mão, se eu também me inclinar no templo de Rimom, se no templo de Rimom me inclino, o SENHOR perdoe nisto a teu servo."}, {"numero": 19, "texto": "E ele lhe disse: Vai em paz. Partiu-se, pois, dele, e caminhou como o espaço de uma milha."}, {"numero": 20, "texto": "Então Geazi, criado de Eliseu o homem de Deus, disse entre si: Eis que meu senhor poupou a este sírio Naamã, não tomando de sua mão as coisas que havia trazido. Vive o SENHOR, que correrei eu atrás dele, e tomarei dele alguma coisa."}, {"numero": 21, "texto": "E Geazi seguiu Naamã; e quando Naamã lhe viu que vinha correndo atrás dele, desceu do carro para receber-lhe, e disse: Vai bem?"}, {"numero": 22, "texto": "E ele disse: Bem. Meu senhor me envia a dizer: Eis que vieram a mim nesta hora do monte de Efraim dois rapazes dos filhos dos profetas: rogo-te que lhes dês um talento de prata, e duas mudas de roupas."}, {"numero": 23, "texto": "E Naamã disse: Rogo-te que tomes dois talentos. E ele lhe constrangeu, e atou dois talentos de prata em dois sacos, e duas mudas de roupas, e o pôs às costas a dois de seus criados, que o levassem diante dele."}, {"numero": 24, "texto": "E chegado que houve a um lugar secreto, ele o tomou da mão deles, e guardou-o em casa: logo mandou aos homens que se fossem."}, {"numero": 25, "texto": "E ele entrou, e pôs-se diante de seu senhor. E Eliseu lhe disse: De onde vens, Geazi? E ele disse: Teu servo não foi a nenhuma parte."}, {"numero": 26, "texto": "O então lhe disse: Não foi também meu coração, quando o homem voltou de seu carro a receber-te? É tempo de tomar prata, e de tomar roupas, olivais, vinhas, ovelhas, bois, servos e servas?"}, {"numero": 27, "texto": "A lepra de Naamã se apegará a ti e à tua semente para sempre. E saiu de diante dele leproso, branco como a neve."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 5, 'en', '[{"numero": 1, "texto": "Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the Lord had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper."}, {"numero": 2, "texto": "And the Syrians had gone out by companies, and had brought away captive out of the land of Israel a little maid; and she waited on Naaman''s wife."}, {"numero": 3, "texto": "And she said unto her mistress, Would God my lord were with the prophet that is in Samaria! for he would recover him of his leprosy."}, {"numero": 4, "texto": "And one went in, and told his lord, saying, Thus and thus said the maid that is of the land of Israel."}, {"numero": 5, "texto": "And the king of Syria said, Go to, go, and I will send a letter unto the king of Israel. And he departed, and took with him ten talents of silver, and six thousand pieces of gold, and ten changes of raiment."}, {"numero": 6, "texto": "And he brought the letter to the king of Israel, saying, Now when this letter is come unto thee, behold, I have therewith sent Naaman my servant to thee, that thou mayest recover him of his leprosy."}, {"numero": 7, "texto": "And it came to pass, when the king of Israel had read the letter, that he rent his clothes, and said, Am I God, to kill and to make alive, that this man doth send unto me to recover a man of his leprosy? wherefore consider, I pray you, and see how he seeketh a quarrel against me."}, {"numero": 8, "texto": "And it was so, when Elisha the man of God had heard that the king of Israel had rent his clothes, that he sent to the king, saying, Wherefore hast thou rent thy clothes? let him come now to me, and he shall know that there is a prophet in Israel."}, {"numero": 9, "texto": "So Naaman came with his horses and with his chariot, and stood at the door of the house of Elisha."}, {"numero": 10, "texto": "And Elisha sent a messenger unto him, saying, Go and wash in Jordan seven times, and thy flesh shall come again to thee, and thou shalt be clean."}, {"numero": 11, "texto": "But Naaman was wroth, and went away, and said, Behold, I thought, He will surely come out to me, and stand, and call on the name of the Lord his God, and strike his hand over the place, and recover the leper."}, {"numero": 12, "texto": "Are not Abana and Pharpar, rivers of Damascus, better than all the waters of Israel? may I not wash in them, and be clean? So he turned and went away in a rage."}, {"numero": 13, "texto": "And his servants came near, and spake unto him, and said, My father, if the prophet had bid thee do some great thing, wouldest thou not have done it? how much rather then, when he saith to thee, Wash, and be clean?"}, {"numero": 14, "texto": "Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean."}, {"numero": 15, "texto": "And he returned to the man of God, he and all his company, and came, and stood before him: and he said, Behold, now I know that there is no God in all the earth, but in Israel: now therefore, I pray thee, take a blessing of thy servant."}, {"numero": 16, "texto": "But he said, As the Lord liveth, before whom I stand, I will receive none. And he urged him to take it; but he refused."}, {"numero": 17, "texto": "And Naaman said, Shall there not then, I pray thee, be given to thy servant two mules'' burden of earth? for thy servant will henceforth offer neither burnt offering nor sacrifice unto other gods, but unto the Lord."}, {"numero": 18, "texto": "In this thing the Lord pardon thy servant, that when my master goeth into the house of Rimmon to worship there, and he leaneth on my hand, and I bow myself in the house of Rimmon: when I bow down myself in the house of Rimmon, the Lord pardon thy servant in this thing."}, {"numero": 19, "texto": "And he said unto him, Go in peace. So he departed from him a little way."}, {"numero": 20, "texto": "But Gehazi, the servant of Elisha the man of God, said, Behold, my master hath spared Naaman this Syrian, in not receiving at his hands that which he brought: but, as the Lord liveth, I will run after him, and take somewhat of him."}, {"numero": 21, "texto": "So Gehazi followed after Naaman. And when Naaman saw him running after him, he lighted down from the chariot to meet him, and said, Is all well?"}, {"numero": 22, "texto": "And he said, All is well. My master hath sent me, saying, Behold, even now there be come to me from mount Ephraim two young men of the sons of the prophets: give them, I pray thee, a talent of silver, and two changes of garments."}, {"numero": 23, "texto": "And Naaman said, Be content, take two talents. And he urged him, and bound two talents of silver in two bags, with two changes of garments, and laid them upon two of his servants; and they bare them before him."}, {"numero": 24, "texto": "And when he came to the tower, he took them from their hand, and bestowed them in the house: and he let the men go, and they departed."}, {"numero": 25, "texto": "But he went in, and stood before his master. And Elisha said unto him, Whence comest thou, Gehazi? And he said, Thy servant went no whither."}, {"numero": 26, "texto": "And he said unto him, Went not mine heart with thee, when the man turned again from his chariot to meet thee? Is it a time to receive money, and to receive garments, and oliveyards, and vineyards, and sheep, and oxen, and menservants, and maidservants?"}, {"numero": 27, "texto": "The leprosy therefore of Naaman shall cleave unto thee, and unto thy seed for ever. And he went out from his presence a leper as white as snow."}]'::jsonb, 'King James Version'),
  ('2Rs', 5, 'fr', '[{"numero": 1, "texto": "Naaman, chef de l''''armée du roi de Syrie, jouissait de la faveur de son maître et d''''une grande considération; car c''''était par lui que l''''Eternel avait délivré les Syriens. Mais cet homme fort et vaillant était lépreux."}, {"numero": 2, "texto": "Or les Syriens étaient sortis par troupes, et ils avaient emmené captive une petite fille du pays d''''Israël, qui était au service de la femme de Naaman."}, {"numero": 3, "texto": "Et elle dit à sa maîtresse: Oh! si mon seigneur était auprès du prophète qui est à Samarie, le prophète le guérirait de sa lèpre!"}, {"numero": 4, "texto": "Naaman alla dire à son maître: La jeune fille du pays d''''Israël a parlé de telle et telle manière."}, {"numero": 5, "texto": "Et le roi de Syrie dit: Va, rends-toi à Samarie, et j''''enverrai une lettre au roi d''''Israël. Il partit, prenant avec lui dix talents d''''argent, six mille sicles d''''or, et dix vêtements de rechange."}, {"numero": 6, "texto": "Il porta au roi d''''Israël la lettre, où il était dit: Maintenant, quand cette lettre te sera parvenue, tu sauras que je t''''envoie Naaman, mon serviteur, afin que tu le guérisses de sa lèpre."}, {"numero": 7, "texto": "Après avoir lu la lettre, le roi d''''Israël déchira ses vêtements, et dit: Suis-je un dieu, pour faire mourir et pour faire vivre, qu''''il s''''adresse à moi afin que je guérisse un homme de sa lèpre? Sachez donc et comprenez qu''''il cherche une occasion de dispute avec moi."}, {"numero": 8, "texto": "Lorsqu''''Elisée, homme de Dieu, apprit que le roi d''''Israël avait déchiré ses vêtements, il envoya dire au roi: Pourquoi as-tu déchiré tes vêtements? Laisse-le venir à moi, et il saura qu''''il y a un prophète en Israël."}, {"numero": 9, "texto": "Naaman vint avec ses chevaux et son char, et il s''''arrêta à la porte de la maison d''''Elisée."}, {"numero": 10, "texto": "Elisée lui fit dire par un messager: Va, et lave-toi sept fois dans le Jourdain; ta chair redeviendra saine, et tu seras pur."}, {"numero": 11, "texto": "Naaman fut irrité, et il s''''en alla, en disant: Voici, je me disais: Il sortira vers moi, il se présentera lui-même, il invoquera le nom de l''''Eternel, son Dieu, il agitera sa main sur la place et guérira le lépreux."}, {"numero": 12, "texto": "Les fleuves de Damas, l''''Abana et le Parpar, ne valent-ils pas mieux que toutes les eaux d''''Israël? Ne pourrais-je pas m''''y laver et devenir pur? Et il s''''en retournait et partait avec fureur."}, {"numero": 13, "texto": "Mais ses serviteurs s''''approchèrent pour lui parler, et ils dirent: Mon père, si le prophète t''''eût demandé quelque chose de difficile, ne l''''aurais-tu pas fait? Combien plus dois-tu faire ce qu''''il t''''a dit: Lave-toi, et tu seras pur!"}, {"numero": 14, "texto": "Il descendit alors et se plongea sept fois dans le Jourdain, selon la parole de l''''homme de Dieu; et sa chair redevint comme la chair d''''un jeune enfant, et il fut pur."}, {"numero": 15, "texto": "Naaman retourna vers l''''homme de Dieu, avec toute sa suite. Lorsqu''''il fut arrivé, il se présenta devant lui, et dit: Voici, je reconnais qu''''il n''''y a point de Dieu sur toute la terre, si ce n''''est en Israël. Et maintenant, accepte, je te prie, un présent de la part de ton serviteur."}, {"numero": 16, "texto": "Elisée répondit: L''''Eternel, dont je suis le serviteur, est vivant! je n''''accepterai pas. Naaman le pressa d''''accepter, mais il refusa."}, {"numero": 17, "texto": "Alors Naaman dit: Puisque tu refuses, permets que l''''on donne de la terre à ton serviteur, une charge de deux mulets; car ton serviteur ne veut plus offrir à d''''autres dieux ni holocauste ni sacrifice, il n''''en offrira qu''''à l''''Eternel."}, {"numero": 18, "texto": "Voici toutefois ce que je prie l''''Eternel de pardonner à ton serviteur. Quand mon maître entre dans la maison de Rimmon pour s''''y prosterner et qu''''il s''''appuie sur ma main, je me prosterne aussi dans la maison de Rimmon: veuille l''''Eternel pardonner à ton serviteur, lorsque je me prosternerai dans la maison de Rimmon!"}, {"numero": 19, "texto": "Elisée lui dit: Va en paix. Lorsque Naaman eut quitté Elisée et qu''''il fut à une certaine distance,"}, {"numero": 20, "texto": "Guéhazi, serviteur d''''Elisée, homme de Dieu, se dit en lui-même: Voici, mon maître a ménagé Naaman, ce Syrien, en n''''acceptant pas de sa main ce qu''''il avait apporté; l''''Eternel est vivant! je vais courir après lui, et j''''en obtiendrai quelque chose."}, {"numero": 21, "texto": "Et Guéhazi courut après Naaman. Naaman, le voyant courir après lui, descendit de son char pour aller à sa rencontre, et dit: Tout va-t-il bien?"}, {"numero": 22, "texto": "Il répondit: Tout va bien. Mon maître m''''envoie te dire: Voici, il vient d''''arriver chez moi deux jeunes gens de la montagne d''''Ephraïm, d''''entre les fils des prophètes; donne pour eux, je te prie, un talent d''''argent et deux vêtements de rechange."}, {"numero": 23, "texto": "Naaman dit: Consens à prendre deux talents. Il le pressa, et il serra deux talents d''''argent dans deux sacs, donna deux habits de rechange, et les fit porter devant Guéhazi par deux de ses serviteurs."}, {"numero": 24, "texto": "Arrivé à la colline, Guéhazi les prit de leurs mains et les déposa dans la maison, et il renvoya ces gens qui partirent."}, {"numero": 25, "texto": "Puis il alla se présenter à son maître. Elisée lui dit: D''''où viens-tu, Guéhazi? Il répondit: Ton serviteur n''''est allé ni d''''un côté ni d''''un autre."}, {"numero": 26, "texto": "Mais Elisée lui dit: Mon esprit n''''était pas absent, lorsque cet homme a quitté son char pour venir à ta rencontre. Est-ce le temps de prendre de l''''argent et de prendre des vêtements, puis des oliviers, des vignes, des brebis, des boeufs, des serviteurs et des servantes?"}, {"numero": 27, "texto": "La lèpre de Naaman s''''attachera à toi et à ta postérité pour toujours. Et Guéhazi sortit de la présence d''''Elisée avec une lèpre comme la neige."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 5, 'es', '[{"numero": 1, "texto": "NAAMÁN, general del ejército del rey de Siria, era gran varón delante de su señor, y en alta estima, porque por medio de él había dado Jehová salvamento á la Siria. Era este hombre valeroso en extremo, pero leproso."}, {"numero": 2, "texto": "Y de Siria habían salido cuadrillas, y habían llevado cautiva de la tierra de Israel una muchacha; la cual sirviendo á la mujer de Naamán,"}, {"numero": 3, "texto": "Dijo á su señora: Si rogase mi señor al profeta que está en Samaria, él lo sanaría de su lepra."}, {"numero": 4, "texto": "Y entrando Naamán á su señor, declaróselo, diciendo: Así y así ha dicho una muchacha que es de la tierra de Israel."}, {"numero": 5, "texto": "Y díjole el rey de Siria: Anda, ve, y yo enviaré letras al rey de Israel. Partió pues él, llevando consigo diez talentos de plata, y seis mil piezas de oro, y diez mudas de vestidos."}, {"numero": 6, "texto": "Tomó también letras para el rey de Israel, que decían así: Luego en llegando á ti estas letras, sabe por ellas que yo envío á ti mi siervo Naamán, para que lo sanes de su lepra."}, {"numero": 7, "texto": "Y luego que el rey de Israel leyó las cartas, rasgó sus vestidos, y dijo: ¿Soy yo Dios, que mate y dé vida, para que éste envíe á mí á que sane un hombre de su lepra? Considerad ahora, y ved cómo busca ocasión contra mí."}, {"numero": 8, "texto": "Y como Eliseo, varón de Dios oyó que el rey de Israel había rasgado sus vestidos, envió á decir al rey: ¿Por qué has rasgado tus vestidos? Venga ahora á mí, y sabrá que hay profeta en Israel."}, {"numero": 9, "texto": "Y vino Naamán con sus caballos y con su carro, y paróse á las puertas de la casa de Eliseo."}, {"numero": 10, "texto": "Entonces Eliseo le envió un mensajero, diciendo: Ve, y lávate siete veces en el Jordán, y tu carne se te restaurará, y serás limpio."}, {"numero": 11, "texto": "Y Naamán se fué enojado, diciendo: He aquí yo decía para mí: Saldrá él luego, y estando en pie invocará el nombre de Jehová su Dios, y alzará su mano, y tocará el lugar, y sanará la lepra."}, {"numero": 12, "texto": "Abana y Pharphar, ríos de Damasco, ¿no son mejores que todas las aguas de Israel? Si me lavare en ellos, ¿no seré también limpio? Y volvióse, y fuése enojado."}, {"numero": 13, "texto": "Mas sus criados se llegaron á él, y habláronle, diciendo: Padre mío, si el profeta te mandara alguna gran cosa, ¿no la hicieras? ¿cuánto más, diciéndote: Lávate, y serás limpio?"}, {"numero": 14, "texto": "El entonces descendió, y zambullóse siete veces en el Jordán, conforme á la palabra del varón de Dios: y su carne se volvió como la carne de un niño, y fué limpio."}, {"numero": 15, "texto": "Y volvió al varón de Dios, él y toda su compañía, y púsose delante de él, y dijo: He aquí ahora conozco que no hay Dios en toda la tierra, sino en Israel. Ruégote que recibas algún presente de tu siervo."}, {"numero": 16, "texto": "Mas él dijo: Vive Jehová, delante del cual estoy, que no lo tomaré. E importunándole que tomase, él nunca quiso."}, {"numero": 17, "texto": "Entonces Naamán dijo: Ruégote pues, ¿no se dará á tu siervo una carga de un par de acémilas de aquesta tierra? porque de aquí adelante tu siervo no sacrificará holocausto ni sacrificio á otros dioses, sino á Jehová."}, {"numero": 18, "texto": "En esto perdone Jehová á tu siervo: que cuando mi señor entrare en el templo de Rimmón, y para adorar en él se apoyare sobre mi mano, si yo también me inclinare en el templo de Rimmón, si en el templo de Rimmón me inclino, Jehová perdone en esto á tu siervo."}, {"numero": 19, "texto": "Y él le dijo: Vete en paz. Partióse pues de él, y caminó como el espacio de una milla."}, {"numero": 20, "texto": "Entonces Giezi, criado de Eliseo el varón de Dios, dijo entre sí: He aquí mi señor estorbó á este Siro Naamán, no tomando de su mano las cosas que había traído. Vive Jehová, que correré yo tras él, y tomaré de él alguna cosa."}, {"numero": 21, "texto": "Y siguió Giezi á Naamán: y como le vió Naamán que venía corriendo tras él, apeóse del carro para recibirle, y dijo: ¿Va bien?"}, {"numero": 22, "texto": "Y él dijo: Bien. Mi señor me envía á decir: He aquí vinieron á mí en esta hora del monte de Ephraim dos mancebos de los hijos de los profetas: ruégote que les des un talento de plata, y sendas mudas de vestidos."}, {"numero": 23, "texto": "Y Naamán dijo: Ruégote que tomes dos talentos. Y él le constriñó, y ató dos talentos de plata en dos sacos, y dos mudas de vestidos, y púsolo á cuestas á dos de sus criados, que lo llevasen delante de él."}, {"numero": 24, "texto": "Y llegado que hubo á un lugar secreto, él lo tomó de mano de ellos, y guardólo en casa: luego mandó á los hombres que se fuesen."}, {"numero": 25, "texto": "Y él entró, y púsose delante de su señor. Y Eliseo le dijo: ¿De dónde vienes, Giezi? Y él dijo: Tu siervo no ha ido á ninguna parte."}, {"numero": 26, "texto": "El entonces le dijo: ¿No fué también mi corazón, cuando el hombre volvió de su carro á recibirte? ¿es tiempo de tomar plata, y de tomar vestidos, olivares, viñas, ovejas, bueyes, siervos y siervas?"}, {"numero": 27, "texto": "La lepra de Naamán se te pegará á ti, y á tu simiente para siempre. Y salió de delante de él leproso, blanco como la nieve."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 6, 'pt', '[{"numero": 1, "texto": "Os filhos dos profetas disseram a Eliseu: Eis que o lugar em que moramos contigo nos é estreito."}, {"numero": 2, "texto": "Vamos agora ao Jordão, e tomemos dali cada um uma viga, e façamo-nos ali lugar em que habitemos. E ele disse: Andai."}, {"numero": 3, "texto": "E disse um: Rogamos-te que queiras vir com teus servos. E ele respondeu: Eu irei."}, {"numero": 4, "texto": "Foi-se, pois, com eles; e como chegaram ao Jordão, cortaram a madeira."}, {"numero": 5, "texto": "E aconteceu que derrubando uma árvore, caiu o machado na água; e deu vozes, dizendo: Ah, senhor meu, que era emprestada!"}, {"numero": 6, "texto": "E o homem de Deus disse: Onde caiu? E ele lhe mostrou o lugar. Então cortou ele um pau, e lançou-o ali; e fez flutuar o ferro."}, {"numero": 7, "texto": "E disse: Toma-o. E ele estendeu a mão, e tomou-o."}, {"numero": 8, "texto": "Tinha o rei da Síria guerra contra Israel, e consultando com seus servos, disse: Em tal e tal lugar estará meu acampamento."}, {"numero": 9, "texto": "E o homem de Deus enviou a dizer ao rei de Israel: Olha que não passes por tal lugar, porque os sírios vão ali."}, {"numero": 10, "texto": "Então o rei de Israel enviou a aquele lugar que o homem de Deus havia dito e alertado-lhe; e guardou-se dali, não uma vez nem duas."}, {"numero": 11, "texto": "E o coração do rei da Síria foi perturbado disto; e chamando a seus servos, disse-lhes: Não me declarareis vós quem dos nossos é do rei de Israel?"}, {"numero": 12, "texto": "Então um dos servos disse: Não, rei, senhor meu; mas sim que o profeta Eliseu está em Israel, o qual declara ao rei de Israel as palavras que tu falas em tua mais secreta câmara."}, {"numero": 13, "texto": "E ele disse: Ide, e olhai onde está, para que eu envie a tomá-lo. E foi-lhe dito: Eis que ele está em Dotã."}, {"numero": 14, "texto": "Então enviou o rei ali cavaleiros, e carros, e um grande exército, os quais vieram de noite, e cercaram a cidade."}, {"numero": 15, "texto": "E levantando-se de manhã o que servia ao homem de Deus, para sair, eis que o exército que tinha cercado a cidade, com cavaleiros e carros. Então seu criado lhe disse: Ah, senhor meu! Que faremos?"}, {"numero": 16, "texto": "E ele lhe disse: Não tenhas medo: porque mais são os que estão conosco do que os que estão com eles."}, {"numero": 17, "texto": "E orou Eliseu, e disse: Rogo-te, ó SENHOR, que abras seus olhos para que veja. Então o SENHOR abriu os olhos do jovem, e olhou; e eis que o monte estava cheio de cavaleiros, e de carros de fogo ao redor de Eliseu."}, {"numero": 18, "texto": "E logo que os sírios desceram a ele, orou Eliseu ao SENHOR, e disse: Rogo-te que firas a esta gente com cegueira. E feriu-os com cegueira, conforme ao dito de Eliseu."}, {"numero": 19, "texto": "Depois lhes disse Eliseu: Não é este o caminho, nem é esta a cidade; segui-me, que eu vos guiarei ao homem que buscais. E guiou-os a Samaria."}, {"numero": 20, "texto": "E assim que chegaram a Samaria, disse Eliseu: SENHOR, abre os olhos destes, para que vejam. E o SENHOR abriu seus olhos, e olharam, e acharam-se em meio de Samaria."}, {"numero": 21, "texto": "E quando o rei de Israel os havia visto, disse a Eliseu: Eu os ferirei, pai meu?"}, {"numero": 22, "texto": "E ele lhe respondeu: Não os firas; feririas tu aos que tomaste cativos com tua espada e com teu arco? Põe diante deles pão e água, para que comam e bebam, e se voltem a seus senhores."}, {"numero": 23, "texto": "Então lhes foi preparada grande comida: e quando houveram comido e bebido, enviou-os, e eles se voltaram a seu senhor. E nunca mais tropas da Síria vieram à terra de Israel."}, {"numero": 24, "texto": "Depois disto aconteceu, que Ben-Hadade rei da Síria juntou todo seu exército, e subiu, e pôs cerco a Samaria."}, {"numero": 25, "texto": "E houve grande fome em Samaria, tendo eles cerco sobre ela; tanto, que a cabeça de um asno era vendida por oitenta peças de prata, e a quarta parte de uma porção de esterco de pombas por cinco peças de prata."}, {"numero": 26, "texto": "E passando o rei de Israel pelo muro, uma mulher gritou-lhe, e disse: Socorro, rei, senhor meu."}, {"numero": 27, "texto": "E ele disse: Se o SENHOR não te salva, de onde eu tenho de te salvar? Do granário, ou da prensa de uvas?"}, {"numero": 28, "texto": "E disse-lhe o rei: Que tens? E ela respondeu: Esta mulher me disse: Dá aqui o teu filho, e o comamos hoje, e amanhã comeremos o meu."}, {"numero": 29, "texto": "Cozinhamos, pois, meu filho, e o comemos. O dia seguinte eu lhe disse: Dá aqui o teu filho, e o comamos. Mas ela escondeu seu filho."}, {"numero": 30, "texto": "E quando o rei ouviu as palavras daquela mulher, rasgou suas roupas, e passou assim pelo muro: e chegou a ver o povo o saco que trazia interiormente sobre sua carne."}, {"numero": 31, "texto": "E ele disse: Assim me faça Deus, e assim me acrescente, se a cabeça de Eliseu filho de Safate restar sobre ele hoje."}, {"numero": 32, "texto": "Estava naquele tempo Eliseu sentado em sua casa, e com ele estavam sentados os anciãos: e o rei enviou a ele um homem. Mas antes que o mensageiro viesse a ele, disse ele aos anciãos: Não vistes como este homicida me envia a tirar a cabeça?"}, {"numero": 33, "texto": "Ainda estava ele falando com eles, e eis que o mensageiro que descia a ele; e disse: Certamente este mal vem do SENHOR. Para que tenho de esperar mais ao SENHOR?"}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 6, 'en', '[{"numero": 1, "texto": "And the sons of the prophets said unto Elisha, Behold now, the place where we dwell with thee is too strait for us."}, {"numero": 2, "texto": "Let us go, we pray thee, unto Jordan, and take thence every man a beam, and let us make us a place there, where we may dwell. And he answered, Go ye."}, {"numero": 3, "texto": "And one said, Be content, I pray thee, and go with thy servants. And he answered, I will go."}, {"numero": 4, "texto": "So he went with them. And when they came to Jordan, they cut down wood."}, {"numero": 5, "texto": "But as one was felling a beam, the axe head fell into the water: and he cried, and said, Alas, master! for it was borrowed."}, {"numero": 6, "texto": "And the man of God said, Where fell it? And he shewed him the place. And he cut down a stick, and cast it in thither; and the iron did swim."}, {"numero": 7, "texto": "Therefore said he, Take it up to thee. And he put out his hand, and took it."}, {"numero": 8, "texto": "Then the king of Syria warred against Israel, and took counsel with his servants, saying, In such and such a place shall be my camp."}, {"numero": 9, "texto": "And the man of God sent unto the king of Israel, saying, Beware that thou pass not such a place; for thither the Syrians are come down."}, {"numero": 10, "texto": "And the king of Israel sent to the place which the man of God told him and warned him of, and saved himself there, not once nor twice."}, {"numero": 11, "texto": "Therefore the heart of the king of Syria was sore troubled for this thing; and he called his servants, and said unto them, Will ye not shew me which of us is for the king of Israel?"}, {"numero": 12, "texto": "And one of his servants said, None, my lord, O king: but Elisha, the prophet that is in Israel, telleth the king of Israel the words that thou speakest in thy bedchamber."}, {"numero": 13, "texto": "And he said, Go and spy where he is, that I may send and fetch him. And it was told him, saying, Behold, he is in Dothan."}, {"numero": 14, "texto": "Therefore sent he thither horses, and chariots, and a great host: and they came by night, and compassed the city about."}, {"numero": 15, "texto": "And when the servant of the man of God was risen early, and gone forth, behold, an host compassed the city both with horses and chariots. And his servant said unto him, Alas, my master! how shall we do?"}, {"numero": 16, "texto": "And he answered, Fear not: for they that be with us are more than they that be with them."}, {"numero": 17, "texto": "And Elisha prayed, and said, Lord, I pray thee, open his eyes, that he may see. And the Lord opened the eyes of the young man; and he saw: and, behold, the mountain was full of horses and chariots of fire round about Elisha."}, {"numero": 18, "texto": "And when they came down to him, Elisha prayed unto the Lord, and said, Smite this people, I pray thee, with blindness. And he smote them with blindness according to the word of Elisha."}, {"numero": 19, "texto": "And Elisha said unto them, This is not the way, neither is this the city: follow me, and I will bring you to the man whom ye seek. But he led them to Samaria."}, {"numero": 20, "texto": "And it came to pass, when they were come into Samaria, that Elisha said, Lord, open the eyes of these men, that they may see. And the Lord opened their eyes, and they saw; and, behold, they were in the midst of Samaria."}, {"numero": 21, "texto": "And the king of Israel said unto Elisha, when he saw them, My father, shall I smite them? shall I smite them?"}, {"numero": 22, "texto": "And he answered, Thou shalt not smite them: wouldest thou smite those whom thou hast taken captive with thy sword and with thy bow? set bread and water before them, that they may eat and drink, and go to their master."}, {"numero": 23, "texto": "And he prepared great provision for them: and when they had eaten and drunk, he sent them away, and they went to their master. So the bands of Syria came no more into the land of Israel."}, {"numero": 24, "texto": "And it came to pass after this, that Benhadad king of Syria gathered all his host, and went up, and besieged Samaria."}, {"numero": 25, "texto": "And there was a great famine in Samaria: and, behold, they besieged it, until an ass''s head was sold for fourscore pieces of silver, and the fourth part of a cab of dove''s dung for five pieces of silver."}, {"numero": 26, "texto": "And as the king of Israel was passing by upon the wall, there cried a woman unto him, saying, Help, my lord, O king."}, {"numero": 27, "texto": "And he said, If the Lord do not help thee, whence shall I help thee? out of the barnfloor, or out of the winepress?"}, {"numero": 28, "texto": "And the king said unto her, What aileth thee? And she answered, This woman said unto me, Give thy son, that we may eat him to day, and we will eat my son to morrow."}, {"numero": 29, "texto": "So we boiled my son, and did eat him: and I said unto her on the next day, Give thy son, that we may eat him: and she hath hid her son."}, {"numero": 30, "texto": "And it came to pass, when the king heard the words of the woman, that he rent his clothes; and he passed by upon the wall, and the people looked, and, behold, he had sackcloth within upon his flesh."}, {"numero": 31, "texto": "Then he said, God do so and more also to me, if the head of Elisha the son of Shaphat shall stand on him this day."}, {"numero": 32, "texto": "But Elisha sat in his house, and the elders sat with him; and the king sent a man from before him: but ere the messenger came to him, he said to the elders, See ye how this son of a murderer hath sent to take away mine head? look, when the messenger cometh, shut the door, and hold him fast at the door: is not the sound of his master''s feet behind him?"}, {"numero": 33, "texto": "And while he yet talked with them, behold, the messenger came down unto him: and he said, Behold, this evil is of the Lord; what should I wait for the Lord any longer?"}]'::jsonb, 'King James Version'),
  ('2Rs', 6, 'fr', '[{"numero": 1, "texto": "Les fils des prophètes dirent à Elisée: Voici, le lieu où nous sommes assis devant toi est trop étroit pour nous."}, {"numero": 2, "texto": "Allons jusqu''''au Jourdain; nous prendrons là chacun une poutre, et nous nous y ferons un lieu d''''habitation. Elisée répondit: Allez."}, {"numero": 3, "texto": "Et l''''un d''''eux dit: Consens à venir avec tes serviteurs. Il répondit: J''''irai."}, {"numero": 4, "texto": "Il partit donc avec eux. Arrivés au Jourdain, ils coupèrent du bois."}, {"numero": 5, "texto": "Et comme l''''un d''''eux abattait une poutre, le fer tomba dans l''''eau. Il s''''écria: Ah! mon seigneur, il était emprunté!"}, {"numero": 6, "texto": "L''''homme de Dieu dit: Où est-il tombé? Et il lui montra la place. Alors Elisée coupa un morceau de bois, le jeta à la même place, et fit surnager le fer."}, {"numero": 7, "texto": "Puis il dit: Enlève-le! Et il avança la main, et le prit."}, {"numero": 8, "texto": "Le roi de Syrie était en guerre avec Israël, et, dans un conseil qu''''il tint avec ses serviteurs, il dit: Mon camp sera dans un tel lieu."}, {"numero": 9, "texto": "Mais l''''homme de Dieu fit dire au roi d''''Israël: Garde-toi de passer dans ce lieu, car les Syriens y descendent."}, {"numero": 10, "texto": "Et le roi d''''Israël envoya des gens, pour s''''y tenir en observation, vers le lieu que lui avait mentionné et signalé l''''homme de Dieu. Cela arriva non pas une fois ni deux fois."}, {"numero": 11, "texto": "Le roi de Syrie en eut le coeur agité; il appela ses serviteurs, et leur dit: Ne voulez-vous pas me déclarer lequel de nous est pour le roi d''''Israël?"}, {"numero": 12, "texto": "L''''un de ses serviteurs répondit: Personne! ô roi mon seigneur; mais Elisée, le prophète, qui est en Israël, rapporte au roi d''''Israël les paroles que tu prononces dans ta chambre à coucher."}, {"numero": 13, "texto": "Et le roi dit: Allez et voyez où il est, et je le ferai prendre. On vint lui dire: Voici, il est à Dothan."}, {"numero": 14, "texto": "Il y envoya des chevaux, des chars et une forte troupe, qui arrivèrent de nuit et qui enveloppèrent la ville."}, {"numero": 15, "texto": "Le serviteur de l''''homme de Dieu se leva de bon matin et sortit; et voici, une troupe entourait la ville, avec des chevaux et des chars. Et le serviteur dit à l''''homme de Dieu: Ah! mon seigneur, comment ferons-nous?"}, {"numero": 16, "texto": "Il répondit: Ne crains point, car ceux qui sont avec nous sont en plus grand nombre que ceux qui sont avec eux."}, {"numero": 17, "texto": "Elisée pria, et dit: Eternel, ouvre ses yeux, pour qu''''il voie. Et l''''Eternel ouvrit les yeux du serviteur, qui vit la montagne pleine de chevaux et de chars de feu autour d''''Elisée."}, {"numero": 18, "texto": "Les Syriens descendirent vers Elisée. Il adressa alors cette prière à l''''Eternel: Daigne frapper d''''aveuglement cette nation! Et l''''Eternel les frappa d''''aveuglement, selon la parole d''''Elisée."}, {"numero": 19, "texto": "Elisée leur dit: Ce n''''est pas ici le chemin, et ce n''''est pas ici la ville; suivez-moi, et je vous conduirai vers l''''homme que vous cherchez. Et il les conduisit à Samarie."}, {"numero": 20, "texto": "Lorsqu''''ils furent entrés dans Samarie, Elisée dit: Eternel, ouvre les yeux de ces gens, pour qu''''ils voient! Et l''''Eternel ouvrit leurs yeux, et ils virent qu''''ils étaient au milieu de Samarie."}, {"numero": 21, "texto": "Le roi d''''Israël, en les voyant, dit à Elisée: Frapperai-je, frapperai-je, mon père?"}, {"numero": 22, "texto": "Tu ne frapperas point, répondit Elisée; est-ce que tu frappes ceux que tu fais prisonniers avec ton épée et avec ton arc? Donne-leur du pain et de l''''eau, afin qu''''ils mangent et boivent; et qu''''ils s''''en aillent ensuite vers leur maître."}, {"numero": 23, "texto": "Le roi d''''Israël leur fit servir un grand repas, et ils mangèrent et burent; puis il les renvoya, et ils s''''en allèrent vers leur maître. Et les troupes des Syriens ne revinrent plus sur le territoire d''''Israël."}, {"numero": 24, "texto": "Après cela, Ben-Hadad, roi de Syrie, ayant rassemblé toute son armée, monta et assiégea Samarie."}, {"numero": 25, "texto": "Il y eut une grande famine dans Samarie; et ils la serrèrent tellement qu''''une tête d''''âne valait quatre-vingts sicles d''''argent, et le quart d''''un kab de fiente de pigeon cinq sicles d''''argent."}, {"numero": 26, "texto": "Et comme le roi passait sur la muraille, une femme lui cria: Sauve-moi, ô roi, mon seigneur!"}, {"numero": 27, "texto": "Il répondit: Si l''''Eternel ne te sauve pas, avec quoi te sauverais-je? avec le produit de l''''aire ou du pressoir?"}, {"numero": 28, "texto": "Et le roi lui dit: Qu''''as-tu? Elle répondit: Cette femme-là m''''a dit: Donne ton fils! nous le mangerons aujourd''''hui, et demain nous mangerons mon fils."}, {"numero": 29, "texto": "Nous avons fait cuire mon fils, et nous l''''avons mangé. Et le jour suivant, je lui ai dit: Donne ton fils, et nous le mangerons. Mais elle a caché son fils."}, {"numero": 30, "texto": "Lorsque le roi entendit les paroles de cette femme, il déchira ses vêtements, en passant sur la muraille; et le peuple vit qu''''il avait en dedans un sac sur son corps."}, {"numero": 31, "texto": "Le roi dit: Que Dieu me punisse dans toute sa rigueur, si la tête d''''Elisée, fils de Schaphath, reste aujourd''''hui sur lui!"}, {"numero": 32, "texto": "Or Elisée était assis dans sa maison, et les anciens étaient assis auprès de lui. Le roi envoya quelqu''''un devant lui. Mais avant que le messager soit arrivé, Elisée dit aux anciens: Voyez-vous que ce fils d''''assassin envoie quelqu''''un pour m''''ôter la tête? Ecoutez! quand le messager viendra, fermez la porte, et repoussez-le avec la porte: le bruit des pas de son maître ne se fait-il pas entendre derrière lui?"}, {"numero": 33, "texto": "Il leur parlait encore, et déjà le messager était descendu vers lui, et disait: Voici, ce mal vient de l''''Eternel; qu''''ai-je à espérer encore de l''''Eternel?"}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 6, 'es', '[{"numero": 1, "texto": "LOS hijos de los profetas dijeron á Eliseo: He aquí, el lugar en que moramos contigo nos es estrecho."}, {"numero": 2, "texto": "Vamos ahora al Jordán, y tomemos de allí cada uno una viga, y hagámonos allí lugar en que habitemos. Y él dijo: Andad."}, {"numero": 3, "texto": "Y dijo uno: Rogámoste que quieras venir con tus siervos. Y él respondió: Yo iré."}, {"numero": 4, "texto": "Fuése pues con ellos; y como llegaron al Jordán, cortaron la madera."}, {"numero": 5, "texto": "Y aconteció que derribando uno un árbol, cayósele el hacha en el agua; y dió voces, diciendo: ¡Ah, señor mío, que era emprestada!"}, {"numero": 6, "texto": "Y el varón de Dios dijo: ¿Dónde cayó? Y él le mostró el lugar. Entonces cortó él un palo, y echólo allí; é hizo nadar el hierro."}, {"numero": 7, "texto": "Y dijo: Tómalo. Y él tendió la mano, y tomólo."}, {"numero": 8, "texto": "Tenía el rey de Siria guerra contra Israel, y consultando con sus siervos, dijo: En tal y tal lugar estará mi campamento."}, {"numero": 9, "texto": "Y el varón de Dios envió á decir al rey de Israel: Mira que no pases por tal lugar, porque los Siros van allí."}, {"numero": 10, "texto": "Entonces el rey de Israel envió á aquel lugar que el varón de Dios había dicho y amonestádole; y guardóse de allí, no una vez ni dos."}, {"numero": 11, "texto": "Y el corazón del rey de Siria fué turbado de esto; y llamando á sus siervos, díjoles: ¿No me declararéis vosotros quién de los nuestros es del rey de Israel?"}, {"numero": 12, "texto": "Entonces uno de los siervos dijo: No, rey señor mío; sino que el profeta Eliseo está en Israel, el cual declara al rey de Israel las palabras que tú hablas en tu más secreta cámara."}, {"numero": 13, "texto": "Y él dijo: Id, y mirad dónde está, para que yo envíe á tomarlo. Y fuéle dicho: He aquí él está en Dothán."}, {"numero": 14, "texto": "Entonces envió el rey allá gente de á caballo, y carros, y un grande ejército, los cuales vinieron de noche, y cercaron la ciudad."}, {"numero": 15, "texto": "Y levantándose de mañana el que servía al varón de Dios, para salir, he aquí el ejército que tenía cercada la ciudad, con gente de á caballo y carros. Entonces su criado le dijo: ¡Ah, señor mío! ¿qué haremos?"}, {"numero": 16, "texto": "Y él le dijo: No hayas miedo: porque más son los que están con nosotros que los que están con ellos."}, {"numero": 17, "texto": "Y oró Eliseo, y dijo: Ruégote, oh Jehová, que abras sus ojos para que vea. Entonces Jehová abrió los ojos del mozo, y miró: y he aquí que el monte estaba lleno de gente de á caballo, y de carros de fuego alrededor de Eliseo."}, {"numero": 18, "texto": "Y luego que los Siros descendieron á él, oró Eliseo á Jehová, y dijo: Ruégote que hieras á esta gente con ceguedad. E hiriólos con ceguedad, conforme al dicho de Eliseo."}, {"numero": 19, "texto": "Después les dijo Eliseo: No es este el camino, ni es esta la ciudad; seguidme, que yo os guiaré al hombre que buscáis. Y guiólos á Samaria."}, {"numero": 20, "texto": "Y así que llegaron á Samaria, dijo Eliseo: Jehová, abre los ojos de éstos, para que vean. Y Jehová abrió sus ojos, y miraron, y halláronse en medio de Samaria."}, {"numero": 21, "texto": "Y cuando el rey de Israel los hubo visto, dijo á Eliseo: ¿Herirélos, padre mío?"}, {"numero": 22, "texto": "Y él le respondió: No los hieras; ¿herirías tú á los que tomaste cautivos con tu espada y con tu arco? Pon delante de ellos pan y agua, para que coman y beban, y se vuelvan á sus señores."}, {"numero": 23, "texto": "Entonces les fué aparejada grande comida: y como hubieron comido y bebido, enviólos, y ellos se volvieron á su señor. Y nunca más vinieron cuadrillas de Siria á la tierra de Israel."}, {"numero": 24, "texto": "Después de esto aconteció, que Ben-adad rey de Siria juntó todo su ejército, y subió, y puso cerco á Samaria."}, {"numero": 25, "texto": "Y hubo grande hambre en Samaria, teniendo ellos cerco sobre ella; tanto, que la cabeza de un asno era vendida por ochenta piezas de plata, y la cuarta de un cabo de estiércol de palomas por cinco piezas de plata."}, {"numero": 26, "texto": "Y pasando el rey de Israel por el muro, una mujer le dió voces, y dijo: Salva, rey señor mío."}, {"numero": 27, "texto": "Y él dijo: Si no te salva Jehová, ¿de dónde te tengo de salvar yo? ¿del alfolí, ó del lagar?"}, {"numero": 28, "texto": "Y díjole el rey: ¿Qué tienes? Y ella respondió: Esta mujer me dijo: Da acá tu hijo, y comámoslo hoy, y mañana comeremos el mío."}, {"numero": 29, "texto": "Cocimos pues mi hijo, y le comimos. El día siguiente yo le dije: Da acá tu hijo, y comámoslo. Mas ella ha escondido su hijo."}, {"numero": 30, "texto": "Y como el rey oyó las palabras de aquella mujer, rasgó sus vestidos, y pasó así por el muro: y llegó á ver el pueblo el saco que traía interiormente sobre su carne."}, {"numero": 31, "texto": "Y él dijo: Así me haga Dios, y así me añada, si la cabeza de Eliseo hijo de Saphat quedare sobre él hoy."}, {"numero": 32, "texto": "Estaba á la sazón Eliseo sentado en su casa, y con él estaban sentados los ancianos: y el rey envió á él un hombre. Mas antes que el mensajero viniese á él, dijo él á los ancianos: ¿No habéis visto cómo este hijo del homicida me envía á quitar la cabeza? Mirad pues, y cuando viniere el mensajero, cerrad la puerta, é impedidle la entrada: ¿no viene tras él el ruido de los pies de su amo?"}, {"numero": 33, "texto": "Aun estaba él hablando con ellos, y he aquí el mensajero que descendía á él; y dijo: Ciertamente este mal de Jehová viene. ¿Para qué tengo de esperar más á Jehová?"}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 18, 'pt', '[{"numero": 1, "texto": "No terceiro ano de Oseias filho de Elá rei de Israel, começou a reinar Ezequias filho de Acaz rei de Judá."}, {"numero": 2, "texto": "Quando começou a reinar era de vinte e cinco anos, e reinou em Jerusalém vinte e nove anos. O nome de sua mãe foi Abi filha de Zacarias."}, {"numero": 3, "texto": "Fez o que era correto aos olhos do SENHOR, conforme todas as coisas que havia feito Davi seu pai."}, {"numero": 4, "texto": "Ele tirou os altos, e quebrou as imagens, e arrancou os bosques, e fez pedaços a serpente de bronze que havia feito Moisés, porque até então lhe queimavam incenso os filhos de Israel; e chamou-lhe por nome Neustã."}, {"numero": 5, "texto": "No SENHOR Deus de Israel pôs sua esperança: depois nem antes dele não houve outro como ele em todos os reis de Judá."}, {"numero": 6, "texto": "Porque se chegou ao SENHOR, e não se separou dele, mas sim que guardou os mandamentos que o SENHOR prescreveu a Moisés."}, {"numero": 7, "texto": "E o SENHOR foi com ele; e em todas as coisas a que saía prosperava. Ele se rebelou contra o rei da Assíria, e não lhe serviu."}, {"numero": 8, "texto": "Feriu também aos filisteus até Gaza e seus termos, desde as torres das atalaias até a cidade fortificada."}, {"numero": 9, "texto": "No quarto ano do rei Ezequias, que era o ano sétimo de Oseias filho de Elá rei de Israel, subiu Salmaneser rei dos assírios contra Samaria, e cercou-a."}, {"numero": 10, "texto": "E tomaram-na ao fim de três anos: isto é, no sexto ano de Ezequias, o qual era o ano nono de Oseias rei de Israel, foi Samaria tomado."}, {"numero": 11, "texto": "E o rei da Assíria transportou a Israel à Assíria, e os pôs em Hala, e em Habor, junto ao rio de Gozã, e nas cidades dos medos:"}, {"numero": 12, "texto": "Porquanto não haviam atendido à voz do SENHOR seu Deus, antes haviam quebrado o seu pacto; e todas as coisas que Moisés servo do SENHOR havia mandado, nem as haviam escutado, nem praticado."}, {"numero": 13, "texto": "E aos catorze anos do rei Ezequias, subiu Senaqueribe rei da Assíria contra todas as cidades fortes de Judá, e tomou-as."}, {"numero": 14, "texto": "Então Ezequias, rei de Judá, mandou dizer ao rei da Assíria em Laquis: Eu pequei; afasta-te de mim, e suportarei tudo o que me impuseres. E o rei da Assíria impôs a Ezequias rei de Judá trezentos talentos de prata, e trinta talentos de ouro."}, {"numero": 15, "texto": "Deu, portanto, Ezequias toda a prata que foi achada na casa do SENHOR, e nos tesouros da casa real."}, {"numero": 16, "texto": "Então desmontou Ezequias as portas do templo do SENHOR, e as dobradiças que o mesmo rei Ezequias havia coberto de ouro, e deu-o ao rei da Assíria."}, {"numero": 17, "texto": "Depois o rei da Assíria enviou ao rei Ezequias, desde Laquis contra Jerusalém, a Tartã e a Rabe-Saris e a Rabsaqué, com um grande exército: e subiram, e vieram a Jerusalém. E havendo subido, vieram e pararam junto ao aqueduto do tanque de acima,"}, {"numero": 18, "texto": "Chamaram logo ao rei, e saiu a eles Eliaquim filho de Hilquias, que era mordomo, e Sebna escriba, e Joá filho de Asafe, chanceler."}, {"numero": 19, "texto": "E disse-lhes Rabsaqué: Dizei agora a Ezequias: Assim diz o grande rei da Assíria: Que confiança é esta em que tu estás?"}, {"numero": 20, "texto": "Dizes, (por certo palavras de lábios): Tenho conselho e esforço para a guerra. Mas em que confias, que te rebelaste contra mim?"}, {"numero": 21, "texto": "Eis que tu confias agora neste bordão de cana quebrada, em Egito, no que se alguém se apoiar, lhe entrará pela mão, e se lhe passará. Assim é Faraó, rei do Egito, para todos os que nele confiam."}, {"numero": 22, "texto": "E se me dizeis: Nós confiamos no SENHOR nosso Deus: não é aquele cujos altos e altares tirou Ezequias, e disse a Judá e a Jerusalém: Diante deste altar adorareis em Jerusalém?"}, {"numero": 23, "texto": "Portanto, agora eu te rogo que dês reféns a meu senhor, o rei da Assíria, e eu te darei dois mil cavalos, se tu puderes dar cavaleiros para eles."}, {"numero": 24, "texto": "Como, pois, farás virar o rosto de um capitão o menor dos servos de meu senhor, ainda que estais confiantes no Egito por seus carros e seus cavaleiros?"}, {"numero": 25, "texto": "Além disso, acaso eu vim sem o SENHOR a este lugar, para destruí-lo? Foi o SENHOR que me disse: Sobe a esta terra, e destrói-a."}, {"numero": 26, "texto": "Então disse Eliaquim filho de Hilquias, e Sebna e Joá, a Rabsaqué: Rogo-te que fales a teus servos em siríaco, porque nós o entendemos, e não fales conosco judaico a ouvidos do povo que está sobre o muro."}, {"numero": 27, "texto": "E Rabsaqué lhes disse: Enviou-me meu senhor a ti e a teu senhor para dizer estas palavras, e não antes aos homens que estão sobre o muro, para comerem o seu excremento, e beberem a sua própria urina convosco?"}, {"numero": 28, "texto": "Logo Rabsaqué ficou de pé, e clamou em alta voz na língua judaica, e falou, dizendo: Ouvi a palavra do grande rei, o rei da Assíria."}, {"numero": 29, "texto": "Assim disse o rei: Não vos engane Ezequias, porque não vos poderá livrar de minha mão."}, {"numero": 30, "texto": "E não vos faça Ezequias confiar no SENHOR, dizendo: De certo nos livrará o SENHOR, e esta cidade não será entregue em mão do rei da Assíria."}, {"numero": 31, "texto": "Não ouçais a Ezequias, porque assim diz o rei da Assíria: Fazei comigo paz, e saí a mim, e cada um comerá de sua vide, e de sua figueira, e cada um beberá as águas de seu poço;"}, {"numero": 32, "texto": "Até que eu venha, e vos leve a uma terra como a vossa, terra de grão e de vinho, terra de pão e de vinhas, terra de olivas, de azeite, e de mel; e vivereis, e não morrereis. Não ouçais a Ezequias, porque vos engana quando disse: o SENHOR nos livrará."}, {"numero": 33, "texto": "Acaso algum dos deuses das nações livrou sua terra da mão do rei da Assíria?"}, {"numero": 34, "texto": "Onde está o deus de Hamate, e de Arpade? Onde está o deus de Sefarvaim, de Hena, e de Iva? Puderam estes livrar a Samaria de minha mão?"}, {"numero": 35, "texto": "Que deus de todos os deuses das províncias livrou a sua província de minha mão, para que livre o SENHOR de minha mão a Jerusalém?"}, {"numero": 36, "texto": "E o povo se calou, de maneira que não lhe responderam palavra: porque havia mandamento do rei, o qual havia dito: Não lhe respondais."}, {"numero": 37, "texto": "Então Eliaquim filho de Hilquias, que era mordomo, e Sebna o escriba, e Joá filho de Asafe, chanceler, vieram a Ezequias, com suas roupas rasgadas, e contaram-lhe as palavras de Rabsaqué."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 18, 'en', '[{"numero": 1, "texto": "Now it came to pass in the third year of Hoshea son of Elah king of Israel, that Hezekiah the son of Ahaz king of Judah began to reign."}, {"numero": 2, "texto": "Twenty and five years old was he when he began to reign; and he reigned twenty and nine years in Jerusalem. His mother''s name also was Abi, the daughter of Zachariah."}, {"numero": 3, "texto": "And he did that which was right in the sight of the Lord, according to all that David his father did."}, {"numero": 4, "texto": "He removed the high places, and brake the images, and cut down the groves, and brake in pieces the brasen serpent that Moses had made: for unto those days the children of Israel did burn incense to it: and he called it Nehushtan."}, {"numero": 5, "texto": "He trusted in the Lord God of Israel; so that after him was none like him among all the kings of Judah, nor any that were before him."}, {"numero": 6, "texto": "For he clave to the Lord, and departed not from following him, but kept his commandments, which the Lord commanded Moses."}, {"numero": 7, "texto": "And the Lord was with him; and he prospered whithersoever he went forth: and he rebelled against the king of Assyria, and served him not."}, {"numero": 8, "texto": "He smote the Philistines, even unto Gaza, and the borders thereof, from the tower of the watchmen to the fenced city."}, {"numero": 9, "texto": "And it came to pass in the fourth year of king Hezekiah, which was the seventh year of Hoshea son of Elah king of Israel, that Shalmaneser king of Assyria came up against Samaria, and besieged it."}, {"numero": 10, "texto": "And at the end of three years they took it: even in the sixth year of Hezekiah, that is in the ninth year of Hoshea king of Israel, Samaria was taken."}, {"numero": 11, "texto": "And the king of Assyria did carry away Israel unto Assyria, and put them in Halah and in Habor by the river of Gozan, and in the cities of the Medes:"}, {"numero": 12, "texto": "Because they obeyed not the voice of the Lord their God, but transgressed his covenant, and all that Moses the servant of the Lord commanded, and would not hear them, nor do them."}, {"numero": 13, "texto": "Now in the fourteenth year of king Hezekiah did Sennacherib king of Assyria come up against all the fenced cities of Judah, and took them."}, {"numero": 14, "texto": "And Hezekiah king of Judah sent to the king of Assyria to Lachish, saying, I have offended; return from me: that which thou puttest on me will I bear. And the king of Assyria appointed unto Hezekiah king of Judah three hundred talents of silver and thirty talents of gold."}, {"numero": 15, "texto": "And Hezekiah gave him all the silver that was found in the house of the Lord, and in the treasures of the king''s house."}, {"numero": 16, "texto": "At that time did Hezekiah cut off the gold from the doors of the temple of the Lord, and from the pillars which Hezekiah king of Judah had overlaid, and gave it to the king of Assyria."}, {"numero": 17, "texto": "And the king of Assyria sent Tartan and Rabsaris and Rabshakeh from Lachish to king Hezekiah with a great host against Jerusalem. And they went up and came to Jerusalem. And when they were come up, they came and stood by the conduit of the upper pool, which is in the highway of the fuller''s field."}, {"numero": 18, "texto": "And when they had called to the king, there came out to them Eliakim the son of Hilkiah, which was over the household, and Shebna the scribe, and Joah the son of Asaph the recorder."}, {"numero": 19, "texto": "And Rabshakeh said unto them, Speak ye now to Hezekiah, Thus saith the great king, the king of Assyria, What confidence is this wherein thou trustest?"}, {"numero": 20, "texto": "Thou sayest, (but they are but vain words,) I have counsel and strength for the war. Now on whom dost thou trust, that thou rebellest against me?"}, {"numero": 21, "texto": "Now, behold, thou trustest upon the staff of this bruised reed, even upon Egypt, on which if a man lean, it will go into his hand, and pierce it: so is Pharaoh king of Egypt unto all that trust on him."}, {"numero": 22, "texto": "But if ye say unto me, We trust in the Lord our God: is not that he, whose high places and whose altars Hezekiah hath taken away, and hath said to Judah and Jerusalem, Ye shall worship before this altar in Jerusalem?"}, {"numero": 23, "texto": "Now therefore, I pray thee, give pledges to my lord the king of Assyria, and I will deliver thee two thousand horses, if thou be able on thy part to set riders upon them."}, {"numero": 24, "texto": "How then wilt thou turn away the face of one captain of the least of my master''s servants, and put thy trust on Egypt for chariots and for horsemen?"}, {"numero": 25, "texto": "Am I now come up without the Lord against this place to destroy it? The Lord said to me, Go up against this land, and destroy it."}, {"numero": 26, "texto": "Then said Eliakim the son of Hilkiah, and Shebna, and Joah, unto Rabshakeh, Speak, I pray thee, to thy servants in the Syrian language; for we understand it: and talk not with us in the Jews'' language in the ears of the people that are on the wall."}, {"numero": 27, "texto": "But Rabshakeh said unto them, Hath my master sent me to thy master, and to thee, to speak these words? hath he not sent me to the men which sit on the wall, that they may eat their own dung, and drink their own piss with you?"}, {"numero": 28, "texto": "Then Rabshakeh stood and cried with a loud voice in the Jews'' language, and spake, saying, Hear the word of the great king, the king of Assyria:"}, {"numero": 29, "texto": "Thus saith the king, Let not Hezekiah deceive you: for he shall not be able to deliver you out of his hand:"}, {"numero": 30, "texto": "Neither let Hezekiah make you trust in the Lord, saying, The Lord will surely deliver us, and this city shall not be delivered into the hand of the king of Assyria."}, {"numero": 31, "texto": "Hearken not to Hezekiah: for thus saith the king of Assyria, Make an agreement with me by a present, and come out to me, and then eat ye every man of his own vine, and every one of his fig tree, and drink ye every one the waters of his cistern:"}, {"numero": 32, "texto": "Until I come and take you away to a land like your own land, a land of corn and wine, a land of bread and vineyards, a land of oil olive and of honey, that ye may live, and not die: and hearken not unto Hezekiah, when he persuadeth you, saying, The Lord will deliver us."}, {"numero": 33, "texto": "Hath any of the gods of the nations delivered at all his land out of the hand of the king of Assyria?"}, {"numero": 34, "texto": "Where are the gods of Hamath, and of Arpad? where are the gods of Sepharvaim, Hena, and Ivah? have they delivered Samaria out of mine hand?"}, {"numero": 35, "texto": "Who are they among all the gods of the countries, that have delivered their country out of mine hand, that the Lord should deliver Jerusalem out of mine hand?"}, {"numero": 36, "texto": "But the people held their peace, and answered him not a word: for the king''s commandment was, saying, Answer him not."}, {"numero": 37, "texto": "Then came Eliakim the son of Hilkiah, which was over the household, and Shebna the scribe, and Joah the son of Asaph the recorder, to Hezekiah with their clothes rent, and told him the words of Rabshakeh."}]'::jsonb, 'King James Version'),
  ('2Rs', 18, 'fr', '[{"numero": 1, "texto": "La troisième année d''''Osée, fils d''''Ela, roi d''''Israël, Ezéchias, fils d''''Achaz, roi de Juda, régna."}, {"numero": 2, "texto": "Il avait vingt-cinq ans lorsqu''''il devint roi, et il régna vingt-neuf ans à Jérusalem. Sa mère s''''appelait Abi, fille de Zacharie."}, {"numero": 3, "texto": "Il fit ce qui est droit aux yeux de l''''Eternel, entièrement comme avait fait David, son père."}, {"numero": 4, "texto": "Il fit disparaître les hauts lieux, brisa les statues, abattit les idoles, et mit en pièces le serpent d''''airain que Moïse avait fait, car les enfants d''''Israël avaient jusqu''''alors brûlé des parfums devant lui: on l''''appelait Nehuschtan."}, {"numero": 5, "texto": "Il mit sa confiance en l''''Eternel, le Dieu d''''Israël; et parmi tous les rois de Juda qui vinrent après lui ou qui le précédèrent, il n''''y en eut point de semblable à lui."}, {"numero": 6, "texto": "Il fut attaché à l''''Eternel, il ne se détourna point de lui, et il observa les commandements que l''''Eternel avait prescrits à Moïse."}, {"numero": 7, "texto": "Et l''''Eternel fut avec Ezéchias, qui réussit dans toutes ses entreprises. Il se révolta contre le roi d''''Assyrie, et ne lui fut plus assujetti."}, {"numero": 8, "texto": "Il battit les Philistins jusqu''''à Gaza, et ravagea leur territoire depuis les tours des gardes jusqu''''aux villes fortes."}, {"numero": 9, "texto": "La quatrième année du roi Ezéchias, qui était la septième année d''''Osée, fils d''''Ela, roi d''''Israël, Salmanasar, roi d''''Assyrie, monta contre Samarie et l''''assiégea."}, {"numero": 10, "texto": "Il la prit au bout de trois ans, la sixième année d''''Ezéchias, qui était la neuvième année d''''Osée, roi d''''Israël: alors Samarie fut prise."}, {"numero": 11, "texto": "Le roi d''''Assyrie emmena Israël captif en Assyrie, et il les établit à Chalach, et sur le Chabor, fleuve de Gozan, et dans les villes des Mèdes,"}, {"numero": 12, "texto": "parce qu''''ils n''''avaient point écouté la voix de l''''Eternel, leur Dieu, et qu''''ils avaient transgressé son alliance, parce qu''''ils n''''avaient ni écouté ni mis en pratique tout ce qu''''avait ordonné Moïse, serviteur de l''''Eternel."}, {"numero": 13, "texto": "La quatorzième année du roi Ezéchias, Sanchérib, roi d''''Assyrie, monta contre toutes les villes fortes de Juda, et s''''en empara."}, {"numero": 14, "texto": "Ezéchias, roi de Juda, envoya dire au roi d''''Assyrie à Lakis: J''''ai commis une faute! Eloigne-toi de moi. Ce que tu m''''imposeras, je le supporterai. Et le roi d''''Assyrie imposa à Ezéchias, roi de Juda, trois cents talents d''''argent et trente talents d''''or."}, {"numero": 15, "texto": "Ezéchias donna tout l''''argent qui se trouvait dans la maison de l''''Eternel et dans les trésors de la maison du roi."}, {"numero": 16, "texto": "Ce fut alors qu''''Ezéchias, roi de Juda, enleva, pour les livrer au roi d''''Assyrie, les lames d''''or dont il avait couvert les portes et les linteaux du temple de l''''Eternel."}, {"numero": 17, "texto": "Le roi d''''Assyrie envoya de Lakis à Jérusalem, vers le roi Ezéchias, Tharthan, Rab-Saris et Rabschaké avec une puissante armée. Ils montèrent, et ils arrivèrent à Jérusalem. Lorsqu''''ils furent montés et arrivés, ils s''''arrêtèrent à l''''aqueduc de l''''étang supérieur, sur le chemin du champ du foulon."}, {"numero": 18, "texto": "Ils appelèrent le roi; et Eliakim, fils de Hilkija, chef de la maison du roi, se rendit auprès d''''eux, avec Schebna, le secrétaire, et Joach, fils d''''Asaph, l''''archiviste."}, {"numero": 19, "texto": "Rabschaké leur dit: Dites à Ezéchias: Ainsi parle le grand roi, le roi d''''Assyrie: Quelle est cette confiance, sur laquelle tu t''''appuies?"}, {"numero": 20, "texto": "Tu as dit: Il faut pour la guerre de la prudence et de la force. Mais ce ne sont que des paroles en l''''air. En qui donc as-tu placé ta confiance, pour t''''être révolté contre moi?"}, {"numero": 21, "texto": "Voici, tu l''''as placée dans l''''Egypte, tu as pris pour soutien ce roseau cassé, qui pénètre et perce la main de quiconque s''''appuie dessus: tel est Pharaon, roi d''''Egypte, pour tous ceux qui se confient en lui."}, {"numero": 22, "texto": "Peut-être me direz-vous: C''''est en l''''Eternel, notre Dieu, que nous nous confions. Mais n''''est-ce pas lui dont Ezéchias a fait disparaître les hauts lieux et les autels, en disant à Juda et à Jérusalem: Vous vous prosternerez devant cet autel à Jérusalem?"}, {"numero": 23, "texto": "Maintenant, fais une convention avec mon maître, le roi d''''Assyrie, et je te donnerai deux mille chevaux, si tu peux fournir des cavaliers pour les monter."}, {"numero": 24, "texto": "Comment repousserais-tu un seul chef d''''entre les moindres serviteurs de mon maître? Tu mets ta confiance dans l''''Egypte pour les chars et pour les cavaliers."}, {"numero": 25, "texto": "D''''ailleurs, est-ce sans la volonté de l''''Eternel que je suis monté contre ce lieu, pour le détruire? L''''Eternel m''''a dit: Monte contre ce pays, et détruis-le."}, {"numero": 26, "texto": "Eliakim, fils de Hilkija, Schebna et Joach, dirent à Rabschaké: Parle à tes serviteurs en araméen, car nous le comprenons; et ne nous parle pas en langue judaïque, aux oreilles du peuple qui est sur la muraille."}, {"numero": 27, "texto": "Rabschaké leur répondit: Est-ce à ton maître et à toi que mon maître m''''a envoyé dire ces paroles? N''''est-ce pas à ces hommes assis sur la muraille pour manger leurs excréments et pour boire leur urine avec vous?"}, {"numero": 28, "texto": "Alors Rabschaké, s''''étant avancé, cria à haute voix en langue judaïque, et dit: Ecoutez la parole du grand roi, du roi d''''Assyrie!"}, {"numero": 29, "texto": "Ainsi parle le roi: Qu''''Ezéchias ne vous abuse point, car il ne pourra vous délivrer de ma main."}, {"numero": 30, "texto": "Qu''''Ezéchias ne vous amène point à vous confier en l''''Eternel, en disant: L''''Eternel nous délivrera, et cette ville ne sera pas livrée entre les mains du roi d''''Assyrie."}, {"numero": 31, "texto": "N''''écoutez point Ezéchias; car ainsi parle le roi d''''Assyrie: Faites la paix avec moi, rendez-vous à moi, et chacun de vous mangera de sa vigne et de son figuier, et chacun boira de l''''eau de sa citerne,"}, {"numero": 32, "texto": "jusqu''''à ce que je vienne, et que je vous emmène dans un pays comme le vôtre, dans un pays de blé et de vin, un pays de pain et de vignes, un pays d''''oliviers à huile et de miel, et vous vivrez et vous ne mourrez point. N''''écoutez donc point Ezéchias; car il pourrait vous séduire en disant: L''''Eternel nous délivrera."}, {"numero": 33, "texto": "Les dieux des nations ont-ils délivré chacun son pays de la main du roi d''''Assyrie?"}, {"numero": 34, "texto": "Où sont les dieux de Hamath et d''''Arpad? Où sont les dieux de Sepharvaïm, d''''Héna et d''''Ivva? Ont-ils délivré Samarie de ma main?"}, {"numero": 35, "texto": "Parmi tous les dieux de ces pays, quels sont ceux qui ont délivré leur pays de ma main, pour que l''''Eternel délivre Jérusalem de ma main?"}, {"numero": 36, "texto": "Le peuple se tut, et ne lui répondit pas un mot; car le roi avait donné cet ordre: Vous ne lui répondrez pas."}, {"numero": 37, "texto": "Et Eliakim, fils de Hilkija, chef de la maison du roi, Schebna, le secrétaire, et Joach, fils d''''Asaph, l''''archiviste, vinrent auprès d''''Ezéchias, les vêtements déchirés, et lui rapportèrent les paroles de Rabschaké."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 18, 'es', '[{"numero": 1, "texto": "EN el tercer año de Oseas hijo de Ela rey de Israel, comenzó á reinar Ezechîas hijo de Achâz rey de Judá."}, {"numero": 2, "texto": "Cuando comenzó á reinar era de veinticinco años, y reinó en Jerusalem veintinueve años. El nombre de su madre fué Abi hija de Zachârías."}, {"numero": 3, "texto": "Hizo lo recto en ojos de Jehová, conforme á todas las cosas que había hecho David su padre."}, {"numero": 4, "texto": "El quitó los altos, y quebró las imágenes, y taló los bosques, é hizo pedazos la serpiente de bronce que había hecho Moisés, porque hasta entonces le quemaban perfumes los hijos de Israel; y llamóle por nombre Nehustán."}, {"numero": 5, "texto": "En Jehová Dios de Israel puso su esperanza: después ni antes de él no hubo otro como él en todos los reyes de Judá."}, {"numero": 6, "texto": "Porque se llegó á Jehová, y no se apartó de él, sino que guardó los mandamientos que Jehová prescribió á Moisés."}, {"numero": 7, "texto": "Y Jehová fué con él; y en todas las cosas á que salía prosperaba. El se rebeló contra el rey de Asiria, y no le sirvió."}, {"numero": 8, "texto": "Hirió también á los Filisteos hasta Gaza y sus términos, desde las torres de las atalayas hasta la ciudad fortalecida."}, {"numero": 9, "texto": "En el cuarto año del rey Ezechîas, que era el año séptimo de Oseas hijo de Ela rey de Israel, subió Salmanasar rey de los Asirios contra Samaria, y cercóla."}, {"numero": 10, "texto": "Y tomáronla al cabo de tres años; esto es, en el sexto año de Ezechîas, el cual era el año nono de Oseas rey de Israel, fué Samaria tomada."}, {"numero": 11, "texto": "Y el rey de Asiria traspuso á Israel á Asiria, y púsolos en Hala, y en Habor, junto al río de Gozán, y en las ciudades de los Medos:"}, {"numero": 12, "texto": "Por cuanto no habían atendido la voz de Jehová su Dios, antes habían quebrantado su pacto; y todas las cosas que Moisés siervo de Jehová había mandado, ni las habían escuchado, ni puesto por obra."}, {"numero": 13, "texto": "Y á los catorce años del rey Ezechîas, subió Sennachêrib rey de Asiria contra todas las ciudades fuertes de Judá, y tomólas."}, {"numero": 14, "texto": "Entonces Ezechîas rey de Judá envió á decir al rey de Asiria en Lachîs: Yo he pecado: vuélvete de mí, y llevaré todo lo que me impusieres. Y el rey de Asiria impuso á Ezechîas rey de Judá trescientos talentos de plata, y treinta talentos de oro."}, {"numero": 15, "texto": "Dió por tanto Ezechîas toda la plata que fué hallada en la casa de Jehová, y en los tesoros de la casa real."}, {"numero": 16, "texto": "Entonces descompuso Ezechîas las puertas del templo de Jehová, y los quiciales que el mismo rey Ezechîas había cubierto de oro, y diólo al rey de Asiria."}, {"numero": 17, "texto": "Después el rey de Asiria envió al rey Ezechîas, desde Lachîs contra Jerusalem, á Thartán y á Rabsaris y á Rabsaces, con un grande ejército: y subieron, y vinieron á Jerusalem. Y habiendo subido, vinieron y pararon junto al conducto del estanque de arriba, que es en el camino de la heredad del batanero."}, {"numero": 18, "texto": "Llamaron luego al rey, y salió á ellos Eliacim hijo de Hilcías, que era mayordomo, y Sebna escriba, y Joah hijo de Asaph, canciller."}, {"numero": 19, "texto": "Y díjoles Rabsaces: Decid ahora á Ezechîas: Así dice el gran rey de Asiria: ¿Qué confianza es esta en que tú estás?"}, {"numero": 20, "texto": "Dices, (por cierto palabras de labios): Consejo tengo y esfuerzo para la guerra. Mas ¿en qué confías, que te has rebelado contra mí?"}, {"numero": 21, "texto": "He aquí tú confías ahora en este bordón de caña cascada, en Egipto, en el que si alguno se apoyare, entrarále por la mano, y se le pasará. Tal es Faraón rey de Egipto, para todos los que en él confían."}, {"numero": 22, "texto": "Y si me decís: Nosotros confiamos en Jehová nuestro Dios: ¿no es aquél cuyos altos y altares ha quitado Ezechîas, y ha dicho á Judá y á Jerusalem: Delante de este altar adoraréis en Jerusalem?"}, {"numero": 23, "texto": "Por tanto, ahora yo te ruego que des rehenes á mi señor, el rey de Asiria, y yo te daré dos mil caballos, si tú pudieres dar jinetes para ellos."}, {"numero": 24, "texto": "¿Cómo pues harás volver el rostro de un capitán el menor de los siervos de mi señor, aunque estés confiado en Egipto por sus carros y su gente de á caballo?"}, {"numero": 25, "texto": "Además, ¿he venido yo ahora sin Jehová á este lugar, para destruirlo? Jehová me ha dicho: Sube á esta tierra, y destrúyela."}, {"numero": 26, "texto": "Entonces dijo Eliacim hijo de Hilcías, y Sebna y Joah, á Rabsaces: Ruégote que hables á tus siervos siriaco, porque nosotros lo entendemos, y no hables con nosotros judaico á oídos del pueblo que está sobre el muro."}, {"numero": 27, "texto": "Y Rabsaces les dijo: ¿Hame enviado mi señor á ti y á tu señor para decir estas palabras, y no antes á los hombres que están sobre el muro, para comer su estiércol, y beber el agua de sus pies con vosotros?"}, {"numero": 28, "texto": "Paróse luego Rabsaces, y clamó á gran voz en judaico, y habló, diciendo: Oid la palabra del gran rey, el rey de Asiria."}, {"numero": 29, "texto": "Así ha dicho el rey: No os engañe Ezechîas, porque no os podrá librar de mi mano."}, {"numero": 30, "texto": "Y no os haga Ezechîas confiar en Jehová, diciendo: De cierto nos librará Jehová, y esta ciudad no será entregada en mano del rey de Asiria."}, {"numero": 31, "texto": "No oigáis á Ezechîas, porque así dice el rey de Asiria: Haced conmigo paz, y salid á mí, y cada uno comerá de su vid, y de su higuera, y cada uno beberá las aguas de su pozo;"}, {"numero": 32, "texto": "Hasta que yo venga, y os lleve á una tierra como la vuestra, tierra de grano y de vino, tierra de pan y de viñas, tierra de olivas, de aceite, y de miel; y viviréis, y no moriréis. No oigáis á Ezechîas, porque os engaña cuando dice: Jehová nos librará."}, {"numero": 33, "texto": "¿Acaso alguno de los dioses de las gentes ha librado su tierra de la mano del rey de Asiria?"}, {"numero": 34, "texto": "¿Dónde está el dios de Hamath, y de Arphad? ¿dónde el dios de Sepharvaim, de Hena, y de Hiva? ¿pudieron éstos librar á Samaria de mi mano?"}, {"numero": 35, "texto": "¿Qué dios de todos los dioses de las provincias ha librado á su provincia de mi mano, para que libre Jehová de mi mano á Jerusalem?"}, {"numero": 36, "texto": "Y el pueblo calló, que no le respondieron palabra: porque había mandamiento del rey, el cual había dicho: No le respondáis."}, {"numero": 37, "texto": "Entonces Eliacim hijo de Hilcías, que era mayordomo, y Sebna el escriba, y Joah hijo de Asaph, canciller, vinieron á Ezechîas, rotos sus vestidos, y recitáronle las palabras de Rabsaces."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 19, 'pt', '[{"numero": 1, "texto": "E quando o rei Ezequias o ouviu, rasgou suas roupas, e cobriu-se de saco, e entrou-se na casa do SENHOR."}, {"numero": 2, "texto": "E enviou a Eliaquim o mordomo, e a Sebna escriba, e aos anciãos dos sacerdotes, vestidos de sacos a Isaías profeta filho de Amoz,"}, {"numero": 3, "texto": "Que lhe dissessem: Assim disse Ezequias: Este dia é dia de angústia, e de repreensão, e de blasfêmia; porque os filhos vieram até o ponto do parto, mas a que dá à luz não tem forças."}, {"numero": 4, "texto": "Talvez ouvirá o SENHOR tua Deus todas as palavras de Rabsaqué, ao qual o rei dos assírios, seu senhor, enviou para afrontar o Deus vivo, e repreenderá pelas palavras que o SENHOR teu Deus ouviu: portanto, eleva oração pelos restantes que ainda continuam."}, {"numero": 5, "texto": "Vieram, pois, os servos do rei Ezequias a Isaías."}, {"numero": 6, "texto": "E Isaías lhes respondeu: Assim direis a vosso senhor: Assim disse o SENHOR; Não temas pelas palavras que ouviste, com as quais me blasfemaram os servos do rei da Assíria."}, {"numero": 7, "texto": "Eis que porei eu nele um espírito, e ouvirá rumor, e se voltará à sua terra: e eu farei que em sua terra caia à espada."}, {"numero": 8, "texto": "E regressando Rabsaqué, achou ao rei da Assíria combatendo a Libna; porque havia ouvido que se havia partido de Laquis."}, {"numero": 9, "texto": "E ouviu dizer de Tiraca rei de Etiópia: Eis que saiu para fazer-te guerra. Então voltou ele, e enviou embaixadores a Ezequias, dizendo:"}, {"numero": 10, "texto": "Assim direis a Ezequias rei de Judá: Não te engane teu Deus em quem tu confias, para dizer: Jerusalém não será entregue em mão do rei da Assíria."}, {"numero": 11, "texto": "Eis que tu ouviste o que fizeram os reis da Assíria a todas as terras, destruindo-as; e hás tu de escapar?"}, {"numero": 12, "texto": "Livraram-nas os deuses das nações, que meus pais destruíram, a saber, Gozã, e Harã, e Rezefe, e os filhos de Éden que estavam em Telassar?"}, {"numero": 13, "texto": "Onde está o rei de Hamate, o rei de Arpade, o rei da cidade de Sefarvaim, de Hena, e de Iva?"}, {"numero": 14, "texto": "E tomou Ezequias as cartas da mão dos embaixadores; e depois que as leu, subiu à casa do SENHOR, e estendeu-as Ezequias diante do SENHOR."}, {"numero": 15, "texto": "E orou Ezequias diante do SENHOR, dizendo: SENHOR Deus de Israel, que habitas entre os querubins, tu só és Deus de todos os reinos da terra; tu fizeste o céu e a terra."}, {"numero": 16, "texto": "Inclina, ó SENHOR, teu ouvido, e ouve; abre, ó SENHOR, teus olhos, e olha: e ouve as palavras de Senaqueribe, que enviou a blasfemar ao Deus vivente."}, {"numero": 17, "texto": "É verdade, ó SENHOR, que os reis da Assíria destruíram as nações e suas terras;"}, {"numero": 18, "texto": "E que puseram no fogo a seus deuses, porquanto eles não eram deuses, mas sim obra de mãos de homens, madeira ou pedra, e assim os destruíram."}, {"numero": 19, "texto": "Agora, pois, ó SENHOR Deus nosso, salva-nos, te suplico, de sua mão, para que saibam todos os reinos da terra que só tu, SENHOR, és Deus."}, {"numero": 20, "texto": "Então Isaías filho de Amoz enviou a dizer a Ezequias: Assim disse o SENHOR, Deus de Israel: O que me rogaste acerca de Senaqueribe rei da Assíria, ouvi."}, {"numero": 21, "texto": "Esta é a palavra que o SENHOR falou contra ele: Menosprezou-te, escarneceu-te a virgem filha de Sião; moveu sua cabeça detrás de ti a filha de Jerusalém."}, {"numero": 22, "texto": "A quem afrontaste e a quem blasfemaste? E contra quem falaste alto, e levantaste em alto teus olhos? Contra o Santo de Israel."}, {"numero": 23, "texto": "Por meio de teus mensageiros proferiste afronta contra o Senhor, e disseste: Com a multidão de meus carros subi aos cumes dos montes, às costas do Líbano; e cortarei seus altos cedros, suas faias escolhidas; e entrarei à morada de seu termo, à floresta de seu terreno fértil."}, {"numero": 24, "texto": "Eu cavei e bebi as águas alheias, e sequei com as plantas de meus pés todos os rios de lugares bloqueados."}, {"numero": 25, "texto": "Nunca ouviste que há muito tempo eu o fiz, e de dias antigos o formei? E agora o fiz vir, e foi para desolação de cidades fortes em amontoados de ruínas."}, {"numero": 26, "texto": "E seus moradores, fracos de mãos, quebrantados e confusos, foram qual erva do campo, como hortaliça verde, e feno dos telhados, que antes que venha a maturidade é seco."}, {"numero": 27, "texto": "Eu soube teu assentar-te, teu sair e teu entrar, e teu furor contra mim."}, {"numero": 28, "texto": "Porquanto te iraste contra mim, e teu estrondo subiu a meus ouvidos, eu, portanto, porei meu anzol em tuas narinas, e meu freio em teus lábios, e te farei voltar pelo caminho por onde vieste."}, {"numero": 29, "texto": "E isto te será por sinal Ezequias: Este ano comerás o que nascerá de si mesmo, e no segundo ano o que nascerá de si mesmo; e ao terceiro ano semeareis, e colhereis, e plantareis vinhas, e comereis o fruto delas."}, {"numero": 30, "texto": "E o que houver escapado, o que haverá restado da casa de Judá, voltará a lançar raiz abaixo, e dará fruto acima."}, {"numero": 31, "texto": "Porque sairão de Jerusalém remanescentes, e os que escaparão, do monte de Sião: o zelo do SENHOR dos exércitos fará isto."}, {"numero": 32, "texto": "Portanto, o SENHOR diz assim do rei da Assíria: Não entrará nesta cidade, nem lançará flecha nela; nem virá diante dela escudo, nem será levantado baluarte contra ela."}, {"numero": 33, "texto": "Pelo caminho que veio se voltará, e não entrará nesta cidade, diz o SENHOR."}, {"numero": 34, "texto": "Porque eu ampararei a esta cidade para salvá-la, por causa de mim, e por causa de Davi meu servo."}, {"numero": 35, "texto": "E aconteceu que a mesma noite saiu o anjo do SENHOR, e feriu no campo dos assírios cento oitenta e cinco mil; e quando se levantaram pela manhã, eis que eram todos cadáveres."}, {"numero": 36, "texto": "Então Senaqueribe, rei da Assíria, partiu-se, e se foi e voltou a Nínive, onde ficou."}, {"numero": 37, "texto": "E aconteceu que, estando ele adorando no templo de Nisroque seu deus, Adrameleque e Sarezer seus filhos o feriram à espada; e fugiram-se à terra de Ararate. E reinou em seu lugar Esar-Hadom seu filho."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 19, 'en', '[{"numero": 1, "texto": "And it came to pass, when king Hezekiah heard it, that he rent his clothes, and covered himself with sackcloth, and went into the house of the Lord."}, {"numero": 2, "texto": "And he sent Eliakim, which was over the household, and Shebna the scribe, and the elders of the priests, covered with sackcloth, to Isaiah the prophet the son of Amoz."}, {"numero": 3, "texto": "And they said unto him, Thus saith Hezekiah, This day is a day of trouble, and of rebuke, and blasphemy; for the children are come to the birth, and there is not strength to bring forth."}, {"numero": 4, "texto": "It may be the Lord thy God will hear all the words of Rabshakeh, whom the king of Assyria his master hath sent to reproach the living God; and will reprove the words which the Lord thy God hath heard: wherefore lift up thy prayer for the remnant that are left."}, {"numero": 5, "texto": "So the servants of king Hezekiah came to Isaiah."}, {"numero": 6, "texto": "And Isaiah said unto them, Thus shall ye say to your master, Thus saith the Lord, Be not afraid of the words which thou hast heard, with which the servants of the king of Assyria have blasphemed me."}, {"numero": 7, "texto": "Behold, I will send a blast upon him, and he shall hear a rumour, and shall return to his own land; and I will cause him to fall by the sword in his own land."}, {"numero": 8, "texto": "So Rabshakeh returned, and found the king of Assyria warring against Libnah: for he had heard that he was departed from Lachish."}, {"numero": 9, "texto": "And when he heard say of Tirhakah king of Ethiopia, Behold, he is come out to fight against thee: he sent messengers again unto Hezekiah, saying,"}, {"numero": 10, "texto": "Thus shall ye speak to Hezekiah king of Judah, saying, Let not thy God in whom thou trustest deceive thee, saying, Jerusalem shall not be delivered into the hand of the king of Assyria."}, {"numero": 11, "texto": "Behold, thou hast heard what the kings of Assyria have done to all lands, by destroying them utterly: and shalt thou be delivered?"}, {"numero": 12, "texto": "Have the gods of the nations delivered them which my fathers have destroyed; as Gozan, and Haran, and Rezeph, and the children of Eden which were in Thelasar?"}, {"numero": 13, "texto": "Where is the king of Hamath, and the king of Arpad, and the king of the city of Sepharvaim, of Hena, and Ivah?"}, {"numero": 14, "texto": "And Hezekiah received the letter of the hand of the messengers, and read it: and Hezekiah went up into the house of the Lord, and spread it before the Lord."}, {"numero": 15, "texto": "And Hezekiah prayed before the Lord, and said, O Lord God of Israel, which dwellest between the cherubims, thou art the God, even thou alone, of all the kingdoms of the earth; thou hast made heaven and earth."}, {"numero": 16, "texto": "Lord, bow down thine ear, and hear: open, Lord, thine eyes, and see: and hear the words of Sennacherib, which hath sent him to reproach the living God."}, {"numero": 17, "texto": "Of a truth, Lord, the kings of Assyria have destroyed the nations and their lands,"}, {"numero": 18, "texto": "And have cast their gods into the fire: for they were no gods, but the work of men''s hands, wood and stone: therefore they have destroyed them."}, {"numero": 19, "texto": "Now therefore, O Lord our God, I beseech thee, save thou us out of his hand, that all the kingdoms of the earth may know that thou art the Lord God, even thou only."}, {"numero": 20, "texto": "Then Isaiah the son of Amoz sent to Hezekiah, saying, Thus saith the Lord God of Israel, That which thou hast prayed to me against Sennacherib king of Assyria I have heard."}, {"numero": 21, "texto": "This is the word that the Lord hath spoken concerning him; The virgin the daughter of Zion hath despised thee, and laughed thee to scorn; the daughter of Jerusalem hath shaken her head at thee."}, {"numero": 22, "texto": "Whom hast thou reproached and blasphemed? and against whom hast thou exalted thy voice, and lifted up thine eyes on high? even against the Holy One of Israel."}, {"numero": 23, "texto": "By thy messengers thou hast reproached the Lord, and hast said, With the multitude of my chariots I am come up to the height of the mountains, to the sides of Lebanon, and will cut down the tall cedar trees thereof, and the choice fir trees thereof: and I will enter into the lodgings of his borders, and into the forest of his Carmel."}, {"numero": 24, "texto": "I have digged and drunk strange waters, and with the sole of my feet have I dried up all the rivers of besieged places."}, {"numero": 25, "texto": "Hast thou not heard long ago how I have done it, and of ancient times that I have formed it? now have I brought it to pass, that thou shouldest be to lay waste fenced cities into ruinous heaps."}, {"numero": 26, "texto": "Therefore their inhabitants were of small power, they were dismayed and confounded; they were as the grass of the field, and as the green herb, as the grass on the house tops, and as corn blasted before it be grown up."}, {"numero": 27, "texto": "But I know thy abode, and thy going out, and thy coming in, and thy rage against me."}, {"numero": 28, "texto": "Because thy rage against me and thy tumult is come up into mine ears, therefore I will put my hook in thy nose, and my bridle in thy lips, and I will turn thee back by the way by which thou camest."}, {"numero": 29, "texto": "And this shall be a sign unto thee, Ye shall eat this year such things as grow of themselves, and in the second year that which springeth of the same; and in the third year sow ye, and reap, and plant vineyards, and eat the fruits thereof."}, {"numero": 30, "texto": "And the remnant that is escaped of the house of Judah shall yet again take root downward, and bear fruit upward."}, {"numero": 31, "texto": "For out of Jerusalem shall go forth a remnant, and they that escape out of mount Zion: the zeal of the Lord of hosts shall do this."}, {"numero": 32, "texto": "Therefore thus saith the Lord concerning the king of Assyria, He shall not come into this city, nor shoot an arrow there, nor come before it with shield, nor cast a bank against it."}, {"numero": 33, "texto": "By the way that he came, by the same shall he return, and shall not come into this city, saith the Lord."}, {"numero": 34, "texto": "For I will defend this city, to save it, for mine own sake, and for my servant David''s sake."}, {"numero": 35, "texto": "And it came to pass that night, that the angel of the Lord went out, and smote in the camp of the Assyrians an hundred fourscore and five thousand: and when they arose early in the morning, behold, they were all dead corpses."}, {"numero": 36, "texto": "So Sennacherib king of Assyria departed, and went and returned, and dwelt at Nineveh."}, {"numero": 37, "texto": "And it came to pass, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer his sons smote him with the sword: and they escaped into the land of Armenia. And Esarhaddon his son reigned in his stead."}]'::jsonb, 'King James Version'),
  ('2Rs', 19, 'fr', '[{"numero": 1, "texto": "Lorsque le roi Ezéchias eut entendu cela, il déchira ses vêtements, se couvrit d''''un sac, et alla dans la maison de l''''Eternel."}, {"numero": 2, "texto": "Il envoya Eliakim, chef de la maison du roi, Schebna, le secrétaire, et les plus anciens des sacrificateurs, couverts de sacs, vers Esaïe, le prophète, fils d''''Amots."}, {"numero": 3, "texto": "Et ils lui dirent: Ainsi parle Ezéchias: Ce jour est un jour d''''angoisse, de châtiment et d''''opprobre; car les enfants sont près de sortir du sein maternel, et il n''''y a point de force pour l''''enfantement."}, {"numero": 4, "texto": "Peut-être l''''Eternel, ton Dieu, a-t-il entendu toutes les paroles de Rabschaké, que le roi d''''Assyrie, son maître, a envoyé pour insulter au Dieu vivant, et peut-être l''''Eternel, ton Dieu, exercera-t-il ses châtiments à cause des paroles qu''''il a entendues. Fais donc monter une prière pour le reste qui subsiste encore."}, {"numero": 5, "texto": "Les serviteurs du roi Ezéchias allèrent donc auprès d''''Esaïe."}, {"numero": 6, "texto": "Et Esaïe leur dit: Voici ce que vous direz à votre maître: Ainsi parle l''''Eternel: Ne t''''effraie point des paroles que tu as entendues et par lesquelles m''''ont outragé les serviteurs du roi d''''Assyrie."}, {"numero": 7, "texto": "Je vais mettre en lui un esprit tel que, sur une nouvelle qu''''il recevra, il retournera dans son pays; et je le ferai tomber par l''''épée dans son pays."}, {"numero": 8, "texto": "Rabschaké, s''''étant retiré, trouva le roi d''''Assyrie qui attaquait Libna, car il avait appris son départ de Lakis."}, {"numero": 9, "texto": "Alors le roi d''''Assyrie reçut une nouvelle au sujet de Tirhaka, roi d''''Ethiopie; on lui dit: Voici, il s''''est mis en marche pour te faire la guerre. Et le roi d''''Assyrie envoya de nouveau des messagers à Ezéchias, en disant:"}, {"numero": 10, "texto": "Vous parlerez ainsi à Ezéchias, roi de Juda: Que ton Dieu, auquel tu te confies, ne t''''abuse point en disant: Jérusalem ne sera pas livrée entre les mains du roi d''''Assyrie."}, {"numero": 11, "texto": "Voici, tu as appris ce qu''''ont fait les rois d''''Assyrie à tous les pays, et comment ils les ont détruits; et toi, tu serais délivré!"}, {"numero": 12, "texto": "Les dieux des nations que mes pères ont détruites les ont-ils délivrées, Gozan, Charan, Retseph, et les fils d''''Eden qui sont à Telassar?"}, {"numero": 13, "texto": "Où sont le roi de Hamath, le roi d''''Arpad, et le roi de la ville de Sepharvaïm, d''''Héna et d''''Ivva?"}, {"numero": 14, "texto": "Ezéchias prit la lettre de la main des messagers, et la lut. Puis il monta à la maison de l''''Eternel, et la déploya devant l''''Eternel,"}, {"numero": 15, "texto": "qui il adressa cette prière: Eternel, Dieu d''''Israël, assis sur les chérubins! C''''est toi qui es le seul Dieu de tous les royaumes de la terre, c''''est toi qui as fait les cieux et la terre."}, {"numero": 16, "texto": "Eternel! incline ton oreille, et écoute. Eternel! ouvre tes yeux, et regarde. Entends les paroles de Sanchérib, qui a envoyé Rabschaké pour insulter au Dieu vivant."}, {"numero": 17, "texto": "Il est vrai, ô Eternel! que les rois d''''Assyrie ont détruit les nations et ravagé leurs pays,"}, {"numero": 18, "texto": "et qu''''ils ont jeté leurs dieux dans le feu; mais ce n''''étaient point des dieux, c''''étaient des ouvrages de mains d''''homme, du bois et de la pierre; et ils les ont anéantis."}, {"numero": 19, "texto": "Maintenant, Eternel, notre Dieu! délivre-nous de la main de Sanchérib, et que tous les royaumes de la terre sachent que toi seul es Dieu, ô Eternel!"}, {"numero": 20, "texto": "Alors Esaïe, fils d''''Amots, envoya dire à Ezéchias: Ainsi parle l''''Eternel, le Dieu d''''Israël: J''''ai entendu la prière que tu m''''as adressée au sujet de Sanchérib, roi d''''Assyrie."}, {"numero": 21, "texto": "Voici la parole que l''''Eternel a prononcée contre lui: Elle te méprise, elle se moque de toi, La vierge, fille de Sion; Elle hoche la tête après toi, La fille de Jérusalem."}, {"numero": 22, "texto": "Qui as-tu insulté et outragé? Contre qui as-tu élevé la voix? Tu as porté tes yeux en haut Sur le Saint d''''Israël!"}, {"numero": 23, "texto": "Par tes messagers tu as insulté le Seigneur, Et tu as dit: Avec la multitude de mes chars, J''''ai gravi le sommet des montagnes, Les extrémités du Liban; Je couperai les plus élevés de ses cèdres, Les plus beaux de ses cyprès, Et j''''atteindrai sa dernière cime, Sa forêt semblable à un verger;"}, {"numero": 24, "texto": "J''''ai creusé, et j''''ai bu des eaux étrangères, Et je tarirai avec la plante de mes pieds Tous les fleuves de l''''Egypte."}, {"numero": 25, "texto": "N''''as-tu pas appris que j''''ai préparé ces choses de loin, Et que je les ai résolues dès les temps anciens? Maintenant j''''ai permis qu''''elles s''''accomplissent, Et que tu réduisisses des villes fortes en monceaux de ruines."}, {"numero": 26, "texto": "Leurs habitants sont impuissants, Epouvantés et confus; Ils sont comme l''''herbe des champs et la tendre verdure, Comme le gazon des toits Et le blé qui sèche avant la formation de sa tige."}, {"numero": 27, "texto": "Mais je sais quand tu t''''assieds, quand tu sors et quand tu entres, Et quand tu es furieux contre moi."}, {"numero": 28, "texto": "Parce que tu es furieux contre moi, Et que ton arrogance est montée à mes oreilles, Je mettrai ma boucle à tes narines et mon mors entre tes lèvres, Et je te ferai retourner par le chemin par lequel tu es venu."}, {"numero": 29, "texto": "Que ceci soit un signe pour toi: On a mangé une année le produit du grain tombé, et une seconde année ce qui croît de soi-même; mais la troisième année, vous sèmerez, vous moissonnerez, vous planterez des vignes, et vous en mangerez le fruit."}, {"numero": 30, "texto": "Ce qui aura été sauvé de la maison de Juda, ce qui sera resté poussera encore des racines par-dessous, et portera du fruit par-dessus."}, {"numero": 31, "texto": "Car de Jérusalem il sortira un reste, et de la montagne de Sion des réchappés. Voilà ce que fera le zèle de l''''Eternel des armées."}, {"numero": 32, "texto": "C''''est pourquoi ainsi parle l''''Eternel sur le roi d''''Assyrie: Il n''''entrera point dans cette ville, Il n''''y lancera point de traits, Il ne lui présentera point de boucliers, Et il n''''élèvera point de retranchements contre elle."}, {"numero": 33, "texto": "Il s''''en retournera par le chemin par lequel il est venu, Et il n''''entrera point dans cette ville, dit l''''Eternel."}, {"numero": 34, "texto": "Je protégerai cette ville pour la sauver, A cause de moi, et à cause de David, mon serviteur."}, {"numero": 35, "texto": "Cette nuit-là, l''''ange de l''''Eternel sortit, et frappa dans le camp des Assyriens cent quatre-vingt-cinq mille hommes. Et quand on se leva le matin, voici, c''''étaient tous des corps morts."}, {"numero": 36, "texto": "Alors Sanchérib, roi d''''Assyrie, leva son camp, partit et s''''en retourna; et il resta à Ninive."}, {"numero": 37, "texto": "Or, comme il était prosterné dans la maison de Nisroc, son dieu, Adrammélec et Scharetser, ses fils, le frappèrent avec l''''épée, et s''''enfuirent au pays d''''Ararat. Et Esar-Haddon, son fils, régna à sa place."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 19, 'es', '[{"numero": 1, "texto": "Y COMO el rey Ezechîas lo oyó, rasgó sus vestidos, y cubrióse de saco, y entróse en la casa de Jehová."}, {"numero": 2, "texto": "Y envió á Eliacim el mayordomo, y á Sebna escriba, y á los ancianos de los sacerdotes, vestidos de sacos á Isaías profeta hijo de Amós,"}, {"numero": 3, "texto": "Que le dijesen: Así ha dicho Ezechîas: Este día es día de angustia, y de reprensión, y de blasfemia; porque los hijos han venido hasta la rotura, y la que pare no tiene fuerzas."}, {"numero": 4, "texto": "Quizá oirá Jehová tu Dios todas las palabras de Rabsaces, al cual el rey de los Asirios su señor ha enviado para injuriar al Dios vivo, y á vituperar con palabras, las cuales Jehová tu Dios ha oído: por tanto, eleva oración por las reliquias que aun se hallan."}, {"numero": 5, "texto": "Vinieron pues los siervos del rey Ezechîas á Isaías."}, {"numero": 6, "texto": "E Isaías les respondió: Así diréis á vuestro señor: Así ha dicho Jehová; No temas por las palabras que has oído, con las cuales me han blasfemado los siervos del rey de Asiria."}, {"numero": 7, "texto": "He aquí pondré yo en él un espíritu, y oirá rumor, y volveráse á su tierra: y yo haré que en su tierra caiga á cuchillo."}, {"numero": 8, "texto": "Y regresando Rabsaces, halló al rey de Asiria combatiendo á Libna; porque había oído que se había partido de Lachîs."}, {"numero": 9, "texto": "Y oyó decir de Thiraca rey de Ethiopía: He aquí es salido para hacerte guerra. Entonces volvió él, y envió embajadores á Ezechîas, diciendo:"}, {"numero": 10, "texto": "Así diréis á Ezechîas rey de Judá: No te engañe tu Dios en quien tú confías, para decir: Jerusalem no será entregada en mano del rey de Asiria."}, {"numero": 11, "texto": "He aquí tú has oído lo que han hecho los reyes de Asiria á todas las tierras, destruyéndolas; ¿y has tú de escapar?"}, {"numero": 12, "texto": "¿Libráronlas los dioses de las gentes, que mis padres destruyeron, es á saber, Gozán, y Harán, y Reseph, y los hijos de Edén que estaban en Thalasar?"}, {"numero": 13, "texto": "¿Dónde está el rey de Hamath, el rey de Arphad, el rey de la ciudad de Sepharvaim, de Hena, y de Hiva?"}, {"numero": 14, "texto": "Y tomó Ezechîas las letras de mano de los embajadores; y después que las hubo leído, subió á la casa de Jehová, y extendiólas Ezechîas delante de Jehová."}, {"numero": 15, "texto": "Y oró Ezechîas delante de Jehová, diciendo: Jehová Dios de Israel, que habitas entre los querubines, tú solo eres Dios de todos los reinos de la tierra; tú hiciste el cielo y la tierra."}, {"numero": 16, "texto": "Inclina, oh Jehová, tu oído, y oye; abre, oh Jehová, tus ojos, y mira: y oye las palabras de Sennachêrib, que ha enviado á blasfemar al Dios viviente."}, {"numero": 17, "texto": "Es verdad, oh Jehová, que los reyes de Asiria han destruído las gentes y sus tierras;"}, {"numero": 18, "texto": "Y que pusieron en el fuego á sus dioses, por cuanto ellos no eran dioses, sino obra de manos de hombres, madera ó piedra, y así los destruyeron."}, {"numero": 19, "texto": "Ahora pues, oh Jehová Dios nuestro, sálvanos, te suplico, de su mano, para que sepan todos los reinos de la tierra que tú solo, Jehová, eres Dios."}, {"numero": 20, "texto": "Entonces Isaías hijo de Amós envió á decir á Ezechîas: Así ha dicho Jehová, Dios de Israel: Lo que me rogaste acerca de Sennachêrib rey de Asiria, he oído."}, {"numero": 21, "texto": "Esta es la palabra que Jehová ha hablado contra él: Hate menospreciado, hate escarnecido la virgen hija de Sión; ha movido su cabeza detrás de ti la hija de Jerusalem."}, {"numero": 22, "texto": "¿A quién has injuriado y á quién has blasfemado? ¿y contra quién has hablado alto, y has alzado en alto tus ojos? Contra el Santo de Israel."}, {"numero": 23, "texto": "Por mano de tus mensajeros has proferido injuria contra el Señor, y has dicho: Con la multitud de mis carros he subido á las cumbres de los montes, á las cuestas del Líbano; y cortaré sus altos cedros, sus hayas escogidas; y entraré á la morada de su término, al monte de su Carmel."}, {"numero": 24, "texto": "Yo he cavado y bebido las aguas ajenas, y he secado con las plantas de mis pies todos los ríos de lugares bloqueados."}, {"numero": 25, "texto": "¿Nunca has oído que mucho tiempo ha yo lo hice, y de días antiguos lo he formado? Y ahora lo he hecho venir, y fué para desolación de ciudades fuertes en montones de ruinas."}, {"numero": 26, "texto": "Y sus moradores, cortos de manos, quebrantados y confusos, fueron cual hierba del campo, como legumbre verde, y heno de los tejados, que antes que venga á madurez es seco."}, {"numero": 27, "texto": "Yo he sabido tu asentarte, tu salir y tu entrar, y tu furor contra mí."}, {"numero": 28, "texto": "Por cuanto te has airado contra mí, y tu estruendo ha subido á mis oídos, yo por tanto pondré mi anzuelo en tus narices, y mi bocado en tus labios, y te haré volver por el camino por donde viniste."}, {"numero": 29, "texto": "Y esto te será por señal Ezechîas: Este año comerás lo que nacerá de suyo, y el segundo año lo que nacerá de suyo; y el tercer año haréis sementera, y segaréis, y plantaréis viñas, y comeréis el fruto de ellas."}, {"numero": 30, "texto": "Y lo que hubiere escapado, lo que habrá quedado de la casa de Judá, tornará á echar raíz abajo, y hará fruto arriba."}, {"numero": 31, "texto": "Porque saldrán de Jerusalem reliquias, y los que escaparán, del monte de Sión: el celo de Jehová de los ejércitos hará esto."}, {"numero": 32, "texto": "Por tanto, Jehová dice así del rey de Asiria: No entrará en esta ciudad, ni echará saeta en ella; ni vendrá delante de ella escudo, ni será echado contra ella baluarte."}, {"numero": 33, "texto": "Por el camino que vino se volverá, y no entrará en esta ciudad, dice Jehová."}, {"numero": 34, "texto": "Porque yo ampararé á esta ciudad para salvarla, por amor de mí, y por amor de David mi siervo."}, {"numero": 35, "texto": "Y aconteció que la misma noche salió el ángel de Jehová, é hirió en el campo de los Asirios ciento ochenta y cinco mil; y como se levantaron por la mañana, he aquí los cuerpos de los muertos."}, {"numero": 36, "texto": "Entonces Sennachêrib, rey de Asiria se partió, y se fué y tornó á Nínive, donde se estuvo."}, {"numero": 37, "texto": "Y aconteció que, estando él adorando en el templo de Nisroch su dios, Adramelech y Saresar sus hijos lo hirieron á cuchillo; y huyéronse á tierra de Ararat. Y reinó en su lugar Esar-hadón su hijo."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 20, 'pt', '[{"numero": 1, "texto": "Naqueles dias caiu Ezequias enfermo de morte, e veio a ele Isaías profeta filho de Amoz, e disse-lhe: o SENHOR disse assim: Dá ordens à tua casa, porque hás de morrer, e não viverás."}, {"numero": 2, "texto": "Então virou ele seu rosto à parede, e orou ao SENHOR, e disse:"}, {"numero": 3, "texto": "Rogo-te, ó SENHOR, rogo-te faças memória de que andei diante de ti em verdade e íntegro coração, e que fiz as coisas que te agradam. E chorou Ezequias com grande choro."}, {"numero": 4, "texto": "E antes que Isaías saísse até a metade do pátio, veio a palavra do SENHOR a Isaías, dizendo:"}, {"numero": 5, "texto": "Volta, e dize a Ezequias, príncipe de meu povo: Assim diz o SENHOR, o Deus de Davi teu pai: Eu ouvi tua oração, e vi tuas lágrimas: eis que eu te saro; ao terceiro dia subirás à casa do SENHOR."}, {"numero": 6, "texto": "E acrescentarei a teus dias quinze anos, e te livrarei a ti e a esta cidade da mão do rei da Assíria; e ampararei esta cidade por causa de mim, e por causa de Davi meu servo."}, {"numero": 7, "texto": "E disse Isaías: Tomai uma pasta de figos. E tomando-a, puseram sobre a chaga, e sanou."}, {"numero": 8, "texto": "E Ezequias havia dito a Isaías: Que sinal terei de que o SENHOR me sarará, e que subirei à casa do SENHOR ao terceiro dia?"}, {"numero": 9, "texto": "E respondeu Isaías: Esta sinal terás do SENHOR, de que fará o SENHOR isto que disse: Avançará a sombra dez degraus, ou retrocederá dez degraus?"}, {"numero": 10, "texto": "E Ezequias respondeu: Fácil coisa é que a sombra decline dez degraus: mas, que a sombra volte atrás dez degraus."}, {"numero": 11, "texto": "Então o profeta Isaías clamou ao SENHOR; e fez voltar a sombra pelos degraus que havia descido no relógio de Acaz, dez degraus atrás."}, {"numero": 12, "texto": "Naquele tempo Berodaque-Baladã, filho de Baladã, rei da Babilônia, enviou cartas e um presente a Ezequias, porque havia ouvido que Ezequias havia estado doente."}, {"numero": 13, "texto": "E Ezequias os ouviu, e mostrou-lhes toda a casa das coisas preciosas, prata, ouro, e especiaria, e preciosos unguentos; e a casa de suas armas, e tudo o que havia em seus tesouros: nenhuma coisa restou que Ezequias não lhes mostrasse, tanto em sua casa como em todo o seu domínio."}, {"numero": 14, "texto": "Então o profeta Isaías veio ao rei Ezequias, e disse-lhe: Que disseram aqueles homens, e de onde vieram a ti? E Ezequias lhe respondeu: De distantes terras vieram, de Babilônia."}, {"numero": 15, "texto": "E ele lhe voltou a dizer: Que viram em tua casa? E Ezequias respondeu: Viram tudo o que havia em minha casa; nada restou em meus tesouros que não lhes mostrasse."}, {"numero": 16, "texto": "Então Isaías disse a Ezequias: Ouve a palavra do SENHOR:"}, {"numero": 17, "texto": "Eis que vêm dias, em que tudo o que está em tua casa, e tudo o que teus pais entesouraram até hoje, será levado a Babilônia, sem restar nada, disse o SENHOR."}, {"numero": 18, "texto": "E de teus filhos que sairão de ti, que haverás gerado, tomarão; e serão eunucos no palácio do rei da Babilônia."}, {"numero": 19, "texto": "Então Ezequias disse a Isaías: A palavra do SENHOR que falaste, é boa. Depois disse: Mas não haverá paz e verdade em meus dias?"}, {"numero": 20, "texto": "Os demais dos feitos de Ezequias, e todo o seu vigor, e como fez o tanque, e o aqueduto, e meteu as águas na cidade, não está escrito no livro das crônicas dos reis de Judá?"}, {"numero": 21, "texto": "E descansou Ezequias com seus pais, e reinou em seu lugar Manassés seu filho."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 20, 'en', '[{"numero": 1, "texto": "In those days was Hezekiah sick unto death. And the prophet Isaiah the son of Amoz came to him, and said unto him, Thus saith the Lord, Set thine house in order; for thou shalt die, and not live."}, {"numero": 2, "texto": "Then he turned his face to the wall, and prayed unto the Lord, saying,"}, {"numero": 3, "texto": "I beseech thee, O Lord, remember now how I have walked before thee in truth and with a perfect heart, and have done that which is good in thy sight. And Hezekiah wept sore."}, {"numero": 4, "texto": "And it came to pass, afore Isaiah was gone out into the middle court, that the word of the Lord came to him, saying,"}, {"numero": 5, "texto": "Turn again, and tell Hezekiah the captain of my people, Thus saith the Lord, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will heal thee: on the third day thou shalt go up unto the house of the Lord."}, {"numero": 6, "texto": "And I will add unto thy days fifteen years; and I will deliver thee and this city out of the hand of the king of Assyria; and I will defend this city for mine own sake, and for my servant David''s sake."}, {"numero": 7, "texto": "And Isaiah said, Take a lump of figs. And they took and laid it on the boil, and he recovered."}, {"numero": 8, "texto": "And Hezekiah said unto Isaiah, What shall be the sign that the Lord will heal me, and that I shall go up into the house of the Lord the third day?"}, {"numero": 9, "texto": "And Isaiah said, This sign shalt thou have of the Lord, that the Lord will do the thing that he hath spoken: shall the shadow go forward ten degrees, or go back ten degrees?"}, {"numero": 10, "texto": "And Hezekiah answered, It is a light thing for the shadow to go down ten degrees: nay, but let the shadow return backward ten degrees."}, {"numero": 11, "texto": "And Isaiah the prophet cried unto the Lord: and he brought the shadow ten degrees backward, by which it had gone down in the dial of Ahaz."}, {"numero": 12, "texto": "At that time Berodachbaladan, the son of Baladan, king of Babylon, sent letters and a present unto Hezekiah: for he had heard that Hezekiah had been sick."}, {"numero": 13, "texto": "And Hezekiah hearkened unto them, and shewed them all the house of his precious things, the silver, and the gold, and the spices, and the precious ointment, and all the house of his armour, and all that was found in his treasures: there was nothing in his house, nor in all his dominion, that Hezekiah shewed them not."}, {"numero": 14, "texto": "Then came Isaiah the prophet unto king Hezekiah, and said unto him, What said these men? and from whence came they unto thee? And Hezekiah said, They are come from a far country, even from Babylon."}, {"numero": 15, "texto": "And he said, What have they seen in thine house? And Hezekiah answered, All the things that are in mine house have they seen: there is nothing among my treasures that I have not shewed them."}, {"numero": 16, "texto": "And Isaiah said unto Hezekiah, Hear the word of the Lord."}, {"numero": 17, "texto": "Behold, the days come, that all that is in thine house, and that which thy fathers have laid up in store unto this day, shall be carried into Babylon: nothing shall be left, saith the Lord."}, {"numero": 18, "texto": "And of thy sons that shall issue from thee, which thou shalt beget, shall they take away; and they shall be eunuchs in the palace of the king of Babylon."}, {"numero": 19, "texto": "Then said Hezekiah unto Isaiah, Good is the word of the Lord which thou hast spoken. And he said, Is it not good, if peace and truth be in my days?"}, {"numero": 20, "texto": "And the rest of the acts of Hezekiah, and all his might, and how he made a pool, and a conduit, and brought water into the city, are they not written in the book of the chronicles of the kings of Judah?"}, {"numero": 21, "texto": "And Hezekiah slept with his fathers: and Manasseh his son reigned in his stead."}]'::jsonb, 'King James Version'),
  ('2Rs', 20, 'fr', '[{"numero": 1, "texto": "En ce temps-là, Ezéchias fut malade à la mort. Le prophète Esaïe, fils d''''Amots, vint auprès de lui, et lui dit: Ainsi parle l''''Eternel: Donne tes ordres à ta maison, car tu vas mourir, et tu ne vivras plus."}, {"numero": 2, "texto": "Ezéchias tourna son visage contre le mur, et fit cette prière à l''''Eternel:"}, {"numero": 3, "texto": "O Eternel! souviens-toi que j''''ai marché devant ta face avec fidélité et intégrité de coeur, et que j''''ai fait ce qui est bien à tes yeux! Et Ezéchias répandit d''''abondantes larmes."}, {"numero": 4, "texto": "Esaïe, qui était sorti, n''''était pas encore dans la cour du milieu, lorsque la parole de l''''Eternel lui fut adressée en ces termes:"}, {"numero": 5, "texto": "Retourne, et dis à Ezéchias, chef de mon peuple: Ainsi parle l''''Eternel, le Dieu de David, ton père: J''''ai entendu ta prière, j''''ai vu tes larmes. Voici, je te guérirai; le troisième jour, tu monteras à la maison de l''''Eternel."}, {"numero": 6, "texto": "J''''ajouterai à tes jours quinze années. Je te délivrerai, toi et cette ville, de la main du roi d''''Assyrie; je protégerai cette ville, à cause de moi, et à cause de David, mon serviteur."}, {"numero": 7, "texto": "Esaïe dit: Prenez une masse de figues. On la prit, et on l''''appliqua sur l''''ulcère. Et Ezéchias guérit."}, {"numero": 8, "texto": "Ezéchias avait dit à Esaïe: A quel signe connaîtrai-je que l''''Eternel me guérira, et que je monterai le troisième jour à la maison de l''''Eternel?"}, {"numero": 9, "texto": "Et Esaïe dit: Voici, de la part de l''''Eternel, le signe auquel tu connaîtras que l''''Eternel accomplira la parole qu''''il a prononcée: L''''ombre avancera-t-elle de dix degrés, ou reculera-t-elle de dix degrés?"}, {"numero": 10, "texto": "Ezéchias répondit: C''''est peu de chose que l''''ombre avance de dix degrés; mais plutôt qu''''elle recule de dix degrés."}, {"numero": 11, "texto": "Alors Esaïe, le prophète, invoqua l''''Eternel, qui fit reculer l''''ombre de dix degrés sur les degrés d''''Achaz, où elle était descendue."}, {"numero": 12, "texto": "En ce même temps, Berodac-Baladan, fils de Baladan, roi de Babylone, envoya une lettre et un présent à Ezéchias, car il avait appris la maladie d''''Ezéchias."}, {"numero": 13, "texto": "Ezéchias donna audience aux envoyés, et il leur montra le lieu où étaient ses choses de prix, l''''argent et l''''or, les aromates et l''''huile précieuse, son arsenal, et tout ce qui se trouvait dans ses trésors: il n''''y eut rien qu''''Ezéchias ne leur fît voir dans sa maison et dans tous ses domaines."}, {"numero": 14, "texto": "Esaïe, le prophète, vint ensuite auprès du roi Ezéchias, et lui dit: Qu''''ont dit ces gens-là, et d''''où sont-ils venus vers toi? Ezéchias répondit: Ils sont venus d''''un pays éloigné, de Babylone."}, {"numero": 15, "texto": "Esaïe dit encore: Qu''''ont-ils vu dans ta maison? Ezéchias répondit: Ils ont vu tout ce qui est dans ma maison: il n''''y a rien dans mes trésors que je ne leur aie fait voir."}, {"numero": 16, "texto": "Alors Esaïe dit à Ezéchias: Ecoute la parole de l''''Eternel!"}, {"numero": 17, "texto": "Voici, les temps viendront où l''''on emportera à Babylone tout ce qui est dans ta maison et ce que tes pères ont amassé jusqu''''à ce jour; il n''''en restera rien, dit l''''Eternel."}, {"numero": 18, "texto": "Et l''''on prendra de tes fils, qui seront sortis de toi, que tu auras engendrés, pour en faire des eunuques dans le palais du roi de Babylone."}, {"numero": 19, "texto": "Ezéchias répondit à Esaïe: La parole de l''''Eternel, que tu as prononcée, est bonne. Et il ajouta: N''''y aura-t-il pas paix et sécurité pendant ma vie?"}, {"numero": 20, "texto": "Le reste des actions d''''Ezéchias, tous ses exploits, et comment il fit l''''étang et l''''aqueduc, et amena les eaux dans la ville, cela n''''est-il pas écrit dans le livre des Chroniques des rois de Juda?"}, {"numero": 21, "texto": "Ezéchias se coucha avec ses pères. Et Manassé, son fils, régna à sa place."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 20, 'es', '[{"numero": 1, "texto": "EN aquellos días cayó Ezechîas enfermo de muerte, y vino á él Isaías profeta hijo de Amós, y díjole: Jehová dice así: Dispón de tu casa, porque has de morir, y no vivirás."}, {"numero": 2, "texto": "Entonces volvió él su rostro á la pared, y oró á Jehová, y dijo:"}, {"numero": 3, "texto": "Ruégote, oh Jehová, ruégote hagas memoria de que he andado delante de ti en verdad é íntegro corazón, y que he hecho las cosas que te agradan. Y lloró Ezechîas con gran lloro."}, {"numero": 4, "texto": "Y antes que Isaías saliese hasta la mitad del patio, fué palabra de Jehová á Isaías, diciendo:"}, {"numero": 5, "texto": "Vuelve, y di á Ezechîas, príncipe de mi pueblo: Así dice Jehová, el Dios de David tu padre: Yo he oído tu oración, y he visto tus lágrimas: he aquí yo te sano; al tercer día subirás á la casa de Jehová."}, {"numero": 6, "texto": "Y añadiré á tus días quince años, y te libraré á ti y á esta ciudad de mano del rey de Asiria; y ampararé esta ciudad por amor de mí, y por amor de David mi siervo."}, {"numero": 7, "texto": "Y dijo Isaías: Tomad masa de higos. Y tomándola, pusieron sobre la llaga, y sanó."}, {"numero": 8, "texto": "Y Ezechîas había dicho á Isaías: ¿Qué señal tendré de que Jehová me sanará, y que subiré á la casa de Jehová al tercer día?"}, {"numero": 9, "texto": "Y respondió Isaías: Esta señal tendrás de Jehová, de que hará Jehová esto que ha dicho: ¿Avanzará la sombra diez grados, ó retrocederá diez grados?"}, {"numero": 10, "texto": "Y Ezechîas respondió: Fácil cosa es que la sombra decline diez grados: pero, que la sombra vuelva atrás diez grados."}, {"numero": 11, "texto": "Entonces el profeta Isaías clamó á Jehová; é hizo volver la sombra por los grados que había descendido en el reloj de Achâz, diez grados atrás."}, {"numero": 12, "texto": "En aquel tiempo Berodach-baladán hijo de Baladán, rey de Babilonia, envió letras y presentes á Ezechîas, porque había oído que Ezechîas había caído enfermo."}, {"numero": 13, "texto": "Y Ezechîas los oyó, y mostróles toda la casa de las cosas preciosas, plata, oro, y especiería, y preciosos ungüentos; y la casa de sus armas, y todo lo que había en sus tesoros: ninguna cosa quedó que Ezechîas no les mostrase, así en su casa como en todo su señorío."}, {"numero": 14, "texto": "Entonces el profeta Isaías vino al rey Ezechîas, y díjole: ¿Qué dijeron aquellos varones, y de dónde vinieron á ti? Y Ezechîas le respondió: De lejanas tierras han venido, de Babilonia."}, {"numero": 15, "texto": "Y él le volvió á decir: ¿Qué vieron en tu casa? Y Ezechîas respondió: Vieron todo lo que había en mi casa; nada quedó en mis tesoros que no les mostrase."}, {"numero": 16, "texto": "Entonces Isaías dijo á Ezechîas: Oye palabra de Jehová:"}, {"numero": 17, "texto": "He aquí vienen días, en que todo lo que está en tu casa, y todo lo que tus padres han atesorado hasta hoy, será llevado á Babilonia, sin quedar nada, dijo Jehová."}, {"numero": 18, "texto": "Y de tus hijos que saldrán de ti, que habrás engendrado, tomarán; y serán eunucos en el palacio del rey de Babilonia."}, {"numero": 19, "texto": "Entonces Ezechîas dijo á Isaías: La palabra de Jehová que has hablado, es buena. Después dijo: ¿Mas no habrá paz y verdad en mis días?"}, {"numero": 20, "texto": "Lo demás de los hechos de Ezechîas, y todo su vigor, y cómo hizo el estanque, y el conducto, y metió las aguas en la ciudad, ¿no está escrito en el libro de las crónicas de los reyes de Judá?"}, {"numero": 21, "texto": "Y durmió Ezechîas con sus padres, y reinó en su lugar Manasés su hijo."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 22, 'pt', '[{"numero": 1, "texto": "Quando Josias começou a reinar era de oito anos, e reinou em Jerusalém trinta e um anos. O nome de sua mãe foi Jedida filha de Adaías de Bozcate."}, {"numero": 2, "texto": "E fez o que era correto aos olhos do SENHOR, e andou em todo o caminho de Davi seu pai, sem desviar-se à direita nem à esquerda."}, {"numero": 3, "texto": "E aos dezoito anos do rei Josias, foi que enviou o rei a Safã filho de Azalias, filho de Mesulão, escriba, à casa do SENHOR, dizendo:"}, {"numero": 4, "texto": "Vai a Hilquias, sumo sacerdote: dize-lhe que recolha o dinheiro que se pôs na casa do SENHOR, que juntaram do povo os guardiões da porta,"}, {"numero": 5, "texto": "E que o ponham em mãos dos que fazem a obra, que têm cargo da casa do SENHOR, e que o entreguem aos que fazem a obra da casa do SENHOR, para reparar as fendas da casa:"}, {"numero": 6, "texto": "Aos carpinteiros, aos mestres e pedreiros, para comprar madeira e pedra lavrada para reparar a casa;"}, {"numero": 7, "texto": "E que não se lhes conte o dinheiro cujo manejo se lhes confiar, porque eles procedem com fidelidade."}, {"numero": 8, "texto": "Então disse o sumo sacerdote Hilquias a Safã escriba: Achei o livro da lei na casa do SENHOR. E Hilquias deu o livro a Safã, e leu-o."}, {"numero": 9, "texto": "Vindo logo Safã escriba ao rei, deu ao rei a resposta, e disse: Teus servos juntaram o dinheiro que se achou no templo, e o entregaram em poder dos que fazem a obra, que têm cargo da casa do SENHOR."}, {"numero": 10, "texto": "Também Safã escriba declarou ao rei, dizendo: Hilquias o sacerdote me deu um livro. E leu-o Safã diante do rei."}, {"numero": 11, "texto": "E quando o rei ouviu as palavras do livro da lei, rasgou suas roupas."}, {"numero": 12, "texto": "Logo mandou o rei a Hilquias o sacerdote, e a Aicã filho de Safã, e a Acbor filho de Micaías, e a Safã escriba, e a Asaías servo do rei, dizendo:"}, {"numero": 13, "texto": "Ide, e perguntai ao SENHOR por mim, e pelo povo, e por todo Judá, acerca das palavras deste livro que se achou: porque grande ira do SENHOR é a que foi acesa contra nós, porquanto nossos pais não escutaram as palavras deste livro, para fazer conforme tudo o que nos foi escrito."}, {"numero": 14, "texto": "Então foi Hilquias o sacerdote, e Aicã e Acbor e Safã e Asaías, a Hulda profetisa, mulher de Salum filho de Ticvá filho de Harás, guarda das vestiduras, a qual morava em Jerusalém na segunda parte da cidade, e falaram com ela."}, {"numero": 15, "texto": "E ela lhes disse: Assim disse o SENHOR o Deus de Israel: Dizei ao homem que vos enviou a mim:"}, {"numero": 16, "texto": "Assim disse o SENHOR: Eis que eu trago mal sobre este lugar, e sobre os que nele moram, a saber, todas as palavras do livro que leu o rei de Judá:"}, {"numero": 17, "texto": "Porquanto me deixaram, e queimaram incenso a deuses alheios, provocando-me à ira em toda obra de suas mãos; e meu furor se acendeu contra este lugar, e não se apagará."}, {"numero": 18, "texto": "Mas ao rei de Judá que vos enviou para que perguntásseis ao SENHOR, direis assim: Assim disse o SENHOR o Deus de Israel: Porquanto ouviste as palavras do livro,"}, {"numero": 19, "texto": "E teu coração se enterneceu, e te humilhaste diante do SENHOR, quando ouviste o que eu pronunciei contra este lugar e contra seus moradores, que viriam a ser assolados e malditos, e rasgaste tuas vestes, e choraste em minha presença, também eu te ouvi, diz o SENHOR."}, {"numero": 20, "texto": "Portanto, eis que eu te recolherei com teus pais, e tu serás recolhido a teu sepulcro em paz, e não verão teus olhos todo o mal que eu trago sobre este lugar. E eles deram ao rei a resposta."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 22, 'en', '[{"numero": 1, "texto": "Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother''s name was Jedidah, the daughter of Adaiah of Boscath."}, {"numero": 2, "texto": "And he did that which was right in the sight of the Lord, and walked in all the way of David his father, and turned not aside to the right hand or to the left."}, {"numero": 3, "texto": "And it came to pass in the eighteenth year of king Josiah, that the king sent Shaphan the son of Azaliah, the son of Meshullam, the scribe, to the house of the Lord, saying,"}, {"numero": 4, "texto": "Go up to Hilkiah the high priest, that he may sum the silver which is brought into the house of the Lord, which the keepers of the door have gathered of the people:"}, {"numero": 5, "texto": "And let them deliver it into the hand of the doers of the work, that have the oversight of the house of the Lord: and let them give it to the doers of the work which is in the house of the Lord, to repair the breaches of the house,"}, {"numero": 6, "texto": "Unto carpenters, and builders, and masons, and to buy timber and hewn stone to repair the house."}, {"numero": 7, "texto": "Howbeit there was no reckoning made with them of the money that was delivered into their hand, because they dealt faithfully."}, {"numero": 8, "texto": "And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the Lord. And Hilkiah gave the book to Shaphan, and he read it."}, {"numero": 9, "texto": "And Shaphan the scribe came to the king, and brought the king word again, and said, Thy servants have gathered the money that was found in the house, and have delivered it into the hand of them that do the work, that have the oversight of the house of the Lord."}, {"numero": 10, "texto": "And Shaphan the scribe shewed the king, saying, Hilkiah the priest hath delivered me a book. And Shaphan read it before the king."}, {"numero": 11, "texto": "And it came to pass, when the king had heard the words of the book of the law, that he rent his clothes."}, {"numero": 12, "texto": "And the king commanded Hilkiah the priest, and Ahikam the son of Shaphan, and Achbor the son of Michaiah, and Shaphan the scribe, and Asahiah a servant of the king''s, saying,"}, {"numero": 13, "texto": "Go ye, enquire of the Lord for me, and for the people, and for all Judah, concerning the words of this book that is found: for great is the wrath of the Lord that is kindled against us, because our fathers have not hearkened unto the words of this book, to do according unto all that which is written concerning us."}, {"numero": 14, "texto": "So Hilkiah the priest, and Ahikam, and Achbor, and Shaphan, and Asahiah, went unto Huldah the prophetess, the wife of Shallum the son of Tikvah, the son of Harhas, keeper of the wardrobe; (now she dwelt in Jerusalem in the college;) and they communed with her."}, {"numero": 15, "texto": "And she said unto them, Thus saith the Lord God of Israel, Tell the man that sent you to me,"}, {"numero": 16, "texto": "Thus saith the Lord, Behold, I will bring evil upon this place, and upon the inhabitants thereof, even all the words of the book which the king of Judah hath read:"}, {"numero": 17, "texto": "Because they have forsaken me, and have burned incense unto other gods, that they might provoke me to anger with all the works of their hands; therefore my wrath shall be kindled against this place, and shall not be quenched."}, {"numero": 18, "texto": "But to the king of Judah which sent you to enquire of the Lord, thus shall ye say to him, Thus saith the Lord God of Israel, As touching the words which thou hast heard;"}, {"numero": 19, "texto": "Because thine heart was tender, and thou hast humbled thyself before the Lord, when thou heardest what I spake against this place, and against the inhabitants thereof, that they should become a desolation and a curse, and hast rent thy clothes, and wept before me; I also have heard thee, saith the Lord."}, {"numero": 20, "texto": "Behold therefore, I will gather thee unto thy fathers, and thou shalt be gathered into thy grave in peace; and thine eyes shall not see all the evil which I will bring upon this place. And they brought the king word again."}]'::jsonb, 'King James Version'),
  ('2Rs', 22, 'fr', '[{"numero": 1, "texto": "Josias avait huit ans lorsqu''''il devint roi, et il régna trente et un ans à Jérusalem. Sa mère s''''appelait Jedida, fille d''''Adaja, de Botskath."}, {"numero": 2, "texto": "Il fit ce qui est droit aux yeux de l''''Eternel, et il marcha dans toute la voie de David, son père; il ne s''''en détourna ni à droite ni à gauche."}, {"numero": 3, "texto": "La dix-huitième année du roi Josias, le roi envoya dans la maison de l''''Eternel Schaphan, le secrétaire, fils d''''Atsalia, fils de Meschullam. Il lui dit:"}, {"numero": 4, "texto": "Monte vers Hilkija, le souverain sacrificateur, et qu''''il amasse l''''argent qui a été apporté dans la maison de l''''Eternel et que ceux qui ont la garde du seuil ont recueilli du peuple."}, {"numero": 5, "texto": "On remettra cet argent entre les mains de ceux qui sont chargés de faire exécuter l''''ouvrage dans la maison de l''''Eternel. Et ils l''''emploieront pour ceux qui travaillent aux réparations de la maison de l''''Eternel,"}, {"numero": 6, "texto": "pour les charpentiers, les manoeuvres et les maçons, pour les achats de bois et de pierres de taille nécessaires aux réparations de la maison."}, {"numero": 7, "texto": "Mais on ne leur demandera pas de compte pour l''''argent remis entre leurs mains, car ils agissent avec probité."}, {"numero": 8, "texto": "Alors Hilkija, le souverain sacrificateur, dit à Schaphan, le secrétaire: J''''ai trouvé le livre de la loi dans la maison de l''''Eternel. Et Hilkija donna le livre à Schaphan, et Schaphan le lut."}, {"numero": 9, "texto": "Puis Schaphan, le secrétaire, alla rendre compte au roi, et dit: Tes serviteurs ont amassé l''''argent qui se trouvait dans la maison, et l''''ont remis entre les mains de ceux qui sont chargés de faire exécuter l''''ouvrage dans la maison de l''''Eternel."}, {"numero": 10, "texto": "Schaphan, le secrétaire, dit encore au roi: Le sacrificateur Hilkija m''''a donné un livre. Et Schaphan le lut devant le roi."}, {"numero": 11, "texto": "Lorsque le roi entendit les paroles du livre de la loi, il déchira ses vêtements."}, {"numero": 12, "texto": "Et le roi donna cet ordre au sacrificateur Hilkija, à Achikam, fils de Schaphan, à Acbor, fils de Michée, à Schaphan, le secrétaire, et à Asaja, serviteur du roi:"}, {"numero": 13, "texto": "Allez, consultez l''''Eternel pour moi, pour le peuple, et pour tout Juda, au sujet des paroles de ce livre qu''''on a trouvé; car grande est la colère de l''''Eternel, qui s''''est enflammée contre nous, parce que nos pères n''''ont point obéi aux paroles de ce livre et n''''ont point mis en pratique tout ce qui nous y est prescrit."}, {"numero": 14, "texto": "Le sacrificateur Hilkija, Achikam, Acbor, Schaphan et Asaja, allèrent auprès de la prophétesse Hulda, femme de Schallum, fils de Thikva, fils de Harhas, gardien des vêtements. Elle habitait à Jérusalem, dans l''''autre quartier de la ville. Après qu''''ils lui eurent parlé,"}, {"numero": 15, "texto": "elle leur dit: Ainsi parle l''''Eternel, le Dieu d''''Israël: Dites à l''''homme qui vous a envoyés vers moi:"}, {"numero": 16, "texto": "Ainsi parle l''''Eternel: Voici, je vais faire venir des malheurs sur ce lieu et sur ses habitants, selon toutes les paroles du livre qu''''a lu le roi de Juda."}, {"numero": 17, "texto": "Parce qu''''ils m''''ont abandonné et qu''''ils ont offert des parfums à d''''autres dieux, afin de m''''irriter par tous les ouvrages de leurs mains, ma colère s''''est enflammée contre ce lieu, et elle ne s''''éteindra point."}, {"numero": 18, "texto": "Mais vous direz au roi de Juda, qui vous a envoyés pour consulter l''''Eternel: Ainsi parle l''''Eternel, le Dieu d''''Israël, au sujet des paroles que tu as entendues:"}, {"numero": 19, "texto": "Parce que ton coeur a été touché, parce que tu t''''es humilié devant l''''Eternel en entendant ce que j''''ai prononcé contre ce lieu et contre ses habitants, qui seront un objet d''''épouvante et de malédiction, et parce que tu as déchiré tes vêtements et que tu as pleuré devant moi, moi aussi, j''''ai entendu, dit l''''Eternel."}, {"numero": 20, "texto": "C''''est pourquoi, voici, je te recueillerai auprès de tes pères, tu seras recueilli en paix dans ton sépulcre, et tes yeux ne verront pas tous les malheurs que je ferai venir sur ce lieu. Ils rapportèrent au roi cette réponse."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 22, 'es', '[{"numero": 1, "texto": "CUANDO Josías comenzó á reinar era de ocho años, y reinó en Jerusalem treinta y un años. El nombre de su madre fué Idida hija de Adaía de Boscath."}, {"numero": 2, "texto": "E hizo lo recto en ojos de Jehová, y anduvo en todo el camino de David su padre, sin apartarse á diestra ni á siniestra."}, {"numero": 3, "texto": "Y á los dieciocho años del rey Josías, fué que envió el rey á Saphán hijo de Azalía, hijo de Mesullam, escriba, á la casa de Jehová, diciendo:"}, {"numero": 4, "texto": "Ve á Hilcías, sumo sacerdote: dile que recoja el dinero que se ha metido en la casa de Jehová, que han juntado del pueblo los guardianes de la puerta,"}, {"numero": 5, "texto": "Y que lo pongan en manos de los que hacen la obra, que tienen cargo de la casa de Jehová, y que lo entreguen á los que hacen la obra de la casa de Jehová, para reparar las aberturas de la casa:"}, {"numero": 6, "texto": "A los carpinteros, á los maestros y albañiles, para comprar madera y piedra de cantería para reparar la casa;"}, {"numero": 7, "texto": "Y que no se les cuente el dinero cuyo manejo se les confiare, porque ellos proceden con fidelidad."}, {"numero": 8, "texto": "Entonces dijo el sumo sacerdote Hilcías á Saphán escriba: El libro de la ley he hallado en la casa de Jehová. E Hilcías dió el libro á Saphán, y leyólo."}, {"numero": 9, "texto": "Viniendo luego Saphán escriba al rey, dió al rey la respuesta, y dijo: Tus siervos han juntado el dinero que se halló en el templo, y lo han entregado en poder de los que hacen la obra, que tienen cargo de la casa de Jehová."}, {"numero": 10, "texto": "Asimismo Saphán escriba declaró al rey, diciendo: Hilcías el sacerdote me ha dado un libro. Y leyólo Saphán delante del rey."}, {"numero": 11, "texto": "Y cuando el rey hubo oído las palabras del libro de la ley, rasgó sus vestidos."}, {"numero": 12, "texto": "Luego mandó el rey á Hilcías el sacerdote, y á Ahicam hijo de Saphán, y á Achbor hijo de Michâía, y á Saphán escriba, y á Asaía siervo del rey, diciendo:"}, {"numero": 13, "texto": "Id, y preguntad á Jehová por mí, y por el pueblo, y por todo Judá, acerca de las palabras de este libro que se ha hallado: porque grande ira de Jehová es la que ha sido encendida contra nosotros, por cuanto nuestros padres no escucharon las palabras de este libro, para hacer conforme á todo lo que nos fué escrito."}, {"numero": 14, "texto": "Entonces fué Hilcías el sacerdote, y Ahicam y Achbor y Saphán y Asaía, á Hulda profetisa, mujer de Sallum hijo de Ticva hijo de Araas, guarda de las vestiduras, la cual moraba en Jerusalem en la segunda parte de la ciudad, y hablaron con ella."}, {"numero": 15, "texto": "Y ella les dijo: Así ha dicho Jehová el Dios de Israel: Decid al varón que os envió á mí:"}, {"numero": 16, "texto": "Así dijo Jehová: He aquí yo traigo mal sobre este lugar, y sobre los que en él moran, á saber, todas las palabras del libro que ha leído el rey de Judá:"}, {"numero": 17, "texto": "Por cuanto me dejaron á mí, y quemaron perfumes á dioses ajenos, provocándome á ira en toda obra de sus manos; y mi furor se ha encendido contra este lugar, y no se apagará."}, {"numero": 18, "texto": "Mas al rey de Judá que os ha enviado para que preguntaseis á Jehová, diréis así: Así ha dicho Jehová el Dios de Israel: Por cuanto oíste las palabras del libro,"}, {"numero": 19, "texto": "Y tu corazón se enterneció, y te humillaste delante de Jehová, cuando oíste lo que yo he pronunciado contra este lugar y contra sus moradores, que vendrían á ser asolados y malditos, y rasgaste tus vestidos, y lloraste en mi presencia, también yo te he oído, dice Jehová."}, {"numero": 20, "texto": "Por tanto, he aquí yo te recogeré con tus padres, y tú serás recogido á tu sepulcro en paz, y no verán tus ojos todo el mal que yo traigo sobre este lugar. Y ellos dieron al rey la respuesta."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 23, 'pt', '[{"numero": 1, "texto": "Então o rei enviou aviso, e juntaram a ele todos os anciãos de Judá e de Jerusalém."}, {"numero": 2, "texto": "E subiu o rei à casa do SENHOR com todos os homens de Judá, e com todos os moradores de Jerusalém, com os sacerdotes e profetas e com todo o povo, desde o menor até o maior; e leu, ouvindo-o eles, todas as palavras do livro do pacto que havia sido achado na casa do SENHOR."}, {"numero": 3, "texto": "E pondo-se o rei em pé junto à coluna, fez aliança diante do SENHOR, de que seguiriam o SENHOR, e guardariam seus mandamentos, e seus testemunhos, e seus estatutos, com todo o coração e com toda a alma, e que cumpririam as palavras da aliança que estavam escritas naquele livro. E todo o povo confirmou o pacto."}, {"numero": 4, "texto": "Então mandou el rei ao sumo sacerdote Hilquias, e aos sacerdotes de segunda ordem, e aos guardiões da porta, que tirassem do templo do SENHOR todos os vasos que haviam sido feitos para Baal, e para o bosque, e para toda o exército do céu; e queimou-os fora de Jerusalém no campo de Cedrom, e fez levar as cinzas deles a Betel."}, {"numero": 5, "texto": "E tirou aos sacerdotes pagãos, que haviam posto os reis de Judá para que queimassem incenso nos altos nas cidades de Judá, e nos arredores de Jerusalém; e também aos que queimavam incenso a Baal, ao sol e à lua, e às constelações, e a todo o exército do céu."}, {"numero": 6, "texto": "Fez também tirar o bosque fora da casa do SENHOR, fora de Jerusalém, ao ribeiro de Cedrom, e queimou-o no ribeiro de Cedrom, e tornou-o em pó, e lançou o pó dele sobre os sepulcros dos filhos do povo."}, {"numero": 7, "texto": "Além disso derrubou as casas dos sodomitas que estavam na casa do SENHOR, nas quais teciam as mulheres tendas para o bosque."}, {"numero": 8, "texto": "E fez vir todos os sacerdotes das cidades de Judá, e profanou os altos de onde os sacerdotes queimavam incenso, desde Gibeá até Berseba; e derrubou os altares das portas que estavam à entrada da porta de Josué, governador da cidade, que estavam à esquerda da porta da cidade."}, {"numero": 9, "texto": "Porém os sacerdotes dos altos não subiam ao altar do SENHOR em Jerusalém, mas comiam pães sem levedura entre seus irmãos."}, {"numero": 10, "texto": "Também profanou a Tofete, que está no vale do filho de Hinom, porque ninguém passasse seu filho ou sua filha por fogo a Moloque."}, {"numero": 11, "texto": "Tirou também os cavalos que os reis de Judá haviam dedicado ao sol à entrada do templo do SENHOR, junto à câmara de Natã-Meleque eunuco, a qual ficava nos recintos; e queimou ao fogo os carros do sol."}, {"numero": 12, "texto": "Derrubou também o rei os altares que estavam sobre o terraço da sala de Acaz, que os reis de Judá haviam feito, e os altares que havia feito Manassés nos dois átrios da casa do SENHOR; e dali correu e lançou o pó no ribeiro de Cedrom."}, {"numero": 13, "texto": "Também profanou o rei os altos que estavam diante de Jerusalém, à direita do monte da destruição, os quais Salomão rei de Israel havia edificado a Astarote, abominação dos sidônios, e a Camos abominação de Moabe, e a Milcom abominação dos filhos de Amom."}, {"numero": 14, "texto": "E quebrou as estátuas, e arrancou os bosques, e encheu o lugar deles de ossos de homens."}, {"numero": 15, "texto": "Igualmente o altar que estava em Betel, e o alto que havia feito Jeroboão filho de Nebate, o que fez pecar a Israel, aquele altar e o alto destruiu; e queimou o alto, e o tornou em pó, e pôs fogo ao bosque."}, {"numero": 16, "texto": "E voltou-se Josias, e vendo os sepulcros que estavam ali no monte, enviou e tirou os ossos dos sepulcros, e queimou-os sobre o altar para contaminá-lo, conforme à palavra do SENHOR que havia profetizado o homem de Deus, o qual havia anunciado estes negócios."}, {"numero": 17, "texto": "E depois disse: Que monumento é este que vejo? E os da cidade lhe responderam: Este é o sepulcro do homem de Deus que veio de Judá, e profetizou estas coisas que tu fizeste sobre o altar de Betel."}, {"numero": 18, "texto": "E ele disse: Deixai-o; ninguém mova seus ossos: e assim foram preservados seus ossos, e os ossos do profeta que havia vindo de Samaria."}, {"numero": 19, "texto": "E todas as casas dos altos que estavam nas cidades de Samaria, as quais haviam feito os reis de Israel para provocar a ira, tirou-as também Josias, e fez delas como havia feito em Betel."}, {"numero": 20, "texto": "Também matou sobre os altares a todos os sacerdotes dos altos que ali estavam, e queimou sobre eles ossos de homens, e voltou-se a Jerusalém."}, {"numero": 21, "texto": "Então mandou o rei a todo o povo, dizendo: Fazei a páscoa ao SENHOR vosso Deus, conforme o que está escrito no livro desta aliança."}, {"numero": 22, "texto": "Não foi feita tal páscoa desde os tempos dos juízes que governaram a Israel, nem em todos os tempos dos reis de Israel, e dos reis de Judá."}, {"numero": 23, "texto": "Aos dezoito anos do rei Josias foi feita aquela páscoa ao SENHOR em Jerusalém."}, {"numero": 24, "texto": "Também expulsou Josias os necromantes, adivinhos, e ídolos, e todas as abominações que se viam na terra de Judá e em Jerusalém, para cumprir as palavras da lei que estavam escritas no livro que o sacerdote Hilquias havia achado na casa do SENHOR."}, {"numero": 25, "texto": "Não houve tal rei antes dele que se convertesse ao SENHOR de todo seu coração, e de toda sua alma, e de todas suas forças, conforme a toda a lei de Moisés; nem depois dele nasceu outro tal."}, {"numero": 26, "texto": "Contudo isso, o SENHOR não se desviou do ardor de sua grande ira, com que se havia encendido sua ira contra Judá, por todas as provocações com que Manassés lhe havia irritado."}, {"numero": 27, "texto": "E disse o SENHOR: Também tirarei de minha presença a Judá, como tirei a Israel, e abominarei a esta cidade que havia escolhido, a Jerusalém, e à casa da qual havia eu dito: Meu nome será ali."}, {"numero": 28, "texto": "Os demais dos feitos de Josias, e todas as coisas que fez, não está tudo escrito no livro das crônicas dos reis de Judá?"}, {"numero": 29, "texto": "Em aqueles dias Faraó Neco rei do Egito subiu contra o rei da Assíria ao rio Eufrates, e saiu contra ele o rei Josias; mas aquele assim que lhe viu, o matou em Megido."}, {"numero": 30, "texto": "E seus servos o puseram em um carro, e trouxeram-no morto de Megido a Jerusalém, e sepultaram-no em seu sepulcro. Então o povo da terra tomou a Jeoacaz filho de Josias, e ungiram-lhe e puseram-no por rei em lugar de seu pai."}, {"numero": 31, "texto": "De vinte e três anos era Jeoacaz quando começou a reinar, e reinou três meses em Jerusalém. O nome de sua mãe foi Hamutal, filha de Jeremias de Libna."}, {"numero": 32, "texto": "E ele fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seus pais haviam feito."}, {"numero": 33, "texto": "E lançou-o preso Faraó Neco em Ribla na província de Hamate, para que ele não reinasse em Jerusalém; e impôs sobre a terra uma multa de cem talentos de prata, e um de ouro."}, {"numero": 34, "texto": "Então Faraó Neco pôs por rei a Eliaquim filho de Josias, em lugar de Josias seu pai, e mudou-lhe o nome no de Jeoaquim; e tomou a Jeoacaz, e levou-o ao Egito, e morreu ali."}, {"numero": 35, "texto": "E Jeoaquim pagou a Faraó a prata e o ouro; mas fez tributar a terra para dar o dinheiro conforme ao mandamento de Faraó, tirando a prata e ouro do povo da terra, de cada um segundo a avaliação de sua riqueza, para dar a Faraó Neco."}, {"numero": 36, "texto": "De vinte e cinco anos era Jeoaquim quando começou a reinar, e onze anos reinou em Jerusalém. O nome de sua mãe foi Zebida filha de Pedaías, de Ruma."}, {"numero": 37, "texto": "E fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seus pais haviam feito."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 23, 'en', '[{"numero": 1, "texto": "And the king sent, and they gathered unto him all the elders of Judah and of Jerusalem."}, {"numero": 2, "texto": "And the king went up into the house of the Lord, and all the men of Judah and all the inhabitants of Jerusalem with him, and the priests, and the prophets, and all the people, both small and great: and he read in their ears all the words of the book of the covenant which was found in the house of the Lord."}, {"numero": 3, "texto": "And the king stood by a pillar, and made a covenant before the Lord, to walk after the Lord, and to keep his commandments and his testimonies and his statutes with all their heart and all their soul, to perform the words of this covenant that were written in this book. And all the people stood to the covenant."}, {"numero": 4, "texto": "And the king commanded Hilkiah the high priest, and the priests of the second order, and the keepers of the door, to bring forth out of the temple of the Lord all the vessels that were made for Baal, and for the grove, and for all the host of heaven: and he burned them without Jerusalem in the fields of Kidron, and carried the ashes of them unto Bethel."}, {"numero": 5, "texto": "And he put down the idolatrous priests, whom the kings of Judah had ordained to burn incense in the high places in the cities of Judah, and in the places round about Jerusalem; them also that burned incense unto Baal, to the sun, and to the moon, and to the planets, and to all the host of heaven."}, {"numero": 6, "texto": "And he brought out the grove from the house of the Lord, without Jerusalem, unto the brook Kidron, and burned it at the brook Kidron, and stamped it small to powder, and cast the powder thereof upon the graves of the children of the people."}, {"numero": 7, "texto": "And he brake down the houses of the sodomites, that were by the house of the Lord, where the women wove hangings for the grove."}, {"numero": 8, "texto": "And he brought all the priests out of the cities of Judah, and defiled the high places where the priests had burned incense, from Geba to Beersheba, and brake down the high places of the gates that were in the entering in of the gate of Joshua the governor of the city, which were on a man''s left hand at the gate of the city."}, {"numero": 9, "texto": "Nevertheless the priests of the high places came not up to the altar of the Lord in Jerusalem, but they did eat of the unleavened bread among their brethren."}, {"numero": 10, "texto": "And he defiled Topheth, which is in the valley of the children of Hinnom, that no man might make his son or his daughter to pass through the fire to Molech."}, {"numero": 11, "texto": "And he took away the horses that the kings of Judah had given to the sun, at the entering in of the house of the Lord, by the chamber of Nathanmelech the chamberlain, which was in the suburbs, and burned the chariots of the sun with fire."}, {"numero": 12, "texto": "And the altars that were on the top of the upper chamber of Ahaz, which the kings of Judah had made, and the altars which Manasseh had made in the two courts of the house of the Lord, did the king beat down, and brake them down from thence, and cast the dust of them into the brook Kidron."}, {"numero": 13, "texto": "And the high places that were before Jerusalem, which were on the right hand of the mount of corruption, which Solomon the king of Israel had builded for Ashtoreth the abomination of the Zidonians, and for Chemosh the abomination of the Moabites, and for Milcom the abomination of the children of Ammon, did the king defile."}, {"numero": 14, "texto": "And he brake in pieces the images, and cut down the groves, and filled their places with the bones of men."}, {"numero": 15, "texto": "Moreover the altar that was at Bethel, and the high place which Jeroboam the son of Nebat, who made Israel to sin, had made, both that altar and the high place he brake down, and burned the high place, and stamped it small to powder, and burned the grove."}, {"numero": 16, "texto": "And as Josiah turned himself, he spied the sepulchres that were there in the mount, and sent, and took the bones out of the sepulchres, and burned them upon the altar, and polluted it, according to the word of the Lord which the man of God proclaimed, who proclaimed these words."}, {"numero": 17, "texto": "Then he said, What title is that that I see? And the men of the city told him, It is the sepulchre of the man of God, which came from Judah, and proclaimed these things that thou hast done against the altar of Bethel."}, {"numero": 18, "texto": "And he said, Let him alone; let no man move his bones. So they let his bones alone, with the bones of the prophet that came out of Samaria."}, {"numero": 19, "texto": "And all the houses also of the high places that were in the cities of Samaria, which the kings of Israel had made to provoke the Lord to anger, Josiah took away, and did to them according to all the acts that he had done in Bethel."}, {"numero": 20, "texto": "And he slew all the priests of the high places that were there upon the altars, and burned men''s bones upon them, and returned to Jerusalem."}, {"numero": 21, "texto": "And the king commanded all the people, saying, Keep the passover unto the Lord your God, as it is written in the book of this covenant."}, {"numero": 22, "texto": "Surely there was not holden such a passover from the days of the judges that judged Israel, nor in all the days of the kings of Israel, nor of the kings of Judah;"}, {"numero": 23, "texto": "But in the eighteenth year of king Josiah, wherein this passover was holden to the Lord in Jerusalem."}, {"numero": 24, "texto": "Moreover the workers with familiar spirits, and the wizards, and the images, and the idols, and all the abominations that were spied in the land of Judah and in Jerusalem, did Josiah put away, that he might perform the words of the law which were written in the book that Hilkiah the priest found in the house of the Lord."}, {"numero": 25, "texto": "And like unto him was there no king before him, that turned to the Lord with all his heart, and with all his soul, and with all his might, according to all the law of Moses; neither after him arose there any like him."}, {"numero": 26, "texto": "Notwithstanding the Lord turned not from the fierceness of his great wrath, wherewith his anger was kindled against Judah, because of all the provocations that Manasseh had provoked him withal."}, {"numero": 27, "texto": "And the Lord said, I will remove Judah also out of my sight, as I have removed Israel, and will cast off this city Jerusalem which I have chosen, and the house of which I said, My name shall be there."}, {"numero": 28, "texto": "Now the rest of the acts of Josiah, and all that he did, are they not written in the book of the chronicles of the kings of Judah?"}, {"numero": 29, "texto": "In his days Pharaohnechoh king of Egypt went up against the king of Assyria to the river Euphrates: and king Josiah went against him; and he slew him at Megiddo, when he had seen him."}, {"numero": 30, "texto": "And his servants carried him in a chariot dead from Megiddo, and brought him to Jerusalem, and buried him in his own sepulchre. And the people of the land took Jehoahaz the son of Josiah, and anointed him, and made him king in his father''s stead."}, {"numero": 31, "texto": "Jehoahaz was twenty and three years old when he began to reign; and he reigned three months in Jerusalem. And his mother''s name was Hamutal, the daughter of Jeremiah of Libnah."}, {"numero": 32, "texto": "And he did that which was evil in the sight of the Lord, according to all that his fathers had done."}, {"numero": 33, "texto": "And Pharaohnechoh put him in bands at Riblah in the land of Hamath, that he might not reign in Jerusalem; and put the land to a tribute of an hundred talents of silver, and a talent of gold."}, {"numero": 34, "texto": "And Pharaohnechoh made Eliakim the son of Josiah king in the room of Josiah his father, and turned his name to Jehoiakim, and took Jehoahaz away: and he came to Egypt, and died there."}, {"numero": 35, "texto": "And Jehoiakim gave the silver and the gold to Pharaoh; but he taxed the land to give the money according to the commandment of Pharaoh: he exacted the silver and the gold of the people of the land, of every one according to his taxation, to give it unto Pharaohnechoh."}, {"numero": 36, "texto": "Jehoiakim was twenty and five years old when he began to reign; and he reigned eleven years in Jerusalem. And his mother''s name was Zebudah, the daughter of Pedaiah of Rumah."}, {"numero": 37, "texto": "And he did that which was evil in the sight of the Lord, according to all that his fathers had done."}]'::jsonb, 'King James Version'),
  ('2Rs', 23, 'fr', '[{"numero": 1, "texto": "Le roi Josias fit assembler auprès de lui tous les anciens de Juda et de Jérusalem."}, {"numero": 2, "texto": "Puis il monta à la maison de l''''Eternel, avec tous les hommes de Juda et tous les habitants de Jérusalem, les sacrificateurs, les prophètes, et tout le peuple, depuis le plus petit jusqu''''au plus grand. Il lut devant eux toutes les paroles du livre de l''''alliance, qu''''on avait trouvé dans la maison de l''''Eternel."}, {"numero": 3, "texto": "Le roi se tenait sur l''''estrade, et il traita alliance devant l''''Eternel, s''''engageant à suivre l''''Eternel, et à observer ses ordonnances, ses préceptes et ses lois, de tout son coeur et de toute son âme, afin de mettre en pratique les paroles de cette alliance, écrites dans ce livre. Et tout le peuple entra dans l''''alliance."}, {"numero": 4, "texto": "Le roi ordonna à Hilkija, le souverain sacrificateur, aux sacrificateurs du second ordre, et à ceux qui gardaient le seuil, de sortir du temple de l''''Eternel tous les ustensiles qui avaient été faits pour Baal, pour Astarté, et pour toute l''''armée des cieux; et il les brûla hors de Jérusalem, dans les champs du Cédron, et en fit porter la poussière à Béthel."}, {"numero": 5, "texto": "Il chassa les prêtres des idoles, établis par les rois de Juda pour brûler des parfums sur les hauts lieux dans les villes de Juda et aux environs de Jérusalem, et ceux qui offraient des parfums à Baal, au soleil, à la lune, au zodiaque et à toute l''''armée des cieux."}, {"numero": 6, "texto": "Il sortit de la maison de l''''Eternel l''''idole d''''Astarté, qu''''il transporta hors de Jérusalem vers le torrent de Cédron; il la brûla au torrent de Cédron et la réduisit en poussière, et il en jeta la poussière sur les sépulcres des enfants du peuple."}, {"numero": 7, "texto": "Il abattit les maisons des prostitués qui étaient dans la maison de l''''Eternel, et où les femmes tissaient des tentes pour Astarté."}, {"numero": 8, "texto": "Il fit venir tous les prêtres des villes de Juda; il souilla les hauts lieux où les prêtres brûlaient des parfums, depuis Guéba jusqu''''à Beer-Schéba; et il renversa les hauts lieux des portes, celui qui était à l''''entrée de la porte de Josué, chef de la ville, et celui qui était à gauche de la porte de la ville."}, {"numero": 9, "texto": "Toutefois les prêtres des hauts lieux ne montaient pas à l''''autel de l''''Eternel à Jérusalem, mais ils mangeaient des pains sans levain au milieu de leurs frères."}, {"numero": 10, "texto": "Le roi souilla Topheth dans la vallée des fils de Hinnom, afin que personne ne fît plus passer son fils ou sa fille par le feu en l''''honneur de Moloc."}, {"numero": 11, "texto": "Il fit disparaître de l''''entrée de la maison de l''''Eternel les chevaux que les rois de Juda avaient consacrés au soleil, près de la chambre de l''''eunuque Nethan-Mélec, qui demeurait dans le faubourg; et il brûla au feu les chars du soleil."}, {"numero": 12, "texto": "Le roi démolit les autels qui étaient sur le toit de la chambre haute d''''Achaz et que les rois de Juda avaient faits, et les autels qu''''avait faits Manassé dans les deux parvis de la maison de l''''Eternel; après les avoir brisés et enlevés de là, il en jeta la poussière dans le torrent de Cédron."}, {"numero": 13, "texto": "Le roi souilla les hauts lieux qui étaient en face de Jérusalem, sur la droite de la montagne de perdition, et que Salomon, roi d''''Israël, avait bâtis à Astarté, l''''abomination des Sidoniens, à Kemosch, l''''abomination de Moab, et à Milcom, l''''abomination des fils d''''Ammon."}, {"numero": 14, "texto": "Il brisa les statues et abattit les idoles, et il remplit d''''ossements d''''hommes la place qu''''elles occupaient."}, {"numero": 15, "texto": "Il renversa aussi l''''autel qui était à Béthel, et le haut lieu qu''''avait fait Jéroboam, fils de Nebath, qui avait fait pécher Israël; il brûla le haut lieu et le réduisit en poussière, et il brûla l''''idole."}, {"numero": 16, "texto": "Josias, s''''étant tourné et ayant vu les sépulcres qui étaient là dans la montagne, envoya prendre les ossements des sépulcres, et il les brûla sur l''''autel et le souilla, selon la parole de l''''Eternel prononcée par l''''homme de Dieu qui avait annoncé ces choses."}, {"numero": 17, "texto": "Il dit: Quel est ce monument que je vois? Les gens de la ville lui répondirent: C''''est le sépulcre de l''''homme de Dieu, qui est venu de Juda, et qui a crié contre l''''autel de Béthel ces choses que tu as accomplies."}, {"numero": 18, "texto": "Et il dit: Laissez-le; que personne ne remue ses os! On conserva ainsi ses os avec les os du prophète qui était venu de Samarie."}, {"numero": 19, "texto": "Josias fit encore disparaître toutes les maisons des hauts lieux, qui étaient dans les villes de Samarie, et qu''''avaient faites les rois d''''Israël pour irriter l''''Eternel; il fit à leur égard entièrement comme il avait fait à Béthel."}, {"numero": 20, "texto": "Il immola sur les autels tous les prêtres des hauts lieux, qui étaient là, et il y brûla des ossements d''''hommes. Puis il retourna à Jérusalem."}, {"numero": 21, "texto": "Le roi donna cet ordre à tout le peuple: Célébrez la Pâque en l''''honneur de l''''Eternel, votre Dieu, comme il est écrit dans ce livre de l''''alliance."}, {"numero": 22, "texto": "Aucune Pâque pareille à celle-ci n''''avait été célébrée depuis le temps où les juges jugeaient Israël et pendant tous les jours des rois d''''Israël et des rois de Juda."}, {"numero": 23, "texto": "Ce fut la dix-huitième année du roi Josias qu''''on célébra cette Pâque en l''''honneur de l''''Eternel à Jérusalem."}, {"numero": 24, "texto": "De plus, Josias fit disparaître ceux qui évoquaient les esprits et ceux qui prédisaient l''''avenir, et les théraphim, et les idoles, et toutes les abominations qui se voyaient dans le pays de Juda et à Jérusalem, afin de mettre en pratique les paroles de la loi, écrites dans le livre que le sacrificateur Hilkija avait trouvé dans la maison de l''''Eternel."}, {"numero": 25, "texto": "Avant Josias, il n''''y eut point de roi qui, comme lui, revînt à l''''Eternel de tout son coeur, de toute son âme et de toute sa force, selon toute la loi de Moïse; et après lui, il n''''en a point paru de semblable."}, {"numero": 26, "texto": "Toutefois l''''Eternel ne se désista point de l''''ardeur de sa grande colère dont il était enflammé contre Juda, à cause de tout ce qu''''avait fait Manassé pour l''''irriter."}, {"numero": 27, "texto": "Et l''''Eternel dit: J''''ôterai aussi Juda de devant ma face comme j''''ai ôté Israël, et je rejetterai cette ville de Jérusalem que j''''avais choisie, et la maison de laquelle j''''avais dit: Là sera mon nom."}, {"numero": 28, "texto": "Le reste des actions de Josias, et tout ce qu''''il a fait, cela n''''est-il pas écrit dans le livre des Chroniques des rois de Juda?"}, {"numero": 29, "texto": "De son temps, Pharaon Néco, roi d''''Egypte, monta contre le roi d''''Assyrie, vers le fleuve de l''''Euphrate. Le roi Josias marcha à sa rencontre; et Pharaon le tua à Meguiddo, dès qu''''il le vit."}, {"numero": 30, "texto": "Ses serviteurs l''''emportèrent mort sur un char; ils l''''amenèrent de Meguiddo à Jérusalem, et ils l''''enterrèrent dans son sépulcre. Et le peuple du pays prit Joachaz, fils de Josias; ils l''''oignirent, et le firent roi à la place de son père."}, {"numero": 31, "texto": "Joachaz avait vingt-trois ans lorsqu''''il devint roi, et il régna trois mois à Jérusalem. Sa mère s''''appelait Hamuthal, fille de Jérémie, de Libna."}, {"numero": 32, "texto": "Il fit ce qui est mal aux yeux de l''''Eternel, entièrement comme avaient fait ses pères."}, {"numero": 33, "texto": "Pharaon Néco l''''enchaîna à Ribla, dans le pays de Hamath, pour qu''''il ne régnât plus à Jérusalem; et il mit sur le pays une contribution de cent talents d''''argent et d''''un talent d''''or."}, {"numero": 34, "texto": "Et Pharaon Néco établit roi Eliakim, fils de Josias, à la place de Josias, son père, et il changea son nom en celui de Jojakim. Il prit Joachaz, qui alla en Egypte et y mourut."}, {"numero": 35, "texto": "Jojakim donna à Pharaon l''''argent et l''''or; mais il taxa le pays pour fournir cet argent, d''''après l''''ordre de Pharaon; il détermina la part de chacun et exigea du peuple du pays l''''argent et l''''or qu''''il devait livrer à Pharaon Néco."}, {"numero": 36, "texto": "Jojakim avait vingt-cinq ans lorsqu''''il devint roi, et il régna onze ans à Jérusalem. Sa mère s''''appelait Zebudda, fille de Pedaja, de Ruma."}, {"numero": 37, "texto": "Il fit ce qui est mal aux yeux de l''''Eternel, entièrement comme avaient fait ses pères."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 23, 'es', '[{"numero": 1, "texto": "ENTONCES el rey envió, y juntaron á él todos los ancianos de Judá y de Jerusalem."}, {"numero": 2, "texto": "Y subió el rey á la casa de Jehová con todos los varones de Judá, y con todos los moradores de Jerusalem, con los sacerdotes y profetas y con todo el pueblo, desde el más chico hasta el más grande; y leyó, oyéndolo ellos, todas las palabras del libro del pacto que había sido hallado en la casa de Jehová."}, {"numero": 3, "texto": "Y poniéndose el rey en pie junto á la columna, hizo alianza delante de Jehová, de que irían en pos de Jehová, y guardarían sus mandamientos, y sus testimonios, y sus estatutos, con todo el corazón y con toda el alma, y que cumplirían las palabras de la alianza que estaban escritas en aquel libro. Y todo el pueblo confirmó el pacto."}, {"numero": 4, "texto": "Entonces mandó el rey al sumo sacerdote Hilcías, y á los sacerdotes de segundo orden, y á los guardianes de la puerta, que sacasen del templo de Jehová todos los vasos que habían sido hechos para Baal, y para el bosque, y para toda la milicia del cielo; y quemólos fuera de Jerusalem en el campo de Cedrón, é hizo llevar las cenizas de ellos á Beth-el."}, {"numero": 5, "texto": "Y quitó á los Camoreos, que habían puesto los reyes de Judá para que quemasen perfumes en los altos en las ciudades de Judá, y en los alrededores de Jerusalem; y asimismo á los que quemaban perfumes á Baal, al sol y á la luna, y á los signos, y á todo el ejército del cielo."}, {"numero": 6, "texto": "Hizo también sacar el bosque fuera de la casa de Jehová, fuera de Jerusalem, al torrente de Cedrón, y quemólo en el torrente de Cedrón, y tornólo en polvo, y echó el polvo de él sobre los sepulcros de los hijos del pueblo."}, {"numero": 7, "texto": "Además derribó las casas de los sodomitas que estaban en la casa de Jehová, en las cuales tejían las mujeres pabellones para el bosque."}, {"numero": 8, "texto": "E hizo venir todos los sacerdotes de las ciudades de Judá, y profanó los altos donde los sacerdotes quemaban perfumes, desde Gabaa hasta Beer-seba; y derribó los altares de las puertas que estaban á la entrada de la puerta de Josué, gobernador de la ciudad, que estaban á la mano izquierda, á la puerta de la ciudad."}, {"numero": 9, "texto": "Empero los sacerdotes de los altos no subían al altar de Jehová en Jerusalem, mas comían panes sin levadura entre sus hermanos."}, {"numero": 10, "texto": "Asimismo profanó á Topheth, que está en el valle del hijo de Hinnom, porque ninguno pasase su hijo ó su hija por fuego á Moloch."}, {"numero": 11, "texto": "Quitó también los caballos que los reyes de Judá habían dedicado al sol á la entrada del templo de Jehová, junto á la cámara de Nathan-melech eunuco, el cual tenía cargo de los ejidos; y quemó al fuego los carros del sol."}, {"numero": 12, "texto": "Derribó además el rey los altares que estaban sobre la techumbre de la sala de Achâz, que los reyes de Judá habían hecho, y los altares que había hecho Manasés en los dos atrios de la casa de Jehová; y de allí corrió y arrojó el polvo en el torrente de Cedrón."}, {"numero": 13, "texto": "Asimismo profanó el rey los altos que estaban delante de Jerusalem, á la mano derecha del monte de la destrucción, los cuales Salomón rey de Israel había edificado á Astharoth, abominación de los Sidonios, y á Chêmos abominación de Moab, y á Milcom abominación de los hijos de Ammón."}, {"numero": 14, "texto": "Y quebró las estatuas, y taló los bosques, é hinchió el lugar de ellos de huesos de hombres."}, {"numero": 15, "texto": "Igualmente el altar que estaba en Beth-el, y el alto que había hecho Jeroboam hijo de Nabat, el que hizo pecar á Israel, aquel altar y el alto destruyó; y quemó el alto, y lo tornó en polvo, y puso fuego al bosque."}, {"numero": 16, "texto": "Y volvióse Josías, y viendo los sepulcros que estaban allí en el monte, envió y sacó los huesos de los sepulcros, y quemólos sobre el altar para contaminarlo, conforme á la palabra de Jehová que había profetizado el varón de Dios, el cual había anunciado estos negocios."}, {"numero": 17, "texto": "Y después dijo: ¿Qué título es este que veo? Y los de la ciudad le respondieron: Este es el sepulcro del varón de Dios que vino de Judá, y profetizó estas cosas que tú has hecho sobre el altar de Beth-el."}, {"numero": 18, "texto": "Y él dijo: Dejadlo; ninguno mueva sus huesos: y así fueron preservados sus huesos, y los huesos del profeta que había venido de Samaria."}, {"numero": 19, "texto": "Y todas las casas de los altos que estaban en las ciudades de Samaria, las cuales habían hecho los reyes de Israel para provocar á ira, quitólas también Josías, é hizo de ellas como había hecho en Beth-el."}, {"numero": 20, "texto": "Mató además sobre los altares á todos los sacerdotes de los altos que allí estaban, y quemó sobre ellos huesos de hombres, y volvióse á Jerusalem."}, {"numero": 21, "texto": "Entonces mandó el rey á todo el pueblo, diciendo: Haced la pascua á Jehová vuestro Dios, conforme á lo que está escrito en el libro de esta alianza."}, {"numero": 22, "texto": "No fué hecha tal pascua desde los tiempos de los jueces que gobernaron á Israel, ni en todos los tiempos de los reyes de Israel, y de los reyes de Judá."}, {"numero": 23, "texto": "A los diez y ocho años del rey Josías fué hecha aquella pascua á Jehová en Jerusalem."}, {"numero": 24, "texto": "Asimismo barrió Josías los pythones, adivinos, y terapheos, y todas las abominaciones que se veían en la tierra de Judá y en Jerusalem, para cumplir las palabras de la ley que estaban escritas en el libro que el sacerdote Hilcías había hallado en la casa de Jehová."}, {"numero": 25, "texto": "No hubo tal rey antes de él que se convirtiese á Jehová de todo su corazón, y de toda su alma, y de todas su fuerzas, conforme á toda la ley de Moisés; ni después de él nació otro tal."}, {"numero": 26, "texto": "Con todo eso, no se volvió Jehová del ardor de su grande ira, con que se había encendido su enojo contra Judá, por todas las provocaciones con que Manasés le había irritado."}, {"numero": 27, "texto": "Y dijo Jehová: También he de quitar de mi presencia á Judá, como quité á Israel, y abominaré á esta ciudad que había escogido, á Jerusalem, y á la casa de la cual había yo dicho: Mi nombre será allí."}, {"numero": 28, "texto": "Lo demás de los hechos de Josías, y todas las cosas que hizo, ¿no está todo escrito en el libro de las crónicas de los reyes de Judá?"}, {"numero": 29, "texto": "En aquellos días Faraón Nechâo rey de Egipto subió contra el rey de Asiria al río Eufrates, y salió contra él el rey Josías; pero aquél, así que le vió, matólo en Megiddo."}, {"numero": 30, "texto": "Y sus siervos lo pusieron en un carro, y trajéronlo muerto de Megiddo á Jerusalem, y sepultáronlo en su sepulcro. Entonces el pueblo de la tierra tomó á Joachâz hijo de Josías, y ungiéronle y pusiéronlo por rey en lugar de su padre."}, {"numero": 31, "texto": "De veintitrés años era Joachâz cuando comenzó á reinar, y reinó tres meses en Jerusalem. El nombre de su madre fué Amutal, hija de Jeremías de Libna."}, {"numero": 32, "texto": "Y él hizo lo malo en ojos de Jehová, conforme á todas las cosas que sus padres habían hecho."}, {"numero": 33, "texto": "Y echólo preso Faraón Nechâo en Ribla en la provincia de Hamath, reinando él en Jerusalem; é impuso sobre la tierra una multa de cien talentos de plata, y uno de oro."}, {"numero": 34, "texto": "Entonces Faraón Nechâo puso por rey á Eliacim hijo de Josías, en lugar de Josías su padre, y mudóle el nombre en el de Joacim; y tomó á Joachâz, y llevólo á Egipto, y murió allí."}, {"numero": 35, "texto": "Y Joacim pagó á Faraón la plata y el oro; mas hizo apreciar la tierra para dar el dinero conforme al mandamiento de Faraón, sacando la plata y oro del pueblo de la tierra, de cada uno según la estimación de su hacienda, para dar á Faraón Nechâo."}, {"numero": 36, "texto": "De veinticinco años era Joacim cuando comenzó á Reinar, y once años reinó en Jerusalem. El nombre de su madre fué Zebuda hija de Pedaia, de Ruma."}, {"numero": 37, "texto": "E hizo lo malo en ojos de Jehová, conforme á todas las cosas que sus padres habían hecho."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 24, 'pt', '[{"numero": 1, "texto": "Em seu tempo subiu Nabucodonosor, rei de Babilônia, ao qual Jeoaquim serviu por três anos; depois voltou-se contra e se rebelou contra ele."}, {"numero": 2, "texto": "O SENHOR, porém, enviou contra ele tropas de caldeus, e tropas de sírios, e tropas de moabitas, e tropas de amonitas; os quais enviou contra Judá para que a destruíssem, conforme a palavra do SENHOR que havia falado por meio dos seus servos, os profetas."}, {"numero": 3, "texto": "Certamente foi por ordem do SENHOR que veio isto contra Judá, para tirá-la de sua presença, pelos pecados de Manassés, conforme tudo o que ele fez;"}, {"numero": 4, "texto": "Também pelo sangue inocente que derramou, pois encheu Jerusalém de sangue inocente; o SENHOR, portanto, não quis perdoar."}, {"numero": 5, "texto": "Os demais dos feitos de Jeoaquim, e todas as coisas que fez, não estão escritos no livro das crônicas dos reis de Judá?"}, {"numero": 6, "texto": "E descansou Jeoaquim com seus pais, e reinou em seu lugar seu filho Joaquim."}, {"numero": 7, "texto": "E nunca mais o rei do Egito saiu de sua terra; porque o rei da Babilônia lhe tomou tudo o que era seu, desde o rio do Egito até o rio de Eufrates."}, {"numero": 8, "texto": "Tinha Joaquim dezoito anos quando começou a reinar, e reinou em Jerusalém três meses. O nome de sua mãe foi Neusta filha de Elnatã, de Jerusalém."}, {"numero": 9, "texto": "E fez o que era mau aos olhos do SENHOR, conforme todas as coisas que seu pai havia feito."}, {"numero": 10, "texto": "Naquele tempo subiram os servos de Nabucodonosor rei da Babilônia contra Jerusalém e a cidade foi cercada."}, {"numero": 11, "texto": "Veio também Nabucodonosor rei da Babilônia contra a cidade, quando seus servos a tinham cercado."}, {"numero": 12, "texto": "Então saiu Joaquim rei de Judá, para render-se ao rei da Babilônia, ele, e sua mãe, e seus servos, e seus príncipes, e seus eunucos; e o rei da Babilônia o prendeu no oitavo ano de seu reinado."}, {"numero": 13, "texto": "E tirou dali todos os tesouros da casa do SENHOR, e os tesouros da casa real, e despedaçou todos os utensílios de ouro que havia feito Salomão rei de Israel na casa do SENHOR, como o SENHOR havia dito."}, {"numero": 14, "texto": "E levou em cativeiro toda Jerusalém, todos os príncipes, e todos os homens valentes, até dez mil cativos, e todos os artesãos e ferreiros; que não restou ninguém, exceto os pobres do povo da terra."}, {"numero": 15, "texto": "Também levou cativo Joaquim à Babilônia, assim como a mãe do rei, as mulheres do rei, os seus eunucos, e os poderosos daquela terra; cativos os levou de Jerusalém à Babilônia."}, {"numero": 16, "texto": "A todos os homens de guerra, que foram sete mil, e aos oficiais e ferreiros, que foram mil, e a todos os valentes para fazer a guerra, levou cativos o rei da Babilônia."}, {"numero": 17, "texto": "E o rei da Babilônia pôs como rei em lugar de Joaquim a Matanias, tio dele, e mudou-lhe o nome para Zedequias."}, {"numero": 18, "texto": "De vinte e um anos era Zedequias quando começou a reinar, e reinou em Jerusalém onze anos. O nome de sua mãe foi Hamutal filha de Jeremias, de Libna."}, {"numero": 19, "texto": "E fez o que era mau aos olhos do SENHOR, conforme a tudo o que havia feito Jeoaquim."}, {"numero": 20, "texto": "Assim aconteceu por causa da ira do SENHOR contra Jerusalém e Judá, até que os expulsou de sua presença. E Zedequias se rebelou contra o rei da Babilônia."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 24, 'en', '[{"numero": 1, "texto": "In his days Nebuchadnezzar king of Babylon came up, and Jehoiakim became his servant three years: then he turned and rebelled against him."}, {"numero": 2, "texto": "And the Lord sent against him bands of the Chaldees, and bands of the Syrians, and bands of the Moabites, and bands of the children of Ammon, and sent them against Judah to destroy it, according to the word of the Lord, which he spake by his servants the prophets."}, {"numero": 3, "texto": "Surely at the commandment of the Lord came this upon Judah, to remove them out of his sight, for the sins of Manasseh, according to all that he did;"}, {"numero": 4, "texto": "And also for the innocent blood that he shed: for he filled Jerusalem with innocent blood; which the Lord would not pardon."}, {"numero": 5, "texto": "Now the rest of the acts of Jehoiakim, and all that he did, are they not written in the book of the chronicles of the kings of Judah?"}, {"numero": 6, "texto": "So Jehoiakim slept with his fathers: and Jehoiachin his son reigned in his stead."}, {"numero": 7, "texto": "And the king of Egypt came not again any more out of his land: for the king of Babylon had taken from the river of Egypt unto the river Euphrates all that pertained to the king of Egypt."}, {"numero": 8, "texto": "Jehoiachin was eighteen years old when he began to reign, and he reigned in Jerusalem three months. And his mother''s name was Nehushta, the daughter of Elnathan of Jerusalem."}, {"numero": 9, "texto": "And he did that which was evil in the sight of the Lord, according to all that his father had done."}, {"numero": 10, "texto": "At that time the servants of Nebuchadnezzar king of Babylon came up against Jerusalem, and the city was besieged."}, {"numero": 11, "texto": "And Nebuchadnezzar king of Babylon came against the city, and his servants did besiege it."}, {"numero": 12, "texto": "And Jehoiachin the king of Judah went out to the king of Babylon, he, and his mother, and his servants, and his princes, and his officers: and the king of Babylon took him in the eighth year of his reign."}, {"numero": 13, "texto": "And he carried out thence all the treasures of the house of the Lord, and the treasures of the king''s house, and cut in pieces all the vessels of gold which Solomon king of Israel had made in the temple of the Lord, as the Lord had said."}, {"numero": 14, "texto": "And he carried away all Jerusalem, and all the princes, and all the mighty men of valour, even ten thousand captives, and all the craftsmen and smiths: none remained, save the poorest sort of the people of the land."}, {"numero": 15, "texto": "And he carried away Jehoiachin to Babylon, and the king''s mother, and the king''s wives, and his officers, and the mighty of the land, those carried he into captivity from Jerusalem to Babylon."}, {"numero": 16, "texto": "And all the men of might, even seven thousand, and craftsmen and smiths a thousand, all that were strong and apt for war, even them the king of Babylon brought captive to Babylon."}, {"numero": 17, "texto": "And the king of Babylon made Mattaniah his father''s brother king in his stead, and changed his name to Zedekiah."}, {"numero": 18, "texto": "Zedekiah was twenty and one years old when he began to reign, and he reigned eleven years in Jerusalem. And his mother''s name was Hamutal, the daughter of Jeremiah of Libnah."}, {"numero": 19, "texto": "And he did that which was evil in the sight of the Lord, according to all that Jehoiakim had done."}, {"numero": 20, "texto": "For through the anger of the Lord it came to pass in Jerusalem and Judah, until he had cast them out from his presence, that Zedekiah rebelled against the king of Babylon."}]'::jsonb, 'King James Version'),
  ('2Rs', 24, 'fr', '[{"numero": 1, "texto": "De son temps, Nebucadnetsar, roi de Babylone, se mit en campagne. Jojakim lui fut assujetti pendant trois ans; mais il se révolta de nouveau contre lui."}, {"numero": 2, "texto": "Alors l''''Eternel envoya contre Jojakim des troupes de Chaldéens, des troupes de Syriens, des troupes de Moabites et des troupes d''''Ammonites; il les envoya contre Juda pour le détruire, selon la parole que l''''Eternel avait prononcée par ses serviteurs les prophètes."}, {"numero": 3, "texto": "Cela arriva uniquement sur l''''ordre de l''''Eternel, qui voulait ôter Juda de devant sa face, à cause de tous les péchés commis par Manassé,"}, {"numero": 4, "texto": "et à cause du sang innocent qu''''avait répandu Manassé et dont il avait rempli Jérusalem. Aussi l''''Eternel ne voulut-il point pardonner."}, {"numero": 5, "texto": "Le reste des actions de Jojakim, et tout ce qu''''il a fait, cela n''''est-il pas écrit dans le livre des Chroniques des rois de Juda?"}, {"numero": 6, "texto": "Jojakim se coucha avec ses pères. Et Jojakin, son fils, régna à sa place."}, {"numero": 7, "texto": "Le roi d''''Egypte ne sortit plus de son pays, car le roi de Babylone avait pris tout ce qui était au roi d''''Egypte depuis le torrent d''''Egypte jusqu''''au fleuve de l''''Euphrate."}, {"numero": 8, "texto": "Jojakin avait dix-huit ans lorsqu''''il devint roi, et il régna trois mois à Jérusalem. Sa mère s''''appelait Nehuschtha, fille d''''Elnathan, de Jérusalem."}, {"numero": 9, "texto": "Il fit ce qui est mal aux yeux de l''''Eternel, entièrement comme avait fait son père."}, {"numero": 10, "texto": "En ce temps-là, les serviteurs de Nebucadnetsar, roi de Babylone, montèrent contre Jérusalem, et la ville fut assiégée."}, {"numero": 11, "texto": "Nebucadnetsar, roi de Babylone, arriva devant la ville pendant que ses serviteurs l''''assiégeaient."}, {"numero": 12, "texto": "Alors Jojakin, roi de Juda, se rendit auprès du roi de Babylone, avec sa mère, ses serviteurs, ses chefs et ses eunuques. Et le roi de Babylone le fit prisonnier, la huitième année de son règne."}, {"numero": 13, "texto": "Il tira de là tous les trésors de la maison de l''''Eternel et les trésors de la maison du roi; et il brisa tous les ustensiles d''''or que Salomon, roi d''''Israël, avait faits dans le temple de l''''Eternel, comme l''''Eternel l''''avait prononcé."}, {"numero": 14, "texto": "Il emmena en captivité tout Jérusalem, tous les chefs et tous les hommes vaillants, au nombre de dix mille exilés, avec tous les charpentiers et les serruriers: il ne resta que le peuple pauvre du pays."}, {"numero": 15, "texto": "Il transporta Jojakin à Babylone; et il emmena captifs de Jérusalem à Babylone la mère du roi, les femmes du roi et ses eunuques, et les grands du pays,"}, {"numero": 16, "texto": "tous les guerriers au nombre de sept mille, et les charpentiers et les serruriers au nombre de mille, tous hommes vaillants et propres à la guerre. Le roi de Babylone les emmena captifs à Babylone."}, {"numero": 17, "texto": "Et le roi de Babylone établit roi, à la place de Jojakin, Matthania, son oncle, dont il changea le nom en celui de Sédécias."}, {"numero": 18, "texto": "Sédécias avait vingt et un ans lorsqu''''il devint roi, et il régna onze ans à Jérusalem. Sa mère s''''appelait Hamuthal, fille de Jérémie, de Libna."}, {"numero": 19, "texto": "Il fit ce qui est mal aux yeux de l''''Eternel, entièrement comme avait fait Jojakim."}, {"numero": 20, "texto": "Et cela arriva à cause de la colère de l''''Eternel contre Jérusalem et contre Juda, qu''''il voulait rejeter de devant sa face. Et Sédécias se révolta contre le roi de Babylone."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 24, 'es', '[{"numero": 1, "texto": "EN su tiempo subió Nabucodonosor rey de Babilonia, al cual sirvió Joacim tres años; volvióse luego, y se rebeló contra él."}, {"numero": 2, "texto": "Jehová empero envió contra él tropas de Caldeos, y tropas de Siros, y tropas de Moabitas, y tropas de Ammonitas; los cuales envió contra Judá para que la destruyesen, conforme á la palabra de Jehová que había hablado por sus siervos los profetas."}, {"numero": 3, "texto": "Ciertamente vino esto contra Judá por dicho de Jehová, para quitarla de su presencia, por los pecados de Manasés, conforme á todo lo que hizo;"}, {"numero": 4, "texto": "Asimismo por la sangre inocente que derramó, pues hinchió á Jerusalem de sangre inocente: Jehová por tanto, no quiso perdonar."}, {"numero": 5, "texto": "Lo demás de los hechos de Joacim, y todas las cosas que hizo, ¿no está escrito en el libro de las crónicas de los reyes de Judá?"}, {"numero": 6, "texto": "Y durmió Joacim con sus padres, y reinó en su lugar Joachîn su hijo."}, {"numero": 7, "texto": "Y nunca más el rey de Egipto salió de su tierra: porque el rey de Babilonia le tomó todo lo que era suyo, desde el río de Egipto hasta el río de Eufrates."}, {"numero": 8, "texto": "De dieciocho años era Joachîn cuando comenzó á reinar, y reinó en Jerusalem tres meses. El nombre de su madre fué Neusta hija de Elnathán, de Jerusalem."}, {"numero": 9, "texto": "E hizo lo malo en ojos de Jehová, conforme á todas las cosas que había hecho su padre."}, {"numero": 10, "texto": "En aquel tiempo subieron los siervos de Nabucodonosor rey de Babilonia contra Jerusalem, y la ciudad fué cercada."}, {"numero": 11, "texto": "Vino también Nabucodonosor rey de Babilonia contra la ciudad, cuando sus siervos la tenían cercada."}, {"numero": 12, "texto": "Entonces salió Joachîn rey de Judá al rey de Babilonia, él, y su madre, y sus siervos, y sus príncipes, y sus eunucos: y prendiólo el rey de Babilonia en el octavo año de su reinado."}, {"numero": 13, "texto": "Y sacó de allí todos los tesoros de la casa de Jehová, y los tesoros de la casa real, y quebró en piezas todos los vasos de oro que había hecho Salomón rey de Israel en la casa de Jehová, como Jehová había dicho."}, {"numero": 14, "texto": "Y llevó en cautiverio á toda Jerusalem, á todos los príncipes, y á todos los hombres valientes, hasta diez mil cautivos, y á todos los oficiales y herreros; que no quedó nadie, excepto los pobres del pueblo de la tierra."}, {"numero": 15, "texto": "Asimismo trasportó á Joachîn á Babilonia, y á la madre del rey, y á las mujeres del rey, y á sus eunucos, y á los poderosos de la tierra; cautivos los llevó de Jerusalem á Babilonia."}, {"numero": 16, "texto": "A todos los hombre de guerra, que fueron siete mil, y á los oficiales y herreros, que fueron mil, y á todos los valientes para hacer la guerra, llevó cautivos el rey de Babilonia."}, {"numero": 17, "texto": "Y el rey de Babilonia puso por rey en lugar de Joachîn á Mathanías su tío, y mudóle el nombre en el de Sedecías."}, {"numero": 18, "texto": "De veintiún años era Sedecías cuando comenzó á reinar, y reinó en Jerusalem once años. El nombre de su madre fué Amutal hija de Jeremías, de Libna."}, {"numero": 19, "texto": "E hizo lo malo en ojos de Jehová, conforme á todo lo que había hecho Joacim."}, {"numero": 20, "texto": "Fué pues la ira de Jehová contra Jerusalem y Judá, hasta que los echó de su presencia. Y Sedecías se rebeló contra el rey de Babilonia."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Rs', 25, 'pt', '[{"numero": 1, "texto": "E aconteceu aos nove anos de seu reinado, no mês décimo, aos dez do mês, que Nabucodonosor rei da Babilônia veio com todo seu exército contra Jerusalém, e cercou-a; e levantaram contra ela rampas de cerco ao redor."}, {"numero": 2, "texto": "E esteve a cidade cercado até o décimo primeiro ano do rei Zedequias."}, {"numero": 3, "texto": "Aos nove do mês prevaleceu a fome na cidade, que não houve pão para o povo da terra."}, {"numero": 4, "texto": "Aberta já a cidade, fugiram de noite todos os homens de guerra pelo caminho da porta que estava entre os dois muros, junto aos jardins do rei, estando os caldeus ao redor da cidade; e o rei se foi caminho da campina."}, {"numero": 5, "texto": "E o exército dos caldeus seguiu o rei, e tomou-o nas planícies de Jericó, e todo o seu exército se dispersou dele."}, {"numero": 6, "texto": "Tomado, pois, o rei, trouxeram-no ao rei da Babilônia a Ribla, e proferiram contra ele sentença."}, {"numero": 7, "texto": "E degolaram aos filhos de Zedequias em sua presença; e a Zedequias tiraram os olhos, e acorrentado com correntes levaram-no à Babilônia."}, {"numero": 8, "texto": "No mês quinto, aos sete do mês, sendo o ano dezenove de Nabucodonosor rei da Babilônia, veio a Jerusalém Nebuzaradã, capitão dos da guarda, servo do rei da Babilônia."}, {"numero": 9, "texto": "E queimou a casa do SENHOR, e a casa do rei, e todas as casas de Jerusalém; e todas as casas dos príncipes queimou a fogo."}, {"numero": 10, "texto": "E todo o exército dos caldeus que estava com o capitão da guarda, derrubou os muros de Jerusalém ao redor."}, {"numero": 11, "texto": "E aos do povo que haviam restado na cidade, e aos que se haviam juntado ao rei da Babilônia, e aos que haviam restado da população, transportou-o Nebuzaradã, capitão dos da guarda."}, {"numero": 12, "texto": "Mas dos pobres da terra deixou Nebuzaradã, capitão dos da guarda, para que lavrassem as vinhas e as terras."}, {"numero": 13, "texto": "E quebraram os caldeus as colunas de bronze que estavam na casa do SENHOR, e as bases, e o mar de bronze que estava na casa do SENHOR, e levaram o bronze disso à Babilônia."}, {"numero": 14, "texto": "Levaram-se também as caldeiras, e as pás, e as tenazes, e as colheres, e todos os vasos de bronze com que ministravam."}, {"numero": 15, "texto": "Incensários, bacias, os que de ouro, em ouro, e os que de prata, em prata, tudo o levou o capitão dos da guarda;"}, {"numero": 16, "texto": "As duas colunas, um mar, e as bases que Salomão havia feito para a casa do SENHOR: não havia peso de todos estes vasos."}, {"numero": 17, "texto": "A altura da uma coluna era dezoito côvados e tinha encima um capitel de bronze, e a altura do capitel era de três côvados; e sobre o capitel havia um enredado e romãs ao redor, todo de bronze: e semelhante obra havia na outra coluna com o enredado."}, {"numero": 18, "texto": "Tomou então o capitão dos da guarda a Seraías o sacerdote principal, e a Sofonias o segundo sacerdote, e três guardas da porta;"}, {"numero": 19, "texto": "E da cidade tomou um eunuco, o qual comandava os soldados, e cinco homens dos assistentes do rei, que se acharam na cidade; e ao principal escriba do exército, que fazia o registro da gente daquela terra; e sessenta homens do povo da terra,"}, {"numero": 20, "texto": "Nebuzaradã, capitão da guarda, tomou-os e os levou a Ribla, ao rei da Babilônia."}, {"numero": 21, "texto": "E o rei da Babilônia os feriu e matou em Ribla, em terra de Hamate. Assim foi transportado Judá de sobre sua terra."}, {"numero": 22, "texto": "E ao povo que Nabucodonosor rei da Babilônia deixou em terra de Judá, pôs por governador a Gedalias, filho de Aicã filho de Safã."}, {"numero": 23, "texto": "E ouvindo todos os príncipes do exército, eles e sua gente, que o rei da Babilônia havia posto por governador a Gedalias, vieram-se a ele em Mispá, a saber, Ismael filho de Netanias, e Joanã filho de Careá, e Seraías filho de Tanumete netofatita, e Jazanias filho do maacatita, eles com os seus subordinados."}, {"numero": 24, "texto": "Então Gedalias lhes fez juramento, a eles e aos seus subordinados, e disse-lhes: Não temais de ser servos dos caldeus; habitai na terra, e servi ao rei da Babilônia, e vos irá bem."}, {"numero": 25, "texto": "Mas no mês sétimo veio Ismael filho de Netanias, filho de Elisama, da família real, e com ele dez homens, e feriram a Gedalias, e morreu, assim como os judeus e os caldeus que estavam com ele em Mispá."}, {"numero": 26, "texto": "E levantando-se todo o povo, desde o menor até o maior, com os capitães do exército, foram-se ao Egito por temor dos caldeus."}, {"numero": 27, "texto": "E aconteceu aos trinta e sete anos do cativeiro de Joaquim rei de Judá, no décimo segundo mês, aos vinte e sete do mês, que Evil-Merodaque rei da Babilônia, no primeiro ano de seu reinado, concedeu favor a Joaquim rei de Judá, tirando-o da prisão."}, {"numero": 28, "texto": "E falou-lhe bem, e pôs seu assento em posição de maior honra do que o assento dos reis que estavam com ele na Babilônia."}, {"numero": 29, "texto": "E mudou-lhe as roupas de sua prisão, e comeu sempre diante dele todos os dias de sua vida."}, {"numero": 30, "texto": "E foi-lhe continuamente dada a sua subsistência diária da parte do rei, por todos os dias de sua vida."}]'::jsonb, 'Almeida Livre'),
  ('2Rs', 25, 'en', '[{"numero": 1, "texto": "And it came to pass in the ninth year of his reign, in the tenth month, in the tenth day of the month, that Nebuchadnezzar king of Babylon came, he, and all his host, against Jerusalem, and pitched against it; and they built forts against it round about."}, {"numero": 2, "texto": "And the city was besieged unto the eleventh year of king Zedekiah."}, {"numero": 3, "texto": "And on the ninth day of the fourth month the famine prevailed in the city, and there was no bread for the people of the land."}, {"numero": 4, "texto": "And the city was broken up, and all the men of war fled by night by the way of the gate between two walls, which is by the king''s garden: (now the Chaldees were against the city round about:) and the king went the way toward the plain."}, {"numero": 5, "texto": "And the army of the Chaldees pursued after the king, and overtook him in the plains of Jericho: and all his army were scattered from him."}, {"numero": 6, "texto": "So they took the king, and brought him up to the king of Babylon to Riblah; and they gave judgment upon him."}, {"numero": 7, "texto": "And they slew the sons of Zedekiah before his eyes, and put out the eyes of Zedekiah, and bound him with fetters of brass, and carried him to Babylon."}, {"numero": 8, "texto": "And in the fifth month, on the seventh day of the month, which is the nineteenth year of king Nebuchadnezzar king of Babylon, came Nebuzaradan, captain of the guard, a servant of the king of Babylon, unto Jerusalem:"}, {"numero": 9, "texto": "And he burnt the house of the Lord, and the king''s house, and all the houses of Jerusalem, and every great man''s house burnt he with fire."}, {"numero": 10, "texto": "And all the army of the Chaldees, that were with the captain of the guard, brake down the walls of Jerusalem round about."}, {"numero": 11, "texto": "Now the rest of the people that were left in the city, and the fugitives that fell away to the king of Babylon, with the remnant of the multitude, did Nebuzaradan the captain of the guard carry away."}, {"numero": 12, "texto": "But the captain of the guard left of the poor of the land to be vinedressers and husbandmen."}, {"numero": 13, "texto": "And the pillars of brass that were in the house of the Lord, and the bases, and the brasen sea that was in the house of the Lord, did the Chaldees break in pieces, and carried the brass of them to Babylon."}, {"numero": 14, "texto": "And the pots, and the shovels, and the snuffers, and the spoons, and all the vessels of brass wherewith they ministered, took they away."}, {"numero": 15, "texto": "And the firepans, and the bowls, and such things as were of gold, in gold, and of silver, in silver, the captain of the guard took away."}, {"numero": 16, "texto": "The two pillars, one sea, and the bases which Solomon had made for the house of the Lord; the brass of all these vessels was without weight."}, {"numero": 17, "texto": "The height of the one pillar was eighteen cubits, and the chapiter upon it was brass: and the height of the chapiter three cubits; and the wreathen work, and pomegranates upon the chapiter round about, all of brass: and like unto these had the second pillar with wreathen work."}, {"numero": 18, "texto": "And the captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the door:"}, {"numero": 19, "texto": "And out of the city he took an officer that was set over the men of war, and five men of them that were in the king''s presence, which were found in the city, and the principal scribe of the host, which mustered the people of the land, and threescore men of the people of the land that were found in the city:"}, {"numero": 20, "texto": "And Nebuzaradan captain of the guard took these, and brought them to the king of Babylon to Riblah:"}, {"numero": 21, "texto": "And the king of Babylon smote them, and slew them at Riblah in the land of Hamath. So Judah was carried away out of their land."}, {"numero": 22, "texto": "And as for the people that remained in the land of Judah, whom Nebuchadnezzar king of Babylon had left, even over them he made Gedaliah the son of Ahikam, the son of Shaphan, ruler."}, {"numero": 23, "texto": "And when all the captains of the armies, they and their men, heard that the king of Babylon had made Gedaliah governor, there came to Gedaliah to Mizpah, even Ishmael the son of Nethaniah, and Johanan the son of Careah, and Seraiah the son of Tanhumeth the Netophathite, and Jaazaniah the son of a Maachathite, they and their men."}, {"numero": 24, "texto": "And Gedaliah sware to them, and to their men, and said unto them, Fear not to be the servants of the Chaldees: dwell in the land, and serve the king of Babylon; and it shall be well with you."}, {"numero": 25, "texto": "But it came to pass in the seventh month, that Ishmael the son of Nethaniah, the son of Elishama, of the seed royal, came, and ten men with him, and smote Gedaliah, that he died, and the Jews and the Chaldees that were with him at Mizpah."}, {"numero": 26, "texto": "And all the people, both small and great, and the captains of the armies, arose, and came to Egypt: for they were afraid of the Chaldees."}, {"numero": 27, "texto": "And it came to pass in the seven and thirtieth year of the captivity of Jehoiachin king of Judah, in the twelfth month, on the seven and twentieth day of the month, that Evilmerodach king of Babylon in the year that he began to reign did lift up the head of Jehoiachin king of Judah out of prison;"}, {"numero": 28, "texto": "And he spake kindly to him, and set his throne above the throne of the kings that were with him in Babylon;"}, {"numero": 29, "texto": "And changed his prison garments: and he did eat bread continually before him all the days of his life."}, {"numero": 30, "texto": "And his allowance was a continual allowance given him of the king, a daily rate for every day, all the days of his life."}]'::jsonb, 'King James Version'),
  ('2Rs', 25, 'fr', '[{"numero": 1, "texto": "La neuvième année du règne de Sédécias, le dixième jour du dixième mois, Nebucadnetsar, roi de Babylone, vint avec toute son armée contre Jérusalem; il campa devant elle, et éleva des retranchements tout autour."}, {"numero": 2, "texto": "La ville fut assiégée jusqu''''à la onzième année du roi Sédécias."}, {"numero": 3, "texto": "Le neuvième jour du mois, la famine était forte dans la ville, et il n''''y avait pas de pain pour le peuple du pays."}, {"numero": 4, "texto": "Alors la brèche fut faite à la ville; et tous les gens de guerre s''''enfuirent de nuit par le chemin de la porte entre les deux murs près du jardin du roi, pendant que les Chaldéens environnaient la ville. Les fuyards prirent le chemin de la plaine."}, {"numero": 5, "texto": "Mais l''''armée des Chaldéens poursuivit le roi et l''''atteignit dans les plaines de Jéricho, et toute son armée se dispersa loin de lui."}, {"numero": 6, "texto": "Ils saisirent le roi, et le firent monter vers le roi de Babylone à Ribla; et l''''on prononça contre lui une sentence."}, {"numero": 7, "texto": "Les fils de Sédécias furent égorgés en sa présence; puis on creva les yeux à Sédécias, on le lia avec des chaînes d''''airain, et on le mena à Babylone."}, {"numero": 8, "texto": "Le septième jour du cinquième mois, -c''''était la dix-neuvième année du règne de Nebucadnetsar, roi de Babylone, -Nebuzaradan, chef des gardes, serviteur du roi de Babylone, entra dans Jérusalem."}, {"numero": 9, "texto": "Il brûla la maison de l''''Eternel, la maison du roi, et toutes les maisons de Jérusalem; il livra au feu toutes les maisons de quelque importance."}, {"numero": 10, "texto": "Toute l''''armée des Chaldéens, qui était avec le chef des gardes, démolit les murailles formant l''''enceinte de Jérusalem."}, {"numero": 11, "texto": "Nebuzaradan, chef des gardes, emmena captifs ceux du peuple qui étaient demeurés dans la ville, ceux qui s''''étaient rendus au roi de Babylone, et le reste de la multitude."}, {"numero": 12, "texto": "Cependant le chef des gardes laissa comme vignerons et comme laboureurs quelques-uns des plus pauvres du pays."}, {"numero": 13, "texto": "Les Chaldéens brisèrent les colonnes d''''airain qui étaient dans la maison de l''''Eternel, les bases, la mer d''''airain qui était dans la maison de l''''Eternel, et ils en emportèrent l''''airain à Babylone."}, {"numero": 14, "texto": "Ils prirent les cendriers, les pelles, les couteaux, les tasses, et tous les ustensiles d''''airain avec lesquels on faisait le service."}, {"numero": 15, "texto": "Le chef des gardes prit encore les brasiers et les coupes, ce qui était d''''or et ce qui était d''''argent."}, {"numero": 16, "texto": "Les deux colonnes, la mer, et les bases, que Salomon avait faites pour la maison de l''''Eternel, tous ces ustensiles d''''airain avaient un poids inconnu."}, {"numero": 17, "texto": "La hauteur d''''une colonne était de dix-huit coudées, et il y avait au-dessus un chapiteau d''''airain dont la hauteur était de trois coudées; autour du chapiteau il y avait un treillis et des grenades, le tout d''''airain; il en était de même pour la seconde colonne avec le treillis."}, {"numero": 18, "texto": "Le chef des gardes prit Seraja, le souverain sacrificateur, Sophonie, le second sacrificateur, et les trois gardiens du seuil."}, {"numero": 19, "texto": "Et dans la ville il prit un eunuque qui avait sous son commandement les gens de guerre, cinq hommes qui faisaient partie des conseillers du roi et qui furent trouvés dans la ville, le secrétaire du chef de l''''armée qui était chargé d''''enrôler le peuple du pays, et soixante hommes du peuple du pays qui se trouvèrent dans la ville."}, {"numero": 20, "texto": "Nebuzaradan, chef des gardes, les prit, et les conduisit vers le roi de Babylone à Ribla."}, {"numero": 21, "texto": "Le roi de Babylone les frappa et les fit mourir à Ribla, dans le pays de Hamath. Ainsi Juda fut emmené captif loin de son pays."}, {"numero": 22, "texto": "Et Nebucadnetsar, roi de Babylone, plaça le reste du peuple, qu''''il laissa dans le pays de Juda, sous le commandement de Guedalia, fils d''''Achikam, fils de Schaphan."}, {"numero": 23, "texto": "Lorsque tous les chefs des troupes eurent appris, eux et leurs hommes, que le roi de Babylone avait établi Guedalia pour gouverneur, ils se rendirent auprès de Guedalia à Mitspa, savoir Ismaël, fils de Nethania, Jochanan, fils de Karéach, Seraja, fils de Thanhumeth, de Nethopha, et Jaazania, fils du Maacathien, eux et leurs hommes."}, {"numero": 24, "texto": "Guedalia leur jura, à eux et à leurs hommes, et leur dit: Ne craignez rien de la part des serviteurs des Chaldéens; demeurez dans le pays, servez le roi de Babylone, et vous vous en trouverez bien."}, {"numero": 25, "texto": "Mais au septième mois, Ismaël, fils de Nethania, fils d''''Elischama, de la race royale, vint, accompagné de dix hommes, et ils frappèrent mortellement Guedalia, ainsi que les Juifs et les Chaldéens qui étaient avec lui à Mitspa."}, {"numero": 26, "texto": "Alors tout le peuple, depuis le plus petit jusqu''''au plus grand, et les chefs des troupes, se levèrent et s''''en allèrent en Egypte, parce qu''''ils avaient peur des Chaldéens."}, {"numero": 27, "texto": "La trente-septième année de la captivité de Jojakin, roi de Juda, le vingt-septième jour du douzième mois, Evil-Merodac, roi de Babylone, dans la première année de son règne, releva la tête de Jojakin, roi de Juda, et le tira de prison."}, {"numero": 28, "texto": "Il lui parla avec bonté, et il mit son trône au-dessus du trône des rois qui étaient avec lui à Babylone."}, {"numero": 29, "texto": "Il lui fit changer ses vêtements de prison, et Jojakin mangea toujours à sa table tout le temps de sa vie."}, {"numero": 30, "texto": "Le roi pourvut constamment à son entretien journalier tout le temps de sa vie."}]'::jsonb, 'Louis Segond 1910'),
  ('2Rs', 25, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ á los nueve años de su reinado, en el mes décimo, á los diez del mes, que Nabucodonosor rey de Babilonia vino con todo su ejército contra Jerusalem, y cercóla; y levantaron contra ella ingenios alrededor."}, {"numero": 2, "texto": "Y estuvo la ciudad cercada hasta el undécimo año del rey Sedecías."}, {"numero": 3, "texto": "A los nueve del mes prevaleció el hambre en la ciudad, que no hubo pan para el pueblo de la tierra."}, {"numero": 4, "texto": "Abierta ya la ciudad, huyeron de noche todos los hombres de guerra por el camino de la puerta que estaba entre los dos muros, junto á los huertos del rey, estando los Caldeos alrededor de la ciudad; y el rey se fué camino de la campiña."}, {"numero": 5, "texto": "Y el ejército de los Caldeos siguió al rey, y tomólo en las llanuras de Jericó, habiéndose esparcido de él todo su ejército."}, {"numero": 6, "texto": "Tomado pues el rey, trajéronle al rey de Babilonia á Ribla, y profirieron contra él sentencia."}, {"numero": 7, "texto": "Y degollaron á los hijos de Sedecías en presencia suya; y á Sedecías sacaron los ojos, y atado con cadenas lleváronlo á Babilonia."}, {"numero": 8, "texto": "En el mes quinto, á los siete del mes, siendo el año diecinueve de Nabucodonosor rey de Babilonia, vino á Jerusalem Nabuzaradán, capitán de los de la guardia, siervo del rey de Babilonia."}, {"numero": 9, "texto": "Y quemó la casa de Jehová, y la casa del rey, y todas las casas de Jerusalem; y todas las casas de los príncipes quemó á fuego."}, {"numero": 10, "texto": "Y todo el ejército de los Caldeos que estaba con el capitán de la guardia, derribó los muros de Jerusalem alrededor."}, {"numero": 11, "texto": "Y á los del pueblo que habían quedado en la ciudad, y á los que se habían juntado al rey de Babilonia, y á los que habían quedado del vulgo, trasportólos Nabuzaradán, capitán de los de la guardia."}, {"numero": 12, "texto": "Mas de los pobres de la tierra dejó Nabuzaradán, capitán de los de la guardia, para que labrasen las viñas y las tierras."}, {"numero": 13, "texto": "Y quebraron los Caldeos las columnas de bronce que estaban en la casa de Jehová, y las basas, y el mar de bronce que estaba en la casa de Jehová, y llevaron el metal de ello á Babilonia."}, {"numero": 14, "texto": "Lleváronse también los calderos, y las paletas, y las tenazas, y los cucharones, y todos los vasos de metal con que ministraban."}, {"numero": 15, "texto": "Incensarios, cuencos, los que de oro, en oro, y los que de plata, en plata, todo lo llevó el capitán de los de la guardia;"}, {"numero": 16, "texto": "Las dos columnas, un mar, y las basas que Salomón había hecho para la casa de Jehová: no había peso de todos estos vasos."}, {"numero": 17, "texto": "La altura de la una columna era diez y ocho codos y tenía encima un capitel de bronce, y la altura del capitel era de tres codos; y sobre el capitel había un enredado y granadas alrededor, todo de bronce: y semejante obra había en la otra columna con el enredado."}, {"numero": 18, "texto": "Tomó entonces el capitán de los de la guardia á Saraías primer sacerdote, y á Sophonías segundo sacerdote, y tres guardas de la vajilla;"}, {"numero": 19, "texto": "Y de la ciudad tomó un eunuco, el cual era maestre de campo, y cinco varones de los continuos del rey, que se hallaron en la ciudad; y al principal escriba del ejército, que hacía la reseña de la gente del país; y sesenta varones del pueblo de la tierra, que se hallaron en la ciudad."}, {"numero": 20, "texto": "Estos tomó Nabuzaradán, capitán de los de la guardia, y llevólos á Ribla al rey de Babilonia."}, {"numero": 21, "texto": "Y el rey de Babilonia los hirió y mató en Ribla, en tierra de Hamath. Así fué trasportado Judá de sobre su tierra."}, {"numero": 22, "texto": "Y al pueblo que Nabucodonosor rey de Babilonia dejó en tierra de Judá, puso por gobernador á Gedalías, hijo de Ahicam hijo de Saphán."}, {"numero": 23, "texto": "Y oyendo todos los príncipes del ejército, ellos y su gente, que el rey de Babilonia había puesto por gobernador á Gedalías, viniéronse á él en Mizpa, es á saber, Ismael hijo de Nathanías, y Johanán hijo de Carea, y Saraía hijo de Tanhumet Netofatita, y Jaazanías hijo de Maachâti, ellos con los suyos."}, {"numero": 24, "texto": "Entonces Gedalías les hizo juramento, á ellos y á los suyos, y díjoles: No temáis de ser siervos de los Caldeos; habitad en la tierra, y servid al rey de Babilonia, y os irá bien."}, {"numero": 25, "texto": "Mas en el mes séptimo vino Ismael hijo de Nathanías, hijo de Elisama, de la estirpe real, y con él diez varones, é hirieron á Gedalías, y murió: y también á los Judíos y Caldeos que estaban con él en Mizpa."}, {"numero": 26, "texto": "Y levantándose todo el pueblo, desde el menor hasta el mayor, con los capitanes del ejército, fuéronse á Egipto por temor de los Caldeos."}, {"numero": 27, "texto": "Y aconteció á los treinta y siete años de la trasportación de Joachîn rey de Judá, en el mes duodécimo, á los veinte y siete del mes, que Evil-merodach rey de Babilonia, en el primer año de su reinado, levantó la cabeza de Joachîn rey de Judá, sacándolo de la casa de la cárcel;"}, {"numero": 28, "texto": "Y hablóle bien, y puso su asiento sobre el asiento de los reyes que con él estaban en Babilonia."}, {"numero": 29, "texto": "Y mudóle los vestidos de su prisión, y comió siempre delante de él todos los días de su vida."}, {"numero": 30, "texto": "Y fuéle diariamente dada su comida de parte del rey de continuo, todos los días de su vida."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Sm', 1, 'pt', '[{"numero": 1, "texto": "E aconteceu depois da morte de Saul, que quando Davi voltou da derrota dos amalequitas, ficou dois dias em Ziclague;"}, {"numero": 2, "texto": "E ao terceiro dia aconteceu, que veio um do acampamento de Saul, rasgadas suas roupas, e terra sobre sua cabeça: e chegando a Davi, prostrou-se em terra, e fez reverência."}, {"numero": 3, "texto": "E perguntou-lhe Davi: De onde vens? E ele respondeu: Eu me escapei do acampamento de Israel."}, {"numero": 4, "texto": "E Davi lhe disse: Que aconteceu? Rogo-te que me digas. E ele respondeu: O povo fugiu da batalha, e também muitos do povo caíram e foram mortos: também Saul e Jônatas seu filho morreram."}, {"numero": 5, "texto": "E disse Davi àquele rapaz que lhe dava as novas: Como sabes que Saul está morto, e Jônatas seu filho?"}, {"numero": 6, "texto": "E o rapaz que lhe dava as novas respondeu: Casualmente vim ao monte de Gilboa, e achei a Saul que estava recostado sobre sua lança, e vinham atrás dele carros e cavaleiros."}, {"numero": 7, "texto": "E quando ele olhou atrás, viu-me e chamou-me; e eu disse: Eis-me aqui."}, {"numero": 8, "texto": "E ele me disse: Quem és tu? E eu lhe respondi: Sou amalequita."}, {"numero": 9, "texto": "E ele me voltou a dizer: Eu te rogo que te ponhas sobre mim, e me mates, porque me tomam angústias, e toda minha alma está ainda em mim."}, {"numero": 10, "texto": "Eu então me pus sobre ele, e matei-o, porque sabia que não podia viver depois de sua queda: e tomei a coroa que tinha em sua cabeça, e o bracelete que trazia em seu braço, e trouxe-os aqui a meu senhor."}, {"numero": 11, "texto": "Então Davi agarrando suas roupas, rompeu-os; e o mesmo fizeram os homens que estavam com ele."}, {"numero": 12, "texto": "E choraram e lamentaram, e jejuaram até à tarde, por Saul e por Jônatas seu filho, e pelo povo do SENHOR, e pela casa de Israel: porque haviam caído à espada."}, {"numero": 13, "texto": "E Davi disse a aquele rapaz que lhe havia trazido as novas: De onde és tu? E ele respondeu: Eu sou filho de um estrangeiro, amalequita."}, {"numero": 14, "texto": "E disse-lhe Davi: Como não tiveste temor de estender tua mão para matar ao ungido do SENHOR?"}, {"numero": 15, "texto": "Então chamou Davi um dos rapazes, e disse-lhe: Chega, e mata-o. E ele o feriu, e morreu."}, {"numero": 16, "texto": "E Davi lhe disse: Teu sangue seja sobre tua cabeça, pois que tua boca testemunhou contra ti, dizendo: Eu matei ao ungido do SENHOR."}, {"numero": 17, "texto": "E lamentou Davi a Saul e a Jônatas seu filho com esta lamentação."}, {"numero": 18, "texto": "(Disse também que ensinassem ao arco aos filhos de Judá. Eis que está escrito no livro do direito:)"}, {"numero": 19, "texto": "Pereceu a glória de Israel sobre tuas montanhas! Como caíram os valentes!"}, {"numero": 20, "texto": "Não o anuncieis em Gate, Não deis as novas nas praças de Asquelom; Para que não se alegrem as filhas dos filisteus, Para que não saltem de alegria as filhas dos incircuncisos."}, {"numero": 21, "texto": "Montes de Gilboa, nem orvalho nem chuva caia sobre vós, nem sejais terras de ofertas; Porque ali foi rejeitado o escudo dos valentes, O escudo de Saul, como se não houvesse sido ungido com azeite."}, {"numero": 22, "texto": "Do sangue de mortos, da gordura de valentes, o arco de Jônatas nunca retrocedeu, nem a espada de Saul voltou vazia."}, {"numero": 23, "texto": "Saul e Jônatas, amados e queridos em sua vida, Em sua morte tampouco foram separados: Mais ligeiros que águas, Mais fortes que leões."}, {"numero": 24, "texto": "Filhas de Israel, chorai sobre Saul, Que vos vestia de escarlata em regozijo, Que adornava vossas roupas com ornamentos de ouro."}, {"numero": 25, "texto": "Como caíram os valentes em meio da batalha! Jônatas, morto em tuas alturas!"}, {"numero": 26, "texto": "Angústia tenho por ti, irmão meu Jônatas, Que me foste muito doce: Mais maravilhoso me foi o teu amor, Que o amor das mulheres."}, {"numero": 27, "texto": "Como caíram os valentes, E pereceram as armas de guerra!"}]'::jsonb, 'Almeida Livre'),
  ('2Sm', 1, 'en', '[{"numero": 1, "texto": "Now it came to pass after the death of Saul, when David was returned from the slaughter of the Amalekites, and David had abode two days in Ziklag;"}, {"numero": 2, "texto": "It came even to pass on the third day, that, behold, a man came out of the camp from Saul with his clothes rent, and earth upon his head: and so it was, when he came to David, that he fell to the earth, and did obeisance."}, {"numero": 3, "texto": "And David said unto him, From whence comest thou? And he said unto him, Out of the camp of Israel am I escaped."}, {"numero": 4, "texto": "And David said unto him, How went the matter? I pray thee, tell me. And he answered, That the people are fled from the battle, and many of the people also are fallen and dead; and Saul and Jonathan his son are dead also."}, {"numero": 5, "texto": "And David said unto the young man that told him, How knowest thou that Saul and Jonathan his son be dead?"}, {"numero": 6, "texto": "And the young man that told him said, As I happened by chance upon mount Gilboa, behold, Saul leaned upon his spear; and, lo, the chariots and horsemen followed hard after him."}, {"numero": 7, "texto": "And when he looked behind him, he saw me, and called unto me. And I answered, Here am I."}, {"numero": 8, "texto": "And he said unto me, Who art thou? And I answered him, I am an Amalekite."}, {"numero": 9, "texto": "He said unto me again, Stand, I pray thee, upon me, and slay me: for anguish is come upon me, because my life is yet whole in me."}, {"numero": 10, "texto": "So I stood upon him, and slew him, because I was sure that he could not live after that he was fallen: and I took the crown that was upon his head, and the bracelet that was on his arm, and have brought them hither unto my lord."}, {"numero": 11, "texto": "Then David took hold on his clothes, and rent them; and likewise all the men that were with him:"}, {"numero": 12, "texto": "And they mourned, and wept, and fasted until even, for Saul, and for Jonathan his son, and for the people of the Lord, and for the house of Israel; because they were fallen by the sword."}, {"numero": 13, "texto": "And David said unto the young man that told him, Whence art thou? And he answered, I am the son of a stranger, an Amalekite."}, {"numero": 14, "texto": "And David said unto him, How wast thou not afraid to stretch forth thine hand to destroy the Lord''s anointed?"}, {"numero": 15, "texto": "And David called one of the young men, and said, Go near, and fall upon him. And he smote him that he died."}, {"numero": 16, "texto": "And David said unto him, Thy blood be upon thy head; for thy mouth hath testified against thee, saying, I have slain the Lord''s anointed."}, {"numero": 17, "texto": "And David lamented with this lamentation over Saul and over Jonathan his son:"}, {"numero": 18, "texto": "(Also he bade them teach the children of Judah the use of the bow: behold, it is written in the book of Jasher.)"}, {"numero": 19, "texto": "The beauty of Israel is slain upon thy high places: how are the mighty fallen!"}, {"numero": 20, "texto": "Tell it not in Gath, publish it not in the streets of Askelon; lest the daughters of the Philistines rejoice, lest the daughters of the uncircumcised triumph."}, {"numero": 21, "texto": "Ye mountains of Gilboa, let there be no dew, neither let there be rain, upon you, nor fields of offerings: for there the shield of the mighty is vilely cast away, the shield of Saul, as though he had not been anointed with oil."}, {"numero": 22, "texto": "From the blood of the slain, from the fat of the mighty, the bow of Jonathan turned not back, and the sword of Saul returned not empty."}, {"numero": 23, "texto": "Saul and Jonathan were lovely and pleasant in their lives, and in their death they were not divided: they were swifter than eagles, they were stronger than lions."}, {"numero": 24, "texto": "Ye daughters of Israel, weep over Saul, who clothed you in scarlet, with other delights, who put on ornaments of gold upon your apparel."}, {"numero": 25, "texto": "How are the mighty fallen in the midst of the battle! O Jonathan, thou wast slain in thine high places."}, {"numero": 26, "texto": "I am distressed for thee, my brother Jonathan: very pleasant hast thou been unto me: thy love to me was wonderful, passing the love of women."}, {"numero": 27, "texto": "How are the mighty fallen, and the weapons of war perished!"}]'::jsonb, 'King James Version'),
  ('2Sm', 1, 'fr', '[{"numero": 1, "texto": "Après la mort de Saül, David, qui avait battu les Amalécites, était depuis deux jours revenu à Tsiklag."}, {"numero": 2, "texto": "Le troisième jour, un homme arriva du camp de Saül, les vêtements déchirés et la tête couverte de terre. Lorsqu''''il fut en présence de David, il se jeta par terre et se prosterna."}, {"numero": 3, "texto": "David lui dit: D''''où viens-tu? Et il lui répondit: Je me suis sauvé du camp d''''Israël."}, {"numero": 4, "texto": "David lui dit: Que s''''est-il passé? dis-moi donc! Et il répondit: Le peuple s''''est enfui du champ de bataille, et un grand nombre d''''hommes sont tombés et ont péri; Saül même et Jonathan, son fils, sont morts."}, {"numero": 5, "texto": "David dit au jeune homme qui lui apportait ces nouvelles: Comment sais-tu que Saül et Jonathan, son fils, sont morts?"}, {"numero": 6, "texto": "Et le jeune homme qui lui apportait ces nouvelles répondit: Je me trouvais sur la montagne de Guilboa; et voici, Saül s''''appuyait sur sa lance, et voici, les chars et les cavaliers étaient près de l''''atteindre."}, {"numero": 7, "texto": "S''''étant retourné, il m''''aperçut et m''''appela. Je dis: Me voici!"}, {"numero": 8, "texto": "Et il me dit: Qui es-tu? Je lui répondis: Je suis Amalécite."}, {"numero": 9, "texto": "Et il dit: Approche donc, et donne-moi la mort; car je suis pris de vertige, quoique encore plein de vie."}, {"numero": 10, "texto": "Je m''''approchai de lui, et je lui donnai la mort, sachant bien qu''''il ne survivrait pas à sa défaite. J''''ai enlevé le diadème qui était sur sa tête et le bracelet qu''''il avait au bras, et je les apporte ici à mon seigneur."}, {"numero": 11, "texto": "David saisit ses vêtements et les déchira, et tous les hommes qui étaient auprès de lui firent de même."}, {"numero": 12, "texto": "Ils furent dans le deuil, pleurèrent et jeûnèrent jusqu''''au soir, à cause de Saül, de Jonathan, son fils, du peuple de l''''Eternel, et de la maison d''''Israël, parce qu''''ils étaient tombés par l''''épée."}, {"numero": 13, "texto": "David dit au jeune homme qui lui avait apporté ces nouvelles: D''''où es-tu? Et il répondit: Je suis le fils d''''un étranger, d''''un Amalécite."}, {"numero": 14, "texto": "David lui dit: Comment n''''as-tu pas craint de porter la main sur l''''oint de l''''Eternel et de lui donner la mort?"}, {"numero": 15, "texto": "Et David appela l''''un de ses gens, et dit: Approche, et tue-le! Cet homme frappa l''''Amalécite, qui mourut."}, {"numero": 16, "texto": "Et David lui dit: Que ton sang retombe sur ta tête, car ta bouche a déposé contre toi, puisque tu as dit: J''''ai donné la mort à l''''oint de l''''Eternel!"}, {"numero": 17, "texto": "Voici le cantique funèbre que David composa sur Saül et sur Jonathan, son fils,"}, {"numero": 18, "texto": "et qu''''il ordonna d''''enseigner aux enfants de Juda. C''''est le cantique de l''''arc: il est écrit dans le livre du Juste."}, {"numero": 19, "texto": "L''''élite d''''Israël a succombé sur tes collines! Comment des héros sont-ils tombés?"}, {"numero": 20, "texto": "Ne l''''annoncez point dans Gath, N''''en publiez point la nouvelle dans les rues d''''Askalon, De peur que les filles des Philistins ne se réjouissent, De peur que les filles des incirconcis ne triomphent."}, {"numero": 21, "texto": "Montagnes de Guilboa! Qu''''il n''''y ait sur vous ni rosée ni pluie, Ni champs qui donnent des prémices pour les offrandes! Car là ont été jetés les boucliers des héros, Le bouclier de Saül; L''''huile a cessé de les oindre."}, {"numero": 22, "texto": "Devant le sang des blessés, devant la graisse des plus vaillants, L''''arc de Jonathan n''''a jamais reculé, Et l''''épée de Saül ne retournait point à vide."}, {"numero": 23, "texto": "Saül et Jonathan, aimables et chéris pendant leur vie, N''''ont point été séparés dans leur mort; Ils étaient plus légers que les aigles, Ils étaient plus forts que les lions."}, {"numero": 24, "texto": "Filles d''''Israël! pleurez sur Saül, Qui vous revêtait magnifiquement de cramoisi, Qui mettait des ornements d''''or sur vos habits."}, {"numero": 25, "texto": "Comment des héros sont-ils tombés au milieu du combat? Comment Jonathan a-t-il succombé sur tes collines?"}, {"numero": 26, "texto": "Je suis dans la douleur à cause de toi, Jonathan, mon frère! Tu faisais tout mon plaisir; Ton amour pour moi était admirable, Au-dessus de l''''amour des femmes."}, {"numero": 27, "texto": "Comment des héros sont-ils tombés? Comment leurs armes se sont-elles perdues?"}]'::jsonb, 'Louis Segond 1910'),
  ('2Sm', 1, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ después de la muerte de Saúl, que vuelto David de la derrota de los Amalecitas, estuvo dos días en Siclag:"}, {"numero": 2, "texto": "Y al tercer día acaeció, que vino uno del campo de Saúl, rotos sus vestidos, y tierra sobre su cabeza: y llegando á David, postróse en tierra, é hizo reverencia."}, {"numero": 3, "texto": "Y preguntóle David: ¿De dónde vienes? Y él respondió: Heme escapado del campo de Israel."}, {"numero": 4, "texto": "Y David le dijo: ¿Qué ha acontecido? ruégote que me lo digas. Y él respondió: El pueblo huyó de la batalla, y también muchos del pueblo cayeron y son muertos: también Saúl y Jonathán su hijo murieron."}, {"numero": 5, "texto": "Y dijo David á aquel mancebo que le daba las nuevas: ¿Cómo sabes que Saúl es muerto, y Jonathán su hijo?"}, {"numero": 6, "texto": "Y el mancebo que le daba las nuevas respondió: Casualmente vine al monte de Gilboa, y hallé á Saúl que estaba recostado sobre su lanza, y venían tras él carros y gente de á caballo."}, {"numero": 7, "texto": "Y como él miró atrás, vióme y llamóme; y yo dije: Heme aquí."}, {"numero": 8, "texto": "Y él me dijo: ¿Quién eres tú? Y yo le respondí: Soy Amalecita."}, {"numero": 9, "texto": "Y él me volvió á decir: Yo te ruego que te pongas sobre mí, y me mates, porque me toman angustias, y toda mi alma está aún en mí."}, {"numero": 10, "texto": "Yo entonces púseme sobre él, y matélo, porque sabía que no podía vivir después de su caída: y tomé la corona que tenía en su cabeza, y la ajorca que traía en su brazo, y helas traído acá á mi señor."}, {"numero": 11, "texto": "Entonces David trabando de sus vestidos, rompiólos; y lo mismo hicieron los hombres que estaban con él."}, {"numero": 12, "texto": "Y lloraron y lamentaron, y ayunaron hasta la tarde, por Saúl y por Jonathán su hijo, y por el pueblo de Jehová, y por la casa de Israel: porque habían caído á cuchillo."}, {"numero": 13, "texto": "Y David dijo á aquel mancebo que le había traído las nuevas: ¿De dónde eres tú? Y él respondió: Yo soy hijo de un extranjero, Amalecita."}, {"numero": 14, "texto": "Y díjole David: ¿Cómo no tuviste temor de extender tu mano para matar al ungido de Jehová?"}, {"numero": 15, "texto": "Entonces llamó David uno de los mancebos, y díjole: Llega, y mátalo. Y él lo hirió, y murió."}, {"numero": 16, "texto": "Y David le dijo: Tu sangre sea sobre tu cabeza, pues que tu boca atestiguó contra ti, diciendo: Yo maté al ungido de Jehová."}, {"numero": 17, "texto": "Y endechó David á Saúl y á Jonathán su hijo con esta endecha."}, {"numero": 18, "texto": "(Dijo también que enseñasen al arco á los hijos de Judá. He aquí que está escrito en el libro del derecho:)"}, {"numero": 19, "texto": "¡Perecido ha la gloria de Israel sobre tus montañas! ¡Cómo han caído los valientes!"}, {"numero": 20, "texto": "No lo denunciéis en Gath, no deis las nuevas en las plazas de Ascalón; porque no se alegren las hijas de los Filisteos, porque no salten de gozo las hijas de los incircuncisos."}, {"numero": 21, "texto": "Montes de Gilboa, ni rocío ni lluvia caiga sobre vosotros, ni seáis tierras de ofrendas; porque allí fué desechado el escudo de los valientes, el escudo de Saúl, como si no hubiera sido ungido con aceite."}, {"numero": 22, "texto": "Sin sangre de muertos, sin grosura de valientes, el arco de Jonathán nunca volvió, ni la espada de Saúl se tornó vacía."}, {"numero": 23, "texto": "Saúl y Jonathán, amados y queridos en su vida, en su muerte tampoco fueron apartados: más ligeros que águilas, más fuertes que leones."}, {"numero": 24, "texto": "Hijas de Israel, llorad sobre Saúl, que os vestía de escarlata en regocijos, que adornaba vuestras ropas con ornamentos de oro."}, {"numero": 25, "texto": "¡Cómo han caído los valientes en medio de la batalla! ¡Jonathán, muerto en tus alturas!"}, {"numero": 26, "texto": "Angustia tengo por ti, hermano mío Jonathán, que me fuiste muy dulce: más maravilloso me fué tu amor, que el amor de las mujeres."}, {"numero": 27, "texto": "¡Cómo han caído los valientes, y perecieron las armas de guerra!"}]'::jsonb, 'Reina-Valera 1909'),
  ('2Sm', 5, 'pt', '[{"numero": 1, "texto": "E vieram todas as tribos de Israel a Davi em Hebrom, e falaram, dizendo: Eis que nós somos teus ossos e tu carne."}, {"numero": 2, "texto": "E ainda ontem e antes, quando Saul reinava sobre nós, tu tiravas e voltavas a Israel. Além disso, o SENHOR te disse: Tu apascentarás a meu povo Israel, e tu serás sobre Israel príncipe."}, {"numero": 3, "texto": "Vieram, pois, todos os anciãos de Israel ao rei em Hebrom, e o rei Davi fez com eles aliança em Hebrom diante do SENHOR; e ungiram a Davi por rei sobre Israel."}, {"numero": 4, "texto": "Era Davi de trinta anos quando começou a reinar, e reinou quarenta anos."}, {"numero": 5, "texto": "Em Hebrom reinou sobre Judá sete anos e seis meses: e em Jerusalém reinou trinta e três anos sobre todo Israel e Judá."}, {"numero": 6, "texto": "Então o rei e os seus foram a Jerusalém aos jebuseus que habitavam na terra; os qual falaram a Davi, dizendo: Tu não entrarás aqui, a não ser que consigas expulsar aos cegos e aos coxos; e pensavam: Davi não entrará aqui."}, {"numero": 7, "texto": "Porém Davi tomou a fortaleza de Sião, a qual é a cidade de Davi."}, {"numero": 8, "texto": "E disse Davi aquele dia: Quem chegará até os canais, e ferirá ao jebuseu, e aos coxos e cegos, aos quais a alma de Davi aborrece? Por isto se disse: Cego nem coxo não entrará em casa."}, {"numero": 9, "texto": "E Davi morou na fortaleza e pôs-lhe por nome a Cidade de Davi: e edificou ao redor, desde Milo para dentro."}, {"numero": 10, "texto": "E Davi ia crescendo e aumentando-se, e o SENHOR Deus dos exércitos era com ele."}, {"numero": 11, "texto": "E Hirão rei de Tiro enviou também embaixadores a Davi, e madeira de cedro, e carpinteiros, e pedreiros para os muros, os quais edificaram a casa de Davi."}, {"numero": 12, "texto": "E entendeu Davi que o SENHOR lhe havia confirmado por rei sobre Israel, e que havia exaltado seu reino por causa de seu povo Israel."}, {"numero": 13, "texto": "E tomou Davi mais concubinas e mulheres de Jerusalém depois que veio de Hebrom, e nasceram-lhe mais filhos e filhas."}, {"numero": 14, "texto": "Estes são os nomes dos que lhe nasceram em Jerusalém: Samua, e Sobabe, e Natã, e Salomão,"}, {"numero": 15, "texto": "E Ibar, e Elisua, e Nefegue,"}, {"numero": 16, "texto": "E Jafia, e Elisama, e Eliada, e Elifelete."}, {"numero": 17, "texto": "E ouvindo os filisteus que haviam ungido a Davi por rei sobre Israel, todos os filisteus subiram a buscar a Davi: o qual quando Davi ouviu, veio à fortaleza."}, {"numero": 18, "texto": "E vieram os filisteus, e estenderam-se pelo vale de Refaim."}, {"numero": 19, "texto": "Então consultou Davi ao SENHOR, dizendo: Irei contra os filisteus? os entregarás em minhas mãos? E o SENHOR respondeu a Davi: Vai, porque certamente entregarei os filisteus em tuas mãos."}, {"numero": 20, "texto": "E veio Davi a Baal-Perazim, e ali os venceu Davi, e disse: O SENHOR rompeu meus inimigos diante de mim, como o romper das águas. E por isto chamou o nome daquele lugar Baal-Perazim."}, {"numero": 21, "texto": "E deixaram ali seus ídolos, os quais queimou Davi e os seus."}, {"numero": 22, "texto": "E os filisteus voltaram a vir, e estenderam-se no vale de Refaim."}, {"numero": 23, "texto": "E consultando Davi ao SENHOR, ele lhe respondeu: Não subas; mas rodeia-os, e virás a eles por diante das amoreiras:"}, {"numero": 24, "texto": "E quando ouvires um estrondo que irá pelas copas das amoreiras, então te moverás; porque o SENHOR sairá diante de ti a ferir o acampamento dos filisteus."}, {"numero": 25, "texto": "E Davi o fez assim como o SENHOR havia lhe mandado; e feriu aos filisteus desde Gibeá até chegar a Gaza."}]'::jsonb, 'Almeida Livre'),
  ('2Sm', 5, 'en', '[{"numero": 1, "texto": "Then came all the tribes of Israel to David unto Hebron, and spake, saying, Behold, we are thy bone and thy flesh."}, {"numero": 2, "texto": "Also in time past, when Saul was king over us, thou wast he that leddest out and broughtest in Israel: and the Lord said to thee, Thou shalt feed my people Israel, and thou shalt be a captain over Israel."}, {"numero": 3, "texto": "So all the elders of Israel came to the king to Hebron; and king David made a league with them in Hebron before the Lord: and they anointed David king over Israel."}, {"numero": 4, "texto": "David was thirty years old when he began to reign, and he reigned forty years."}, {"numero": 5, "texto": "In Hebron he reigned over Judah seven years and six months: and in Jerusalem he reigned thirty and three years over all Israel and Judah."}, {"numero": 6, "texto": "And the king and his men went to Jerusalem unto the Jebusites, the inhabitants of the land: which spake unto David, saying, Except thou take away the blind and the lame, thou shalt not come in hither: thinking, David cannot come in hither."}, {"numero": 7, "texto": "Nevertheless David took the strong hold of Zion: the same is the city of David."}, {"numero": 8, "texto": "And David said on that day, Whosoever getteth up to the gutter, and smiteth the Jebusites, and the lame and the blind that are hated of David''s soul, he shall be chief and captain. Wherefore they said, The blind and the lame shall not come into the house."}, {"numero": 9, "texto": "So David dwelt in the fort, and called it the city of David. And David built round about from Millo and inward."}, {"numero": 10, "texto": "And David went on, and grew great, and the Lord God of hosts was with him."}, {"numero": 11, "texto": "And Hiram king of Tyre sent messengers to David, and cedar trees, and carpenters, and masons: and they built David an house."}, {"numero": 12, "texto": "And David perceived that the Lord had established him king over Israel, and that he had exalted his kingdom for his people Israel''s sake."}, {"numero": 13, "texto": "And David took him more concubines and wives out of Jerusalem, after he was come from Hebron: and there were yet sons and daughters born to David."}, {"numero": 14, "texto": "And these be the names of those that were born unto him in Jerusalem; Shammuah, and Shobab, and Nathan, and Solomon,"}, {"numero": 15, "texto": "Ibhar also, and Elishua, and Nepheg, and Japhia,"}, {"numero": 16, "texto": "And Elishama, and Eliada, and Eliphalet."}, {"numero": 17, "texto": "But when the Philistines heard that they had anointed David king over Israel, all the Philistines came up to seek David; and David heard of it, and went down to the hold."}, {"numero": 18, "texto": "The Philistines also came and spread themselves in the valley of Rephaim."}, {"numero": 19, "texto": "And David enquired of the Lord, saying, Shall I go up to the Philistines? wilt thou deliver them into mine hand? And the Lord said unto David, Go up: for I will doubtless deliver the Philistines into thine hand."}, {"numero": 20, "texto": "And David came to Baalperazim, and David smote them there, and said, The Lord hath broken forth upon mine enemies before me, as the breach of waters. Therefore he called the name of that place Baalperazim."}, {"numero": 21, "texto": "And there they left their images, and David and his men burned them."}, {"numero": 22, "texto": "And the Philistines came up yet again, and spread themselves in the valley of Rephaim."}, {"numero": 23, "texto": "And when David enquired of the Lord, he said, Thou shalt not go up; but fetch a compass behind them, and come upon them over against the mulberry trees."}, {"numero": 24, "texto": "And let it be, when thou hearest the sound of a going in the tops of the mulberry trees, that then thou shalt bestir thyself: for then shall the Lord go out before thee, to smite the host of the Philistines."}, {"numero": 25, "texto": "And David did so, as the Lord had commanded him; and smote the Philistines from Geba until thou come to Gazer."}]'::jsonb, 'King James Version'),
  ('2Sm', 5, 'fr', '[{"numero": 1, "texto": "Toutes les tribus d''''Israël vinrent auprès de David, à Hébron, et dirent: Voici, nous sommes tes os et ta chair."}, {"numero": 2, "texto": "Autrefois déjà, lorsque Saül était notre roi, c''''était toi qui conduisais et qui ramenais Israël. L''''Eternel t''''a dit: Tu paîtras mon peuple d''''Israël, et tu seras le chef d''''Israël."}, {"numero": 3, "texto": "Ainsi tous les anciens d''''Israël vinrent auprès du roi à Hébron, et le roi David fit alliance avec eux à Hébron, devant l''''Eternel. Ils oignirent David pour roi sur Israël."}, {"numero": 4, "texto": "David était âgé de trente ans lorsqu''''il devint roi, et il régna quarante ans."}, {"numero": 5, "texto": "A Hébron il régna sur Juda sept ans et six mois, et à Jérusalem il régna trente-trois ans sur tout Israël et Juda."}, {"numero": 6, "texto": "Le roi marcha avec ses gens sur Jérusalem contre les Jébusiens, habitants du pays. Ils dirent à David: Tu n''''entreras point ici, car les aveugles mêmes et les boiteux te repousseront! Ce qui voulait dire: David n''''entrera point ici."}, {"numero": 7, "texto": "Mais David s''''empara de la forteresse de Sion: c''''est la cité de David."}, {"numero": 8, "texto": "David avait dit en ce jour: Quiconque battra les Jébusiens et atteindra le canal, quiconque frappera ces boiteux et ces aveugles qui sont les ennemis de David... -C''''est pourquoi l''''on dit: L''''aveugle et le boiteux n''''entreront point dans la maison."}, {"numero": 9, "texto": "David s''''établit dans la forteresse, qu''''il appela cité de David. Il fit de tous côtés des constructions, en dehors et en dedans de Millo."}, {"numero": 10, "texto": "David devenait de plus en plus grand, et l''''Eternel, le Dieu des armées, était avec lui."}, {"numero": 11, "texto": "Hiram, roi de Tyr, envoya des messagers à David, et du bois de cèdre, et des charpentiers et des tailleurs de pierres, qui bâtirent une maison pour David."}, {"numero": 12, "texto": "David reconnut que l''''Eternel l''''affermissait comme roi d''''Israël, et qu''''il élevait son royaume à cause de son peuple d''''Israël."}, {"numero": 13, "texto": "David prit encore des concubines et des femmes de Jérusalem, après qu''''il fut venu d''''Hébron, et il lui naquit encore des fils et des filles."}, {"numero": 14, "texto": "Voici les noms de ceux qui lui naquirent à Jérusalem: Schammua, Schobab, Nathan, Salomon,"}, {"numero": 15, "texto": "Jibhar, Elischua, Népheg, Japhia,"}, {"numero": 16, "texto": "Elischama, Eliada et Eliphéleth."}, {"numero": 17, "texto": "Les Philistins apprirent qu''''on avait oint David pour roi sur Israël, et ils montèrent tous à sa recherche. David, qui en fut informé, descendit à la forteresse."}, {"numero": 18, "texto": "Les Philistins arrivèrent, et se répandirent dans la vallée des Rephaïm."}, {"numero": 19, "texto": "David consulta l''''Eternel, en disant: Monterai-je contre les Philistins? Les livreras-tu entre mes mains? Et l''''Eternel dit à David: Monte, car je livrerai les Philistins entre tes mains."}, {"numero": 20, "texto": "David vint à Baal-Peratsim, où il les battit. Puis il dit: L''''Eternel a dispersé mes ennemis devant moi, comme des eaux qui s''''écoulent. C''''est pourquoi l''''on a donné à ce lieu le nom de Baal-Peratsim."}, {"numero": 21, "texto": "Ils laissèrent là leurs idoles, et David et ses gens les emportèrent."}, {"numero": 22, "texto": "Les Philistins montèrent de nouveau, et se répandirent dans la vallée des Rephaïm."}, {"numero": 23, "texto": "David consulta l''''Eternel. Et l''''Eternel dit: Tu ne monteras pas; tourne-les par derrière, et tu arriveras sur eux vis-à-vis des mûriers."}, {"numero": 24, "texto": "Quand tu entendras un bruit de pas dans les cimes des mûriers, alors hâte-toi, car c''''est l''''Eternel qui marche devant toi pour battre l''''armée des Philistins."}, {"numero": 25, "texto": "David fit ce que l''''Eternel lui avait ordonné, et il battit les Philistins depuis Guéba jusqu''''à Guézer."}]'::jsonb, 'Louis Segond 1910'),
  ('2Sm', 5, 'es', '[{"numero": 1, "texto": "Y VINIERON todas las tribus de Israel á David en Hebrón, y hablaron, diciendo: He aquí nosotros somos tus huesos y tu carne."}, {"numero": 2, "texto": "Y aun ayer y antes, cuando Saúl reinaba sobre nosotros, tú sacabas y volvías á Israel. Además Jehová te ha dicho: Tú apacentarás á mi pueblo Israel, y tú serás sobre Israel príncipe."}, {"numero": 3, "texto": "Vinieron pues todos los ancianos de Israel al rey en Hebrón, y el rey David hizo con ellos alianza en Hebrón delante de Jehová; y ungieron á David por rey sobre Israel."}, {"numero": 4, "texto": "Era David de treinta años cuando comenzó á reinar, y reinó cuarenta años."}, {"numero": 5, "texto": "En Hebrón reinó sobre Judá siete años y seis meses: y en Jerusalem reinó treinta y tres años sobre todo Israel y Judá."}, {"numero": 6, "texto": "Entonces el rey y los suyos fueron á Jerusalem al Jebuseo que habitaba en la tierra; el cual habló á David, diciendo: Tú no entrarás acá, si no echares los ciegos y los cojos; diciendo: No entrará acá David."}, {"numero": 7, "texto": "Empero David tomó la fortaleza de Sión, la cual es la ciudad de David."}, {"numero": 8, "texto": "Y dijo David aquel día: ¿Quién llegará hasta las canales, y herirá al Jebuseo, y á los cojos y ciegos, á los cuales el alma de David aborrece? Por esto se dijo: Ciego ni cojo no entrará en casa."}, {"numero": 9, "texto": "Y David moró en la fortaleza, y púsole por nombre la Ciudad de David: y edificó alrededor, desde Millo para adentro."}, {"numero": 10, "texto": "Y David iba creciendo y aumentándose, y Jehová Dios de los ejércitos era con él."}, {"numero": 11, "texto": "E Hiram rey de Tiro envió también embajadores á David, y madera de cedro, y carpinteros, y canteros para los muros, los cuales edificaron la casa de David."}, {"numero": 12, "texto": "Y entendió David que Jehová le había confirmado por rey sobre Israel, y que había ensalzado su reino por amor de su pueblo Israel."}, {"numero": 13, "texto": "Y tomó David más concubinas y mujeres de Jerusalem después que vino de Hebrón, y naciéronle más hijos é hijas."}, {"numero": 14, "texto": "Estos son los nombres de los que le nacieron en Jerusalem: Sammua, y Sobab, y Nathán, y Salomón,"}, {"numero": 15, "texto": "E Ibhar, y Elisua, y Nepheg,"}, {"numero": 16, "texto": "Y Japhia, y Elisama, y Eliada, y Eliphelet."}, {"numero": 17, "texto": "Y oyendo los Filisteos que habían ungido á David por rey sobre Israel, todos los Filisteos subieron á buscar á David: lo cual como David oyó, vino á la fortaleza."}, {"numero": 18, "texto": "Y vinieron los Filisteos, y extendiéronse por el valle de Raphaim."}, {"numero": 19, "texto": "Entonces consultó David á Jehová, diciendo: ¿Iré contra los Filisteos? ¿los entregarás en mis manos? Y Jehová respondió á David: Ve, porque ciertamente entregaré los Filisteos en tus manos."}, {"numero": 20, "texto": "Y vino David á Baal-perasim, y allí los venció David, y dijo: Rompió Jehová mis enemigos delante de mí, como quien rompe aguas. Y por esto llamó el nombre de aquel lugar Baal-perasim."}, {"numero": 21, "texto": "Y dejaron allí sus ídolos, los cuales quemó David y los suyos."}, {"numero": 22, "texto": "Y los Filisteos tornaron á venir, y extendiéronse en el valle de Raphaim."}, {"numero": 23, "texto": "Y consultando David á Jehová, él le respondió: No subas; mas rodéalos, y vendrás á ellos por delante de los morales:"}, {"numero": 24, "texto": "Y cuando oyeres un estruendo que irá por las copas de los morales, entonces te moverás; porque Jehová saldrá delante de ti á herir el campo de los Filisteos."}, {"numero": 25, "texto": "Y David lo hizo así, como Jehová se lo había mandado; é hirió á los Filisteos desde Gabaa hasta llegar á Gaza."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Sm', 7, 'pt', '[{"numero": 1, "texto": "E aconteceu que, estando já o rei assentado em sua casa, depois que o SENHOR lhe havia dado repouso de todos os seus inimigos em derredor,"}, {"numero": 2, "texto": "Disse o rei ao profeta Natã: Olha agora, eu moro em edifícios de cedro, e a arca de Deus está entre cortinas."}, {"numero": 3, "texto": "E Natã disse ao rei: Anda, e faze tudo o que está em teu coração, que o SENHOR é contigo."}, {"numero": 4, "texto": "E aconteceu aquela noite, que veio a palavra do SENHOR a Natã, dizendo:"}, {"numero": 5, "texto": "Vai e dize a meu servo Davi: Assim disse o SENHOR: Tu me edificarás casa em que eu more?"}, {"numero": 6, "texto": "Certamente não habitei em casas desde o dia que tirei aos filhos de Israel do Egito até hoje, mas sim que andei em tenda e em tabernáculo."}, {"numero": 7, "texto": "E em tudo quanto andei com todos os filhos de Israel, falei palavra em alguma das tribos de Israel, a quem tenha mandado que apascente meu povo de Israel, para dizer: Por que não me edificastes casa de cedros?"}, {"numero": 8, "texto": "Agora, pois, dirás assim a meu servo Davi: Assim disse o SENHOR dos exércitos: Eu te tomei da malhada, de detrás das ovelhas, para que fosses príncipe sobre meu povo, sobre Israel;"}, {"numero": 9, "texto": "E fui contigo em tudo quanto andaste, e diante de ti exterminei todos teus inimigos, e te fiz nome grande, como o nome dos grandes que são na terra."}, {"numero": 10, "texto": "Além disso, eu fixarei lugar a meu povo Israel; eu o plantarei, para que habite em seu lugar, e nunca mais seja removido, nem os iníquos lhe aflijam mais, como antes,"}, {"numero": 11, "texto": "Desde o dia que pus juízes sobre meu povo Israel; e eu te darei descanso de todos teus inimigos. Também o SENHOR te faz saber, que ele te quer fazer casa."}, {"numero": 12, "texto": "E quando teus dias forem cumpridos, e descansares com teus pais, eu establecerei tua semente depois de ti, a qual procederá de tuas entranhas, e assegurarei seu reino."}, {"numero": 13, "texto": "Ele edificará casa a meu nome, e eu afirmarei para sempre o trono de seu reino."}, {"numero": 14, "texto": "Eu serei a ele pai, e ele me será filho. E se ele fizer mal, eu lhe castigarei com vara de homens, e com açoites de filhos de homens;"}, {"numero": 15, "texto": "Porém não removerei minha misericórdia dele, como a removi de Saul, ao qual tirei de diante de ti."}, {"numero": 16, "texto": "E será firmada tua casa e teu reino para sempre diante de teu rosto; e teu trono será estável eternamente."}, {"numero": 17, "texto": "Conforme todas estas palavras, e conforme toda esta visão, assim falou Natã a Davi."}, {"numero": 18, "texto": "E entrou o rei Davi, e pôs-se diante do SENHOR, e disse: Senhor DEUS, Quem sou eu, e que é minha casa, para que tu me tragas até aqui?"}, {"numero": 19, "texto": "E ainda te pareceu pouco isto, Senhor DEUS, pois que também falaste da casa de teu servo no porvir. É esse o modo de agir do homem, Senhor DEUS?"}, {"numero": 20, "texto": "E que mais pode acrescentar Davi falando contigo? Tu, pois, conheces teu servo, Senhor DEUS."}, {"numero": 21, "texto": "Todas estas grandezas operaste por tua palavra e conforme teu coração, fazendo-as saber a teu servo."}, {"numero": 22, "texto": "Portanto tu te engrandeceste, SENHOR Deus: porquanto não há como tu, nem há Deus além de ti, conforme tudo o que ouvimos com nossos ouvidos."}, {"numero": 23, "texto": "E quem como teu povo, como Israel, na terra? Uma gente por causa da qual Deus fosse a resgatá-la por povo, e lhe pusesse nome, e fizesse por vós, ó Israel, grandes e espantosas obras em tua terra, por causa de teu povo, ó Deus, que tu resgataste do Egito, das nações e de seus deuses?"}, {"numero": 24, "texto": "Porque tu confirmaste a ti teu povo Israel por povo teu para sempre: e tu, ó SENHOR, foste a eles por Deus."}, {"numero": 25, "texto": "Agora, pois, SENHOR Deus, a palavra que falaste sobre teu servo e sobre sua casa, desperta-a para sempre, e faze conforme o que disseste."}, {"numero": 26, "texto": "Que seja engrandecido teu nome para sempre, e diga-se: o SENHOR dos exércitos é Deus sobre Israel; e que a casa de teu servo Davi seja firme diante de ti."}, {"numero": 27, "texto": "Porque tu, SENHOR dos exércitos, Deus de Israel, revelaste ao ouvido de teu servo, dizendo: Eu te edificarei casa. Por isto teu servo achou em seu coração para fazer diante de ti esta súplica."}, {"numero": 28, "texto": "Agora, pois, SENHOR Deus, tu és Deus, e tuas palavras serão firmes, já que disseste a teu servo este bem."}, {"numero": 29, "texto": "Agrada-te, pois, de abençoar a casa de teu servo, para que perpetuamente permaneça diante de ti: pois que tu, SENHOR Deus, o disseste, e com tua bênção será bendita a casa de teu servo para sempre."}]'::jsonb, 'Almeida Livre'),
  ('2Sm', 7, 'en', '[{"numero": 1, "texto": "And it came to pass, when the king sat in his house, and the Lord had given him rest round about from all his enemies;"}, {"numero": 2, "texto": "That the king said unto Nathan the prophet, See now, I dwell in an house of cedar, but the ark of God dwelleth within curtains."}, {"numero": 3, "texto": "And Nathan said to the king, Go, do all that is in thine heart; for the Lord is with thee."}, {"numero": 4, "texto": "And it came to pass that night, that the word of the Lord came unto Nathan, saying,"}, {"numero": 5, "texto": "Go and tell my servant David, Thus saith the Lord, Shalt thou build me an house for me to dwell in?"}, {"numero": 6, "texto": "Whereas I have not dwelt in any house since the time that I brought up the children of Israel out of Egypt, even to this day, but have walked in a tent and in a tabernacle."}, {"numero": 7, "texto": "In all the places wherein I have walked with all the children of Israel spake I a word with any of the tribes of Israel, whom I commanded to feed my people Israel, saying, Why build ye not me an house of cedar?"}, {"numero": 8, "texto": "Now therefore so shalt thou say unto my servant David, Thus saith the Lord of hosts, I took thee from the sheepcote, from following the sheep, to be ruler over my people, over Israel:"}, {"numero": 9, "texto": "And I was with thee whithersoever thou wentest, and have cut off all thine enemies out of thy sight, and have made thee a great name, like unto the name of the great men that are in the earth."}, {"numero": 10, "texto": "Moreover I will appoint a place for my people Israel, and will plant them, that they may dwell in a place of their own, and move no more; neither shall the children of wickedness afflict them any more, as beforetime,"}, {"numero": 11, "texto": "And as since the time that I commanded judges to be over my people Israel, and have caused thee to rest from all thine enemies. Also the Lord telleth thee that he will make thee an house."}, {"numero": 12, "texto": "And when thy days be fulfilled, and thou shalt sleep with thy fathers, I will set up thy seed after thee, which shall proceed out of thy bowels, and I will establish his kingdom."}, {"numero": 13, "texto": "He shall build an house for my name, and I will stablish the throne of his kingdom for ever."}, {"numero": 14, "texto": "I will be his father, and he shall be my son. If he commit iniquity, I will chasten him with the rod of men, and with the stripes of the children of men:"}, {"numero": 15, "texto": "But my mercy shall not depart away from him, as I took it from Saul, whom I put away before thee."}, {"numero": 16, "texto": "And thine house and thy kingdom shall be established for ever before thee: thy throne shall be established for ever."}, {"numero": 17, "texto": "According to all these words, and according to all this vision, so did Nathan speak unto David."}, {"numero": 18, "texto": "Then went king David in, and sat before the Lord, and he said, Who am I, O Lord God? and what is my house, that thou hast brought me hitherto?"}, {"numero": 19, "texto": "And this was yet a small thing in thy sight, O Lord God; but thou hast spoken also of thy servant''s house for a great while to come. And is this the manner of man, O Lord God?"}, {"numero": 20, "texto": "And what can David say more unto thee? for thou, Lord God, knowest thy servant."}, {"numero": 21, "texto": "For thy word''s sake, and according to thine own heart, hast thou done all these great things, to make thy servant know them."}, {"numero": 22, "texto": "Wherefore thou art great, O Lord God: for there is none like thee, neither is there any God beside thee, according to all that we have heard with our ears."}, {"numero": 23, "texto": "And what one nation in the earth is like thy people, even like Israel, whom God went to redeem for a people to himself, and to make him a name, and to do for you great things and terrible, for thy land, before thy people, which thou redeemedst to thee from Egypt, from the nations and their gods?"}, {"numero": 24, "texto": "For thou hast confirmed to thyself thy people Israel to be a people unto thee for ever: and thou, Lord, art become their God."}, {"numero": 25, "texto": "And now, O Lord God, the word that thou hast spoken concerning thy servant, and concerning his house, establish it for ever, and do as thou hast said."}, {"numero": 26, "texto": "And let thy name be magnified for ever, saying, The Lord of hosts is the God over Israel: and let the house of thy servant David be established before thee."}, {"numero": 27, "texto": "For thou, O Lord of hosts, God of Israel, hast revealed to thy servant, saying, I will build thee an house: therefore hath thy servant found in his heart to pray this prayer unto thee."}, {"numero": 28, "texto": "And now, O Lord God, thou art that God, and thy words be true, and thou hast promised this goodness unto thy servant:"}, {"numero": 29, "texto": "Therefore now let it please thee to bless the house of thy servant, that it may continue for ever before thee: for thou, O Lord God, hast spoken it: and with thy blessing let the house of thy servant be blessed for ever."}]'::jsonb, 'King James Version'),
  ('2Sm', 7, 'fr', '[{"numero": 1, "texto": "Lorsque le roi habita dans sa maison, et que l''''Eternel lui eut donné du repos, après l''''avoir délivré de tous les ennemis qui l''''entouraient,"}, {"numero": 2, "texto": "il dit à Nathan le prophète: Vois donc! j''''habite dans une maison de cèdre, et l''''arche de Dieu habite au milieu d''''une tente."}, {"numero": 3, "texto": "Nathan répondit au roi: Va, fais tout ce que tu as dans le coeur, car l''''Eternel est avec toi."}, {"numero": 4, "texto": "La nuit suivante, la parole de l''''Eternel fut adressée à Nathan:"}, {"numero": 5, "texto": "Va dire à mon serviteur David: Ainsi parle l''''Eternel: Est-ce toi qui me bâtirais une maison pour que j''''en fasse ma demeure?"}, {"numero": 6, "texto": "Mais je n''''ai point habité dans une maison depuis le jour où j''''ai fait monter les enfants d''''Israël hors d''''Egypte jusqu''''à ce jour; j''''ai voyagé sous une tente et dans un tabernacle."}, {"numero": 7, "texto": "Partout où j''''ai marché avec tous les enfants d''''Israël, ai-je dit un mot à quelqu''''une des tribus d''''Israël à qui j''''avais ordonné de paître mon peuple d''''Israël, ai-je dit: Pourquoi ne me bâtissez-vous pas une maison de cèdre?"}, {"numero": 8, "texto": "Maintenant tu diras à mon serviteur David: Ainsi parle l''''Eternel des armées: Je t''''ai pris au pâturage, derrière les brebis, pour que tu fusses chef sur mon peuple, sur Israël;"}, {"numero": 9, "texto": "j''''ai été avec toi partout où tu as marché, j''''ai exterminé tous tes ennemis devant toi, et j''''ai rendu ton nom grand comme le nom des grands qui sont sur la terre;"}, {"numero": 10, "texto": "j''''ai donné une demeure à mon peuple, à Israël, et je l''''ai planté pour qu''''il y soit fixé et ne soit plus agité, pour que les méchants ne l''''oppriment plus comme auparavant"}, {"numero": 11, "texto": "et comme à l''''époque où j''''avais établi des juges sur mon peuple d''''Israël. Je t''''ai accordé du repos en te délivrant de tous tes ennemis. Et l''''Eternel t''''annonce qu''''il te créera une maison."}, {"numero": 12, "texto": "Quand tes jours seront accomplis et que tu seras couché avec tes pères, j''''élèverai ta postérité après toi, celui qui sera sorti de tes entrailles, et j''''affermirai son règne."}, {"numero": 13, "texto": "Ce sera lui qui bâtira une maison à mon nom, et j''''affermirai pour toujours le trône de son royaume."}, {"numero": 14, "texto": "Je serai pour lui un père, et il sera pour moi un fils. S''''il fait le mal, je le châtierai avec la verge des hommes et avec les coups des enfants des hommes;"}, {"numero": 15, "texto": "mais ma grâce ne se retirera point de lui, comme je l''''ai retirée de Saül, que j''''ai rejeté devant toi."}, {"numero": 16, "texto": "Ta maison et ton règne seront pour toujours assurés, ton trône sera pour toujours affermi."}, {"numero": 17, "texto": "Nathan rapporta à David toutes ces paroles et toute cette vision."}, {"numero": 18, "texto": "Et le roi David alla se présenter devant l''''Eternel, et dit: Qui suis-je, Seigneur Eternel, et quelle est ma maison, pour que tu m''''aies fait parvenir où je suis?"}, {"numero": 19, "texto": "C''''est encore peu de chose à tes yeux, Seigneur Eternel; tu parles aussi de la maison de ton serviteur pour les temps à venir. Et tu daignes instruire un homme de ces choses, Seigneur Eternel!"}, {"numero": 20, "texto": "Que pourrait te dire de plus David? Tu connais ton serviteur, Seigneur Eternel!"}, {"numero": 21, "texto": "A cause de ta parole, et selon ton coeur, tu as fait toutes ces grandes choses pour les révéler à ton serviteur."}, {"numero": 22, "texto": "Que tu es donc grand, Eternel Dieu! car nul n''''est semblable à toi, et il n''''y a point d''''autre Dieu que toi, d''''après tout ce que nous avons entendu de nos oreilles."}, {"numero": 23, "texto": "Est-il sur la terre une seule nation qui soit comme ton peuple, comme Israël, que Dieu est venu racheter pour en former son peuple, pour se faire un nom et pour accomplir en sa faveur, en faveur de ton pays, des miracles et des prodiges, en chassant devant ton peuple, que tu as racheté d''''Egypte, des nations et leurs dieux?"}, {"numero": 24, "texto": "Tu as affermi ton peuple d''''Israël, pour qu''''il fût ton peuple à toujours; et toi, Eternel, tu es devenu son Dieu."}, {"numero": 25, "texto": "Maintenant, Eternel Dieu, fais subsister jusque dans l''''éternité la parole que tu as prononcée sur ton serviteur et sur sa maison, et agis selon ta parole."}, {"numero": 26, "texto": "Que ton nom soit à jamais glorifié, et que l''''on dise: L''''Eternel des armées est le Dieu d''''Israël! Et que la maison de ton serviteur David soit affermie devant toi!"}, {"numero": 27, "texto": "Car toi-même, Eternel des armées, Dieu d''''Israël, tu t''''es révélé à ton serviteur, en disant: Je te fonderai une maison! C''''est pourquoi ton serviteur a pris courage pour t''''adresser cette prière."}, {"numero": 28, "texto": "Maintenant, Seigneur Eternel, tu es Dieu, et tes paroles sont vérité, et tu as annoncé cette grâce à ton serviteur."}, {"numero": 29, "texto": "Veuille donc bénir la maison de ton serviteur, afin qu''''elle subsiste à toujours devant toi! Car c''''est toi, Seigneur Eternel, qui as parlé, et par ta bénédiction la maison de ton serviteur sera bénie éternellement."}]'::jsonb, 'Louis Segond 1910'),
  ('2Sm', 7, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ que, estando ya el rey asentado en su casa, después que Jehová le había dado reposo de todos sus enemigos en derredor,"}, {"numero": 2, "texto": "Dijo el rey al profeta Nathán: Mira ahora, yo moro en edificios de cedro, y el arca de Dios está entre cortinas."}, {"numero": 3, "texto": "Y Nathán dijo al rey: Anda, y haz todo lo que está en tu corazón, que Jehová es contigo."}, {"numero": 4, "texto": "Y aconteció aquella noche, que fué palabra de Jehová á Nathán, diciendo:"}, {"numero": 5, "texto": "Ve y di á mi siervo David: Así ha dicho Jehová: ¿Tú me has de edificar casa en que yo more?"}, {"numero": 6, "texto": "Ciertamente no he habitado en casas desde el día que saqué á los hijos de Israel de Egipto hasta hoy, sino que anduve en tienda y en tabernáculo."}, {"numero": 7, "texto": "Y en todo cuanto he andado con todos los hijos de Israel, ¿he hablado palabra en alguna de las tribus de Israel, á quien haya mandado que apaciente mi pueblo de Israel, para decir: ¿Por qué no me habéis edificado casa de cedros?"}, {"numero": 8, "texto": "Ahora pues, dirás así á mi siervo David: Así ha dicho Jehová de los ejércitos: Yo te tomé de la majada, de detrás de las ovejas, para que fueses príncipe sobre mi pueblo, sobre Israel;"}, {"numero": 9, "texto": "Y he sido contigo en todo cuanto has andado, y delante de ti he talado todos tus enemigos, y te he hecho nombre grande, como el nombre de los grandes que son en la tierra."}, {"numero": 10, "texto": "Además yo fijaré lugar á mi pueblo Israel, yo lo plantaré, para que habite en su lugar, y nunca más sea removido, ni los inicuos le aflijan más, como antes,"}, {"numero": 11, "texto": "Desde el día que puse jueces sobre mi pueblo Israel; y yo te daré descanso de todos tus enemigos. Asimismo Jehová te hace saber, que él te quiere hacer casa."}, {"numero": 12, "texto": "Y cuando tus días fueren cumplidos, y durmieres con tus padres, yo estableceré tu simiente después de ti, la cual procederá de tus entrañas, y aseguraré su reino."}, {"numero": 13, "texto": "El edificará casa á mi nombre, y yo afirmaré para siempre el trono de su reino."}, {"numero": 14, "texto": "Yo le seré á él padre, y él me será á mí hijo. Y si él hiciere mal, yo le castigaré con vara de hombres, y con azotes de hijos de hombres;"}, {"numero": 15, "texto": "Empero mi misericordia no se apartará de él, como la aparté de Saúl, al cual quité de delante de ti."}, {"numero": 16, "texto": "Y será afirmada tu casa y tu reino para siempre delante de tu rostro; y tu trono será estable eternalmente."}, {"numero": 17, "texto": "Conforme á todas estas palabras, y conforme á toda esta visión, así habló Nathán á David."}, {"numero": 18, "texto": "Y entró el rey David, y púsose delante de Jehová, y dijo: Señor Jehová, ¿quién soy yo, y qué es mi casa, para que tú me traigas hasta aquí?"}, {"numero": 19, "texto": "Y aun te ha parecido poco esto, Señor Jehová, pues que también has hablado de la casa de tu siervo en lo por venir. ¿Es ése el modo de obrar del hombre, Señor Jehová?"}, {"numero": 20, "texto": "¿Y qué más puede añadir David hablando contigo? Tú pues conoces tu siervo, Señor Jehová."}, {"numero": 21, "texto": "Todas estas grandezas has obrado por tu palabra y conforme á tu corazón, haciéndolas saber á tu siervo."}, {"numero": 22, "texto": "Por tanto tú te has engrandecido, Jehová Dios: por cuanto no hay como tú, ni hay Dios fuera de ti, conforme á todo lo que hemos oído con nuestros oídos."}, {"numero": 23, "texto": "¿Y quién como tu pueblo, como Israel, en la tierra? una gente por amor de la cual Dios fuese á redimírsela por pueblo, y le pusiese nombre, é hiciese por vosotros, oh Israel, grandes y espantosas obras en tu tierra, por amor de tu pueblo, oh Dios, que tú redimiste de Egipto, de las gentes y de sus dioses?"}, {"numero": 24, "texto": "Porque tú te has confirmado á tu pueblo Israel por pueblo tuyo para siempre: y tú, oh Jehová, fuiste á ellos por Dios."}, {"numero": 25, "texto": "Ahora pues, Jehová Dios, la palabra que has hablado sobre tu siervo y sobre su casa, despiértala para siempre, y haz conforme á lo que has dicho."}, {"numero": 26, "texto": "Que sea engrandecido tu nombre para siempre, y dígase: Jehová de los ejércitos es Dios sobre Israel; y que la casa de tu siervo David sea firme delante de ti."}, {"numero": 27, "texto": "Porque tú, Jehová de los ejércitos, Dios de Israel, revelaste al oído de tu siervo, diciendo: Yo te edificaré casa. Por esto tu siervo ha hallado en su corazón para hacer delante de ti esta súplica."}, {"numero": 28, "texto": "Ahora pues, Jehová Dios, tú eres Dios, y tus palabras serán firmes, ya que has dicho á tu siervo este bien."}, {"numero": 29, "texto": "Tenlo pues ahora á bien, y bendice la casa de tu siervo, para que perpetuamente permanezca delante de ti: pues que tú, Jehová Dios, lo has dicho, y con tu bendición será bendita la casa de tu siervo para siempre."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Sm', 15, 'pt', '[{"numero": 1, "texto": "Aconteceu depois disto, que Absalão se fez de carros e cavalos, e cinquenta que corressem diante dele."}, {"numero": 2, "texto": "E levantava-se Absalão de manhã, e punha-se a um lado do caminho da porta; e a qualquer um que tinha pleito e vinha ao rei a juízo, Absalão lhe chamava a si, e dizia-lhe: De que cidade és? E ele respondia: Teu servo é de uma das tribos de Israel."}, {"numero": 3, "texto": "Então Absalão lhe dizia: Olha que tuas palavras são boas e justas: mas não tens quem te ouça pelo rei."}, {"numero": 4, "texto": "E dizia Absalão: Quem me dera se eu fosse constituído juiz na terra, para que viessem a mim todos os que têm pleito ou negócio, que eu lhes faria justiça!"}, {"numero": 5, "texto": "E acontecia que, quando alguém se chegava para inclinar-se a ele, ele estendia sua mão, e o tomava, e o beijava."}, {"numero": 6, "texto": "E desta maneira fazia com todo Israel que vinha ao rei a juízo: e assim roubava Absalão o coração dos de Israel."}, {"numero": 7, "texto": "E ao fim de quarenta anos aconteceu que Absalão disse ao rei: Eu te rogo me permitas que vá a Hebrom, a pagar meu voto que ei prometido ao SENHOR:"}, {"numero": 8, "texto": "Porque teu servo fez voto quando estava em Gesur em Síria, dizendo: Se o SENHOR me voltar a Jerusalém, eu servirei ao SENHOR."}, {"numero": 9, "texto": "E o rei disse: Vai em paz. E ele se levantou, e se foi a Hebrom."}, {"numero": 10, "texto": "Porém enviou Absalão espias por todas as tribos de Israel, dizendo: Quando ouvirdes o som da trombeta, direis: Absalão reina em Hebrom."}, {"numero": 11, "texto": "E foram com Absalão duzentos homens de Jerusalém por ele convidados, os quais iam em sua ingenuidade, sem saber nada."}, {"numero": 12, "texto": "Também enviou Absalão por Aitofel gilonita, do conselho de Davi, a Gilo sua cidade, enquanto fazia seus sacrifícios. E a conspiração veio a ser grande, pois se ia aumentando o povo com Absalão."}, {"numero": 13, "texto": "E veio o aviso a Davi, dizendo: O coração de todo Israel segue Absalão."}, {"numero": 14, "texto": "Então Davi disse a todos os seus servos que estavam com ele em Jerusalém: Levantai-vos, e fujamos, porque não poderemos escapar diante de Absalão; apressai-vos a partir, não seja que se apressando ele nos alcance, e lance o mal sobre nós, e fira a cidade a fio de espada."}, {"numero": 15, "texto": "E os servos do rei disseram ao rei: Eis que, teus servos estão prontos a tudo que nosso senhor, o rei, decidir fazer."}, {"numero": 16, "texto": "O rei então saiu, com toda sua família depois dele. E deixou o rei dez mulheres concubinas para que guardassem a casa."}, {"numero": 17, "texto": "Saiu pois o rei com todo o povo que lhe seguia, e pararam-se em um lugar distante."}, {"numero": 18, "texto": "E todos os seus servos passavam a seu lado, com todos os quereteus e peleteus; e todos os giteus, seiscentos homens que haviam vindo a pé desde Gate, iam diante do rei."}, {"numero": 19, "texto": "E disse o rei a Itai giteu: Para que vens tu também conosco? Volta, e fica com o rei; porque tu és estrangeiro, e desterrado também de teu lugar."}, {"numero": 20, "texto": "Ontem vieste, e tenho-te de fazer hoje que mudes lugar para ir conosco? Eu vou como vou: tu volta, e faze voltar a teus irmãos: em ti haja misericórdia e verdade."}, {"numero": 21, "texto": "E respondeu Itai ao rei, dizendo: Vive Deus, e vive meu senhor o rei, que, ou para morte ou para vida, de onde meu senhor o rei estiver, ali estará também teu servo."}, {"numero": 22, "texto": "Então Davi disse a Itai: Vem, pois, e passa. E passou Itai giteu, e todos os seus homens, e toda sua família."}, {"numero": 23, "texto": "E toda aquela terra chorou em alta voz; passou, logo, toda a gente o ribeiro de Cedrom; também passou o rei, e todo aquele povo passou, ao caminho que vai ao deserto."}, {"numero": 24, "texto": "E eis que, também ia Zadoque, e com ele todos os levitas que levavam a arca do pacto de Deus; e assentaram a arca do pacto de Deus. E subiu Abiatar depois que acabou de sair da cidade todo aquele povo."}, {"numero": 25, "texto": "Porém disse o rei a Zadoque: Volta a arca de Deus à cidade; que se eu achar favor aos olhos do SENHOR, ele me voltará, e me fará ver a ela e a seu tabernáculo:"}, {"numero": 26, "texto": "E se disser: Não me agradas: aqui estou, faça de mim o que bem lhe parecer."}, {"numero": 27, "texto": "Disse ainda o rei a Zadoque sacerdote: Não és tu vidente? Volta-te em paz à cidade; e convosco vossos dois filhos, teu filho Aimaás, e Jônatas filho de Abiatar."}, {"numero": 28, "texto": "Olhai que eu me deterei nos campos do deserto, até que venha resposta de vós que me dê aviso."}, {"numero": 29, "texto": "Então Zadoque e Abiatar trouxeram de volta a arca de Deus a Jerusalém; e estiveram ali."}, {"numero": 30, "texto": "E Davi subiu o monte das Oliveiras; e subiu chorando, levando a cabeça coberta, e os pés descalços. Também todo aquele povo que tinha consigo cobriu cada um sua cabeça, e subiram chorando assim como subiam."}, {"numero": 31, "texto": "E deram aviso a Davi, dizendo: Aitofel está entre os que conspiraram com Absalão. Então disse Davi: Torna loucura agora, ó SENHOR, o conselho de Aitofel."}, {"numero": 32, "texto": "E quando Davi chegou ao cume do monte para adorar ali a Deus, eis que Husai arquita que lhe saiu ao encontro, trazendo rasgada sua roupa, e terra sobre sua cabeça."}, {"numero": 33, "texto": "E disse-lhe Davi: Se passares comigo, tu me serás prejudicial;"}, {"numero": 34, "texto": "Mas se voltares à cidade, e disseres a Absalão: Rei, eu serei teu servo; como até aqui fui servo de teu pai, assim serei agora servo teu, então tu me dissiparás o conselho de Aitofel."}, {"numero": 35, "texto": "Não estarão ali contigo Zadoque e Abiatar sacerdotes? Portanto, tudo o que ouvires na casa do rei, darás aviso disso a Zadoque e a Abiatar sacerdotes."}, {"numero": 36, "texto": "E eis que estão com eles seus dois filhos, Aimaás o de Zadoque, e Jônatas o de Abiatar; por meio deles me enviareis aviso de tudo o que ouvirdes."}, {"numero": 37, "texto": "Assim se veio Husai amigo de Davi à cidade; e Absalão entrou em Jerusalém."}]'::jsonb, 'Almeida Livre'),
  ('2Sm', 15, 'en', '[{"numero": 1, "texto": "And it came to pass after this, that Absalom prepared him chariots and horses, and fifty men to run before him."}, {"numero": 2, "texto": "And Absalom rose up early, and stood beside the way of the gate: and it was so, that when any man that had a controversy came to the king for judgment, then Absalom called unto him, and said, Of what city art thou? And he said, Thy servant is of one of the tribes of Israel."}, {"numero": 3, "texto": "And Absalom said unto him, See, thy matters are good and right; but there is no man deputed of the king to hear thee."}, {"numero": 4, "texto": "Absalom said moreover, Oh that I were made judge in the land, that every man which hath any suit or cause might come unto me, and I would do him justice!"}, {"numero": 5, "texto": "And it was so, that when any man came nigh to him to do him obeisance, he put forth his hand, and took him, and kissed him."}, {"numero": 6, "texto": "And on this manner did Absalom to all Israel that came to the king for judgment: so Absalom stole the hearts of the men of Israel."}, {"numero": 7, "texto": "And it came to pass after forty years, that Absalom said unto the king, I pray thee, let me go and pay my vow, which I have vowed unto the Lord, in Hebron."}, {"numero": 8, "texto": "For thy servant vowed a vow while I abode at Geshur in Syria, saying, If the Lord shall bring me again indeed to Jerusalem, then I will serve the Lord."}, {"numero": 9, "texto": "And the king said unto him, Go in peace. So he arose, and went to Hebron."}, {"numero": 10, "texto": "But Absalom sent spies throughout all the tribes of Israel, saying, As soon as ye hear the sound of the trumpet, then ye shall say, Absalom reigneth in Hebron."}, {"numero": 11, "texto": "And with Absalom went two hundred men out of Jerusalem, that were called; and they went in their simplicity, and they knew not any thing."}, {"numero": 12, "texto": "And Absalom sent for Ahithophel the Gilonite, David''s counsellor, from his city, even from Giloh, while he offered sacrifices. And the conspiracy was strong; for the people increased continually with Absalom."}, {"numero": 13, "texto": "And there came a messenger to David, saying, The hearts of the men of Israel are after Absalom."}, {"numero": 14, "texto": "And David said unto all his servants that were with him at Jerusalem, Arise, and let us flee; for we shall not else escape from Absalom: make speed to depart, lest he overtake us suddenly, and bring evil upon us, and smite the city with the edge of the sword."}, {"numero": 15, "texto": "And the king''s servants said unto the king, Behold, thy servants are ready to do whatsoever my lord the king shall appoint."}, {"numero": 16, "texto": "And the king went forth, and all his household after him. And the king left ten women, which were concubines, to keep the house."}, {"numero": 17, "texto": "And the king went forth, and all the people after him, and tarried in a place that was far off."}, {"numero": 18, "texto": "And all his servants passed on beside him; and all the Cherethites, and all the Pelethites, and all the Gittites, six hundred men which came after him from Gath, passed on before the king."}, {"numero": 19, "texto": "Then said the king to Ittai the Gittite, Wherefore goest thou also with us? return to thy place, and abide with the king: for thou art a stranger, and also an exile."}, {"numero": 20, "texto": "Whereas thou camest but yesterday, should I this day make thee go up and down with us? seeing I go whither I may, return thou, and take back thy brethren: mercy and truth be with thee."}, {"numero": 21, "texto": "And Ittai answered the king, and said, As the Lord liveth, and as my lord the king liveth, surely in what place my lord the king shall be, whether in death or life, even there also will thy servant be."}, {"numero": 22, "texto": "And David said to Ittai, Go and pass over. And Ittai the Gittite passed over, and all his men, and all the little ones that were with him."}, {"numero": 23, "texto": "And all the country wept with a loud voice, and all the people passed over: the king also himself passed over the brook Kidron, and all the people passed over, toward the way of the wilderness."}, {"numero": 24, "texto": "And lo Zadok also, and all the Levites were with him, bearing the ark of the covenant of God: and they set down the ark of God; and Abiathar went up, until all the people had done passing out of the city."}, {"numero": 25, "texto": "And the king said unto Zadok, Carry back the ark of God into the city: if I shall find favour in the eyes of the Lord, he will bring me again, and shew me both it, and his habitation:"}, {"numero": 26, "texto": "But if he thus say, I have no delight in thee; behold, here am I, let him do to me as seemeth good unto him."}, {"numero": 27, "texto": "The king said also unto Zadok the priest, Art not thou a seer? return into the city in peace, and your two sons with you, Ahimaaz thy son, and Jonathan the son of Abiathar."}, {"numero": 28, "texto": "See, I will tarry in the plain of the wilderness, until there come word from you to certify me."}, {"numero": 29, "texto": "Zadok therefore and Abiathar carried the ark of God again to Jerusalem: and they tarried there."}, {"numero": 30, "texto": "And David went up by the ascent of mount Olivet, and wept as he went up, and had his head covered, and he went barefoot: and all the people that was with him covered every man his head, and they went up, weeping as they went up."}, {"numero": 31, "texto": "And one told David, saying, Ahithophel is among the conspirators with Absalom. And David said, O Lord, I pray thee, turn the counsel of Ahithophel into foolishness."}, {"numero": 32, "texto": "And it came to pass, that when David was come to the top of the mount, where he worshipped God, behold, Hushai the Archite came to meet him with his coat rent, and earth upon his head:"}, {"numero": 33, "texto": "Unto whom David said, If thou passest on with me, then thou shalt be a burden unto me:"}, {"numero": 34, "texto": "But if thou return to the city, and say unto Absalom, I will be thy servant, O king; as I have been thy father''s servant hitherto, so will I now also be thy servant: then mayest thou for me defeat the counsel of Ahithophel."}, {"numero": 35, "texto": "And hast thou not there with thee Zadok and Abiathar the priests? therefore it shall be, that what thing soever thou shalt hear out of the king''s house, thou shalt tell it to Zadok and Abiathar the priests."}, {"numero": 36, "texto": "Behold, they have there with them their two sons, Ahimaaz Zadok''s son, and Jonathan Abiathar''s son; and by them ye shall send unto me every thing that ye can hear."}, {"numero": 37, "texto": "So Hushai David''s friend came into the city, and Absalom came into Jerusalem."}]'::jsonb, 'King James Version'),
  ('2Sm', 15, 'fr', '[{"numero": 1, "texto": "Après cela, Absalom se procura un char et des chevaux, et cinquante hommes qui couraient devant lui."}, {"numero": 2, "texto": "Il se levait de bon matin, et se tenait au bord du chemin de la porte. Et chaque fois qu''''un homme ayant une contestation se rendait vers le roi pour obtenir un jugement, Absalom l''''appelait, et disait: De quelle ville es-tu? Lorsqu''''il avait répondu: Je suis d''''une telle tribu d''''Israël,"}, {"numero": 3, "texto": "Absalom lui disait: Vois, ta cause est bonne et juste; mais personne de chez le roi ne t''''écoutera."}, {"numero": 4, "texto": "Absalom disait: Qui m''''établira juge dans le pays? Tout homme qui aurait une contestation et un procès viendrait à moi, et je lui ferais justice."}, {"numero": 5, "texto": "Et quand quelqu''''un s''''approchait pour se prosterner devant lui, il lui tendait la main, le saisissait et l''''embrassait."}, {"numero": 6, "texto": "Absalom agissait ainsi à l''''égard de tous ceux d''''Israël, qui se rendaient vers le roi pour demander justice. Et Absalom gagnait le coeur des gens d''''Israël."}, {"numero": 7, "texto": "Au bout de quarante ans, Absalom dit au roi: Permets que j''''aille à Hébron, pour accomplir le voeu que j''''ai fait à l''''Eternel."}, {"numero": 8, "texto": "Car ton serviteur a fait un voeu, pendant que je demeurais à Gueschur en Syrie; j''''ai dit: Si l''''Eternel me ramène à Jérusalem, je servirai l''''Eternel."}, {"numero": 9, "texto": "Le roi lui dit: Va en paix. Et Absalom se leva et partit pour Hébron."}, {"numero": 10, "texto": "Absalom envoya des espions dans toutes les tribus d''''Israël, pour dire: Quand vous entendrez le son de la trompette, vous direz: Absalom règne à Hébron."}, {"numero": 11, "texto": "Deux cents hommes de Jérusalem, qui avaient été invités, accompagnèrent Absalom; et ils le firent en toute simplicité, sans rien savoir."}, {"numero": 12, "texto": "Pendant qu''''Absalom offrait les sacrifices, il envoya chercher à la ville de Guilo Achitophel, le Guilonite, conseiller de David. La conjuration devint puissante, et le peuple était de plus en plus nombreux auprès d''''Absalom."}, {"numero": 13, "texto": "Quelqu''''un vint informer David, et lui dit: Le coeur des hommes d''''Israël s''''est tourné vers Absalom."}, {"numero": 14, "texto": "Et David dit à tous ses serviteurs qui étaient avec lui à Jérusalem: Levez-vous, fuyons, car il n''''y aura point de salut pour nous devant Absalom. Hâtez-vous de partir; sinon, il ne tarderait pas à nous atteindre, et il nous précipiterait dans le malheur et frapperait la ville du tranchant de l''''épée."}, {"numero": 15, "texto": "Les serviteurs du roi lui dirent: Tes serviteurs feront tout ce que voudra mon seigneur le roi."}, {"numero": 16, "texto": "Le roi sortit, et toute sa maison le suivait, et il laissa dix concubines pour garder la maison."}, {"numero": 17, "texto": "Le roi sortit, et tout le peuple le suivait, et ils s''''arrêtèrent à la dernière maison."}, {"numero": 18, "texto": "Tous ses serviteurs, tous les Kéréthiens et tous les Péléthiens, passèrent à ses côtés; et tous les Gathiens, au nombre de six cents hommes, venus de Gath à sa suite, passèrent devant le roi."}, {"numero": 19, "texto": "Le roi dit à Ittaï de Gath: Pourquoi viendrais-tu aussi avec nous? Retourne, et reste avec le roi, car tu es étranger, et même tu as été emmené de ton pays."}, {"numero": 20, "texto": "Tu es arrivé d''''hier, et aujourd''''hui je te ferais errer avec nous çà et là, quand je ne sais moi-même où je vais! Retourne, et emmène tes frères avec toi. Que l''''Eternel use envers toi de bonté et de fidélité!"}, {"numero": 21, "texto": "Ittaï répondit au roi, et dit: L''''Eternel est vivant et mon seigneur le roi est vivant! au lieu où sera mon seigneur le roi, soit pour mourir, soit pour vivre, là aussi sera ton serviteur."}, {"numero": 22, "texto": "David dit alors à Ittaï: Va, passe! Et Ittaï de Gath passa, avec tous ses gens et tous les enfants qui étaient avec lui."}, {"numero": 23, "texto": "Toute la contrée était en larmes et l''''on poussait de grands cris, au passage de tout le peuple. Le roi passa le torrent de Cédron, et tout le peuple passa vis-à-vis du chemin qui mène au désert."}, {"numero": 24, "texto": "Tsadok était aussi là, et avec lui tous les Lévites portant l''''arche de l''''alliance de Dieu; et ils posèrent l''''arche de Dieu, et Abiathar montait, pendant que tout le peuple achevait de sortir de la ville."}, {"numero": 25, "texto": "Le roi dit à Tsadok: Reporte l''''arche de Dieu dans la ville. Si je trouve grâce aux yeux de l''''Eternel, il me ramènera, et il me fera voir l''''arche et sa demeure."}, {"numero": 26, "texto": "Mais s''''il dit: Je ne prends point plaisir en toi! me voici, qu''''il me fasse ce qui lui semblera bon."}, {"numero": 27, "texto": "Le roi dit encore au sacrificateur Tsadok: Comprends-tu? retourne en paix dans la ville, avec Achimaats, ton fils, et avec Jonathan, fils d''''Abiathar, vos deux fils."}, {"numero": 28, "texto": "Voyez, j''''attendrai dans les plaines du désert, jusqu''''à ce qu''''il m''''arrive des nouvelles de votre part."}, {"numero": 29, "texto": "Ainsi Tsadok et Abiathar reportèrent l''''arche de Dieu à Jérusalem, et ils y restèrent."}, {"numero": 30, "texto": "David monta la colline des oliviers. Il montait en pleurant et la tête couverte, et il marchait nu-pieds; et tous ceux qui étaient avec lui se couvrirent aussi la tête, et ils montaient en pleurant."}, {"numero": 31, "texto": "On vint dire à David: Achitophel est avec Absalom parmi les conjurés. Et David dit: O Eternel, réduis à néant les conseils d''''Achitophel!"}, {"numero": 32, "texto": "Lorsque David fut arrivé au sommet, où il se prosterna devant Dieu, voici, Huschaï, l''''Arkien, vint au-devant de lui, la tunique déchirée et la tête couverte de terre."}, {"numero": 33, "texto": "David lui dit: Si tu viens avec moi, tu me seras à charge."}, {"numero": 34, "texto": "Et, au contraire, tu anéantiras en ma faveur les conseils d''''Achitophel, si tu retournes à la ville, et que tu dises à Absalom: O roi, je serai ton serviteur; je fus autrefois le serviteur de ton père, mais je suis maintenant ton serviteur."}, {"numero": 35, "texto": "Les sacrificateurs Tsadok et Abiathar ne seront-ils pas là avec toi? Tout ce que tu apprendras de la maison du roi, tu le diras aux sacrificateurs Tsadok et Abiathar."}, {"numero": 36, "texto": "Et comme ils ont là auprès d''''eux leurs deux fils, Achimaats, fils de Tsadok, et Jonathan, fils d''''Abiathar, c''''est par eux que vous me ferez savoir tout ce que vous aurez appris."}, {"numero": 37, "texto": "Huschaï, ami de David, retourna donc à la ville. Et Absalom entra dans Jérusalem."}]'::jsonb, 'Louis Segond 1910'),
  ('2Sm', 15, 'es', '[{"numero": 1, "texto": "ACONTECIÓ después de esto, que Absalom se hizo de carros y caballos, y cincuenta hombres que corriesen delante de él."}, {"numero": 2, "texto": "Y levantábase Absalom de mañana, y poníase á un lado del camino de la puerta; y á cualquiera que tenía pleito y venía al rey á juicio, Absalom le llamaba á sí, y decíale: ¿De qué ciudad eres? Y él respondía: Tu siervo es de una de las tribus de Israel."}, {"numero": 3, "texto": "Entonces Absalom le decía: Mira, tus palabras son buenas y justas: mas no tienes quien te oiga por el rey."}, {"numero": 4, "texto": "Y decía Absalom: ¡Quién me pusiera por juez en la tierra, para que viniesen á mí todos los que tienen pleito ó negocio, que yo les haría justicia!"}, {"numero": 5, "texto": "Y acontecía que, cuando alguno se llegaba para inclinarse á él, él extendía la mano, y lo tomaba, y lo besaba."}, {"numero": 6, "texto": "Y de esta manera hacía con todo Israel que venía al rey á juicio: y así robaba Absalom el corazón de los de Israel."}, {"numero": 7, "texto": "Y al cabo de cuarenta años aconteció que Absalom dijo al rey: Yo te ruego me permitas que vaya á Hebrón, á pagar mi voto que he prometido á Jehová:"}, {"numero": 8, "texto": "Porque tu siervo hizo voto cuando estaba en Gessur en Siria, diciendo: Si Jehová me volviere á Jerusalem, yo serviré á Jehová."}, {"numero": 9, "texto": "Y el rey le dijo: Ve en paz. Y él se levantó, y se fué á Hebrón."}, {"numero": 10, "texto": "Empero envió Absalom espías por todas las tribus de Israel, diciendo: Cuando oyereis el sonido de la trompeta, diréis: Absalom reina en Hebrón."}, {"numero": 11, "texto": "Y fueron con Absalom doscientos hombres de Jerusalem por él convidados, los cuales iban en su sencillez, sin saber nada."}, {"numero": 12, "texto": "También envió Absalom por Achitophel Gilonita, del consejo de David, á Gilo su ciudad, mientras hacía sus sacrificios. Y la conjuración vino á ser grande, pues se iba aumentando el pueblo con Absalom."}, {"numero": 13, "texto": "Y vino el aviso á David, diciendo: El corazón de todo Israel va tras Absalom."}, {"numero": 14, "texto": "Entonces David dijo á todos sus siervos que estaban con él en Jerusalem: Levantaos y huyamos, porque no podremos escapar delante de Absalom; daos priesa á partir, no sea que apresurándose él nos alcance, y arroje el mal sobre nosotros, y hiera la ciudad á filo de espada."}, {"numero": 15, "texto": "Y los siervos del rey dijeron al rey: He aquí, tus siervos están prestos á todo lo que nuestro señor el rey eligiere."}, {"numero": 16, "texto": "El rey entonces salió, con toda su familia en pos de él. Y dejó el rey diez mujeres concubinas para que guardasen la casa."}, {"numero": 17, "texto": "Salió pues el rey con todo el pueblo que le seguía, y paráronse en un lugar distante."}, {"numero": 18, "texto": "Y todos sus siervos pasaban á su lado, con todos los Ceretheos y Peletheos; y todos los Getheos, seiscientos hombres que habían venido á pie desde Gath, iban delante del rey."}, {"numero": 19, "texto": "Y dijo el rey á Ittai Getheo: ¿Para qué vienes tú también con nosotros? vuélvete y quédate con el rey; porque tú eres extranjero, y desterrado también de tu lugar."}, {"numero": 20, "texto": "¿Ayer viniste, y téngote de hacer hoy que mudes lugar para ir con nosotros? Yo voy como voy: tú vuélvete, y haz volver á tus hermanos; en ti haya misericordia y verdad."}, {"numero": 21, "texto": "Y respondió Ittai al rey, diciendo: Vive Dios, y vive mi señor el rey, que, ó para muerte ó para vida, donde mi señor el rey estuviere, allí estará también tu siervo."}, {"numero": 22, "texto": "Entonces David dijo á Ittai: Ven pues, y pasa. Y pasó Ittai Getheo, y todos sus hombres, y toda su familia."}, {"numero": 23, "texto": "Y todo el país lloró en alta voz; pasó luego toda la gente el torrente de Cedrón; asimismo pasó el rey, y todo el pueblo pasó, al camino que va al desierto."}, {"numero": 24, "texto": "Y he aquí, también iba Sadoc, y con él todos los Levitas que llevaban el arca del pacto de Dios; y asentaron el arca del pacto de Dios. Y subió Abiathar después que hubo acabado de salir de la ciudad todo el pueblo."}, {"numero": 25, "texto": "Pero dijo el rey á Sadoc: Vuelve el arca de Dios á la ciudad; que si yo hallare gracia en los ojos de Jehová, él me volverá, y me hará ver á ella y á su tabernáculo:"}, {"numero": 26, "texto": "Y si dijere: No me agradas: aquí estoy, haga de mí lo que bien le pareciere."}, {"numero": 27, "texto": "Dijo aún el rey á Sadoc sacerdote: ¿No eres tú el vidente? Vuélvete en paz á la ciudad; y con vosotros vuestros dos hijos, tu hijo Ahimaas, y Jonathán hijo de Abiathar."}, {"numero": 28, "texto": "Mirad, yo me detendré en los campos del desierto, hasta que venga respuesta de vosotros que me dé aviso."}, {"numero": 29, "texto": "Entonces Sadoc y Abiathar volvieron el arca de Dios á Jerusalem; y estuviéronse allá."}, {"numero": 30, "texto": "Y David subió la cuesta de las olivas; y subióla llorando, llevando la cabeza cubierta, y los pies descalzos. También todo el pueblo que tenía consigo cubrió cada uno su cabeza, y subieron llorando así como subían."}, {"numero": 31, "texto": "Y dieron aviso á David, diciendo: Achitophel está entre los que conspiraron con Absalom. Entonces dijo David: Entontece ahora, oh Jehová, el consejo de Achitophel."}, {"numero": 32, "texto": "Y como David llegó á la cumbre del monte para adorar allí á Dios, he aquí Husai Arachîta que le salió al encuentro, trayendo rota su ropa, y tierra sobre su cabeza."}, {"numero": 33, "texto": "Y díjole David: Si pasares conmigo, serme has de carga;"}, {"numero": 34, "texto": "Mas si volvieres á la ciudad, y dijeres á Absalom: Rey, yo seré tu siervo; como hasta aquí he sido siervo de tu padre, así seré ahora siervo tuyo, entonces tú me disiparás el consejo de Achitophel."}, {"numero": 35, "texto": "¿No estarán allí contigo Sadoc y Abiathar sacerdotes? Por tanto, todo lo que oyeres en la casa del rey, darás aviso de ello á Sadoc y á Abiathar sacerdotes."}, {"numero": 36, "texto": "Y he aquí que están con ellos sus dos hijos, Ahimaas el de Sadoc, y Jonathán el de Abiathar: por mano de ellos me enviaréis aviso de todo lo que oyereis."}, {"numero": 37, "texto": "Así se vino Husai amigo de David á la ciudad; y Absalom entró en Jerusalem."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Sm', 17, 'pt', '[{"numero": 1, "texto": "Então Aitofel disse a Absalão: Eu escolherei agora doze mil homens, e me levantarei, e seguirei a Davi esta noite;"}, {"numero": 2, "texto": "E o atacarei quando ele estiver cansado e fraco das mãos; eu o atemorizarei, e todo aquele povo que está com ele fugirá, e ferirei ao rei somente."}, {"numero": 3, "texto": "Assim farei tornar todo aquele povo a ti: e quando eles houverem voltado, (pois aquele homem é o que tu queres) todo aquele povo estará em paz."}, {"numero": 4, "texto": "Esta razão apareceu bem a Absalão e a todos os anciãos de Israel."}, {"numero": 5, "texto": "E disse Absalão: Chama também agora a Husai arquita, para que também ouçamos o que ele dirá."}, {"numero": 6, "texto": "E quando Husai veio a Absalão, falou-lhe Absalão, dizendo: Assim disse Aitofel; seguiremos seu conselho, ou não? Dize tu."}, {"numero": 7, "texto": "Então Husai disse a Absalão: O conselho que deu esta vez Aitofel não é bom."}, {"numero": 8, "texto": "E acrescentou Husai: Tu sabes que teu pai e os seus são homens valentes, e que estão com amargura de ânimo, como a ursa no campo quando lhe tiraram os filhos. Além disso, teu pai é homem de guerra, e não terá a noite com o povo."}, {"numero": 9, "texto": "Eis que ele estará agora escondido em alguma cova, ou em outro lugar: e se ao princípio caírem alguns dos teus, ouvirá quem o ouvir, e dirá: O povo que segue a Absalão foi derrotado."}, {"numero": 10, "texto": "Assim ainda o homem valente, cujo coração seja como coração de leão, sem dúvida desmaiará: porque todo Israel sabe que teu pai é homem valente, e que os que estão com ele são esforçados."}, {"numero": 11, "texto": "Aconselho, pois, que todo Israel se junte a ti, desde Dã até Berseba, em multidão como a areia que está à beira do mar, e que tu em pessoa vás à batalha."}, {"numero": 12, "texto": "Então lhe acometeremos em qualquer lugar que puder achar-se, e viremos contra ele como quando o orvalho cai sobre a terra, e a ninguém deixaremos dele, e de todos os que com ele estão."}, {"numero": 13, "texto": "E se se recolher em alguma cidade, todos os de Israel trarão cordas àquela cidade, e a arrastaremos até o ribeiro, que nunca mais apareça pedra dela."}, {"numero": 14, "texto": "Então Absalão e todos os de Israel disseram: O conselho de Husai arquita é melhor que o conselho de Aitofel. Porque o SENHOR havia ordenado que o acertado conselho de Aitofel se frustrasse, para que o SENHOR fizesse vir o mal sobre Absalão."}, {"numero": 15, "texto": "Disse logo Husai a Zadoque e a Abiatar sacerdotes: Assim e assim aconselhou Aitofel a Absalão e aos anciãos de Israel: e desta maneira aconselhei eu."}, {"numero": 16, "texto": "Portanto enviai imediatamente, e dai aviso a Davi, dizendo: Não fiques esta noite nos campos do deserto, mas sim passa logo o Jordão, para que o rei não seja consumido, e todo aquele povo que com ele está."}, {"numero": 17, "texto": "E Jônatas e Aimaás estavam junto à fonte de Rogel, porque não podiam eles mostrar-se vindo à cidade; foi, portanto, uma criada, e deu-lhes o aviso: e eles foram, e noticiaram-no ao rei Davi."}, {"numero": 18, "texto": "Porém foram vistos por um jovem, o qual deu conta a Absalão: porém os dois se apressaram em caminhar, e chegaram à casa de um homem em Baurim, que tinha um poço em seu pátio, dentro do qual se meteram."}, {"numero": 19, "texto": "E tomando a mulher da casa uma manta, estendeu-a sobre a boca do poço, e estendeu sobre ela o grão trilhado; e não se penetrou o negócio."}, {"numero": 20, "texto": "Chegando logo os criados de Absalão à casa à mulher, disseram-lhe: Onde estão Aimaás e Jônatas? E a mulher lhes respondeu: Já passaram o vau das águas. E quando eles os buscaram e não os acharam voltaram a Jerusalém."}, {"numero": 21, "texto": "E depois que eles se houveram ido, aqueles saíram do poço, e foram-se, e deram aviso ao rei Davi; e disseram-lhe: Levantai-vos e apressai-vos a passar as águas, porque Aitofel deu tal conselho contra vós."}, {"numero": 22, "texto": "Então Davi se levantou, e todo aquele povo que com ele estava, e passaram o Jordão antes que amanhecesse; nem sequer faltou um que não passasse o Jordão."}, {"numero": 23, "texto": "E Aitofel, vendo que não se havia praticado seu conselho, preparou seu asno, e levantou-se, e foi-se à sua casa em sua cidade; e depois de dar ordens acerca de sua casa, enforcou-se e morreu, e foi sepultado no sepulcro de seu pai."}, {"numero": 24, "texto": "E Davi chegou a Maanaim, e Absalão passou o Jordão com toda a gente de Israel."}, {"numero": 25, "texto": "E Absalão constituiu a Amasa, sobre o exército em lugar de Joabe, o qual Amasa foi filho de um homem de Israel chamado Itra, o qual havia se deitado com Abigail filha de Naás, irmã de Zeruia, mãe de Joabe."}, {"numero": 26, "texto": "E Israel assentou acampamento com Absalão na terra de Gileade."}, {"numero": 27, "texto": "E logo que Davi chegou a Maanaim, Sobi filho de Naás de Rabá dos filhos de Amom, e Maquir filho de Amiel de Lo-Debar, e Barzilai gileadita de Rogelim,"}, {"numero": 28, "texto": "Trouxeram a Davi e ao povo que estava com ele, camas, e bacias, e vasilhas de barro, e trigo, e cevada, e farinha, e grão tostado, favas, lentilhas, e grãos tostados,"}, {"numero": 29, "texto": "Mel, manteiga, ovelhas, e queijos de vacas, para que comessem; porque disseram: Aquele povo está faminto, e cansado, e terá sede no deserto."}]'::jsonb, 'Almeida Livre'),
  ('2Sm', 17, 'en', '[{"numero": 1, "texto": "Moreover Ahithophel said unto Absalom, Let me now choose out twelve thousand men, and I will arise and pursue after David this night:"}, {"numero": 2, "texto": "And I will come upon him while he is weary and weak handed, and will make him afraid: and all the people that are with him shall flee; and I will smite the king only:"}, {"numero": 3, "texto": "And I will bring back all the people unto thee: the man whom thou seekest is as if all returned: so all the people shall be in peace."}, {"numero": 4, "texto": "And the saying pleased Absalom well, and all the elders of Israel."}, {"numero": 5, "texto": "Then said Absalom, Call now Hushai the Archite also, and let us hear likewise what he saith."}, {"numero": 6, "texto": "And when Hushai was come to Absalom, Absalom spake unto him, saying, Ahithophel hath spoken after this manner: shall we do after his saying? if not; speak thou."}, {"numero": 7, "texto": "And Hushai said unto Absalom, The counsel that Ahithophel hath given is not good at this time."}, {"numero": 8, "texto": "For, said Hushai, thou knowest thy father and his men, that they be mighty men, and they be chafed in their minds, as a bear robbed of her whelps in the field: and thy father is a man of war, and will not lodge with the people."}, {"numero": 9, "texto": "Behold, he is hid now in some pit, or in some other place: and it will come to pass, when some of them be overthrown at the first, that whosoever heareth it will say, There is a slaughter among the people that follow Absalom."}, {"numero": 10, "texto": "And he also that is valiant, whose heart is as the heart of a lion, shall utterly melt: for all Israel knoweth that thy father is a mighty man, and they which be with him are valiant men."}, {"numero": 11, "texto": "Therefore I counsel that all Israel be generally gathered unto thee, from Dan even to Beersheba, as the sand that is by the sea for multitude; and that thou go to battle in thine own person."}, {"numero": 12, "texto": "So shall we come upon him in some place where he shall be found, and we will light upon him as the dew falleth on the ground: and of him and of all the men that are with him there shall not be left so much as one."}, {"numero": 13, "texto": "Moreover, if he be gotten into a city, then shall all Israel bring ropes to that city, and we will draw it into the river, until there be not one small stone found there."}, {"numero": 14, "texto": "And Absalom and all the men of Israel said, The counsel of Hushai the Archite is better than the counsel of Ahithophel. For the Lord had appointed to defeat the good counsel of Ahithophel, to the intent that the Lord might bring evil upon Absalom."}, {"numero": 15, "texto": "Then said Hushai unto Zadok and to Abiathar the priests, Thus and thus did Ahithophel counsel Absalom and the elders of Israel; and thus and thus have I counselled."}, {"numero": 16, "texto": "Now therefore send quickly, and tell David, saying, Lodge not this night in the plains of the wilderness, but speedily pass over; lest the king be swallowed up, and all the people that are with him."}, {"numero": 17, "texto": "Now Jonathan and Ahimaaz stayed by Enrogel; for they might not be seen to come into the city: and a wench went and told them; and they went and told king David."}, {"numero": 18, "texto": "Nevertheless a lad saw them, and told Absalom: but they went both of them away quickly, and came to a man''s house in Bahurim, which had a well in his court; whither they went down."}, {"numero": 19, "texto": "And the woman took and spread a covering over the well''s mouth, and spread ground corn thereon; and the thing was not known."}, {"numero": 20, "texto": "And when Absalom''s servants came to the woman to the house, they said, Where is Ahimaaz and Jonathan? And the woman said unto them, They be gone over the brook of water. And when they had sought and could not find them, they returned to Jerusalem."}, {"numero": 21, "texto": "And it came to pass, after they were departed, that they came up out of the well, and went and told king David, and said unto David, Arise, and pass quickly over the water: for thus hath Ahithophel counselled against you."}, {"numero": 22, "texto": "Then David arose, and all the people that were with him, and they passed over Jordan: by the morning light there lacked not one of them that was not gone over Jordan."}, {"numero": 23, "texto": "And when Ahithophel saw that his counsel was not followed, he saddled his ass, and arose, and gat him home to his house, to his city, and put his household in order, and hanged himself, and died, and was buried in the sepulchre of his father."}, {"numero": 24, "texto": "Then David came to Mahanaim. And Absalom passed over Jordan, he and all the men of Israel with him."}, {"numero": 25, "texto": "And Absalom made Amasa captain of the host instead of Joab: which Amasa was a man''s son, whose name was Ithra an Israelite, that went in to Abigail the daughter of Nahash, sister to Zeruiah Joab''s mother."}, {"numero": 26, "texto": "So Israel and Absalom pitched in the land of Gilead."}, {"numero": 27, "texto": "And it came to pass, when David was come to Mahanaim, that Shobi the son of Nahash of Rabbah of the children of Ammon, and Machir the son of Ammiel of Lodebar, and Barzillai the Gileadite of Rogelim,"}, {"numero": 28, "texto": "Brought beds, and basons, and earthen vessels, and wheat, and barley, and flour, and parched corn, and beans, and lentiles, and parched pulse,"}, {"numero": 29, "texto": "And honey, and butter, and sheep, and cheese of kine, for David, and for the people that were with him, to eat: for they said, The people is hungry, and weary, and thirsty, in the wilderness."}]'::jsonb, 'King James Version'),
  ('2Sm', 17, 'fr', '[{"numero": 1, "texto": "Achitophel dit à Absalom: Laisse-moi choisir douze mille hommes! Je me lèverai, et je poursuivrai David cette nuit même."}, {"numero": 2, "texto": "Je le surprendrai pendant qu''''il est fatigué et que ses mains sont affaiblies, je l''''épouvanterai, et tout le peuple qui est avec lui s''''enfuira. Je frapperai le roi seul,"}, {"numero": 3, "texto": "et je ramènerai à toi tout le peuple; la mort de l''''homme à qui tu en veux assurera le retour de tous, et tout le peuple sera en paix."}, {"numero": 4, "texto": "Cette parole plut à Absalom et à tous les anciens d''''Israël."}, {"numero": 5, "texto": "Cependant Absalom dit: Appelez encore Huschaï, l''''Arkien, et que nous entendions aussi ce qu''''il dira."}, {"numero": 6, "texto": "Huschaï vint auprès d''''Absalom, et Absalom lui dit: Voici comment a parlé Achitophel: devons-nous faire ce qu''''il a dit, ou non? Parle, toi!"}, {"numero": 7, "texto": "Huschaï répondit à Absalom: Pour cette fois le conseil qu''''a donné Achitophel n''''est pas bon."}, {"numero": 8, "texto": "Et Huschaï dit: Tu connais la bravoure de ton père et de ses gens, ils sont furieux comme le serait dans les champs une ourse à qui l''''on aurait enlevé ses petits. Ton père est un homme de guerre, et il ne passera pas la nuit avec le peuple;"}, {"numero": 9, "texto": "voici maintenant, il est caché dans quelque fosse ou dans quelque autre lieu. Et si, dès le commencement, il en est qui tombent sous leurs coups, on ne tardera pas à l''''apprendre et l''''on dira: Il y a une défaite parmi le peuple qui suit Absalom!"}, {"numero": 10, "texto": "Alors le plus vaillant, eût-il un coeur de lion, sera saisi d''''épouvante; car tout Israël sait que ton père est un héros et qu''''il a des braves avec lui."}, {"numero": 11, "texto": "Je conseille donc que tout Israël se rassemble auprès de toi, depuis Dan jusqu''''à Beer-Schéba, multitude pareille au sable qui est sur le bord de la mer. Tu marcheras en personne au combat."}, {"numero": 12, "texto": "Nous arriverons à lui en quelque lieu que nous le trouvions, et nous tomberons sur lui comme la rosée tombe sur le sol; et pas un n''''échappera, ni lui ni aucun des hommes qui sont avec lui."}, {"numero": 13, "texto": "S''''il se retire dans une ville, tout Israël portera des cordes vers cette ville, et nous la traînerons au torrent, jusqu''''à ce qu''''on n''''en trouve plus une pierre."}, {"numero": 14, "texto": "Absalom et tous les gens d''''Israël dirent: Le conseil de Huschaï, l''''Arkien, vaut mieux que le conseil d''''Achitophel. Or l''''Eternel avait résolu d''''anéantir le bon conseil d''''Achitophel, afin d''''amener le malheur sur Absalom."}, {"numero": 15, "texto": "Huschaï dit aux sacrificateurs Tsadok et Abiathar: Achitophel a donné tel et tel conseil à Absalom et aux anciens d''''Israël; et moi, j''''ai conseillé telle et telle chose."}, {"numero": 16, "texto": "Maintenant, envoyez tout de suite informer David et faites-lui dire: Ne passe point la nuit dans les plaines du désert, mais va plus loin, de peur que le roi et tout le peuple qui est avec lui ne soient exposés à périr."}, {"numero": 17, "texto": "Jonathan et Achimaats se tenaient à En-Roguel. Une servante vint leur dire d''''aller informer le roi David; car ils n''''osaient pas se montrer et entrer dans la ville."}, {"numero": 18, "texto": "Un jeune homme les aperçut, et le rapporta à Absalom. Mais ils partirent tous deux en hâte, et ils arrivèrent à Bachurim à la maison d''''un homme qui avait un puits dans sa cour, et ils y descendirent."}, {"numero": 19, "texto": "La femme prit une couverture qu''''elle étendit sur l''''ouverture du puits, et elle y répandit du grain pilé pour qu''''on ne se doutât de rien."}, {"numero": 20, "texto": "Les serviteurs d''''Absalom entrèrent dans la maison auprès de cette femme, et dirent: Où sont Achimaats et Jonathan? La femme leur répondit: Ils ont passé le ruisseau. Ils cherchèrent, et ne les trouvant pas, ils retournèrent à Jérusalem."}, {"numero": 21, "texto": "Après leur départ, Achimaats et Jonathan remontèrent du puits et allèrent informer le roi David. Ils dirent à David: Levez-vous et hâtez-vous de passer l''''eau, car Achitophel a conseillé contre vous telle chose."}, {"numero": 22, "texto": "David et tout le peuple qui était avec lui se levèrent et ils passèrent le Jourdain; à la lumière du matin, il n''''y en avait pas un qui fût resté à l''''écart, pas un qui n''''eût passé le Jourdain."}, {"numero": 23, "texto": "Achitophel, voyant que son conseil n''''était pas suivi, sella son âne et partit pour s''''en aller chez lui dans sa ville. Il donna ses ordres à sa maison, et il s''''étrangla. C''''est ainsi qu''''il mourut, et on l''''enterra dans le sépulcre de son père."}, {"numero": 24, "texto": "David arriva à Mahanaïm. Et Absalom passa le Jourdain, lui et tous les hommes d''''Israël avec lui."}, {"numero": 25, "texto": "Absalom mit Amasa à la tête de l''''armée, en remplacement de Joab; Amasa était fils d''''un homme appelé Jithra, l''''Israélite, qui était allé vers Abigal, fille de Nachasch et soeur de Tseruja, mère de Joab."}, {"numero": 26, "texto": "Israël et Absalom campèrent dans le pays de Galaad."}, {"numero": 27, "texto": "Lorsque David fut arrivé à Mahanaïm, Schobi, fils de Nachasch, de Rabba des fils d''''Ammon, Makir, fils d''''Ammiel, de Lodebar, et Barzillaï, le Galaadite, de Roguelim,"}, {"numero": 28, "texto": "apportèrent des lits, des bassins, des vases de terre, du froment, de l''''orge, de la farine, du grain rôti, des fèves, des lentilles, des pois rôtis,"}, {"numero": 29, "texto": "du miel, de la crème, des brebis, et des fromages de vache. Ils apportèrent ces choses à David et au peuple qui était avec lui, afin qu''''ils mangeassent; car ils disaient: Ce peuple a dû souffrir de la faim, de la fatigue et de la soif, dans le désert."}]'::jsonb, 'Louis Segond 1910'),
  ('2Sm', 17, 'es', '[{"numero": 1, "texto": "ENTONCES Achitophel dijo á Absalom: Yo escogeré ahora doce mil hombres, y me levantaré, y seguiré á David esta noche;"}, {"numero": 2, "texto": "Y daré sobre él cuando él estará cansado y flaco de manos: lo atemorizaré, y todo el pueblo que está con él huirá, y heriré al rey solo."}, {"numero": 3, "texto": "Así tornaré á todo el pueblo á ti: y cuando ellos hubieren vuelto, (pues aquel hombre es el que tú quieres) todo el pueblo estará en paz."}, {"numero": 4, "texto": "Esta razón pareció bien á Absalom y á todos los ancianos de Israel."}, {"numero": 5, "texto": "Y dijo Absalom: Llama también ahora á Husai Arachîta, para que asimismo oigamos lo que él dirá."}, {"numero": 6, "texto": "Y como Husai vino á Absalom, hablóle Absalom, diciendo: Así ha dicho Achitophel; ¿seguiremos su consejo, ó no? Di tú."}, {"numero": 7, "texto": "Entonces Husai dijo á Absalom: El consejo que ha dado esta vez Achitophel no es bueno."}, {"numero": 8, "texto": "Y añadió Husai: Tú sabes que tu padre y los suyos son hombres valientes, y que están con amargura de ánimo, como la osa en el campo cuando le han quitado los hijos. Además, tu padre es hombre de guerra, y no tendrá la noche con el pueblo."}, {"numero": 9, "texto": "He aquí él estará ahora escondido en alguna cueva, ó en otro lugar: y si al principio cayeren algunos de los tuyos, oirálo quien lo oyere, y dirá: El pueblo que sigue á Absalom ha sido derrotado."}, {"numero": 10, "texto": "Así aun el hombre valiente, cuyo corazón sea como corazón de león, sin duda desmayará: porque todo Israel sabe que tu padre es hombre valiente, y que los que están con él son esforzados."}, {"numero": 11, "texto": "Aconsejo pues que todo Israel se junte á ti, desde Dan hasta Beer-seba, en multitud como la arena que está á la orilla de la mar, y que tú en persona vayas á la batalla."}, {"numero": 12, "texto": "Entonces le acometeremos en cualquier lugar que pudiere hallarse, y daremos sobre él como cuando el rocío cae sobre la tierra, y ni uno dejaremos de él, y de todos los que con él están."}, {"numero": 13, "texto": "Y si se recogiere en alguna ciudad, todos los de Israel traerán sogas á aquella ciudad, y la arrastraremos hasta el arroyo, que nunca más parezca piedra de ella."}, {"numero": 14, "texto": "Entonces Absalom y todos los de Israel dijeron: El consejo de Husai Arachîta es mejor que el consejo de Achitophel. Porque había Jehová ordenado que el acertado consejo de Achitophel se frustrara, para que Jehová hiciese venir el mal sobre Absalom."}, {"numero": 15, "texto": "Dijo luego Husai á Sadoc y á Abiathar sacerdotes: Así y así aconsejó Achitophel á Absalom y á los ancianos de Israel: y de esta manera aconsejé yo."}, {"numero": 16, "texto": "Por tanto enviad inmediatamente, y dad aviso á David, diciendo: No quedes esta noche en los campos del desierto, sino pasa luego el Jordán, porque el rey no sea consumido, y todo el pueblo que con él está."}, {"numero": 17, "texto": "Y Jonathán y Ahimaas estaban junto á la fuente de Rogel, porque no podían ellos mostrarse viniendo á la ciudad; fué por tanto una criada, y dióles el aviso: y ellos fueron, y noticiáronlo al rey David."}, {"numero": 18, "texto": "Empero fueron vistos por un mozo, el cual dió cuenta á Absalom: sin embargo los dos se dieron priesa á caminar, y llegaron á casa de un hombre en Bahurim, que tenía un pozo en su patio, dentro del cual se metieron."}, {"numero": 19, "texto": "Y tomando la mujer de la casa una manta, extendióla sobre la boca del pozo, y tendió sobre ella el grano trillado; y no se penetró el negocio."}, {"numero": 20, "texto": "Llegando luego los criados de Absalom á la casa á la mujer, dijéronle: ¿Dónde están Ahimaas y Jonathán? Y la mujer les respondió: Ya han pasado el vado de las aguas. Y como ellos los buscaron y no los hallaron, volviéronse á Jerusalem."}, {"numero": 21, "texto": "Y después que ellos se hubieron ido, estotros salieron del pozo, y fuéronse, y dieron aviso al rey David; y dijéronle: Levantaos y daos priesa á pasar las aguas, porque Achitophel ha dado tal consejo contra vosotros."}, {"numero": 22, "texto": "Entonces David se levantó, y todo el pueblo que con él estaba, y pasaron el Jordán antes que amaneciese; ni siquiera faltó uno que no pasase el Jordán."}, {"numero": 23, "texto": "Y Achitophel, viendo que no se había puesto por obra su consejo, enalbardó su asno, y levantóse, y fuése á su casa en su ciudad; y después de disponer acerca de su casa, ahorcóse y murió, y fué sepultado en el sepulcro de su padre."}, {"numero": 24, "texto": "Y David llegó á Mahanaim, y Absalom pasó el Jordán con toda la gente de Israel."}, {"numero": 25, "texto": "Y Absalom constituyó á Amasa sobre el ejército en lugar de Joab, el cual Amasa fué hijo de un varón de Israel llamado Itra, el cual había entrado á Abigail hija de Naas, hermana de Sarvia, madre de Joab."}, {"numero": 26, "texto": "Y asentó campo Israel con Absalom en tierra de Galaad."}, {"numero": 27, "texto": "Y luego que David llegó á Mahanaim, Sobi hijo de Naas de Rabba de los hijos de Ammon, y Machîr hijo de Ammiel de Lodebar, y Barzillai Galaadita de Rogelim,"}, {"numero": 28, "texto": "Trajeron á David y al pueblo que estaba con él, camas, y tazas, y vasijas de barro, y trigo, y cebada, y harina, y grano tostado, habas, lentejas, y garbanzos tostados,"}, {"numero": 29, "texto": "Miel, manteca, ovejas, y quesos de vacas, para que comiesen; porque dijeron: Aquel pueblo está hambriento, y cansado, y tendrá sed en el desierto."}]'::jsonb, 'Reina-Valera 1909'),
  ('2Sm', 18, 'pt', '[{"numero": 1, "texto": "Davi, pois, revistou o povo que tinha consigo, e pôs sobre eles comandantes de mil e comandantes de cem."}, {"numero": 2, "texto": "E enviou a terça parte do povo ao mando de Joabe, e outra terça parte ao mando de Abisai, filho de Zeruia, irmão de Joabe, e a outra terceira parte ao mando de Itai geteu. E disse o rei ao povo: Eu também sairei convosco."}, {"numero": 3, "texto": "Mas o povo disse: Não sairás; porque se nós fugirmos, não farão caso de nós; e ainda que a metade de nós morra, não farão caso de nós: mas tu agora vales tanto quanto dez mil de nós. Será pois melhor que da cidade tu nos ajudes."}, {"numero": 4, "texto": "Então o rei lhes disse: Eu farei o que bem vos parecer. E pôs-se o rei à entrada da porta, enquanto saía todo aquele povo de cento em cento e de mil em mil."}, {"numero": 5, "texto": "E o rei mandou a Joabe e a Abisai e a Itai, dizendo: Tratai benignamente por causa de mim ao jovem Absalão. E todo aquele povo ouviu quando deu o rei ordem acerca de Absalão a todos os capitães."}, {"numero": 6, "texto": "Saiu, pois, o povo ao acampamento contra Israel, e houve a batalha no bosque de Efraim;"}, {"numero": 7, "texto": "E ali caiu o povo de Israel diante dos servos de Davi, e fez-se uma grande matança de vinte mil homens."}, {"numero": 8, "texto": "E espalhando-se ali o exército pela face de toda a terra, foram mais os que o bosque consumiu dos do povo, que os que a espada consumiu naquele dia."}, {"numero": 9, "texto": "E encontrou-se Absalão com os servos de Davi: e ia Absalão sobre um mulo, e o mulo se entrou debaixo de um espesso e grande carvalho, e prendeu-lhe a cabeça ao carvalho, e ficou entre o céu e a terra; pois o mulo em que ia passou adiante."}, {"numero": 10, "texto": "E vendo-o um, avisou a Joabe, dizendo: Eis que vi a Absalão pendurado em um carvalho."}, {"numero": 11, "texto": "E Joabe respondeu ao homem que lhe dava a nova: E vendo-o tu, por que não lhe feriste logo ali lançando-lhe à terra? E sobre mim, que te haveria dado dez siclos de prata, e um cinto."}, {"numero": 12, "texto": "E o homem disse a Joabe: Ainda que me importasse em minhas mãos mil siclos de prata, não estenderia eu minha mão contra o filho do rei; porque nós o ouvimos quando o rei te mandou a ti e a Abisai e a Itai, dizendo: Olhai que ninguém toque no jovem Absalão."}, {"numero": 13, "texto": "Por outra parte, haveria eu feito traição contra minha vida (pois que ao rei nada se lhe esconde), e tu mesmo estarias contra mim."}, {"numero": 14, "texto": "E respondeu Joabe: Não perderei tempo contigo. E tomando três dardos em suas mãos, fincou-os no coração de Absalão, que ainda estava vivo em meio do carvalho."}, {"numero": 15, "texto": "Cercando-o logo dez rapazes escudeiros de Joabe, feriram a Absalão, e acabaram-lhe."}, {"numero": 16, "texto": "Então Joabe tocou a trombeta, e o povo deixou de seguir a Israel, porque Joabe deteve ao povo."}, {"numero": 17, "texto": "Tomando depois a Absalão, lançaram-lhe em um grande fosso no bosque, e levantaram sobre ele um muito grande amontoado de pedras; e todo Israel fugiu, cada um a suas moradas."}, {"numero": 18, "texto": "E havia Absalão em sua vida tomado e levantado-se uma coluna, a qual está no vale do rei; porque havia dito: Eu não tenho filho que conserve a memória de meu nome. E chamou aquela coluna de seu nome: e assim se chamou o Lugar de Absalão, até hoje."}, {"numero": 19, "texto": "Então Aimaás filho de Zadoque disse: Correrei agora, e darei as novas ao rei de como o SENHOR defendeu sua causa da mão de seus inimigos?"}, {"numero": 20, "texto": "E respondeu Joabe: Hoje não levarás as novas: as levarás outro dia: não darás hoje a nova, porque o filho do rei está morto."}, {"numero": 21, "texto": "E Joabe disse a um cuxita: Vai tu, e dize ao rei o que viste. E o cuxita fez reverência a Joabe, e correu."}, {"numero": 22, "texto": "Então Aimaás filho de Zadoque voltou a dizer a Joabe: Seja o que for, eu correrei agora atrás do cuxita. E Joabe disse: Filho meu, para que hás tu de escorrer, pois que não acharás prêmio pelas novas?"}, {"numero": 23, "texto": "Mas ele respondeu: Seja o que for, eu correrei. Então lhe disse: Corre. Correu, pois, Aimaás pelo caminho da planície, e passou diante do cuxita."}, {"numero": 24, "texto": "Estava Davi naquele tempo sentado entre as duas portas; e o atalaia havia ido ao terraço de sobre a porta no muro, e levantando seus olhos, olhou, e viu a um que corria sozinho."}, {"numero": 25, "texto": "O vigilante deu logo vozes, e o fez saber ao rei. E o rei disse: Se está sozinho, boas novas traze. Em tanto que ele vinha aproximando-se,"}, {"numero": 26, "texto": "Viu o vigilante outro que corria; e deu vozes o vigilante ao porteiro, dizendo: Eis que outro homem que corre sozinho. E o rei disse: Este também é mensageiro."}, {"numero": 27, "texto": "E o vigilante voltou a dizer: Parece-me o correr do primeiro como o correr de Aimaás filho de Zadoque. E respondeu o rei: Esse é homem de bem, e vem com boa nova."}, {"numero": 28, "texto": "Então Aimaás disse em alta voz ao rei: Paz. E inclinou-se à terra diante do rei, e disse: Bendito seja o SENHOR Deus teu, que entregou aos homens que haviam levantado suas mãos contra meu senhor o rei."}, {"numero": 29, "texto": "E o rei disse: O jovem Absalão tem paz? E Aimaás respondeu: Vi eu um grande alvoroço quando enviou Joabe ao servo do rei e a mim teu servo; mas não sei que era."}, {"numero": 30, "texto": "E o rei disse: Passa, e põe-te ali. E ele passou, e parou-se."}, {"numero": 31, "texto": "E logo veio o cuxita, e disse: Receba notícia, meu senhor o rei, que hoje o SENHOR defendeu tua causa da mão de todos os que se haviam levantado contra ti."}, {"numero": 32, "texto": "O rei então disse ao cuxita: O jovem Absalão tem paz? E o cuxita respondeu: Sejam como aquele jovem os inimigos de meu senhor o rei, e todos os que se levantam contra ti para mal."}, {"numero": 33, "texto": "Então o rei se perturbou, e subiu-se à sala da porta, e chorou; e indo, dizia assim: Filho meu Absalão, filho meu, filho meu Absalão! Quem me dera que morresse eu em lugar de ti, Absalão, filho meu, filho meu!"}]'::jsonb, 'Almeida Livre'),
  ('2Sm', 18, 'en', '[{"numero": 1, "texto": "And David numbered the people that were with him, and set captains of thousands, and captains of hundreds over them."}, {"numero": 2, "texto": "And David sent forth a third part of the people under the hand of Joab, and a third part under the hand of Abishai the son of Zeruiah, Joab''s brother, and a third part under the hand of Ittai the Gittite. And the king said unto the people, I will surely go forth with you myself also."}, {"numero": 3, "texto": "But the people answered, Thou shalt not go forth: for if we flee away, they will not care for us; neither if half of us die, will they care for us: but now thou art worth ten thousand of us: therefore now it is better that thou succour us out of the city."}, {"numero": 4, "texto": "And the king said unto them, What seemeth you best I will do. And the king stood by the gate side, and all the people came out by hundreds and by thousands."}, {"numero": 5, "texto": "And the king commanded Joab and Abishai and Ittai, saying, Deal gently for my sake with the young man, even with Absalom. And all the people heard when the king gave all the captains charge concerning Absalom."}, {"numero": 6, "texto": "So the people went out into the field against Israel: and the battle was in the wood of Ephraim;"}, {"numero": 7, "texto": "Where the people of Israel were slain before the servants of David, and there was there a great slaughter that day of twenty thousand men."}, {"numero": 8, "texto": "For the battle was there scattered over the face of all the country: and the wood devoured more people that day than the sword devoured."}, {"numero": 9, "texto": "And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away."}, {"numero": 10, "texto": "And a certain man saw it, and told Joab, and said, Behold, I saw Absalom hanged in an oak."}, {"numero": 11, "texto": "And Joab said unto the man that told him, And, behold, thou sawest him, and why didst thou not smite him there to the ground? and I would have given thee ten shekels of silver, and a girdle."}, {"numero": 12, "texto": "And the man said unto Joab, Though I should receive a thousand shekels of silver in mine hand, yet would I not put forth mine hand against the king''s son: for in our hearing the king charged thee and Abishai and Ittai, saying, Beware that none touch the young man Absalom."}, {"numero": 13, "texto": "Otherwise I should have wrought falsehood against mine own life: for there is no matter hid from the king, and thou thyself wouldest have set thyself against me."}, {"numero": 14, "texto": "Then said Joab, I may not tarry thus with thee. And he took three darts in his hand, and thrust them through the heart of Absalom, while he was yet alive in the midst of the oak."}, {"numero": 15, "texto": "And ten young men that bare Joab''s armour compassed about and smote Absalom, and slew him."}, {"numero": 16, "texto": "And Joab blew the trumpet, and the people returned from pursuing after Israel: for Joab held back the people."}, {"numero": 17, "texto": "And they took Absalom, and cast him into a great pit in the wood, and laid a very great heap of stones upon him: and all Israel fled every one to his tent."}, {"numero": 18, "texto": "Now Absalom in his lifetime had taken and reared up for himself a pillar, which is in the king''s dale: for he said, I have no son to keep my name in remembrance: and he called the pillar after his own name: and it is called unto this day, Absalom''s place."}, {"numero": 19, "texto": "Then said Ahimaaz the son of Zadok, Let me now run, and bear the king tidings, how that the Lord hath avenged him of his enemies."}, {"numero": 20, "texto": "And Joab said unto him, Thou shalt not bear tidings this day, but thou shalt bear tidings another day: but this day thou shalt bear no tidings, because the king''s son is dead."}, {"numero": 21, "texto": "Then said Joab to Cushi, Go tell the king what thou hast seen. And Cushi bowed himself unto Joab, and ran."}, {"numero": 22, "texto": "Then said Ahimaaz the son of Zadok yet again to Joab, But howsoever, let me, I pray thee, also run after Cushi. And Joab said, Wherefore wilt thou run, my son, seeing that thou hast no tidings ready?"}, {"numero": 23, "texto": "But howsoever, said he, let me run. And he said unto him, Run. Then Ahimaaz ran by the way of the plain, and overran Cushi."}, {"numero": 24, "texto": "And David sat between the two gates: and the watchman went up to the roof over the gate unto the wall, and lifted up his eyes, and looked, and behold a man running alone."}, {"numero": 25, "texto": "And the watchman cried, and told the king. And the king said, If he be alone, there is tidings in his mouth. And he came apace, and drew near."}, {"numero": 26, "texto": "And the watchman saw another man running: and the watchman called unto the porter, and said, Behold another man running alone. And the king said, He also bringeth tidings."}, {"numero": 27, "texto": "And the watchman said, Me thinketh the running of the foremost is like the running of Ahimaaz the son of Zadok. And the king said, He is a good man, and cometh with good tidings."}, {"numero": 28, "texto": "And Ahimaaz called, and said unto the king, All is well. And he fell down to the earth upon his face before the king, and said, Blessed be the Lord thy God, which hath delivered up the men that lifted up their hand against my lord the king."}, {"numero": 29, "texto": "And the king said, Is the young man Absalom safe? And Ahimaaz answered, When Joab sent the king''s servant, and me thy servant, I saw a great tumult, but I knew not what it was."}, {"numero": 30, "texto": "And the king said unto him, Turn aside, and stand here. And he turned aside, and stood still."}, {"numero": 31, "texto": "And, behold, Cushi came; and Cushi said, Tidings, my lord the king: for the Lord hath avenged thee this day of all them that rose up against thee."}, {"numero": 32, "texto": "And the king said unto Cushi, Is the young man Absalom safe? And Cushi answered, The enemies of my lord the king, and all that rise against thee to do thee hurt, be as that young man is."}, {"numero": 33, "texto": "And the king was much moved, and went up to the chamber over the gate, and wept: and as he went, thus he said, O my son Absalom, my son, my son Absalom! would God I had died for thee, O Absalom, my son, my son!"}]'::jsonb, 'King James Version'),
  ('2Sm', 18, 'fr', '[{"numero": 1, "texto": "David passa en revue le peuple qui était avec lui, et il établit sur eux des chefs de milliers et des chefs de centaines."}, {"numero": 2, "texto": "Il plaça le tiers du peuple sous le commandement de Joab, le tiers sous celui d''''Abischaï, fils de Tseruja, frère de Joab, et le tiers sous celui d''''Ittaï, de Gath. Et le roi dit au peuple: Moi aussi, je veux sortir avec vous."}, {"numero": 3, "texto": "Mais le peuple dit: Tu ne sortiras point! Car si nous prenons la fuite, ce n''''est pas sur nous que l''''attention se portera; et quand la moitié d''''entre nous succomberait, on n''''y ferait pas attention; mais toi, tu es comme dix mille de nous, et maintenant il vaut mieux que de la ville tu puisses venir à notre secours."}, {"numero": 4, "texto": "Le roi leur répondit: Je ferai ce qui vous paraît bon. Et le roi se tint à côté de la porte, pendant que tout le peuple sortait par centaines et par milliers."}, {"numero": 5, "texto": "Le roi donna cet ordre à Joab, à Abischaï et à Ittaï: Pour l''''amour de moi, doucement avec le jeune Absalom! Et tout le peuple entendit l''''ordre du roi à tous les chefs au sujet d''''Absalom."}, {"numero": 6, "texto": "Le peuple sortit dans les champs à la rencontre d''''Israël, et la bataille eut lieu dans la forêt d''''Ephraïm."}, {"numero": 7, "texto": "Là, le peuple d''''Israël fut battu par les serviteurs de David, et il y eut en ce jour une grande défaite de vingt mille hommes."}, {"numero": 8, "texto": "Le combat s''''étendit sur toute la contrée, et la forêt dévora plus de peuple ce jour-là que l''''épée n''''en dévora."}, {"numero": 9, "texto": "Absalom se trouva en présence des gens de David. Il était monté sur un mulet. Le mulet pénétra sous les branches entrelacées d''''un grand térébinthe, et la tête d''''Absalom fut prise au térébinthe; il demeura suspendu entre le ciel et la terre, et le mulet qui était sous lui passa outre."}, {"numero": 10, "texto": "Un homme ayant vu cela vint dire à Joab: Voici, j''''ai vu Absalom suspendu à un térébinthe."}, {"numero": 11, "texto": "Et Joab dit à l''''homme qui lui apporta cette nouvelle: Tu l''''as vu! pourquoi donc ne l''''as-tu pas abattu sur place? Je t''''aurais donné dix sicles d''''argent et une ceinture."}, {"numero": 12, "texto": "Mais cet homme dit à Joab: Quand je pèserais dans ma main mille sicles d''''argent, je ne mettrais pas la main sur le fils du roi; car nous avons entendu cet ordre que le roi t''''a donné, à toi, à Abischaï et à Ittaï: Prenez garde chacun au jeune Absalom!"}, {"numero": 13, "texto": "Et si j''''eusse attenté perfidement à sa vie, rien n''''aurait été caché au roi, et tu aurais été toi-même contre moi."}, {"numero": 14, "texto": "Joab dit: Je ne m''''arrêterai pas auprès de toi! Et il prit en main trois javelots, et les enfonça dans le coeur d''''Absalom encore plein de vie au milieu du térébinthe."}, {"numero": 15, "texto": "Dix jeunes gens, qui portaient les armes de Joab, entourèrent Absalom, le frappèrent et le firent mourir."}, {"numero": 16, "texto": "Joab fit sonner de la trompette; et le peuple revint, cessant ainsi de poursuivre Israël, parce que Joab l''''en empêcha."}, {"numero": 17, "texto": "Ils prirent Absalom, le jetèrent dans une grande fosse au milieu de la forêt, et mirent sur lui un très grand monceau de pierres. Tout Israël s''''enfuit, chacun dans sa tente."}, {"numero": 18, "texto": "De son vivant, Absalom s''''était fait ériger un monument dans la vallée du roi; car il disait: Je n''''ai point de fils par qui le souvenir de mon nom puisse être conservé. Et il donna son propre nom au monument, qu''''on appelle encore aujourd''''hui monument d''''Absalom."}, {"numero": 19, "texto": "Achimaats, fils de Tsadok, dit: Laisse-moi courir, et porter au roi la bonne nouvelle que l''''Eternel lui a rendu justice en le délivrant de la main de ses ennemis."}, {"numero": 20, "texto": "Joab lui dit: Ce n''''est pas toi qui dois porter aujourd''''hui les nouvelles; tu les porteras un autre jour, mais non aujourd''''hui, puisque le fils du roi est mort."}, {"numero": 21, "texto": "Et Joab dit à Cuschi: Va, et annonce au roi ce que tu as vu. Cuschi se prosterna devant Joab, et courut."}, {"numero": 22, "texto": "Achimaats, fils de Tsadok, dit encore à Joab: Quoi qu''''il arrive, laisse-moi courir après Cuschi. Et Joab dit: Pourquoi veux-tu courir, mon fils? Ce n''''est pas un message qui te sera profitable."}, {"numero": 23, "texto": "Quoi qu''''il arrive, je veux courir, reprit Achimaats. Et Joab lui dit: Cours! Achimaats courut par le chemin de la plaine, et il devança Cuschi."}, {"numero": 24, "texto": "David était assis entre les deux portes. La sentinelle alla sur le toit de la porte vers la muraille; elle leva les yeux et regarda. Et voici, un homme courait tout seul."}, {"numero": 25, "texto": "La sentinelle cria, et avertit le roi. Le roi dit: S''''il est seul, il apporte des nouvelles. Et cet homme arrivait toujours plus près."}, {"numero": 26, "texto": "La sentinelle vit un autre homme qui courait; elle cria au portier: Voici un homme qui court tout seul. Le roi dit: Il apporte aussi des nouvelles."}, {"numero": 27, "texto": "La sentinelle dit: La manière de courir du premier me paraît celle d''''Achimaats, fils de Tsadok. Et le roi dit: C''''est un homme de bien, et il apporte de bonnes nouvelles."}, {"numero": 28, "texto": "Achimaats cria, et il dit au roi: Tout va bien! Il se prosterna devant le roi la face contre terre, et dit: Béni soit l''''Eternel, ton Dieu, qui a livré les hommes qui levaient la main contre le roi mon seigneur!"}, {"numero": 29, "texto": "Le roi dit: Le jeune Absalom est-il en bonne santé? Achimaats répondit: J''''ai aperçu un grand tumulte au moment où Joab envoya le serviteur du roi et moi ton serviteur; mais je ne sais ce que c''''était."}, {"numero": 30, "texto": "Et le roi dit: Mets-toi là de côté. Et Achimaats se tint de côté."}, {"numero": 31, "texto": "Aussitôt arriva Cuschi. Et il dit: Que le roi mon seigneur apprenne la bonne nouvelle! Aujourd''''hui l''''Eternel t''''a rendu justice en te délivrant de la main de tous ceux qui s''''élevaient contre toi."}, {"numero": 32, "texto": "Le roi dit à Cuschi: Le jeune homme Absalom est-il en bonne santé? Cuschi répondit: Qu''''ils soient comme ce jeune homme, les ennemis du roi mon seigneur et tous ceux qui s''''élèvent contre toi pour te faire du mal!"}, {"numero": 33, "texto": "Alors le roi, saisi d''''émotion, monta dans la chambre au-dessus de la porte et pleura. Il disait en marchant: Mon fils Absalom! mon fils, mon fils Absalom! Que ne suis-je mort à ta place! Absalom, mon fils, mon fils!"}]'::jsonb, 'Louis Segond 1910'),
  ('2Sm', 18, 'es', '[{"numero": 1, "texto": "DAVID pues revistó el pueblo que tenía consigo, y puso sobre ellos tribunos y centuriones."}, {"numero": 2, "texto": "Y consignó la tercera parte del pueblo al mando de Joab, y otra tercera al mando de Abisai, hijo de Sarvia, hermano de Joab, y la otra tercera parte al mando de Ittai Getheo. Y dijo el rey al pueblo: Yo también saldré con vosotros."}, {"numero": 3, "texto": "Mas el pueblo dijo: No saldrás; porque si nosotros huyéremos, no harán caso de nosotros; y aunque la mitad de nosotros muera, no harán caso de nosotros: mas tú ahora vales tanto como diez mil de nosotros. Será pues mejor que tú nos des ayuda desde la ciudad."}, {"numero": 4, "texto": "Entonces el rey les dijo: Yo haré lo que bien os pareciere. Y púsose el rey á la entrada de la puerta, mientras salía todo el pueblo de ciento en ciento y de mil en mil."}, {"numero": 5, "texto": "Y el rey mandó á Joab y á Abisai y á Ittai, diciendo: Tratad benignamente por amor de mí al mozo Absalom. Y todo el pueblo oyó cuando dió el rey orden acerca de Absalom á todos los capitanes."}, {"numero": 6, "texto": "Salió pues el pueblo al campo contra Israel, y dióse la batalla en el bosque de Ephraim;"}, {"numero": 7, "texto": "Y allí cayó el pueblo de Israel delante de los siervos de David, é hízose allí en aquel día una gran matanza de veinte mil hombres;"}, {"numero": 8, "texto": "Y derramándose allí el ejército por la haz de toda la tierra, fueron más los que consumió el bosque de los del pueblo, que los que consumió el cuchillo aquel día."}, {"numero": 9, "texto": "Y encontróse Absalom con los siervos de David: é iba Absalom sobre un mulo, y el mulo se entró debajo de un espeso y grande alcornoque, y asiósele la cabeza al alcornoque, y quedó entre el cielo y la tierra; pues el mulo en que iba pasó delante."}, {"numero": 10, "texto": "Y viéndolo uno, avisó á Joab, diciendo: He aquí que he visto á Absalom colgado de un alcornoque."}, {"numero": 11, "texto": "Y Joab respondió al hombre que le daba la nueva: Y viéndolo tú, ¿por qué no le heriste luego allí echándole á tierra? y sobre mí, que te hubiera dado diez siclos de plata, y un talabarte."}, {"numero": 12, "texto": "Y el hombre dijo á Joab: Aunque me importara en mis manos mil siclos de plata, no extendiera yo mi mano contra el hijo del rey; porque nosotros lo oímos cuando el rey te mandó á ti y á Abisai y á Ittai, diciendo: Mirad que ninguno toque en el joven Absalom."}, {"numero": 13, "texto": "Por otra parte, habría yo hecho traición contra mi vida (pues que al rey nada se le esconde), y tú mismo estarías en contra."}, {"numero": 14, "texto": "Y respondió Joab: No es razón que yo te ruegue. Y tomando tres dardos en sus manos, hincólos en el corazón de Absalom, que aun estaba vivo en medio del alcornoque."}, {"numero": 15, "texto": "Cercándolo luego diez mancebos escuderos de Joab, hirieron á Absalom, y acabáronle."}, {"numero": 16, "texto": "Entonces Joab tocó la corneta, y el pueblo se volvió de seguir á Israel, porque Joab detuvo al pueblo."}, {"numero": 17, "texto": "Tomando después á Absalom, echáronle en un gran hoyo en el bosque, y levantaron sobre él un muy grande montón de piedras; y todo Israel huyó, cada uno á sus estancias."}, {"numero": 18, "texto": "Y había Absalom en su vida tomado y levantádose una columna, la cual está en el valle del rey; porque había dicho: Yo no tengo hijo que conserve la memoria de mi nombre. Y llamó aquella columna de su nombre: y así se llamó el Lugar de Absalom, hasta hoy."}, {"numero": 19, "texto": "Entonces Ahimaas hijo de Sadoc dijo: ¿Correré ahora, y daré las nuevas al rey de como Jehová ha defendido su causa de la mano de sus enemigos?"}, {"numero": 20, "texto": "Y respondió Joab: Hoy no llevarás las nuevas: las llevarás otro día: no darás hoy la nueva, porque el hijo del rey es muerto."}, {"numero": 21, "texto": "Y Joab dijo á Cusi: Ve tú, y di al rey lo que has visto. Y Cusi hizo reverencia á Joab, y corrió."}, {"numero": 22, "texto": "Entonces Ahimaas hijo de Sadoc tornó á decir á Joab: Sea lo que fuere, yo correré ahora tras Cusi. Y Joab dijo: Hijo mío, ¿para qué has tú de correr, pues que no hallarás premio por las nuevas?"}, {"numero": 23, "texto": "Mas él respondió: Sea lo que fuere, yo correré. Entonces le dijo: Corre. Corrió pues Ahimaas por el camino de la llanura, y pasó delante de Cusi."}, {"numero": 24, "texto": "Estaba David á la sazón sentado entre las dos puertas; y el atalaya había ido al terrado de sobre la puerta en el muro, y alzando sus ojos, miró, y vió á uno que corría solo."}, {"numero": 25, "texto": "El atalaya dió luego voces, é hízolo saber al rey. Y el rey dijo: Si es solo, buenas nuevas trae. En tanto que él venía acercándose,"}, {"numero": 26, "texto": "Vió el atalaya otro que corría; y dió voces el atalaya al portero, diciendo: He aquí otro hombre que corre solo. Y el rey dijo: Éste también es mensajero."}, {"numero": 27, "texto": "Y el atalaya volvió á decir: Paréceme el correr del primero como el correr de Ahimaas hijo de Sadoc. Y respondió el rey: Ese es hombre de bien, y viene con buena nueva."}, {"numero": 28, "texto": "Entonces Ahimaas dijo en alta voz al rey: Paz. E inclinóse á tierra delante del rey, y dijo: Bendito sea Jehová Dios tuyo, que ha entregado á los hombres que habían levantado sus manos contra mi señor el rey."}, {"numero": 29, "texto": "Y el rey dijo: ¿El mozo Absalom tiene paz? Y Ahimaas respondió: Vi yo un grande alboroto cuando envió Joab al siervo del rey y á mí tu siervo; mas no sé qué era."}, {"numero": 30, "texto": "Y el rey dijo: Pasa, y ponte allí. Y él pasó, y paróse."}, {"numero": 31, "texto": "Y luego vino Cusi, y dijo: Reciba nueva mi señor el rey, que hoy Jehová ha defendido tu causa de la mano de todos los que se habían levantado contra ti."}, {"numero": 32, "texto": "El rey entonces dijo á Cusi: ¿El mozo Absalom tiene paz? Y Cusi respondió: Como aquel mozo sean los enemigos de mi señor el rey, y todos los que se levantan contra ti para mal."}, {"numero": 33, "texto": "Entonces el rey se turbó, y subióse á la sala de la puerta, y lloró; y yendo, decía así: ¡Hijo mío Absalom, hijo mío, hijo mío Absalom! ¡Quién me diera que muriera yo en lugar de ti, Absalom, hijo mío, hijo mío!"}]'::jsonb, 'Reina-Valera 1909'),
  ('2Tm', 3, 'pt', '[{"numero": 1, "texto": "Sabe porém isto, que nos últimos dias virão tempos difíceis."}, {"numero": 2, "texto": "Pois haverá alguns que serão egoístas, gananciosos, presunçosos, soberbos, blasfemos, desobedientes a pais e a mães, ingratos, profanos,"}, {"numero": 3, "texto": "sem afeto natural, irreconciliáveis, caluniadores, sem dominio próprio, cruéis, sem amor com os bons,"}, {"numero": 4, "texto": "traidores, precipitados, orgulhosos, que amam mais os prazeres que a Deus."}, {"numero": 5, "texto": "Eles têm uma aparência de devoção divina, mas negam o poder dela. Afasta-te desses também."}, {"numero": 6, "texto": "Pois dentre esses são os que entram pelas casas, e levam cativas as mulheres insensatas carregadas de pecados, levadas com vários maus desejos;"}, {"numero": 7, "texto": "que sempre estão aprendendo, e jamais conseguem chegar ao conhecimento da verdade."}, {"numero": 8, "texto": "E assim como Janes e Jambres se opuseram a Moisés, assim também esses se opõem a verdade; esses são corruptos de entendimento, e reprovados quanto à fé."}, {"numero": 9, "texto": "Eles, porém, não avançarão; pois a insensatez deles será evidente a todos, como também foi a daqueles."}, {"numero": 10, "texto": "Porém tu tens seguido a minha doutrina, conduta, intenção, fé, paciência, amor, perseverança,"}, {"numero": 11, "texto": "perseguições, aflições; as quais me aconteceram em Antioquia, em Icônio e em Listra; tais perseguições sofri, e o Senhor me livrou de todas."}, {"numero": 12, "texto": "E também todos os que querem viver devotamente em Cristo Jesus sofrerão perseguição."}, {"numero": 13, "texto": "Mas os que são maus e enganadores irão de mal a pior, enganando e sendo enganados."}, {"numero": 14, "texto": "Tu, porém, continua nas coisas que aprendeste e das quais foste convencido, pois sabes de quem as aprendeste."}, {"numero": 15, "texto": "e que desde tua infância conheceste as Sagradas Escrituras, que podem te fazer sábio para a salvação pela fé em Cristo Jesus."}, {"numero": 16, "texto": "Toda a Escritura [é] divinamente inspirada e proveitosa para ensinar, para mostrar erros, para corrigir, e para instruir na justiça;"}, {"numero": 17, "texto": "para que o homem de Deus seja completo, plenamente instruído para toda boa obra."}]'::jsonb, 'Almeida Livre'),
  ('2Tm', 3, 'en', '[{"numero": 1, "texto": "This know also, that in the last days perilous times shall come."}, {"numero": 2, "texto": "For men shall be lovers of their own selves, covetous, boasters, proud, blasphemers, disobedient to parents, unthankful, unholy,"}, {"numero": 3, "texto": "Without natural affection, trucebreakers, false accusers, incontinent, fierce, despisers of those that are good,"}, {"numero": 4, "texto": "Traitors, heady, highminded, lovers of pleasures more than lovers of God;"}, {"numero": 5, "texto": "Having a form of godliness, but denying the power thereof: from such turn away."}, {"numero": 6, "texto": "For of this sort are they which creep into houses, and lead captive silly women laden with sins, led away with divers lusts,"}, {"numero": 7, "texto": "Ever learning, and never able to come to the knowledge of the truth."}, {"numero": 8, "texto": "Now as Jannes and Jambres withstood Moses, so do these also resist the truth: men of corrupt minds, reprobate concerning the faith."}, {"numero": 9, "texto": "But they shall proceed no further: for their folly shall be manifest unto all men, as their''s also was."}, {"numero": 10, "texto": "But thou hast fully known my doctrine, manner of life, purpose, faith, longsuffering, charity, patience,"}, {"numero": 11, "texto": "Persecutions, afflictions, which came unto me at Antioch, at Iconium, at Lystra; what persecutions I endured: but out of them all the Lord delivered me."}, {"numero": 12, "texto": "Yea, and all that will live godly in Christ Jesus shall suffer persecution."}, {"numero": 13, "texto": "But evil men and seducers shall wax worse and worse, deceiving, and being deceived."}, {"numero": 14, "texto": "But continue thou in the things which thou hast learned and hast been assured of, knowing of whom thou hast learned them;"}, {"numero": 15, "texto": "And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus."}, {"numero": 16, "texto": "All scripture is given by inspiration of God, and is profitable for doctrine, for reproof, for correction, for instruction in righteousness:"}, {"numero": 17, "texto": "That the man of God may be perfect, thoroughly furnished unto all good works."}]'::jsonb, 'King James Version'),
  ('2Tm', 3, 'fr', '[{"numero": 1, "texto": "Sache que, dans les derniers jours, il y aura des temps difficiles."}, {"numero": 2, "texto": "Car les hommes seront égoïstes, amis de l''''argent, fanfarons, hautains, blasphémateurs, rebelles à leurs parents, ingrats, irréligieux,"}, {"numero": 3, "texto": "insensibles, déloyaux, calomniateurs, intempérants, cruels, ennemis des gens de bien,"}, {"numero": 4, "texto": "traîtres, emportés, enflés d''''orgueil, aimant le plaisir plus que Dieu,"}, {"numero": 5, "texto": "ayant l''''apparence de la piété, mais reniant ce qui en fait la force. Eloigne-toi de ces hommes-là."}, {"numero": 6, "texto": "Il en est parmi eux qui s''''introduisent dans les maisons, et qui captivent des femmes d''''un esprit faible et borné, chargées de péchés, agitées par des passions de toute espèce,"}, {"numero": 7, "texto": "apprenant toujours et ne pouvant jamais arriver à la connaissance de la vérité."}, {"numero": 8, "texto": "De même que Jannès et Jambrès s''''opposèrent à Moïse, de même ces hommes s''''opposent à la vérité, étant corrompus d''''entendement, réprouvés en ce qui concerne la foi."}, {"numero": 9, "texto": "Mais ils ne feront pas de plus grands progrès; car leur folie sera manifeste pour tous, comme le fut celle de ces deux hommes."}, {"numero": 10, "texto": "Pour toi, tu as suivi de près mon enseignement, ma conduite, mes résolutions, ma foi, ma douceur, ma charité, ma constance,"}, {"numero": 11, "texto": "mes persécutions, mes souffrances. A quelles souffrances n''''ai-je pas été exposé à Antioche, à Icone, à Lystre? Quelles persécutions n''''ai-je pas supportées? Et le Seigneur m''''a délivré de toutes."}, {"numero": 12, "texto": "Or, tous ceux qui veulent vivre pieusement en Jésus-Christ seront persécutés."}, {"numero": 13, "texto": "Mais les hommes méchants et imposteurs avanceront toujours plus dans le mal, égarant les autres et égarés eux-mêmes."}, {"numero": 14, "texto": "Toi, demeure dans les choses que tu as apprises, et reconnues certaines, sachant de qui tu les as apprises;"}, {"numero": 15, "texto": "dès ton enfance, tu connais les saintes lettres, qui peuvent te rendre sage à salut par la foi en Jésus-Christ."}, {"numero": 16, "texto": "Toute Ecriture est inspirée de Dieu, et utile pour enseigner, pour convaincre, pour corriger, pour instruire dans la justice,"}, {"numero": 17, "texto": "afin que l''''homme de Dieu soit accompli et propre à toute bonne oeuvre."}]'::jsonb, 'Louis Segond 1910'),
  ('2Tm', 3, 'es', '[{"numero": 1, "texto": "ESTO también sepas, que en los postreros días vendrán tiempos peligrosos:"}, {"numero": 2, "texto": "Que habrá hombres amadores de sí mismos, avaros, vanagloriosos, soberbios, detractores, desobedientes á los padres, ingratos, sin santidad,"}, {"numero": 3, "texto": "Sin afecto, desleales, calumniadores, destemplados, crueles, aborrecedores de lo bueno,"}, {"numero": 4, "texto": "Traidores, arrebatados, hinchados, amadores de los deleites más que de Dios;"}, {"numero": 5, "texto": "Teniendo apariencia de piedad, mas habiendo negado la eficacia de ella: y á éstos evita."}, {"numero": 6, "texto": "Porque de éstos son los que se entran por las casas, y llevan cautivas las mujercillas cargadas de pecados, llevadas de diversas concupiscencias;"}, {"numero": 7, "texto": "Que siempre aprenden, y nunca pueden acabar de llegar al conocimiento de la verdad."}, {"numero": 8, "texto": "Y de la manera que Jannes y Jambres resistieron á Moisés, así también éstos resisten á la verdad; hombres corruptos de entendimiento, réprobos acerca de la fe."}, {"numero": 9, "texto": "Mas no prevalecerán; porque su insensatez será manifiesta á todos, como también lo fué la de aquéllos."}, {"numero": 10, "texto": "Pero tú has comprendido mi doctrina, instrucción, intento, fe, largura de ánimo, caridad, paciencia,"}, {"numero": 11, "texto": "Persecuciones, aflicciones, cuales me sobrevinieron en Antioquía, en Iconio, en Listra, cuales persecuciones he sufrido; y de todas me ha librado el Señor."}, {"numero": 12, "texto": "Y también todos los que quieren vivir píamente en Cristo Jesús, padecerán persecución."}, {"numero": 13, "texto": "Mas los malos hombres y los engañadores, irán de mal en peor, engañando y siendo engañados."}, {"numero": 14, "texto": "Empero persiste tú en lo que has aprendido y te persuadiste, sabiendo de quién has aprendido;"}, {"numero": 15, "texto": "Y que desde la niñez has sabido las Sagradas Escrituras, las cuales te pueden hacer sabio para la salud por la fe que es en Cristo Jesús."}, {"numero": 16, "texto": "Toda Escritura es inspirada divinamente y útil para enseñar, para redargüir, para corregir, para instituir en justicia,"}, {"numero": 17, "texto": "Para que el hombre de Dios sea perfecto, enteramente instruído para toda buena obra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ag', 2, 'pt', '[{"numero": 1, "texto": "No sétimo mês, no vigésimo primeiro [dia] mês, veio a palavra do SENHOR por meio do profeta Ageu, dizendo:"}, {"numero": 2, "texto": "Fala agora a Zorobabel filho de Sealtiel, governador de Judá, e a Josué filho de Jeozadaque, sumo sacerdote, e ao resto do povo, dizendo:"}, {"numero": 3, "texto": "Quem restou dentre vós que tenha visto esta casa em sua primeira glória? E como a vedes agora? Não é esta como nada diante de vossos olhos?"}, {"numero": 4, "texto": "Agora, pois, esforça-te, Zorobabel, diz o SENHOR; esforça-te também Josué, filho de Jeozadaque, sumo sacerdote; e esforça-te, todo o povo da terra, diz o SENHOR, e trabalhai; porque eu estou convosco, diz o SENHOR dos exércitos."}, {"numero": 5, "texto": "Conforme o pacto que estabeleci convosco quando saístes do Egito, assim meu Espírito está em meio de vós; não temais."}, {"numero": 6, "texto": "Porque assim diz o SENHOR dos exércitos: Ainda uma vez, daqui a pouco, eu farei tremer os céus e a terra, o mar e a terra seca;"}, {"numero": 7, "texto": "E farei tremer a todas as nações, e virá as coisas preciosas de todas as nações; e encherei esta casa de glória, diz o SENHOR dos exércitos."}, {"numero": 8, "texto": "Minha é a prata, e meu é o ouro, diz o SENHOR dos exércitos."}, {"numero": 9, "texto": "A glória desta última casa será maior que a da primeira, diz o SENHOR dos exércitos; e neste lugar darei paz, diz o SENHOR dos exércitos."}, {"numero": 10, "texto": "Ao vigésimo quarto [dia] do nono mês, no segundo ano de Dario, veio a palavra do SENHOR por mão do profeta Ageu, dizendo:"}, {"numero": 11, "texto": "Assim diz o SENHOR dos exércitos: Pergunta agora aos sacerdotes acerca da lei, dizendo:"}, {"numero": 12, "texto": "Se alguém levar carnes santas na borda de sua veste, e com sua borda tocar o pão, a comida, o vinho, o azeite, ou qualquer [outra] comida, por acaso isso será santificado?E os sacerdotes responderam: Não."}, {"numero": 13, "texto": "E Ageu disse: Se um impuro por causa de um corpo morto tocar alguma destas coisas, ela será impura? E os sacerdotes responderam: Impura será."}, {"numero": 14, "texto": "Então Ageu respondeu: Assim é este povo, esta nação, diante de mim, diz o SENHOR; e assim é toda obra de suas mãos; e todo o que ali oferecem é impuro."}, {"numero": 15, "texto": "Agora pois, considerai desde este dia em diante, antes que se ponha pedra sobre pedra no templo do SENHOR,"}, {"numero": 16, "texto": "Antes que fossem estas coisas, vinham ao amontoado de grãos [buscar] vinte [medidas] , conseguiam[apenas] dez; vinham à prensa de uvas para tirar dali cinquenta [vasos] mas ali havia[somente] vinte."}, {"numero": 17, "texto": "Eu vos feri com ferrugem, mofo, e granizo em toda obra de vossas mãos; mas não vos [convertestes] a mim,diz o SENHOR."}, {"numero": 18, "texto": "Considerai, pois, isto, desde este dia em diante, desde o dia vigésimo quatro [dia] do nono mês, desde o dia em o fundamento do templo do SENHOR foi posto; considerai."}, {"numero": 19, "texto": "Ainda há semente no celeiro? A videira, a figueira, a romeira, e oliveira ainda não têm dado frutos; mas a partir de hoje eu [vos] abençoarei."}, {"numero": 20, "texto": "E a palavra do SENHOR veio pela segunda vez a Ageu, ao vigésimo quarto [dia] do mês, dizendo:"}, {"numero": 21, "texto": "Fala a Zorobabel, governador de Judá, dizendo: Eu farei tremer os céus e a terra;"}, {"numero": 22, "texto": "E transtornarei o trono dos reinos, e destruirei a força dos reinos das nações; e transtornarei as carruagens, e os que nelas se sentam; e os cavalos e os que neles montam cairão, cada um pela espada de seu irmão."}, {"numero": 23, "texto": "Naquele dia, diz o SENHOR dos exércitos, eu te tomarei, Zorobabel, filho de Sealtiel, servo meu, diz o SENHOR, e te porei como anel de selar; porque eu te escolhi, diz o SENHOR dos exércitos."}]'::jsonb, 'Almeida Livre'),
  ('Ag', 2, 'en', '[{"numero": 1, "texto": "In the seventh month, in the one and twentieth day of the month, came the word of the Lord by the prophet Haggai, saying,"}, {"numero": 2, "texto": "Speak now to Zerubbabel the son of Shealtiel, governor of Judah, and to Joshua the son of Josedech, the high priest, and to the residue of the people, saying,"}, {"numero": 3, "texto": "Who is left among you that saw this house in her first glory? and how do ye see it now? is it not in your eyes in comparison of it as nothing?"}, {"numero": 4, "texto": "Yet now be strong, O Zerubbabel, saith the Lord; and be strong, O Joshua, son of Josedech, the high priest; and be strong, all ye people of the land, saith the Lord, and work: for I am with you, saith the Lord of hosts:"}, {"numero": 5, "texto": "According to the word that I covenanted with you when ye came out of Egypt, so my spirit remaineth among you: fear ye not."}, {"numero": 6, "texto": "For thus saith the Lord of hosts; Yet once, it is a little while, and I will shake the heavens, and the earth, and the sea, and the dry land;"}, {"numero": 7, "texto": "And I will shake all nations, and the desire of all nations shall come: and I will fill this house with glory, saith the Lord of hosts."}, {"numero": 8, "texto": "The silver is mine, and the gold is mine, saith the Lord of hosts."}, {"numero": 9, "texto": "The glory of this latter house shall be greater than of the former, saith the Lord of hosts: and in this place will I give peace, saith the Lord of hosts."}, {"numero": 10, "texto": "In the four and twentieth day of the ninth month, in the second year of Darius, came the word of the Lord by Haggai the prophet, saying,"}, {"numero": 11, "texto": "Thus saith the Lord of hosts; Ask now the priests concerning the law, saying,"}, {"numero": 12, "texto": "If one bear holy flesh in the skirt of his garment, and with his skirt do touch bread, or pottage, or wine, or oil, or any meat, shall it be holy? And the priests answered and said, No."}, {"numero": 13, "texto": "Then said Haggai, If one that is unclean by a dead body touch any of these, shall it be unclean? And the priests answered and said, It shall be unclean."}, {"numero": 14, "texto": "Then answered Haggai, and said, So is this people, and so is this nation before me, saith the Lord; and so is every work of their hands; and that which they offer there is unclean."}, {"numero": 15, "texto": "And now, I pray you, consider from this day and upward, from before a stone was laid upon a stone in the temple of the Lord:"}, {"numero": 16, "texto": "Since those days were, when one came to an heap of twenty measures, there were but ten: when one came to the pressfat for to draw out fifty vessels out of the press, there were but twenty."}, {"numero": 17, "texto": "I smote you with blasting and with mildew and with hail in all the labours of your hands; yet ye turned not to me, saith the Lord."}, {"numero": 18, "texto": "Consider now from this day and upward, from the four and twentieth day of the ninth month, even from the day that the foundation of the Lord''s temple was laid, consider it."}, {"numero": 19, "texto": "Is the seed yet in the barn? yea, as yet the vine, and the fig tree, and the pomegranate, and the olive tree, hath not brought forth: from this day will I bless you."}, {"numero": 20, "texto": "And again the word of the Lord came unto Haggai in the four and twentieth day of the month, saying,"}, {"numero": 21, "texto": "Speak to Zerubbabel, governor of Judah, saying, I will shake the heavens and the earth;"}, {"numero": 22, "texto": "And I will overthrow the throne of kingdoms, and I will destroy the strength of the kingdoms of the heathen; and I will overthrow the chariots, and those that ride in them; and the horses and their riders shall come down, every one by the sword of his brother."}, {"numero": 23, "texto": "In that day, saith the Lord of hosts, will I take thee, O Zerubbabel, my servant, the son of Shealtiel, saith the Lord, and will make thee as a signet: for I have chosen thee, saith the Lord of hosts."}]'::jsonb, 'King James Version'),
  ('Ag', 2, 'fr', '[{"numero": 1, "texto": "Le vingt et unième jour du septième mois, la parole de l''''Eternel se révéla par Aggée, le prophète, en ces mots:"}, {"numero": 2, "texto": "Parle à Zorobabel, fils de Schealthiel, gouverneur de Juda, à Josué, fils de Jotsadak, le souverain sacrificateur, et au reste du peuple, et dis-leur:"}, {"numero": 3, "texto": "Quel est parmi vous le survivant Qui ait vu cette maison dans sa gloire première? Et comment la voyez-vous maintenant? Telle qu''''elle est, ne paraît-elle pas comme rien à vos yeux?"}, {"numero": 4, "texto": "Maintenant fortifie-toi, Zorobabel! dit l''''Eternel. Fortifie-toi, Josué, fils de Jotsadak, souverain sacrificateur! Fortifie-toi, peuple entier du pays! dit l''''Eternel. Et travaillez! Car je suis avec vous, Dit l''''Eternel des armées."}, {"numero": 5, "texto": "Je reste fidèle à l''''alliance que j''''ai faite avec vous Quand vous sortîtes de l''''Egypte, Et mon esprit est au milieu de vous; Ne craignez pas!"}, {"numero": 6, "texto": "Car ainsi parle l''''Eternel des armées: Encore un peu de temps, Et j''''ébranlerai les cieux et la terre, La mer et le sec;"}, {"numero": 7, "texto": "J''''ébranlerai toutes les nations; Les trésors de toutes les nations viendront, Et je remplirai de gloire cette maison, Dit l''''Eternel des armées."}, {"numero": 8, "texto": "L''''argent est à moi, et l''''or est à moi, Dit l''''Eternel des armées."}, {"numero": 9, "texto": "La gloire de cette dernière maison sera plus grande Que celle de la première, Dit l''''Eternel des armées; Et c''''est dans ce lieu que je donnerai la paix, Dit l''''Eternel des armées."}, {"numero": 10, "texto": "le vingt-quatrième jour du neuvième mois, la seconde année de Darius, la parole de l''''Eternel se révéla par Aggée, le prophète, en ces mots:"}, {"numero": 11, "texto": "Ainsi parle l''''Eternel des armées: Propose aux sacrificateurs cette question sur la loi:"}, {"numero": 12, "texto": "Si quelqu''''un porte dans le pan de son vêtement de la chair consacrée, et qu''''il touche avec son vêtement du pain, des mets, du vin, de l''''huile, ou un aliment quelconque, ces choses seront-elles sanctifiées? Les sacrificateurs répondirent: Non!"}, {"numero": 13, "texto": "Et Aggée dit: Si quelqu''''un souillé par le contact d''''un cadavre touche toutes ces choses, seront-elles souillées? Les sacrificateurs répondirent: Elles seront souillées."}, {"numero": 14, "texto": "Alors Aggée, reprenant la parole, dit: Tel est ce peuple, telle est cette nation devant moi, dit l''''Eternel, Telles sont toutes les oeuvres de leurs mains; Ce qu''''ils m''''offrent là est souillé."}, {"numero": 15, "texto": "Considérez donc attentivement Ce qui s''''est passé jusqu''''à ce jour, Avant qu''''on eût mis pierre sur pierre au temple de l''''Eternel!"}, {"numero": 16, "texto": "Alors, quand on venait à un tas de vingt mesures, Il n''''y en avait que dix; Quand on venait à la cuve pour puiser cinquante mesures, Il n''''y en avait que vingt."}, {"numero": 17, "texto": "Je vous ai frappés par la rouille et par la nielle, et par la grêle; J''''ai frappé tout le travail de vos mains. Malgré cela, vous n''''êtes pas revenus à moi, dit l''''Eternel."}, {"numero": 18, "texto": "Considérez attentivement Ce qui s''''est passé jusqu''''à ce jour, Jusqu''''au vingt-quatrième jour du neuvième mois, Depuis le jour où le temple de l''''Eternel a été fondé, Considérez-le attentivement!"}, {"numero": 19, "texto": "Y avait-il encore de la semence dans les greniers? Même la vigne, le figuier, le grenadier et l''''olivier, N''''ont rien rapporté. Mais dès ce jour je répandrai ma bénédiction."}, {"numero": 20, "texto": "La parole de l''''Eternel fut adressée pour la seconde fois à Aggée, le vingt-quatrième jour du mois, en ces mots:"}, {"numero": 21, "texto": "Parle à Zorobabel, gouverneur de Juda, et dis: J''''ébranlerai les cieux et la terre;"}, {"numero": 22, "texto": "Je renverserai le trône des royaumes, Je détruirai la force des royaumes des nations, Je renverserai les chars et ceux qui les montent; Les chevaux et leurs cavaliers seront abattus, L''''un par l''''épée de l''''autre."}, {"numero": 23, "texto": "En ce jour-là, dit l''''Eternel des armées, Je te prendrai, Zorobabel, fils de Schealthiel, Mon serviteur, dit l''''Eternel, Et je te garderai comme un sceau; Car je t''''ai choisi, dit l''''Eternel des armées."}]'::jsonb, 'Louis Segond 1910'),
  ('Ag', 2, 'es', '[{"numero": 1, "texto": "EN el mes séptimo, á los veinte y uno del mes, fué palabra de Jehová por mano del profeta Haggeo, diciendo:"}, {"numero": 2, "texto": "Habla ahora á Zorobabel hijo de Sealtiel, gobernador de Judá, y á Josué hijo de Josadac, gran sacerdote, y al resto del pueblo, diciendo:"}, {"numero": 3, "texto": "¿Quién ha quedado entre vosotros que haya visto esta casa en su primera gloria, y cual ahora la veis? ¿No es ella como nada delante de vuestros ojos?"}, {"numero": 4, "texto": "Pues ahora, Zorobabel, esfuérzate, dice Jehová; esfuérzate también Josué, hijo de Josadac, gran sacerdote; y cobra ánimo, pueblo todo de la tierra, dice Jehová, y obrad: porque yo soy con vosotros, dice Jehová de los ejércitos."}, {"numero": 5, "texto": "Según el pacto que concerté con vosotros á vuestra salida de Egipto, así mi espíritu estará en medio de vosotros: no temáis."}, {"numero": 6, "texto": "Porque así dice Jehová de los ejércitos: De aquí á poco aun haré yo temblar los cielos y la tierra, y la mar y la seca:"}, {"numero": 7, "texto": "Y haré temblar á todas las gentes, y vendrá el Deseado de todas las gentes; y henchiré esta casa de gloria, ha dicho Jehová de los ejércitos."}, {"numero": 8, "texto": "Mía es la plata, y mío el oro, dice Jehová de los ejércitos."}, {"numero": 9, "texto": "La gloria de aquesta casa postrera será mayor que la de la primera, ha dicho Jehová de los ejércitos; y daré paz en este lugar, dice Jehová de los ejércitos."}, {"numero": 10, "texto": "A veinticuatro del noveno mes, en el segundo año de Darío, fué palabra de Jehová por mano del profeta Haggeo, diciendo:"}, {"numero": 11, "texto": "Así ha dicho Jehová de los ejércitos: Pregunta ahora á los sacerdotes acerca de la ley, diciendo:"}, {"numero": 12, "texto": "Si llevare alguno las carnes sagradas en la falda de su ropa, y con el vuelo de ella tocare el pan, ó la vianda, ó el vino, ó el aceite, ú otra cualquier comida, ¿será santificado? Y respondieron los sacerdotes, y dijeron: No."}, {"numero": 13, "texto": "Y dijo Haggeo: Si un inmundo á causa de cuerpo muerto tocare alguna cosa de éstas, ¿será inmunda? Y respondieron los sacerdotes, y dijeron: Inmunda será."}, {"numero": 14, "texto": "Y respondió Haggeo y dijo: Así es este pueblo, y esta gente, delante de mí, dice Jehová; y asimismo toda obra de sus manos; y todo lo que aquí ofrecen es inmundo."}, {"numero": 15, "texto": "Ahora pues, poned vuestro corazón desde este día en adelante, antes que pusiesen piedra sobre piedra en el templo de Jehová,"}, {"numero": 16, "texto": "Antes que fuesen estas cosas, venían al montón de veinte hanegas, y había diez; venían al lagar para sacar cincuenta cántaros del lagar, y había veinte."}, {"numero": 17, "texto": "Os herí con viento solano, y con tizoncillo, y con granizo en toda obra de vuestras manos; mas no os convertisteis á mí, dice Jehová."}, {"numero": 18, "texto": "Pues poned ahora vuestro corazón desde este día en adelante, desde el día veinticuatro del noveno mes, desde el día que se echó el cimiento al templo de Jehová; poned vuestro corazón."}, {"numero": 19, "texto": "¿Aun no está la simiente en el granero? Ni la vid, ni la higuera, ni el granado, ni el árbol de la oliva ha todavía florecido: mas desde aqueste día daré bendición."}, {"numero": 20, "texto": "Y fué segunda vez palabra de Jehová á Haggeo, á los veinticuatro del mismo mes, diciendo:"}, {"numero": 21, "texto": "Habla á Zorobabel, gobernador de Judá, diciendo: Yo haré temblar los cielos y la tierra;"}, {"numero": 22, "texto": "Y trastornaré el trono de los reinos, y destruiré la fuerza del reino de las gentes; y trastornaré el carro, y los que en él suben; y vendrán abajo los caballos, y los que en ellos montan, cada cual por la espada de su hermano."}, {"numero": 23, "texto": "En aquel día, dice Jehová de los ejércitos, te tomaré, oh Zorobabel, hijo de Sealtiel, siervo mío, dice Jehová, y ponerte he como anillo de sellar: porque yo te escogí, dice Jehová de los ejércitos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Am', 8, 'pt', '[{"numero": 1, "texto": "Assim o SENHOR me fez ver: eis um cesto com frutos de verão."}, {"numero": 2, "texto": "E ele disse: O que vês, Amós? E eu disse: Um cesto com frutos de verão. Então o SENHOR me disse: Chegou o fim sobre meu povo Israel; não mais o tolerarei."}, {"numero": 3, "texto": "E os cânticos do templo serão gemidos naquele dia,diz o Senhor DEUS; os cadáveres serão muitos, em todo lugar serão lançados. Silêncio!"}, {"numero": 4, "texto": "Ouvi isto, vós que tragais os necessitados, e arruinais os pobres da terra,"}, {"numero": 5, "texto": "Dizendo: Quando passará a lua nova, para vendermos o alimento? E o sábado, para abriremos os depósitos de trigo, e diminuirmos a medida, aumentarmos o preço, e fraudarmos com balanças enganosas,"}, {"numero": 6, "texto": "Para comprarmos os pobres por dinheiro, e os necessitados por um par de sapatos, e venderemos os refugos do trigo?"}, {"numero": 7, "texto": "O SENHOR jurou pela glória de Jacó: Eu nunca me esquecerei das obras deles."}, {"numero": 8, "texto": "A terra não se abalará por causa disto, e todo habitante dela não chorará? Certamente ela se levantará como um rio, se agitará, e se afundará como o rio do Egito."}, {"numero": 9, "texto": "E será naquele dia,diz o Senhor DEUS, que farei o sol se pôr ao meio-dia, e escurecerei a terra no dia claro."}, {"numero": 10, "texto": "E tornarei vossas festas em luto, e todas as vossas canções em pranto; e farei com que todos se vistam de saco, e se façam calvas sobre todas as cabeças; e farei com que haja luto como de um filho único, e seu fim será como um dia amargo."}, {"numero": 11, "texto": "Eis que vêm dias,diz o Senhor DEUS, nos quais enviarei fome à terra; fome não de pão, nem sede de água, mas sim de ouvir as palavras do SENHOR."}, {"numero": 12, "texto": "E irão sem rumo de mar a mar, do norte até o oriente; correrão de um lado para o outro em busca da palavra do SENHOR, mas não a encontrarão."}, {"numero": 13, "texto": "Naquele tempo as belas virgens e os rapazes desmaiarão de sede."}, {"numero": 14, "texto": "Quanto aos que juram pelo pecado de Samaria, e dizem: Vive o teu deus de Dã; e: Vive o caminho de Berseba; esses cairão, e nunca mais se levantarão."}]'::jsonb, 'Almeida Livre'),
  ('Am', 8, 'en', '[{"numero": 1, "texto": "Thus hath the Lord God shewed unto me: and behold a basket of summer fruit."}, {"numero": 2, "texto": "And he said, Amos, what seest thou? And I said, A basket of summer fruit. Then said the Lord unto me, The end is come upon my people of Israel; I will not again pass by them any more."}, {"numero": 3, "texto": "And the songs of the temple shall be howlings in that day, saith the Lord God: there shall be many dead bodies in every place; they shall cast them forth with silence."}, {"numero": 4, "texto": "Hear this, O ye that swallow up the needy, even to make the poor of the land to fail,"}, {"numero": 5, "texto": "Saying, When will the new moon be gone, that we may sell corn? and the sabbath, that we may set forth wheat, making the ephah small, and the shekel great, and falsifying the balances by deceit?"}, {"numero": 6, "texto": "That we may buy the poor for silver, and the needy for a pair of shoes; yea, and sell the refuse of the wheat?"}, {"numero": 7, "texto": "The Lord hath sworn by the excellency of Jacob, Surely I will never forget any of their works."}, {"numero": 8, "texto": "Shall not the land tremble for this, and every one mourn that dwelleth therein? and it shall rise up wholly as a flood; and it shall be cast out and drowned, as by the flood of Egypt."}, {"numero": 9, "texto": "And it shall come to pass in that day, saith the Lord God, that I will cause the sun to go down at noon, and I will darken the earth in the clear day:"}, {"numero": 10, "texto": "And I will turn your feasts into mourning, and all your songs into lamentation; and I will bring up sackcloth upon all loins, and baldness upon every head; and I will make it as the mourning of an only son, and the end thereof as a bitter day."}, {"numero": 11, "texto": "Behold, the days come, saith the Lord God, that I will send a famine in the land, not a famine of bread, nor a thirst for water, but of hearing the words of the Lord:"}, {"numero": 12, "texto": "And they shall wander from sea to sea, and from the north even to the east, they shall run to and fro to seek the word of the Lord, and shall not find it."}, {"numero": 13, "texto": "In that day shall the fair virgins and young men faint for thirst."}, {"numero": 14, "texto": "They that swear by the sin of Samaria, and say, Thy god, O Dan, liveth; and, The manner of Beersheba liveth; even they shall fall, and never rise up again."}]'::jsonb, 'King James Version'),
  ('Am', 8, 'fr', '[{"numero": 1, "texto": "Le Seigneur, l''''Eternel, m''''envoya cette vision. Voici, c''''était une corbeille de fruits."}, {"numero": 2, "texto": "Il dit: Que vois-tu, Amos? Je répondis: Une corbeille de fruits. Et l''''Eternel me dit: La fin est venue pour mon peuple d''''Israël; Je ne lui pardonnerai plus."}, {"numero": 3, "texto": "En ce jour-là, les chants du palais seront des gémissements, Dit le Seigneur, l''''Eternel; On jettera partout en silence une multitude de cadavres."}, {"numero": 4, "texto": "Ecoutez ceci, vous qui dévorez l''''indigent, Et qui ruinez les malheureux du pays!"}, {"numero": 5, "texto": "Vous dites: Quand la nouvelle lune sera-t-elle passée, Afin que nous vendions du blé? Quand finira le sabbat, afin que nous ouvrions les greniers? Nous diminuerons l''''épha, nous augmenterons le prix, Nous falsifierons les balances pour tromper;"}, {"numero": 6, "texto": "Puis nous achèterons les misérables pour de l''''argent, Et le pauvre pour une paire de souliers, Et nous vendrons la criblure du froment."}, {"numero": 7, "texto": "L''''Eternel l''''a juré par la gloire de Jacob: Je n''''oublierai jamais aucune de leurs oeuvres."}, {"numero": 8, "texto": "Le pays, à cause d''''elles, ne sera-t-il pas ébranlé, Et tous ses habitants ne seront-ils pas dans le deuil? Le pays montera tout entier comme le fleuve, Il se soulèvera et s''''affaissera comme le fleuve d''''Egypte."}, {"numero": 9, "texto": "En ce jour-là, dit le Seigneur, l''''Eternel, Je ferai coucher le soleil à midi, Et j''''obscurcirai la terre en plein jour;"}, {"numero": 10, "texto": "Je changerai vos fêtes en deuil, Et tous vos chants en lamentations, Je couvrirai de sacs tous les reins, Et je rendrai chauves toutes les têtes; Je mettrai le pays dans le deuil comme pour un fils unique, Et sa fin sera comme un jour d''''amertume."}, {"numero": 11, "texto": "Voici, les jours viennent, dit le Seigneur, l''''Eternel, Où j''''enverrai la famine dans le pays, Non pas la disette du pain et la soif de l''''eau, Mais la faim et la soif d''''entendre les paroles de l''''Eternel."}, {"numero": 12, "texto": "Ils seront alors errants d''''une mer à l''''autre, Du septentrion à l''''orient, Ils iront çà et là pour chercher la parole de l''''Eternel, Et ils ne la trouveront pas."}, {"numero": 13, "texto": "En ce jour, les belles jeunes filles et les jeunes hommes mourront de soif."}, {"numero": 14, "texto": "Ils jurent par le péché de Samarie, Et ils disent: Vive ton Dieu, Dan! Vive la voie de Beer-Schéba! Mais ils tomberont, et ne se relèveront plus."}]'::jsonb, 'Louis Segond 1910'),
  ('Am', 8, 'es', '[{"numero": 1, "texto": "ASÍ me ha mostrado Jehová: y he aquí un canastillo de fruta de verano."}, {"numero": 2, "texto": "Y dijo: ¿Qué ves, Amós? Y dije: Un canastillo de fruta de verano. Y díjome Jehová: Venido ha el fin sobre mi pueblo Israel; no le pasaré más."}, {"numero": 3, "texto": "Y los cantores del templo aullarán en aquel día, dice el Señor Jehová; muchos serán los cuerpos muertos; en todo lugar echados serán en silencio."}, {"numero": 4, "texto": "Oid esto, los que tragáis á los menesterosos, y arruináis los pobres de la tierra,"}, {"numero": 5, "texto": "Diciendo: ¿Cuándo pasará el mes, y venderemos el trigo; y la semana, y abriremos los alfolíes del pan, y achicaremos la medida, y engrandeceremos el precio, y falsearemos el peso engañoso;"}, {"numero": 6, "texto": "Para comprar los pobres por dinero, y los necesitados por un par de zapatos, y venderemos las aechaduras del trigo?"}, {"numero": 7, "texto": "Jehová juró por la gloria de Jacob: No me olvidaré para siempre de todas sus obras."}, {"numero": 8, "texto": "¿No se ha de estremecer la tierra sobre esto? ¿y todo habitador de ella no llorará? y subirá toda como un río, y será arrojada, y hundiráse como el río de Egipto."}, {"numero": 9, "texto": "Y acaecerá en aquel día, dice el Señor Jehová, que haré se ponga el sol al mediodía, y la tierra cubriré de tinieblas en el día claro."}, {"numero": 10, "texto": "Y tornaré vuestras fiestas en lloro, y todos vuestros cantares en endechas; y haré poner saco sobre todos lomos, y peladura sobre toda cabeza; y tornaréla como en llanto de unigénito, y su postrimería como día amargo."}, {"numero": 11, "texto": "He aquí vienen días, dice el Señor Jehová, en los cuales enviaré hambre á la tierra, no hambre de pan, ni sed de agua, sino de oir palabra de Jehová."}, {"numero": 12, "texto": "E irán errantes de mar á mar: desde el norte hasta el oriente discurrirán buscando palabra de Jehová, y no la hallarán."}, {"numero": 13, "texto": "En aquel tiempo las doncellas hermosas y los mancebos desmayarán de sed."}, {"numero": 14, "texto": "Los que juran por el pecado de Samaria, y dicen, Vive tu Dios de Dan: y, Vive el camino de Beer-seba: caerán, y nunca más se levantarán."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ap', 21, 'pt', '[{"numero": 1, "texto": "E eu vi um novo céu e uma nova terra; porque o primeiro céu e a primeira terra [já] passaram; e e [já] não havia mar."}, {"numero": 2, "texto": "E eu, João, vi a cidade santa, a nova Jerusalém, descendo do céu [vinda] de Deus, preparada como noiva, adornada para seu marido."}, {"numero": 3, "texto": "E eu ouvi uma grande voz do céu, dizendo: “Eis que o tabernáculo de Deus está com os seres humanos; e com eles habitará, e eles serão seu povo, e o próprio Deus estará com eles, [e será] seu Deus."}, {"numero": 4, "texto": "E Deus limpará toda lágrima dos olhos deles; e não haverá mais morte, nem pranto, nem clamor, nem mais haverá dor; porque as primeiras coisas [já] passaram.”"}, {"numero": 5, "texto": "E o que estava sentado sobre o trono disse: “Eis que eu faço novas todas as coisas.” E ele me disse: “Escreve, porque estas palavras são verdadeiras e fiéis.”"}, {"numero": 6, "texto": "E ele me disse: “Está feito. Eu sou o Alfa e o Ômega, o princípio e o fim. Quem tiver sede, de graça eu lhe darei da fonte da água da vida."}, {"numero": 7, "texto": "Quem vencer herdará todas as coisas; e eu serei Deus dele, e ele será meu filho."}, {"numero": 8, "texto": "Mas [quanto] aos covardes, e aos incrédulos, e aos abomináveis, e aos homicidas, e aos pecadores sexuais, e aos feiticeiros, e aos idólatras, e a todos os mentirosos, a parte deles será no lago que queima com fogo e enxofre, que é a segunda morte.”"}, {"numero": 9, "texto": "E veio a mim um dos sete anjos que tinham as sete taças cheias das sete últimas pragas; e ele falou comigo, dizendo: “Vem, [e] eu te mostrarei a noiva, a mulher do Cordeiro.”"}, {"numero": 10, "texto": "E ele me levou em espírito a um grande e alto monte; e ele me mostrou a grande cidade, a santa Jerusalém, descendo do céu [vinda] de Deus;"}, {"numero": 11, "texto": "[E] tendo a glória de Deus; e sua luz era semelhante a uma pedra preciosíssima, como a pedra de jaspe, como cristal brilhante;"}, {"numero": 12, "texto": "[E] tinha um grande e alto muro tendo doze portas; e nas portas doze anjos, e nomes escritos nelas, que são os [nomes] das doze tribos dos filhos de Israel."}, {"numero": 13, "texto": "No oriente [tinha] três portas; no norte três portas, no sul três portas, [e] no ocidente três portas."}, {"numero": 14, "texto": "E o muro da cidade tinha doze fundamentos, e neles os nomes dos doze apóstolos do Cordeiro."}, {"numero": 15, "texto": "E aquele que estava falando comigo tinha uma cana de ouro, para medir a cidade, e suas portas, e seu muro."}, {"numero": 16, "texto": "E a cidade estava posta [na forma] de um quadrado; e o seu comprimento era tanto quanto [sua] largura. E ele mediu a cidade com a cana até doze mil estádios; e seu comprimento, largura e altura eram iguais."}, {"numero": 17, "texto": "E ele mediu seu muro de cento e quarenta e quatro côvados, [conforme] a medida humana, que é [também] a do anjo."}, {"numero": 18, "texto": "E a constituição de seu muro era [de] jaspe; e a cidade [era] de ouro puro, semelhante a vidro puro."}, {"numero": 19, "texto": "E os fundamentos do muro da cidade estavam adornados com toda pedra preciosa; o primeiro fundamento era jaspe; o segundo, safira; o terceiro, calcedônia; o quarto, esmeralda;"}, {"numero": 20, "texto": "O quinto, sardônica; o sexto, sárdio; o sétimo, crisólito; o oitavo, berilo; o nono, topázio; o décimo, crisópraso; o décimo primeiro, jacinto; o décimo segundo, ametista."}, {"numero": 21, "texto": "E as doze portas eram doze pérolas; cada uma das portas era de uma pérola; e a praça da cidade [era] de ouro puro, como vidro transparente."}, {"numero": 22, "texto": "E nela eu não vi templo, porque o templo dela é o Senhor Deus Todo-Poderoso, e o Cordeiro."}, {"numero": 23, "texto": "E a cidade não necessita de sol nem de lua para que brilhem nela; porque a glória de Deus a ilumina, e sua lâmpada [é] o Cordeiro."}, {"numero": 24, "texto": "E as nações dos salvos andarão na luz dela; e os reis da terra trarão a ela a glória e honra deles."}, {"numero": 25, "texto": "E suas portas não se fecharão de dia; porque ali não haverá noite."}, {"numero": 26, "texto": "E a ela serão trazidas a glória e a honra das nações."}, {"numero": 27, "texto": "E de maneira nenhuma entrará nela algo que contamine, faça abominação e mentira; a não ser somente aqueles que estão escritos no livro da vida do Cordeiro."}]'::jsonb, 'Almeida Livre'),
  ('Ap', 21, 'en', '[{"numero": 1, "texto": "And I saw a new heaven and a new earth: for the first heaven and the first earth were passed away; and there was no more sea."}, {"numero": 2, "texto": "And I John saw the holy city, new Jerusalem, coming down from God out of heaven, prepared as a bride adorned for her husband."}, {"numero": 3, "texto": "And I heard a great voice out of heaven saying, Behold, the tabernacle of God is with men, and he will dwell with them, and they shall be his people, and God himself shall be with them, and be their God."}, {"numero": 4, "texto": "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."}, {"numero": 5, "texto": "And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful."}, {"numero": 6, "texto": "And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely."}, {"numero": 7, "texto": "He that overcometh shall inherit all things; and I will be his God, and he shall be my son."}, {"numero": 8, "texto": "But the fearful, and unbelieving, and the abominable, and murderers, and whoremongers, and sorcerers, and idolaters, and all liars, shall have their part in the lake which burneth with fire and brimstone: which is the second death."}, {"numero": 9, "texto": "And there came unto me one of the seven angels which had the seven vials full of the seven last plagues, and talked with me, saying, Come hither, I will shew thee the bride, the Lamb''s wife."}, {"numero": 10, "texto": "And he carried me away in the spirit to a great and high mountain, and shewed me that great city, the holy Jerusalem, descending out of heaven from God,"}, {"numero": 11, "texto": "Having the glory of God: and her light was like unto a stone most precious, even like a jasper stone, clear as crystal;"}, {"numero": 12, "texto": "And had a wall great and high, and had twelve gates, and at the gates twelve angels, and names written thereon, which are the names of the twelve tribes of the children of Israel:"}, {"numero": 13, "texto": "On the east three gates; on the north three gates; on the south three gates; and on the west three gates."}, {"numero": 14, "texto": "And the wall of the city had twelve foundations, and in them the names of the twelve apostles of the Lamb."}, {"numero": 15, "texto": "And he that talked with me had a golden reed to measure the city, and the gates thereof, and the wall thereof."}, {"numero": 16, "texto": "And the city lieth foursquare, and the length is as large as the breadth: and he measured the city with the reed, twelve thousand furlongs. The length and the breadth and the height of it are equal."}, {"numero": 17, "texto": "And he measured the wall thereof, an hundred and forty and four cubits, according to the measure of a man, that is, of the angel."}, {"numero": 18, "texto": "And the building of the wall of it was of jasper: and the city was pure gold, like unto clear glass."}, {"numero": 19, "texto": "And the foundations of the wall of the city were garnished with all manner of precious stones. The first foundation was jasper; the second, sapphire; the third, a chalcedony; the fourth, an emerald;"}, {"numero": 20, "texto": "The fifth, sardonyx; the sixth, sardius; the seventh, chrysolyte; the eighth, beryl; the ninth, a topaz; the tenth, a chrysoprasus; the eleventh, a jacinth; the twelfth, an amethyst."}, {"numero": 21, "texto": "And the twelve gates were twelve pearls: every several gate was of one pearl: and the street of the city was pure gold, as it were transparent glass."}, {"numero": 22, "texto": "And I saw no temple therein: for the Lord God Almighty and the Lamb are the temple of it."}, {"numero": 23, "texto": "And the city had no need of the sun, neither of the moon, to shine in it: for the glory of God did lighten it, and the Lamb is the light thereof."}, {"numero": 24, "texto": "And the nations of them which are saved shall walk in the light of it: and the kings of the earth do bring their glory and honour into it."}, {"numero": 25, "texto": "And the gates of it shall not be shut at all by day: for there shall be no night there."}, {"numero": 26, "texto": "And they shall bring the glory and honour of the nations into it."}, {"numero": 27, "texto": "And there shall in no wise enter into it any thing that defileth, neither whatsoever worketh abomination, or maketh a lie: but they which are written in the Lamb''s book of life."}]'::jsonb, 'King James Version'),
  ('Ap', 21, 'fr', '[{"numero": 1, "texto": "Puis je vis un nouveau ciel et une nouvelle terre; car le premier ciel et la première terre avaient disparu, et la mer n''''était plus."}, {"numero": 2, "texto": "Et je vis descendre du ciel, d''''auprès de Dieu, la ville sainte, la nouvelle Jérusalem, préparée comme une épouse qui s''''est parée pour son époux."}, {"numero": 3, "texto": "Et j''''entendis du trône une forte voix qui disait: Voici le tabernacle de Dieu avec les hommes! Il habitera avec eux, et ils seront son peuple, et Dieu lui-même sera avec eux."}, {"numero": 4, "texto": "Il essuiera toute larme de leurs yeux, et la mort ne sera plus, et il n''''y aura plus ni deuil, ni cri, ni douleur, car les premières choses ont disparu."}, {"numero": 5, "texto": "Et celui qui était assis sur le trône dit: Voici, je fais toutes choses nouvelles. Et il dit: Ecris; car ces paroles sont certaines et véritables."}, {"numero": 6, "texto": "Et il me dit: C''''est fait! Je suis l''''alpha et l''''oméga, le commencement et la fin. A celui qui a soif je donnerai de la source de l''''eau de la vie, gratuitement."}, {"numero": 7, "texto": "Celui qui vaincra héritera ces choses; je serai son Dieu, et il sera mon fils."}, {"numero": 8, "texto": "Mais pour les lâches, les incrédules, les abominables, les meurtriers, les impudiques, les enchanteurs, les idolâtres, et tous les menteurs, leur part sera dans l''''étang ardent de feu et de soufre, ce qui est la seconde mort."}, {"numero": 9, "texto": "Puis un des sept anges qui tenaient les sept coupes remplies des sept derniers fléaux vint, et il m''''adressa la parole, en disant: Viens, je te montrerai l''''épouse, la femme de l''''agneau."}, {"numero": 10, "texto": "Et il me transporta en esprit sur une grande et haute montagne. Et il me montra la ville sainte, Jérusalem, qui descendait du ciel d''''auprès de Dieu,"}, {"numero": 11, "texto": "ayant la gloire de Dieu. Son éclat était semblable à celui d''''une pierre très précieuse, d''''une pierre de jaspe transparente comme du cristal."}, {"numero": 12, "texto": "Elle avait une grande et haute muraille. Elle avait douze portes, et sur les portes douze anges, et des noms écrits, ceux des douze tribus des fils d''''Israël:"}, {"numero": 13, "texto": "l''''orient trois portes, au nord trois portes, au midi trois portes, et à l''''occident trois portes."}, {"numero": 14, "texto": "La muraille de la ville avait douze fondements, et sur eux les douze noms des douze apôtres de l''''agneau."}, {"numero": 15, "texto": "Celui qui me parlait avait pour mesure un roseau d''''or, afin de mesurer la ville, ses portes et sa muraille."}, {"numero": 16, "texto": "La ville avait la forme d''''un carré, et sa longueur était égale à sa largeur. Il mesura la ville avec le roseau, et trouva douze mille stades; la longueur, la largeur et la hauteur en étaient égales."}, {"numero": 17, "texto": "Il mesura la muraille, et trouva cent quarante-quatre coudées, mesure d''''homme, qui était celle de l''''ange."}, {"numero": 18, "texto": "La muraille était construite en jaspe, et la ville était d''''or pur, semblable à du verre pur."}, {"numero": 19, "texto": "Les fondements de la muraille de la ville étaient ornés de pierres précieuses de toute espèce: le premier fondement était de jaspe, le second de saphir, le troisième de calcédoine, le quatrième d''''émeraude,"}, {"numero": 20, "texto": "le cinquième de sardonyx, le sixième de sardoine, le septième de chrysolithe, le huitième de béryl, le neuvième de topaze, le dixième de chrysoprase, le onzième d''''hyacinthe, le douzième d''''améthyste."}, {"numero": 21, "texto": "Les douze portes étaient douze perles; chaque porte était d''''une seule perle. La place de la ville était d''''or pur, comme du verre transparent."}, {"numero": 22, "texto": "Je ne vis point de temple dans la ville; car le Seigneur Dieu tout-puissant est son temple, ainsi que l''''agneau."}, {"numero": 23, "texto": "La ville n''''a besoin ni du soleil ni de la lune pour l''''éclairer; car la gloire de Dieu l''''éclaire, et l''''agneau est son flambeau."}, {"numero": 24, "texto": "Les nations marcheront à sa lumière, et les rois de la terre y apporteront leur gloire."}, {"numero": 25, "texto": "Ses portes ne se fermeront point le jour, car là il n''''y aura point de nuit."}, {"numero": 26, "texto": "On y apportera la gloire et l''''honneur des nations."}, {"numero": 27, "texto": "Il n''''entrera chez elle rien de souillé, ni personne qui se livre à l''''abomination et au mensonge; il n''''entrera que ceux qui sont écrits dans le livre de vie de l''''agneau."}]'::jsonb, 'Louis Segond 1910'),
  ('Ap', 21, 'es', '[{"numero": 1, "texto": "Y VI un cielo nuevo, y una tierra nueva: porque el primer cielo y la primera tierra se fueron, y el mar ya no es."}, {"numero": 2, "texto": "Y yo Juan vi la santa ciudad, Jerusalem nueva, que descendía del cielo, de Dios, dispuesta como una esposa ataviada para su marido."}, {"numero": 3, "texto": "Y oí una gran voz del cielo que decía: He aquí el tabernáculo de Dios con los hombres, y morará con ellos; y ellos serán su pueblo, y el mismo Dios será su Dios con ellos."}, {"numero": 4, "texto": "Y limpiará Dios toda lágrima de los ojos de ellos; y la muerte no será más; y no habrá más llanto, ni clamor, ni dolor: porque las primeras cosas son pasadas."}, {"numero": 5, "texto": "Y el que estaba sentado en el trono dijo: He aquí, yo hago nuevas todas las cosas. Y me dijo: Escribe; porque estas palabras son fieles y verdaderas."}, {"numero": 6, "texto": "Y díjome: Hecho es. Yo soy Alpha y Omega, el principio y el fin. Al que tuviere sed, yo le daré de la fuente del agua de vida gratuitamente."}, {"numero": 7, "texto": "El que venciere, poseerá todas las cosas; y yo seré su Dios, y él será mi hijo."}, {"numero": 8, "texto": "Mas á los temerosos é incrédulos, á los abominables y homicidas, á los fornicarios y hechiceros, y á los idólatras, y á todos los mentirosos, su parte será en el lago ardiendo con fuego y azufre, que es la muerte segunda."}, {"numero": 9, "texto": "Y vino á mí uno de los siete ángeles que tenían las siete copas llenas de las siete postreras plagas, y habló conmigo, diciendo: Ven acá, yo te mostraré la esposa, mujer del Cordero."}, {"numero": 10, "texto": "Y llevóme en Espíritu á un grande y alto monte, y me mostró la grande ciudad santa de Jerusalem, que descendía del cielo de Dios,"}, {"numero": 11, "texto": "Teniendo la claridad de Dios: y su luz era semejante á una piedra preciosísima, como piedra de jaspe, resplandeciente como cristal."}, {"numero": 12, "texto": "Y tenía un muro grande y alto con doce puertas; y en las puertas, doce ángeles, y nombres escritos, que son los de las doce tribus de los hijos de Israel."}, {"numero": 13, "texto": "Al oriente tres puertas; al norte tres puertas; al mediodía tres puertas; al poniente tres puertas."}, {"numero": 14, "texto": "Y el muro de la ciudad tenía doce fundamentos, y en ellos los doce nombres de los doce apóstoles del Cordero."}, {"numero": 15, "texto": "Y el que hablaba conmigo, tenía una medida de una caña de oro para medir la ciudad, y sus puertas, y su muro."}, {"numero": 16, "texto": "Y la ciudad está situada y puesta en cuadro, y su largura es tanta como su anchura: y él midió la ciudad con la caña, doce mil estadios: la largura y la altura y la anchura de ella son iguales."}, {"numero": 17, "texto": "Y midió su muro, ciento cuarenta y cuatro codos, de medida de hombre, la cual es del ángel."}, {"numero": 18, "texto": "Y el material de su muro era de jaspe: mas la ciudad era de oro puro, semejante al vidrio limpio."}, {"numero": 19, "texto": "Y los fundamentos del muro de la ciudad estaban adornados de toda piedra preciosa. El primer fundamento era jaspe; el segundo, zafiro; el tercero, calcedonia; el cuarto, esmeralda;"}, {"numero": 20, "texto": "El quinto, sardónica; el sexto, sardio; el séptimo, crisólito; el octavo, berilo; el nono, topacio; el décimo, crisopraso; el undécimo, jacinto; el duodécimo, amatista."}, {"numero": 21, "texto": "Y las doce puertas eran doce perlas, en cada una, una; cada puerta era de una perla. Y la plaza de la ciudad era de oro puro como vidrio trasparente."}, {"numero": 22, "texto": "Y no vi en ella templo; porque el Señor Dios Todopoderoso es el templo de ella, y el Cordero."}, {"numero": 23, "texto": "Y la ciudad no tenía necesidad de sol, ni de luna, para que resplandezcan en ella: porque la claridad de Dios la iluminó, y el Cordero era su lumbrera."}, {"numero": 24, "texto": "Y las naciones que hubieren sido salvas andarán en la lumbre de ella: y los reyes de la tierra traerán su gloria y honor á ella."}, {"numero": 25, "texto": "Y sus puertas nunca serán cerradas de día, porque allí no habrá noche."}, {"numero": 26, "texto": "Y llevarán la gloria y la honra de las naciones á ella."}, {"numero": 27, "texto": "No entrará en ella ninguna cosa sucia, ó que hace abominación y mentira; sino solamente los que están escritos en el libro de la vida del Cordero."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ap', 22, 'pt', '[{"numero": 1, "texto": "E ele me mostrou o rio puro da água da vida, claro como cristal, que vinha do trono de Deus e do Cordeiro."}, {"numero": 2, "texto": "No meio de sua praça, e de um lado e do outro do rio, [estava] a árvore da vida, que produz doze frutos, dando seu fruto a cada mês; e as folhas das árvores são para a saúde das nações."}, {"numero": 3, "texto": "E não haverá mais maldição alguma; e nela estará o trono de Deus e do Cordeiro, e seus servos o servirão."}, {"numero": 4, "texto": "E eles verão o rosto dele, e o nome dele [estará] em suas testas."}, {"numero": 5, "texto": "E ali não haverá mais noite, e não terão necessidade de lâmpada, nem de luz do sol; porque o Senhor Deus os ilumina; e reinarão para todo o sempre."}, {"numero": 6, "texto": "E ele me disse: “Estas palavras são fiéis e verdadeiras; e o Senhor, o Deus dos santos profetas, enviou o seu anjo para mostrar a seus servos as coisas que devem acontecer em breve.”"}, {"numero": 7, "texto": "“Eis que logo venho; bendito [é] aquele que guarda as palavras da profecia deste livro.”"}, {"numero": 8, "texto": "E eu, João, sou aquele que vi e ouvi estas coisas. E quando eu [as] ouvi e vi, prostrei-me para adorar diante dos pés do anjo, que me mostrava estas coisas."}, {"numero": 9, "texto": "E ele me disse: “Olha, não [faças isto] ! Porque eu sou um companheiro de serviço teu, e de teus irmãos, os profetas, e dos que guardam as palavras deste livro. Adora a Deus.”"}, {"numero": 10, "texto": "E ele me disse: “Não seles as palavras da profecia deste livro, porque o tempo está próximo."}, {"numero": 11, "texto": "Quem é injusto, faça injustiça ainda; e quem é sujo, suje-se ainda; e quem é justo, seja ainda justificado; e quem é santo, seja ainda santificado.”"}, {"numero": 12, "texto": "“Eis que logo venho, e minha recompensa está comigo, para retribuir a cada um assim como for sua obra."}, {"numero": 13, "texto": "Eu sou o Alfa e o Ômega, o principio e o fim, o primeiro e o último.”"}, {"numero": 14, "texto": "Benditos são os que guardam os mandamentos dele, para que tenham direito à árvore da vida, e possam entrar na cidade pelas portas."}, {"numero": 15, "texto": "Mas de fora [estarão] os cães, os feiticeiros, os pecadores sexuais, os homicidas, os idólatras, e todo aquele que ama e pratica a mentira."}, {"numero": 16, "texto": "“Eu, Jesus, enviei o meu anjo, para vos dar testemunho destas coisas nas igrejas. Eu sou a raiz e descendência de Davi; [sou] a brilhante estrela da manhã.”"}, {"numero": 17, "texto": "E o Espírito e a noiva dizem: “Vem!” E quem [o] ouve, diga: “Vem!” E quem tem sede, venha; e quem quiser, tome de graça da água da vida."}, {"numero": 18, "texto": "Porque eu também dou testemunho a todo aquele que ouvir as palavras da profecia deste livro, [que] se alguém acrescentar a estas, Deus lhe acrescentará as pragas que estão escritas neste livro;"}, {"numero": 19, "texto": "E se alguém tirar das palavras do livro desta profecia, Deus tirará sua parte do livro da vida, e da cidade santa, e das coisas que estão escritas neste livro."}, {"numero": 20, "texto": "Aquele que dá testemunho destas coisas diz: “Certamente logo venho.” Amém! Sim, vem, Senhor Jesus!"}, {"numero": 21, "texto": "A graça do nosso Senhor Jesus Cristo [seja] com todos vós. Amém!"}]'::jsonb, 'Almeida Livre'),
  ('Ap', 22, 'en', '[{"numero": 1, "texto": "And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb."}, {"numero": 2, "texto": "In the midst of the street of it, and on either side of the river, was there the tree of life, which bare twelve manner of fruits, and yielded her fruit every month: and the leaves of the tree were for the healing of the nations."}, {"numero": 3, "texto": "And there shall be no more curse: but the throne of God and of the Lamb shall be in it; and his servants shall serve him:"}, {"numero": 4, "texto": "And they shall see his face; and his name shall be in their foreheads."}, {"numero": 5, "texto": "And there shall be no night there; and they need no candle, neither light of the sun; for the Lord God giveth them light: and they shall reign for ever and ever."}, {"numero": 6, "texto": "And he said unto me, These sayings are faithful and true: and the Lord God of the holy prophets sent his angel to shew unto his servants the things which must shortly be done."}, {"numero": 7, "texto": "Behold, I come quickly: blessed is he that keepeth the sayings of the prophecy of this book."}, {"numero": 8, "texto": "And I John saw these things, and heard them. And when I had heard and seen, I fell down to worship before the feet of the angel which shewed me these things."}, {"numero": 9, "texto": "Then saith he unto me, See thou do it not: for I am thy fellowservant, and of thy brethren the prophets, and of them which keep the sayings of this book: worship God."}, {"numero": 10, "texto": "And he saith unto me, Seal not the sayings of the prophecy of this book: for the time is at hand."}, {"numero": 11, "texto": "He that is unjust, let him be unjust still: and he which is filthy, let him be filthy still: and he that is righteous, let him be righteous still: and he that is holy, let him be holy still."}, {"numero": 12, "texto": "And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be."}, {"numero": 13, "texto": "I am Alpha and Omega, the beginning and the end, the first and the last."}, {"numero": 14, "texto": "Blessed are they that do his commandments, that they may have right to the tree of life, and may enter in through the gates into the city."}, {"numero": 15, "texto": "For without are dogs, and sorcerers, and whoremongers, and murderers, and idolaters, and whosoever loveth and maketh a lie."}, {"numero": 16, "texto": "I Jesus have sent mine angel to testify unto you these things in the churches. I am the root and the offspring of David, and the bright and morning star."}, {"numero": 17, "texto": "And the Spirit and the bride say, Come. And let him that heareth say, Come. And let him that is athirst come. And whosoever will, let him take the water of life freely."}, {"numero": 18, "texto": "For I testify unto every man that heareth the words of the prophecy of this book, If any man shall add unto these things, God shall add unto him the plagues that are written in this book:"}, {"numero": 19, "texto": "And if any man shall take away from the words of the book of this prophecy, God shall take away his part out of the book of life, and out of the holy city, and from the things which are written in this book."}, {"numero": 20, "texto": "He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus."}, {"numero": 21, "texto": "The grace of our Lord Jesus Christ be with you all. Amen."}]'::jsonb, 'King James Version'),
  ('Ap', 22, 'fr', '[{"numero": 1, "texto": "Et il me montra un fleuve d''''eau de la vie, limpide comme du cristal, qui sortait du trône de Dieu et de l''''agneau."}, {"numero": 2, "texto": "Au milieu de la place de la ville et sur les deux bords du fleuve, il y avait un arbre de vie, produisant douze fois des fruits, rendant son fruit chaque mois, et dont les feuilles servaient à la guérison des nations."}, {"numero": 3, "texto": "Il n''''y aura plus d''''anathème. Le trône de Dieu et de l''''agneau sera dans la ville; ses serviteurs le serviront"}, {"numero": 4, "texto": "et verront sa face, et son nom sera sur leurs fronts."}, {"numero": 5, "texto": "Il n''''y aura plus de nuit; et ils n''''auront besoin ni de lampe ni de lumière, parce que le Seigneur Dieu les éclairera. Et ils régneront aux siècles des siècles."}, {"numero": 6, "texto": "Et il me dit: Ces paroles sont certaines et véritables; et le Seigneur, le Dieu des esprits des prophètes, a envoyé son ange pour montrer à ses serviteurs les choses qui doivent arriver bientôt."}, {"numero": 7, "texto": "Et voici, je viens bientôt. -Heureux celui qui garde les paroles de la prophétie de ce livre!"}, {"numero": 8, "texto": "C''''est moi Jean, qui ai entendu et vu ces choses. Et quand j''''eus entendu et vu, je tombai aux pieds de l''''ange qui me les montrait, pour l''''adorer."}, {"numero": 9, "texto": "Mais il me dit: Garde-toi de le faire! Je suis ton compagnon de service, et celui de tes frères les prophètes, et de ceux qui gardent les paroles de ce livre. Adore Dieu."}, {"numero": 10, "texto": "Et il me dit: Ne scelle point les paroles de la prophétie de ce livre. Car le temps est proche."}, {"numero": 11, "texto": "Que celui qui est injuste soit encore injuste, que celui qui est souillé se souille encore; et que le juste pratique encore la justice, et que celui qui est saint se sanctifie encore."}, {"numero": 12, "texto": "Voici, je viens bientôt, et ma rétribution est avec moi, pour rendre à chacun selon ce qu''''est son oeuvre."}, {"numero": 13, "texto": "Je suis l''''alpha et l''''oméga, le premier et le dernier, le commencement et la fin."}, {"numero": 14, "texto": "Heureux ceux qui lavent leurs robes, afin d''''avoir droit à l''''arbre de vie, et d''''entrer par les portes dans la ville!"}, {"numero": 15, "texto": "Dehors les chiens, les enchanteurs, les impudiques, les meurtriers, les idolâtres, et quiconque aime et pratique le mensonge!"}, {"numero": 16, "texto": "Moi, Jésus, j''''ai envoyé mon ange pour vous attester ces choses dans les Eglises. Je suis le rejeton et la postérité de David, l''''étoile brillante du matin."}, {"numero": 17, "texto": "Et l''''Esprit et l''''épouse disent: Viens. Et que celui qui entend dise: Viens. Et que celui qui a soif vienne; que celui qui veut, prenne de l''''eau de la vie, gratuitement."}, {"numero": 18, "texto": "Je le déclare à quiconque entend les paroles de la prophétie de ce livre: Si quelqu''''un y ajoute quelque chose, Dieu le frappera des fléaux décrits dans ce livre;"}, {"numero": 19, "texto": "et si quelqu''''un retranche quelque chose des paroles du livre de cette prophétie, Dieu retranchera sa part de l''''arbre de la vie et de la ville sainte, décrits dans ce livre."}, {"numero": 20, "texto": "Celui qui atteste ces choses dit: Oui, je viens bientôt. Amen! Viens, Seigneur Jésus!"}, {"numero": 21, "texto": "Que la grâce du Seigneur Jésus soit avec tous!"}]'::jsonb, 'Louis Segond 1910'),
  ('Ap', 22, 'es', '[{"numero": 1, "texto": "DESPUÉS me mostró un río limpio de agua de vida, resplandeciente como cristal, que salía del trono de Dios y del Cordero."}, {"numero": 2, "texto": "En el medio de la plaza de ella, y de la una y de la otra parte del río, estaba el árbol de la vida, que lleva doce frutos, dando cada mes su fruto: y las hojas del árbol eran para la sanidad de las naciones."}, {"numero": 3, "texto": "Y no habrá más maldición; sino que el trono de Dios y del Cordero estará en ella, y sus siervos le servirán."}, {"numero": 4, "texto": "Y verán su cara; y su nombre estará en sus frentes."}, {"numero": 5, "texto": "Y allí no habrá más noche; y no tienen necesidad de lumbre de antorcha, ni de lumbre de sol: porque el Señor Dios los alumbrará: y reinarán para siempre jamás."}, {"numero": 6, "texto": "Y me dijo: Estas palabras son fieles y verdaderas. Y el Señor Dios de los santos profetas ha enviado su ángel, para mostrar á sus siervos las cosas que es necesario que sean hechas presto."}, {"numero": 7, "texto": "Y he aquí, vengo presto. Bienaventurado el que guarda las palabras de la profecía de este libro."}, {"numero": 8, "texto": "Yo Juan soy el que ha oído y visto estas cosas. Y después que hube oído y visto, me postré para adorar delante de los pies del ángel que me mostraba estas cosas."}, {"numero": 9, "texto": "Y él me dijo: Mira que no lo hagas: porque yo soy siervo contigo, y con tus hermanos los profetas, y con los que guardan las palabras de este libro. Adora á Dios."}, {"numero": 10, "texto": "Y me dijo: No selles las palabras de la profecía de este libro; porque el tiempo está cerca."}, {"numero": 11, "texto": "El que es injusto, sea injusto todavía: y el que es sucio, ensúciese todavía: y el que es justo, sea todavía justificado: y el santo sea santificado todavía."}, {"numero": 12, "texto": "Y he aquí, yo vengo presto, y mi galardón conmigo, para recompensar á cada uno según fuere su obra."}, {"numero": 13, "texto": "Yo soy Alpha y Omega, principio y fin, el primero y el postrero."}, {"numero": 14, "texto": "Bienaventurados los que guardan sus mandamientos, para que su potencia sea en el árbol de la vida, y que entren por las puertas en la ciudad."}, {"numero": 15, "texto": "Mas los perros estarán fuera, y los hechiceros, y los disolutos, y los homicidas, y los idólatras, y cualquiera que ama y hace mentira."}, {"numero": 16, "texto": "Yo Jesús he enviado mi ángel para daros testimonio de estas cosas en las iglesias. Yo soy la raíz y el linaje de David, la estrella resplandeciente, y de la mañana."}, {"numero": 17, "texto": "Y el Espíritu y la Esposa dicen: Ven. Y el que oye, diga: Ven. Y el que tiene sed, venga: y el que quiere, tome del agua de la vida de balde."}, {"numero": 18, "texto": "Porque yo protesto á cualquiera que oye las palabras de la profecía de este libro: Si alguno añadiere á estas cosas, Dios pondrá sobre él las plagas que están escritas en este libro."}, {"numero": 19, "texto": "Y si alguno quitare de las palabras del libro de esta profecía, Dios quitará su parte del libro de la vida, y de la santa ciudad, y de las cosas que están escritas en este libro."}, {"numero": 20, "texto": "El que da testimonio de estas cosas, dice: Ciertamente, vengo en breve. Amén, sea así. Ven, Señor Jesús."}, {"numero": 21, "texto": "La gracia de nuestro Señor Jesucristo sea con todos vosotros. Amén."}]'::jsonb, 'Reina-Valera 1909')
